int main(){
    ll N; cin>>N;
    vector<ll> d(N), sum(N+1,0);
    for(int i=0;i<N;i++){
        cin>>d.at(i);
        sum.at(i+1)=sum.at(i)+d.at(i);
    }

    ll TOTAL=sum.at(N);
    ll K=TOTAL/4;
    ll NG=-1, OK=TOTAL-3;

    while(NG<OK-1){
        ll MID=(OK+NG)/2;
        bool able=false;
        ll MIN=K-(MID*3/4), MAX=K+(MID*3/4);
        for(int i=1;i<=N;i++){
            while(sum.at(i)<MIN) i++;
            if(sum.at(i)>MAX) break;


            ll P=sum.at(i);
            for(int j=i+1;j<=N;j++){
                while(sum.at(j)-sum.at(i)<MIN) j++;
                if(sum.at(j)-sum.at(i)>MAX) break;
                ll Q=sum.at(j)-sum.at(i);

                for(int k=j+1;k<=N;k++) {

                    while(sum.at(k)-sum.at(j)<MIN) k++;
                    if(sum.at(k)-sum.at(j)>MAX) break;

                    ll R=sum.at(k)-sum.at(j), S=sum.at(N)-sum.at(k);
                    //cout<<MID<<" arrived "<<P<<':'<<Q<<':'<<R<<':'<<S<<endl;
                    vector<ll> kari(4);
                    kari.at(0)=P;
                    kari.at(1)=Q;
                    kari.at(2)=R;
                    kari.at(3)=S;
                    sort(kari.begin(),kari.end());
                    if(kari.at(3)-kari.at(0)<=MID) able=true;
                    if(able) break;
                }
                if(able) break;

            }
            if(able) break;
        }
        if(able) OK=MID;
        else NG=MID;
        //cout<<MID<<':'<<MAX<<':'<<MIN<<endl;
    }
    cout<<OK<<endl;



