int calc(int l, int m, int r) {
  if (0 <= l && l < m && m < r && r < N - 1) {
    int a1 = vb[l];
    int a2 = vb[m] - a1;
    int a3 = vb[r] - vb[m];
    int a4 = vb[N - 1] - vb[r];
    return (max({a1, a2, a3, a4}) - min({a1, a2, a3, a4}));
  } else
    return INF;
}
