void solve() {
  // 尺取法
  int l = 0;
  int mid = 1;
  int r = 2;
  int ans = INF;
  while (mid < N - 2) {  // midをきめる
    while (vb[mid] > vb[l] * 2) {
      ++l;
    }
    while (vb[N - 1] - vb[mid] > (vb[r] - vb[mid]) * 2) {
      ++r;
    }
    chmin(ans, calc(l, mid, r));
    chmin(ans, calc(l - 1, mid, r));
    chmin(ans, calc(l - 1, mid, r - 1));
    chmin(ans, calc(l, mid, r - 1));
    mid++;
  }
  cout << ans << endl;
}
signed main() {
  input();
  solve();
  return 0;
}

