bool Solve1(int m, int mid){ return v[mid] - v[0] < v[m] - v[mid]; }
bool Solve2(int m, int mid){ return v[mid] - v[m] < v[N] - v[mid]; } 

int main(void){

    scanf("%d", &N);
    for(int i = 1; i <= N; ++i) scanf("%lld", &A[i]);

    v = A;
    for(int i = 1; i < N; ++i) v[i + 1] += v[i]; 

