    for(int m = 2; m <= N - 2; ++m){

        int ok = 0, ng = m;
	    while(abs(ok - ng) > 1){
		    int mid = (ok + ng) / 2;
		    if(Solve1(m, mid)) ok = mid;
		    else ng = mid;
	    }
        int Lmid = ( abs((v[m] - v[ok]) - v[ok]) < abs((v[m] - v[ng]) - v[ng]) ) ? ok : ng;

        ok = m, ng = N;
