int cut(vector<ll> &A, int N, int i, int &il, int &ir, vector<ll> &S){

    while(il < i - 1){
        if(llabs(S[0] - S[1] + 2 * A[il + 1]) < llabs(S[0] - S[1])){
            il++;
            S[0] += A[il];
            S[1] -= A[il];
        }else{
            break;
        }
    }

    while(ir < N - 2){
        if(llabs(S[2] - S[3] + 2 * A[ir + 1]) < llabs(S[2] - S[3])){
            ir++;
            S[2] += A[ir];
            S[3] -= A[ir];
        }else{
            break;
        }
    }

    return *max_element(S.begin(), S.end()) - *min_element(S.begin(), S.end());

}

