#define REP(i,s,N) for(ll i=s;i<N;++i)

// ib : begin index
// ie : end index
ll split(vector<ll> &cum, ll ib, ll ie) {
	if (ie - ib <= 2) return ib+1;
	double mid_value = (cum[ib]+cum[ie-1])/2;
	vector<ll>::iterator it_l = lower_bound(next(cum.begin(), ib), next(cum.begin(),ie), mid_value);
	ll idx;
	if (abs(*prev(it_l,1) - mid_value) < abs(*it_l - mid_value)) {
		idx = distance(cum.begin(), prev(it_l,1));
	} else {
		idx = distance(cum.begin(), it_l);
	}
	return idx;
}

int main () {
	int N;
	cin >> N;
	vector<ll> A(N);
	REP(i,0,N) scanf("%lld", &A[i]);
	// (P,Q), (R,S)で区切ってO(N)
	// PとQが近く, RとSが近くなるように区切る.
	vector<ll> Cum(N,0);
	// 累積和
	Cum[0] = A[0];
	REP(i,1,N) Cum[i] += Cum[i-1] + A[i]; 
	// 初期値
	ll sum3 = 0; REP(i,3,N) sum3 += A[i];
	ll ans = abs(max(max(max(A[0],A[1]),A[2]),sum3) - min(min(min(A[0],A[1]),A[2]),sum3));
	// index icで(P,Q) と (R,S)に分割
	for (ll ic=2;ic<N-2;ic++) {
		ll pq_idx = split(Cum, 0, ic);
		ll rs_idx = split(Cum, ic, N);
		ll p = Cum[pq_idx];
		ll q = Cum[ic-1] - p;
		ll r = Cum[rs_idx] - Cum[ic-1];
		ll s = Cum[N-1] - Cum[rs_idx];
		ans = min(ans, abs(max(max(max(p,q),r),s) - min(min(min(p,q),r),s)));
	}
	cout << ans << endl;
	return 0;
}

