const int MAX_N = (int)(1e5 + 5);

/////////////////////////////////////////////////////////////
class BinaryIndexedTree {
 public:
  static const int MAX_N = (int)(2e5 + 100);

  ll bit_arr[MAX_N];
  int n;

  BinaryIndexedTree(int n) {
    this->n = n;
    init();
  }

  void init() {
    for (int i = 0; i < n; ++i) bit_arr[i] = 0LL;
  }

  ll sum(int i) {
    ll s = 0LL;
    while (i > 0) {
      s += bit_arr[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, ll x) {
    while (i <= n) {
      bit_arr[i] += x;
      i += i & -i;
    }
  }
};
