  }

  long long ans=-1;
  vector<long long> sums;
  REP(i,n){
    if(i==0 || i>=n-2)continue;
    sums.clear();
    sums.push_back(s[b[i]]);
    sums.push_back(rs[e[i+1]]);
    sums.push_back(s[i]-s[b[i]]);
    sums.push_back(rs[i+1]-rs[e[i+1]]);
    sort(sums.begin(), sums.end());
    if(ans<0){
      ans = sums[3]-sums[0];
    }else{
      ans = min(ans,sums[3]-sums[0]);
    }
  }

  cout<<ans<<endl;

  return 0;
}

