const int MOD = 1e9 + 7;
const int INF = 1001001001;
const ll LINF = 1001002003004005006ll;

void solve() {
  int n;
  cin >> n;
  vi a(n);
  vl cum(n + 1);
  rep(i, n) cin >> a[i];
  rep(i, n) cum[i + 1] = cum[i] + a[i];
  dump(n, a, cum);
  ll b, c, d, e;
  auto calc1 = [&](int left, int right, ll val) {
    int maxRight = right;
    while (right - left > 1) {
      int mid = left + (right - left) / 2;
      if (val < cum[mid + 1])
        right = mid;
      else
        left = mid;
    }
    b = cum[left + 1];
    c = cum[maxRight + 1] - cum[left + 1];
    if (right < maxRight - 1) {
      ll b2 = cum[right + 1];
      ll c2 = cum[maxRight + 1] - cum[right + 1];
      if (abs(c2 - b2) < abs(c - b)) {
        b = b2;
        c = c2;
      }
    }
    // dump(left, right, b, c);
  };
  auto calc2 = [&](int left, int right, ll val) {
    int maxLeft = left;
    while (right - left > 1) {
      int mid = left + (right - left) / 2;
      if (val < (cum[mid + 1] - cum[maxLeft]))
        right = mid;
      else
        left = mid;
    }
    d = cum[left + 1] - cum[maxLeft];
    e = cum[n] - cum[left + 1];
    if (right < n - 1) {
      ll d2 = cum[right + 1] - cum[maxLeft];
      ll e2 = cum[n] - cum[right + 1];
      if (abs(e2 - d2) < abs(e - d)) {
        d = d2;
        e = e2;
      }
    }
    // dump(left, right, d, e);
  };
  ll ans = INF;
  for (int mid = 2; mid <= n - 2; mid++) {
    b = 0, c = 0, d = 0, e = 0;
    ll h1 = cum[mid];
    ll h2 = cum[n] - cum[mid];
    // dump(mid, h1, h2);
    calc1(0, mid - 1, h1 / 2);
    calc2(mid, n - 1, h2 / 2);
    ll minVal, maxVal;
    minVal = min(min(b, c), min(d, e));
    maxVal = max(max(b, c), max(d, e));
    // dump(minVal, maxVal);
    dump(mid, b, c, d, e, minVal, maxVal);
    ans = min(ans, abs(maxVal - minVal));
  }
  cout << ans << endl;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(15);
  // freopen("temp.1", "r", stdin);
  solve();
  return 0;
}

