			if(prev > next) r++;
			else break;
		}

		P = sum[l];
		Q = sum[mid] - sum[l];
		R = sum[r] - sum[mid];
		S = sum[n-1] - sum[r];

		res = min(res, max({P,Q,R,S}) - min({P,Q,R,S}));
