int N;
vector<int> A;

void init()
{
	cin >> N;
	A.RS(N+1, 0);
	rep(i, N) {
		cin >> A[i+1];
		A[i+1] += A[i];
	}
}

bool hikaku(int s, int C, int t) {
	return A[C] - A[s] < A[t] - A[C];
}

bool calc(int s, int C, int t, int& val) {
	if (C <= s || t <= C) {
		return false;
	}
	val = abs((A[C] - A[s]) -(A[t] - A[C]));
	return true;
}

void calcminmax(int s, int& C, int t, int& ma, int& mi)
{
	int v = hikaku(s, C, t) ? 1 : -1;
	int val = abs((A[C] - A[s]) -(A[t] - A[C]));
	while (true) {
		int val2 = 0;
		if (!(calc(s, C+v, t, val2))) break;
		if (val > val2) {
			val = val2;
			C += v;
		} else {
			break;
		}
	}
	ma = max((A[C] - A[s]), (A[t] - A[C]));
	mi = min((A[C] - A[s]), (A[t] - A[C]));
}

void solve()
{
	int res = LLONG_MAX;
	int X = 1;
	int Z = 3;
	reps(Y, 2, N-1) {
		int mal, mil, mar, mir;
		calcminmax(0, X, Y, mal, mil);
		calcminmax(Y, Z, N, mar, mir);
		int mi = min(mir, mil);
		int ma = max(mar, mal);
		chmin(res, ma-mi);
	}
	cout << res << endl;
}

