int main(int argc, char const *argv[])
{
	int n; cin >> n;
	vector<ll> a(n);
	rep(i, n) cin >> a[i];
	vector<ll> b(n + 1, 0);
	rep(i, n) b[i + 1] += a[i] + b[i];

	vector<int> left(n, 0);
	for (int i = 2; i <= n - 2; ++i) {
		ll sum = b[i] - b[0];
		// printf("i %d sum %lld\n", i, sum);
		int idx = left[i - 1];
		while(b[idx] - b[0] < sum / 2) idx++;
		if (abs(sum/2 - (b[idx - 1] - b[0])) < abs(sum/2 - (b[idx] - b[0]))) left[i] = idx - 1;
		else left[i] = idx;
		// printf("idx %d\n", idx);
	}
	// printf("\n");
	vector<int> right(n, n);
	for (int i = n - 2; i >= 2; --i) {
		ll sum = b[n] - b[i];
		// printf("i %d sum %lld\n", i, sum);
		int idx = right[i + 1];
		while(b[n] - b[idx] < sum / 2) idx--;
		if (abs(sum/2 - (b[n] - b[idx + 1])) < abs(sum/2 - (b[n] - b[idx]))) right[i] = idx + 1;
		else right[i] = idx;
		// printf("idx %d\n", idx);
	}

/*
	printf("left\n");
	rep(i, n) printf("%d ", left[i]);
	printf("\n");
	printf("right\n");
	rep(i, n) printf("%d ", right[i]);
	printf("\n");
*/

	ll ans = 1e18;
	for (int i = 2; i <= n - 2; ++i) {
		ll l1 = b[left[i]] - b[0];
		ll l2 = (b[i] - b[0]) - l1;
		ll r1 = b[right[i]] - b[i];
		ll r2 = (b[n] - b[i]) - r1;
		// printf("%lld %lld %lld %lld\n", l1, l2, r1, r2);
		ans = min(ans, max<ll>({l1, l2, r1, r2}) - min<ll>({l1, l2, r1, r2}));
	}

	printf("%lld\n", ans);
	return 0;
}

