        }
        ll minr = inf;
        repi(j,Ri[i-1],N-1){
            ll l = Sum[j+1]-Sum[i+1];
            ll r = Sum[N]-Sum[j+1];
            if (abs(r-l) <= minl){
                Ri[i] = j;
                minr = abs(r-l);
            }
        }
        ll P,Q,R,S;
        P = Sum[Le[i]+1];
        Q = Sum[i+1]-Sum[Le[i]+1];
        R = Sum[Ri[i]+1]-Sum[i+1];
        S = Sum[N]-Sum[Ri[i]+1];
        ll M = max(max(P,Q),max(R,S));
        ll m = min(min(P,Q),min(R,S));
        ans = min(ans,abs(M-m));
    }
    cout << ans << endl;
    return 0;
}

