long equal_cut(long * a, long offset, int n){  // n is the number of factors, a is summension
    long m1 = *lower_bound(a, a + n, (a[n-1] + offset) / 2);
    long m2 = *(lower_bound(a, a + n, (a[n-1] + offset) / 2) - 1);
    if(abs(a[n-1] - 2 * m1 + offset) > abs(a[n-1] - 2 * m2 + offset)) return m2 - offset;
    else return m1 - offset;
}
