	ll valR = prefSums[r];
	return valR - valL;
}

void recalcMaxMin()
{
	maxSum = -INF; minSum = INF;
	maxSumI = 0; minSumI = 0;
	for (int i = 0; i < 4; i++)
	{
		if (sum[i] > maxSum)
		{
			maxSum = sum[i];
			maxSumI = i;
		}
		if (sum[i] < minSum)
		{
			minSum = sum[i];
			minSumI = i;
		}
	}
	sumDiff = maxSum - minSum;
}

ll f(ll x)
{
	int currI = 0;
	for (int i = 0; i < 4; i++)
	{
		if (currI == n)
			return -INF + 1;
		sum[i] = a[currI];
		currI++;
		for (; currI < n; currI++)
		{
			if (sum[i] + a[currI] <= x)
				sum[i] += a[currI];
			else
				break;
		}
	}
	if (currI != n)
		return -INF;
	recalcMaxMin();
	return sumDiff;
}

