ll sums[4];

vector<half_sum> half_cand(int s, int t) {
  vector<half_sum> ret;
  half_sum hs1, hs2;
  int i = upper_bound(acc + s, acc + t, (acc[s] + acc[t]) / 2) - acc;
  // printf("  s: %d, t: %d, i: %d\n", s, t, i);
  hs1 = { acc[i - 1] - acc[s], acc[t] - acc[i - 1] };
  hs2 = { acc[i] - acc[s], acc[t] - acc[i] };
  // printf("  hs1: %lld %lld\n", hs1.v1, hs1.v2);
  // printf("  hs2: %lld %lld\n", hs2.v1, hs2.v2);
  if (hs1.v1 > 0 && hs1.d() <= hs2.d()) ret.push_back(hs1);
  if (hs1.v1 == 0 || hs1.d() >= hs2.d()) ret.push_back(hs2);
  return ret;
}

void solve() {
  ll ans = INF;
  REP(i, N) acc[i + 1] = acc[i] + A[i];
  // DUMP(acc, N + 1);
  FOR(k, 2, N - 2) {
    // printf("k: %d\n", k);
    auto hss1 = half_cand(0, k);
    auto hss2 = half_cand(k, N);
    for (auto hs1 : hss1) for (auto hs2 : hss2) {
      sums[0] = hs1.v1;
      sums[1] = hs1.v2;
      sums[2] = hs2.v1;
      sums[3] = hs2.v2;
      // printf("  sums: "); DUMP(sums, 4);

      ll d = *max_element(sums, sums + 4) - *min_element(sums, sums + 4);
      // printf("  d: %lld\n", d);
      ans = min(ans, d);
    }
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d", &N);
  REP(i, N) scanf("%d", A + i);
}

int main() {
  input();
  solve();
  return 0;
}

