LL check(const vector<LL>& s, int l, int mid, int r) {
  int N = s.size() - 1;

  LL P = s[l], Q = s[mid] - s[l], R = s[r] - s[mid], S = s[N] - s[r];
  LL vmax = max({P, Q, R, S});
  LL vmin = min({P, Q, R, S});
  return vmax - vmin;
}

int main() {
  int N; cin >> N;
  vector<LL> A(N); cin >> A;
  vector<LL> S(N + 1); S[0] = 0;
  for (int i = 0; i < N; ++i) S[i + 1] = S[i] + A[i];

  int l = 1, mid = 2, r = 3;
  LL vmin = 1e18;
  for (; mid < N; ++mid) {
    LL vmin1 = abs(S[mid] - 2 * S[l]);
    while (vmin1 > abs(S[mid] - 2 * S[l + 1])) {
      ++l;
      vmin1 =  abs(S[mid] - 2 * S[l]);
    }
    LL vmin2 = abs(S[N] - 2 * S[r] + S[mid]);
    while (vmin2 > abs(S[N] - 2 * S[r + 1] + S[mid])) {
      ++r;
      vmin2 = abs(S[N] - 2 * S[r] + S[mid]);
    }

    vmin = min(vmin, check(S, l, mid, r));
  }
  cout << vmin << endl;
}

