		d[i] += d[i - 1] + a[i];
	}

	ll res = 1e18;
	int l = 0, r = 2;
	for (int i = 2; i <= N - 2; i++) {
		while (abs(d[i - 1] - d[l]*2) >= abs(d[i - 1] - d[l + 1]*2)) {
