using namespace std;

long a[N_MAX];
long cumsum[N_MAX];

long calc_min_diff(long B, long C, long D, long E);

int main(){
    int N;
    int left, center, right;
    long min_diff, prev_diff;
    long B, C, D, E;
    cin >> N;
    cin >> a[0];
    cumsum[0] = a[0];
    for(int i = 1; i < N; i++){
        cin >> a[i];
        cumsum[i] = cumsum[i -1] + a[i];
    }

    left = 1;
    right = 3;
    min_diff = __LONG_MAX__;

    for(center = 2; center <= N - 2; center++){
        //B, C
        prev_diff = __LONG_MAX__;
        while(left < center){
            B = cumsum[left - 1];
            C = cumsum[center - 1] - cumsum[left - 1];
            if(abs(B - C) > prev_diff){
                B = cumsum[left - 2];
                C = cumsum[center - 1] - cumsum[left - 2];
                left--;
                break;
            }
            if(left + 1 == center){break;}

            prev_diff = abs(B - C);
            left++;
        }
        //D, E
        prev_diff = __LONG_MAX__;
        while(right < N){
            D = cumsum[right - 1] - cumsum[center - 1];
            E = cumsum[N - 1] - cumsum[right - 1];
            if(abs(D - E) > prev_diff){
                D = cumsum[right - 2] - cumsum[center - 1];
                E = cumsum[N - 1] - cumsum[right - 2];
                right--;
                break;
            }
            if(right + 1 == N){break;}
            prev_diff = abs(E - D);
            right++;
        }
        if(min_diff > calc_min_diff(B, C, D, E)){
            min_diff = calc_min_diff(B, C, D, E);
        }
    }
    cout << min_diff << '\n';
}

long calc_min_diff(long B, long C, long D, long E){
    long min, max;
    if(B <= C && B <= D && B <= E){
        min = B;
    }
    else if(C < B && C <= D && C <= E){
        min = C;
    }
    else if(D < B && D < C && D <= E){
        min = D;
    }
    else{
        min = E;
    }

    if(B >= C && B >= D && B >= E){
        max = B;
    }
    else if(C > B && C >= D && C >= E){
        max = C;
    }
    else if(D > B && D > C && D >= E){
        max = D;
    }
    else{
        max = E;
    }
    return max - min;
}

