const int N = (int) 2e5 + 5;
const long long INF = (long long) 1e18;

int n;
long long s[N];	
long long ans = INF;

void solve(int opLeft, int opRight) {
	int l = 1, r = 3;
	for (int i = 2; i < n - 1; i++) {
		long long mi, ma;
		r = max(r, i + 1);
		while (1) {
			if (l + 1 == i) break;
			if (opLeft * s[l + 1] > opLeft * (s[i] - s[l + 1])) break;
			l++;
		}
		while (1) {
			if (r + 1 == n) break;
			if (opRight * (s[r + 1] - s[i]) > opRight * (s[n] - s[r + 1])) break;
			r++;
		}
		ma = max({s[l], s[i] - s[l], s[r] - s[i], s[n] - s[r]});
		mi = min({s[l], s[i] - s[l], s[r] - s[i], s[n] - s[r]});
		ans = min(ans, ma - mi);
	}
}

