const int MAX = 200000;
ll sum[MAX];
ll binary(ll s,ll e){
    ll l = s+1,r = e-1;

    while(r-l > 1){
        ll m = (l+r)/2;
        if(sum[m] - sum[s] <= sum[e]-sum[m]){
            l = m;
        }else {
            r = m;
        }
    }
    return l;
}


