int N;
vector<ll> A(200001, 0);

int main(void){

    scanf("%d", &N);
    for(int i = 1; i <= N; ++i) scanf("%lld", &A[i]);

    vector<ll> v = A;
    for(int i = 1; i < N; ++i) v[i + 1] += v[i];

    vector<P> B;
    int j = 1;
    for(int i = 1; i < N - 1; ++i){
        while(j < N - 2){
            B.push_back(make_pair(i, j));
            ++j;
        }
    }

    vector<P> D;
    int left = 3, right = N - 1;
    while(left <= right){
        for(int i = left; i <= right; ++i) D.push_back(make_pair(i, right));
        for(int i = right - 1; i >= left; --i) D.push_back(make_pair(left, i));
        ++left, --right;
    }

    ll ans = LLONG_MAX;
    for(int b = 0; b < B.size(); ++b){
        for(int d = 0; d < D.size(); ++d){
            if(B[b].second + 1 >= D[d].first) continue;
            ll w = v[B[b].second] - v[B[b].first - 1];
            ll x = v[D[d].first - 1] - v[B[b].second];
            ll y = v[D[d].second] - v[D[d].first - 1];
            ll z = v[N] - v[D[d].second];
            ll mx = max({w, x, y, z}), mn = min({w, x, y, z});
            ans = min(ans, abs(mx - mn));
        }
    }
    printf("%lld\n", ans);

    return 0;
}

