ll min4 ( ll P, ll R, ll Q, ll S )
{
  ll mmin = min(P,R);
  ll mmax = max(P,R);
  mmin = min(mmin,Q);
  mmax = max(mmax,Q);
  mmin = min(mmin,S);
  mmax = max(mmax,S);

  return abs(mmax-mmin);
}


int main()
{
  ll ans = MAX;
  int l, r;
  ll P,R,Q,S;
  ll min = MAX;

  cin >> N;
  for ( int i = 0; i < N; ++i ) scanf("%d", &A[i]);

  B[0] = A[0];
  for ( int i = 1; i < N; ++i ) B[i] = B[i-1]+A[i];
  l = 0;
  r = 2;
  for ( int i = 1; i < N-2; ++i ) {
    ll Lmin = MAX;
    ll Rmin = MAX;

    for ( int j = l; j < i; ++j ) {
      P = B[j];
      Q = B[i]-B[j];
      if ( abs(P-Q) < Lmin ) {
        Lmin = abs(P-Q);
        l = j;
      }
      if ( P >= Q ) break;
    }

    for ( int j = r; j < N-1; ++j ) {
      R = B[j]-B[i];
      S = B[N-1]-B[j];
      if ( abs(R-S) < Rmin ) {
        Rmin = abs(R-S);
        r = j;
      }
      if ( R >= S ) break;
    }

    P = B[l]; Q = B[i]-B[l];
    R = B[r]-B[i]; S = B[N-1]-B[r];
    ll tmp = min4(P,Q,R,S);
    if ( ans > tmp ) ans = tmp;
  }

  cout << ans << endl;


}

