template <class _Tp>
class CumulativeSum {
 public:
  CumulativeSum(const std::vector<_Tp>& vec) : vec_(vec) { build(); }

  // return sum of [l, r]
  inline _Tp get(int l, int r) { return sum_[r + 1] - sum_[l]; }

  // return the first k where sum of [0, k] >= value
  int lower_bound(_Tp value) {
    assert(all_of(vec_.begin(), vec_.end(), [](_Tp e) { return e >= 0; }));
    int high = vec_.size() + 1, low = -1;
    while (high - low > 1) {
      int mid = (high + low) >> 1;
      if (sum_[mid + 1] - sum_[0] < value) {
        low = mid;
      } else {
        high = mid;
      }
    }
    return high;
  }

  // return the first k where sum of [0, k] > value
  int upper_bound(_Tp value) {
    assert(all_of(vec_.begin(), vec_.end(), [](_Tp e) { return e >= (_Tp)0; }));
    int high = vec_.size() + 1, low = -1;
    while (high - low > 1) {
      int mid = (high + low) >> 1;
      if (sum_[mid + 1] - sum_[0] <= value) {
        low = mid;
      } else {
        high = mid;
      }
    }
    return high;
  }

 private:
  std::vector<_Tp> vec_;
  std::vector<_Tp> sum_;

  void build() {
    sum_.assign(vec_.size() + 1, static_cast<_Tp>(0));
    for (size_t i = 0; i < vec_.size(); ++i) {
      sum_[i + 1] = sum_[i] + vec_[i];
    }
  }
};

constexpr int64 inf = 1e18;

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n; cin >> n;
  vector<int64> a(n); cin >> a;

  CumulativeSum<int64> cs(a);

  int64 ans = inf;

  for (int i = 0; i < n - 3; ++i) {
    int64 s1 = cs.get(0, i + 1);
    int64 s2 = cs.get(i + 2, n - 1);

    int p1 = cs.upper_bound(s1 / 2);
    int p2 = cs.upper_bound(s1 + s2 / 2);

    int64 t1 = cs.get(0, p1 - 1), t2 = cs.get(p1, i + 1);
    int64 t3 = cs.get(0, p1), t4 = cs.get(p1 + 1, i + 1);
    int64 ans1, ans2, ans3, ans4;
    if (abs(t1 - t2) < abs(t3 - t4)) {
      ans1 = t1, ans2 = t2;
    } else {
      ans1 = t3, ans2 = t4;
    }
    t1 = cs.get(i + 2, p2 - 1), t2 = cs.get(p2, n - 1);
    t3 = cs.get(i + 2, p2), t4 = cs.get(p2 + 1, n - 1);
    if (abs(t1 - t2) < abs(t3 - t4)) {
      ans3 = t1, ans4 = t2;
    } else {
      ans3 = t3, ans4 = t4;
    }
    ans = min(ans, max({ans1, ans2, ans3, ans4}) - min({ans1, ans2, ans3, ans4}));
  }

  cout << ans << endl;

  return 0;
}

