           diff = abs(A[N-1] + A[mid] - 2*A[right+1]);
           right++; 
        }

        uint m = calc_diff(A[left], A[mid] - A[left], A[right] - A[mid], A[N-1] - A[right]);
        //printf("left:%d, mid:%d, right:%d   m = %d\n",left,mid,right,m);
        if(m < min)
            min = m;
    }

    cout << min << endl;
    return 0;
}

