      p[r-2][1] = sum[r] - sum[l+1];
    }
  }

  rep(i, n/2) swap(a[i], a[n-i-1]);
  rep(i, n) sum[i+1] = sum[i] + a[i];
  l = 1;
  for(int r=2; r<n-1; r++){
    while(l<r-1 && sum[l+1]*2<=sum[r]) l++;
    p[n-r-2][3] = sum[l];
    p[n-r-2][2] = sum[r] - sum[l];
    if(l<r-2 && abs(sum[r]-2*sum[l+1])<abs(p[n-r-2][3]-p[n-r-2][2])){
      p[n-r-2][3] = sum[l+1];
      p[n-r-2][2] = sum[r] - sum[l+1];
    }
  }
  long ans = LONG_MAX;
  rep(i, n-3){
    long sumax = p[i][0];
    long sumin = p[i][0];
    rep(j, 3){
      if(sumax < p[i][j+1]) sumax = p[i][j+1];
      if(sumin > p[i][j+1]) sumin = p[i][j+1];
    }
    ans = min(ans, sumax-sumin);
  }
  cout << ans << endl;
}

