vector<vector<int>> f(int b, int e, const vector<int>& v, const vector<long long int>& pre) {
	vector<vector<int>> res;
	long long int s = pre[e];
	if (b > 0) s -= pre[b - 1];
	long long int c = 0;
	for (int i = b; i < e; i++) {
		c += v[i];
		if (c >= s - c) {
			res.push_back({(int)min(c, s - c), (int)max(c, s - c)});
			if (i > b) {
				c -= v[i];
				res.push_back({(int)min(c, s - c), (int)max(c, s - c)});
			}
			return res;
		}
	}
	if (res.size() == 0) {
		res.push_back({(int)min((long long int)v[e], s - v[e]), (int)max((long long int)v[e], s - v[e])});
	}
	return res;
}

