ll bruteforce() {
    ll diff = LLONG_MAX;
    for(int i=1;i<=n-3;i++) {
        for(int j=i+1;j<=n-2;j++) {
            for(int k=j+1;k<=n-1;k++) {
                ll a = prefsum[i];
                ll b = prefsum[j] - prefsum[i];
                ll c = prefsum[k] - prefsum[j];
                ll d = prefsum[n] - prefsum[k];

                ll maxv = max(max(a, b), max(c, d));
                ll minv = min(min(a, b), min(c, d));
                ll curr = maxv - minv;
                if(curr < diff) {
                    diff = curr;
                }
            }
        }
    }
    return diff;
}

int main() {
    cin>>n;
    for(int i=1;i<=n;i++) {
        cin>>arr[i];
        prefsum[i] = prefsum[i-1] + arr[i];
    }

    for(int i=2;i<=n;i++) {
        ll mindiff = LLONG_MAX;
        for(int j=i;j>1;j--) {
            // separate interval [1, i] -> [1, j-1] U [j, i]
            ll li = prefsum[j-1];
            ll ri = prefsum[i] - prefsum[j-1];
            if(ri < li) swap(li, ri);
            if(ri - li < mindiff) {
                mindiff = ri - li;
                pref[i][0] = ri;
                pref[i][1] = li;
            }
        }
    }

    for(int i=n-1;i>=1;i--) {
        // split interval [i, n] -> [i, j] U [j+1, n]
        ll mindiff = LLONG_MAX;
        for(int j=i;j<n;j++) {
            ll li = prefsum[j] - prefsum[i-1];
            ll ri = prefsum[n] - prefsum[j];
            if(ri < li) swap(li, ri);
            if(ri - li < mindiff) {
                mindiff = ri - li;
                suff[i][0] = ri;
                suff[i][1] = li;
            }
        }
    }

    ll diff = LLONG_MAX;
    for(int i=3;i<=n-1;i++) {
        ll a = pref[i-1][0];
        ll b = pref[i-1][1];
        ll c = suff[i][0];
        ll d = suff[i][1];
        ll maxv = max(max(a,b), max(c,d));
        ll minv = min(min(a,b), min(c,d));
        diff = min(maxv - minv, diff);
    }

    cout<<diff<<"\n";

    return 0;
}

