void srch(int dep, int ii, int st)
{
	if(ok==0)
		return ;
	if(dep==3){
		if(st>=N){
			ok = 0;
			return ;
		}
		a[3] = sum[N-1]-sum[st]+A[st];
		sort(a, a+4);
		val = a[3] - a[0];
		return ;
	}
	int l=st, r=N; 
	int m;
	while(l<r){
		m = (l+r)/2;
		if(sum[m]-sum[st]+A[st] >= 1.0*(sum[N-1]-sum[st]+A[st])/(4-dep)-1e-6)
			r = m;
		else
			l = m+1;
	}
	if( (ii & (1<<dep)) == 0){
		if(l==st){
			ok = 0;
			return ;
		}
		a[dep] = sum[l-1]-sum[st]+A[st];
		srch(dep+1, ii, l);
	}
	else{
		if(l==N){
			ok = 0;
			return ;
		}
		a[dep] = sum[l]-sum[st]+A[st];
		srch(dep+1, ii, l+1);
	}
}

