    if(i==0){
      s[i] = a[i];
    }else{
      s[i] = s[i-1]+a[i];
    }
  }

  for(int i=n-1;i>=0;i--){
    if(i==n-1){
      rs[i] = a[i];
    }else{
      rs[i] = rs[i+1]+a[i];
    }
  }

  int b[n],e[n];
  int temp;
  REP(i,n){
    if(i==0){
      b[i] = -1;
    }else if(i==1){
      b[i] = 0;
    }else{
      temp = b[i-1];
