int n;
vector<ll> A;
vector<ll> B;
ll g(ll s, ll e)
{
    return B[e] - (s > 0 ? B[s-1] : 0);
}

ll f(ll mid)
{
    if(mid < 1 || mid >= n-2) return INF + abs(mid);
    ll first = g(0,mid);
    int i = 0;
    while(i < mid && 2*g(0,i) < first) i++;
    ll second = g(mid+1, n-1);
    int j = mid+1;
    while(j < n-1 && 2*g(mid+1,j) < second) j++;

    ll a = g(0,i), b = g(i+1, mid), c = g(mid+1, j), d = g(j+1, n-1);
    //cout << a << " " << b << " " << c << " " << d << endl;
    ll res = INF;
    res = min(res, max(max(a,b), max(c,d)) - min(min(a,b), min(c,d)));
    if(i > 0)
    {   
        a = g(0,i-1), b = g(i, mid), c = g(mid+1, j), d = g(j+1, n-1);
        res = min(res, max(max(a,b), max(c,d)) - min(min(a,b), min(c,d)));
    }
    if(j > mid+1)
    {
        a = g(0,i), b = g(i+1, mid), c = g(mid+1, j-1), d = g(j, n-1);
        res = min(res, max(max(a,b), max(c,d)) - min(min(a,b), min(c,d)));
    }
    if(i > 0 && j > mid+1)
    {
        a = g(0,i-1), b = g(i, mid), c = g(mid+1, j-1), d = g(j, n-1);
        res = min(res, max(max(a,b), max(c,d)) - min(min(a,b), min(c,d)));
    }
    return res;
}

