  //cout << Q[0] << " " << Q[1] << " " << Q[2] << " " << Q[3] <<endl;

  long long result = pow(10,15);

  for(int i=1;i<N-2;i++){ //中央の区切り
    Q[1] = i;

    long long left_S = S[Q[1]];
    long long tmp_left = abs( 2 * S[Q[0]] - left_S );
    for(int j=Q[0] + 1; j<i; j++){ //左の区間の区切り
      long long tmp = abs( 2 * S[j] - left_S );
      if(tmp < tmp_left){
        tmp_left = tmp;
        Q[0] = j;
      }else{ // 左の区間の差が開いたらやめる
        break;
      }
    }

    //cout << Q[0] << " " << Q[1] << " " << Q[2] << " " << Q[3] <<endl;

    long long right_S = S[Q[3]] - S[Q[1]];
    long long tmp_right = abs( 2 * ( S[Q[2]] - S[Q[1]] ) - right_S );
    for(int j=Q[2] + 1; j < N-1; j++){ //右の区間の区切り
      long long tmp = abs( 2 * (S[j] - S[Q[1]]) - right_S );
      if(tmp < tmp_right){
        tmp_right = tmp;
        Q[2] = j;
      }else{ // 左の区間の差が開いたらやめる
        break;
      }
    }

    //cout << Q[0] << " " << Q[1] << " " << Q[2] << " " << Q[3] <<endl;

    P[0] = S[Q[0]];
    P[1] = S[Q[1]] - S[Q[0]];
    P[2] = S[Q[2]] - S[Q[1]];
    P[3] = S[Q[3]] - S[Q[2]];
    long long R[6] = {};
    int count = 0;
    for(int i=0;i<4;i++){
      for(int j=i+1;j<4;j++){
        R[count] = abs(P[i] - P[j]);
        count++;
      }
    }

