long long n;
vector<long long> sum[2], a[2], memo[2];

long long solve();
long long myabs(long long x) { return max(x, -x); }

int main() {
  cin >> n;
  a[0].resize(n);
  for(int i = 0; i < n; ++i) cin >> a[0][i];
  a[1] = a[0];
  reverse(a[1].begin(), a[1].end());
  for(int t = 0; t < 2; ++t) {
    sum[t].assign(n, a[t][0]);
    for(int i = 1; i < n; ++i)
      sum[t][i] = sum[t][i - 1] + a[t][i];
  }
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 10000000000000000;
  for(int t = 0; t < 2; ++t) {
    memo[t].assign(n, 0);
    for(int l = 1, r = 1; r < n; ++r) {
      while(r > l && myabs(sum[t][r] - 2 * sum[t][l - 1]) >
                         myabs(sum[t][r] - 2 * sum[t][l]))
        ++l;
      memo[t][r] = l;
    }
  }
  for(int i = 1; i < n - 2; ++i) {
    long long maxn = -1, minn = 1000000000000000;
    maxn = max(maxn, sum[0][i] - sum[0][memo[0][i] - 1]);
    minn = min(minn, sum[0][i] - sum[0][memo[0][i] - 1]);
    maxn = max(maxn, sum[0][memo[0][i] - 1]);
    minn = min(minn, sum[0][memo[0][i] - 1]);
    maxn = max(maxn, sum[1][n - i - 2] -
                         sum[1][memo[1][n - i - 2] - 1]);
    minn = min(minn, sum[1][n - i - 2] -
                         sum[1][memo[1][n - i - 2] - 1]);
    maxn = max(maxn, sum[1][memo[1][n - i - 2] - 1]);
    minn = min(minn, sum[1][memo[1][n - i - 2] - 1]);
    ans = min(ans, myabs(maxn - minn));
  }
  return ans;
}

