pair<ll,ll> f1(ll* A, int i,int j){
    ll sum=A[j]-A[i];
    int pos = lower_bound(A+i+1,A+j,sum/2) - A;
    pos-=(pos==j);
    if(pos>1){
        if(abs(2*(A[pos]-A[i])-sum)<abs(2*(A[pos-1]-A[i])-sum))return {A[pos]-A[i],A[j]-A[pos]};
        return {A[pos-1]-A[i],A[j]-A[pos-1]};
    }
    return {A[pos]-A[i],A[j]-A[pos]};


}

