int main() {
    int n;
    cin >> n;

    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    vector<int> s(n, a[0]);
    for (int i = 1; i < n; i++) {
        s[i] = s[i-1] + a[i];
    }

    vector<int> f(n-2);
    int l = 0, r = 1;
    while (r < n-2) {
        while (l < n-3 && abs(s[r]-2*s[l]) > abs(s[r]-2*s[l+1])) {
            l++;
        }
        f[r] = l;
        r++;
    }

    vector<int> g(n-2);
    l = 1, r = 2;
    while (l < n-2) {
        while (r < n-1 && abs(s[n-1]-2*s[r]+s[l]) > abs(s[n-1]-2*s[r+1]+s[l])) {
            r++;
        }
        g[l] = r;
        l++;
    }

    vector<int> ans(n-2);
    for (int i = 1; i < n-2; i++){
        ans[i] = max({s[f[i]], s[i]-s[f[i]], s[g[i]]-s[i], s[n-1]-s[g[i]]})
            - min({s[f[i]], s[i]-s[f[i]], s[g[i]]-s[i], s[n-1]-s[g[i]]});
    }

    cout << *min_element(ans.begin()+1, ans.end()) << endl;
}

