int main(void){
    ll n, a[200020], s[200020];
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (i == 0) s[i] = a[i];
        else s[i] = s[i - 1] + a[i];
    }

    ll ans = 1e18;
    for (int i = 1; i < n - 2; i++) {
        int l_l = 0, l_r = i;
        while (l_r - l_l > 1) {
            int l_mid = (l_l + l_r) / 2;
            ll ll_sum = s[l_mid], lr_sum = s[i] - s[l_mid];
            if (ll_sum <= lr_sum) l_l = l_mid;
            else l_r = l_mid;
        }

        //cout << l_l << endl;

        ll p, q;
        ll ll_sum = s[l_l], lr_sum = s[i] - s[l_l];
        //cout << ll_sum << " " << lr_sum << endl;
        if (l_r != i && abs(lr_sum - ll_sum) > abs(s[i] - s[l_l + 1] - s[l_l + 1])) {
            q = s[i] - s[l_l + 1];
            p = s[l_l + 1];
        }
        else {
            p = ll_sum;  q = lr_sum;
        }

        int r_l = i + 1, r_r = n - 1;
        while (r_r - r_l > 1) {
            int r_mid = (r_l + r_r) / 2;
            ll rl_sum = s[r_mid] - s[i], rr_sum = s[n - 1] - s[r_mid];
            if (rl_sum <= rr_sum) r_l = r_mid;
            else r_r = r_mid;
        }

        ll r, ss;
        ll rl_sum = s[r_l] - s[i], rr_sum = s[n - 1] - s[r_l];
        if (r_r != n - 1 && abs(rr_sum - rl_sum) > abs(s[n - 1] - s[r_l + 1] - (s[r_l + 1] - s[i]))) {
            ss = s[n - 1] - s[r_l + 1];
            r = s[r_l + 1] - s[i];
        }
        else {
            r = rl_sum;  ss = rr_sum;
        }

        ans = min(ans, max({p, q, r, ss}) - min({p, q, r, ss}));

        //cout << p << " " << q << " " << r << " " << ss << endl;
    }

    cout << ans << endl;

}

