using Graph = vector<vector<Edge>>;
/* LCA(G, root): 木 G に対する根を root として Lowest Common Ancestor を求める構造体
    query(u,v): u と v の LCA を求める。計算量 O(logn)
    前処理: O(nlogn)時間, O(nlogn)空間
*/
struct LCA {
    vector<vector<int>> parent;  // parent[k][u]:= u の 2^k 先の親
    vector<int> dist;            // root からの距離
    LCA(const Graph &G, int root = 0) { init(G, root); }
    // 初期化
    void init(const Graph &G, int root = 0) {
        int V = G.size();
        int K = 1;
        while ((1 << K) < V) K++;
        parent.assign(K, vector<int>(V, -1));
        dist.assign(V, -1);
        dfs(G, root, -1, 0);
        for (int k = 0; k + 1 < K; k++) {
            for (int v = 0; v < V; v++) {
                if (parent[k][v] < 0) {
                    parent[k + 1][v] = -1;
                } else {
                    parent[k + 1][v] = parent[k][parent[k][v]];
                }
            }
        }
    }
    // 根からの距離と1つ先の頂点を求める
    void dfs(const Graph &G, int v, int p, int d) {
        parent[0][v] = p;
        dist[v] = d;
        for (auto e : G[v]) {
            if (e.to != p) dfs(G, e.to, v, d + 1);
        }
    }
    int query(int u, int v) {
        if (dist[u] < dist[v]) swap(u, v);  // u の方が深いとする
        int K = parent.size();
        // LCA までの距離を同じにする
        for (int k = 0; k < K; k++) {
            if ((dist[u] - dist[v]) >> k & 1) {
                u = parent[k][u];
            }
        }
        // 二分探索で LCA を求める
        if (u == v) return u;
        for (int k = K - 1; k >= 0; k--) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }

    int get_dist(int u, int v) { return dist[u] + dist[v] - 2 * dist[query(u, v)]; }
    bool is_on_path(int u, int v, int a) { return get_dist(u, a) + get_dist(a, v) == get_dist(u, v); }
};

int main(){
  ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  cout << fixed << setprecision(10);
  /*--------------------------------*/

  ll n;cin>>n;
  vl a(n);
  rep(i,n)cin>>a[i];
  vl sa(n+1);
  rep(i,n)sa[i+1]=sa[i]+a[i];
  ll ans=INF;
  rep(i,n+1){
      ll low=0,high=i;
      while(high-low>1){
          ll mid=(high+low)/2;
          sa[mid]*2>=sa[i]?high=mid:low=mid;
      }
    ll p=sa[low],q=sa[i]-sa[low];
    ll p2=sa[high],q2=sa[i]-sa[high];
    ll lmin=min(p,q),lmax=max(p,q);

    if(abs(p2-q2)<abs(p-q))lmin=min(p2,q2),lmax=max(p2,q2);

    low=i;high=n;
    while(high-low>1){
        ll mid=(high+low)/2;
        (sa[mid])*2>=sa[i]+sa[n]?high=mid:low=mid;
    }
    p=sa[low]-sa[i],q=sa[n]-sa[low];
    p2=sa[high]-sa[i],q2=sa[n]-sa[high];
    ll rmin=min(p,q),rmax=max(p,q);

    if(abs(p2-q2)<abs(p-q))rmin=min(p2,q2),rmax=max(p2,q2);
    ll tmp=max(lmax,rmax)-min(lmin,rmin);
    chmin(ans,tmp);
