	}

	vector<int> disList(n);
	int sum = 0;
	for (int i = 0; i < n; ++i) {
		sum += v[i];
		disList[i] = sum;
	}
	auto d = [&](int a, int b) {
		if (a > 0) {
			return disList[b] - disList[a - 1];
		} else {
			return disList[b];
		}
	};

	int p = 0;
	int q = 0;
	int r = 0;
	int s = 0;
	int mx = -1;
	//0-mid (mid+1)-(n-1)
	for (int mid = 1; mid < n - 2; ++mid) {
		int dmin = disList[n - 1];
		for (int l = 0; l < mid; ++l) {
			int tmp = abs(d(0, l) - d(l + 1, mid));
			if (dmin > tmp) {
				dmin = tmp;
				p = d(0, l);
				q = d(l + 1, mid);
			}
		}
		dmin = disList[n - 1];
		for (int ri = mid + 1; ri < n - 1; ++ri) {
			int tmp = abs(d(mid + 1, ri) - d(ri + 1, n - 1));
			if (dmin > tmp) {
				dmin = tmp;
				r = d(mid + 1, ri);
				s = d(ri + 1, n - 1);
			}
		}
		vector<int> t = { p,q,r,s };
		std::sort(t.begin(), t.end());
		if (mx < 0) { mx = t[3] - t[0]; }
