void solve() {
  int n;
  cin >> n;
  vector<int> a(n);
  cin >> a;

  vector<ll> acc(n + 1);
  rep(i, n) acc[i + 1] = acc[i] + a[i];

  ll ans = INF;
  // 真ん中を探索
  // a に関して, 左の右端
  rep3(i, 1, n - 2) {
    vector<pair<pair<ll, ll>, pair<ll, ll> > > v(4);
    // 左
    int it = lb(acc, (acc[i + 1] + 1) / 2);
    if (it == i + 1) it--;

    rep(j, 2) {
      v[j].F.F = acc[it];
      v[j].F.S = acc[i + 1] - acc[it];

      it--;
      if (it == 0) it++;
      v[2 + j].F.F = acc[it];
      v[2 + j].F.S = acc[i + 1] - acc[it];
    }
    // debug
    /*
    cout << endl << v[0].F.F << " " << v[0].F.S << endl;
    cout << v[2].F.F << " " << v[2].F.S << endl;
    */

    // 右
    it = lb(acc, acc[i + 1] + ((acc[n] - acc[i + 1]) + 1) / 2);
    if (it == n) it--;
    rep(j, 2) {
      v[2 * j].S.F = acc[n] - acc[it];
      v[2 * j].S.S = acc[it] - acc[i + 1];

      it--;
      if (it == i + 1) it++;
      v[2 * j + 1].S.F = acc[n] - acc[it];
      v[2 * j + 1].S.S = acc[it] - acc[i + 1];
    }
    /*
    cout << endl << v[0].S.F << " " << v[0].S.S << endl;
    cout << v[1].S.F << " " << v[1].S.S << endl;
    */
    rep(j, 4) {
      vector<ll> v2(4);
      v2[0] = v[j].F.F;
      v2[1] = v[j].F.S;
      v2[2] = v[j].S.F;
      v2[3] = v[j].S.S;
      sort(all(v2));
      chmin(ans, v2[3] - v2[0]);
    }
  }
  cout << ans << endl;
}

