using namespace std;
typedef vector<long>::const_iterator iter;

vector<long> cumsum(vector<long> vec){
  if(vec.size()==0) return vec;
  for(auto it = vec.begin()+1; it!=vec.end(); ++it){
    *it += *(it-1);
  }
  return vec;
}

int cut(iter bgn, iter end, int nu){
  long half = *(end-1);
  long nb =0;
  if (nu!=0) nb=*(bgn-1);
  half= (half-nb)/(4-nu)+nb;
  for (auto it = bgn; it != end; ++it){
    if(*it >= half) return (it - bgn);
  }
  return 0;
}

