// Cuts A[i:j] into A[i:x] and A[x:j]
int cut(const vector<long> &A, int i, int j)
{
    long si = A.at(i);
    long sj = A.at(--j);
    while (i < j - 1)
    {
        long di = abs((si + A.at(i + 1)) - sj);
        long dj = abs((sj + A.at(j - 2)) - si);
        if (di < dj)
            si += A.at(++i);
        else
            sj += A.at(--j);
    }
    return j;
}


long sum(const vector<long> &A, int i, int j)
{
    long s(0);
    for (; i < j; ++i) s += A.at(i);
    return s;
}


long delta(const array<long, 4> &S)
{
    long s_min(0), s_max(0);
    for (auto s : S)
    {
        if (s < s_min || s_min == 0) s_min = s; 
        if (s > s_max || s_max == 0) s_max = s;
    }
    return (s_max - s_min);
}


int main()
{
    int N;
    cin >> N;

    vector<long> A(N, 0);
    for (int i = 0; i < N; ++i)
        cin >> A[i];

    array<long, 3> C{0, 0, 0};
    C[1] = max(2, min(N - 2, cut(A, 0, N)));
    C[0] = cut(A, 0, C[1]);
    C[2] = cut(A, C[1], N);

    array<long, 4> S({
            sum(A, 0, C[0]),
            sum(A, C[0], C[1]),
            sum(A, C[1], C[2]),
            sum(A, C[2], N) });
    auto d_min = delta(S);

    auto move = [&C, &A](array<long, 4> &S, int i, int d)
    {
        if (d == 1)
        {
            S[i] += A[C[i]];
            S[i + 1] -= A[C[i]];
        }
        else if (d == -1)
        {
            S[i] -= A[C[i] - 1];
            S[i + 1] += A[C[i] - 1];
        }
    };
    auto print = [&]()
    {
        cerr << "C: { 0, ";
        for (int i = 0; i < 3; ++i) cerr << C[i] << ((i < 2) ? ", " : " }   ");
        cerr << "S: { ";
        for (int i = 0; i < 4; ++i) cerr << S[i] << ((i < 3) ? ", " : " }   ");
        cerr << "d_min: " << d_min << endl;
    };
    print();

    bool do_break;
    do
    {
        do_break = true;
        for (auto d1 : { 0, 1, -1 })
        {
            for (auto d2 : { 0, 1, -1 })
            {
                for (auto d3 : { 0, 1, -1 })
                {                    
                    array<int, 3> D{ d1, d2, d3 };

                    bool good(true);
                    for (int i = 0; i < 2; ++i)
                    {
                        if (C[i] + D[i] == C[i+1] + D[i+1])
                        {
                            good = false;
                            break;
                        }
                    }
                    if (not good) continue;

                    auto S_ = S;
                    for (int i = 0; i < 3; ++i)
                        move(S_, i, D[i]);

                    auto d = delta(S_);
                    if (d < d_min)
                    {
                        do_break = false;
                        d_min = d;
                        S = S_;
                        for (int i = 0; i < 3; ++i)
                            C[i] += D[i];
                        print();
                    }
                    if (not do_break) break;
                }
                if (not do_break) break;
            }
            if (not do_break) break;
        }
    } while(not do_break);

    cout << d_min << endl;
}

