    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N;cin >> N;
    vector<long long> retu(N);
    for(int i = 0;i<N;i++) cin >> retu.at(i);
    vector<long long> rui(N+1);
    for(int i = 0;i<N;i++){
        rui.at(i+1) = rui.at(i)+retu.at(i);
    }
    //中央切りを全探索
    long long ans = INF;
    for(int i = 2;i<N-1;i++){
        //左側
        long long PQ = rui.at(i);
        int left = 0,right = i;
        while(right - left > 1){
            int mid = left+(right-left)/2;
            if(rui.at(mid) < rui.at(i)-rui.at(mid)){
                left = mid;
            }
            else{
                right = mid;
            }
        }
        long long P = rui.at(left);long long Q = PQ-P;
        //一応left,rightの両方見ておく
        long long P2 = rui.at(right);long long Q2 = PQ-P2;
        long long LEFT_MAX = 0,LEFT_MIN = INF;
        if(abs(P-Q) > abs(P2-Q2)){
            LEFT_MAX = max(P2,Q2);
            LEFT_MIN = min(P2,Q2);
        }
        else{
            LEFT_MAX = max(P,Q);
            LEFT_MIN = min(P,Q);
        }
        //右側
        long long RS = rui.at(N)-PQ;
        left = i,right = N;
        while(right - left > 1){
            int mid = left+(right-left)/2;
            if(rui.at(mid)-rui.at(i) < rui.at(N)-rui.at(left)){
                left = mid;
            }
            else{
                right = mid;
            }
        }
        long long R = rui.at(left)-rui.at(i);long long S = RS-R;
        long long R2 = rui.at(right)-rui.at(i);long long S2 = RS-R2;
        long long RIGHT_MAX = 0,RIGHT_MIN = INF;
        if(abs(R-S) > abs(R2-S2)){
            RIGHT_MAX = max(R2,S2);
            RIGHT_MIN = min(R2,S2);
        }
        else{
            RIGHT_MAX = max(R,S);
            RIGHT_MIN = min(R,S);
        }
        ans = min(ans,max(LEFT_MAX,RIGHT_MAX) - min(LEFT_MIN,RIGHT_MIN));
    }
    cout << ans << endl;
}

