Int N;

bool isOK_R(Int x, Int i) {

	if (s[x] - s[i] < s[N] - s[x]) {
		return true;
	}
	else {
		return false;
	}
}

Int binary_search_R(Int i) {
	Int ng = N;
	Int ok = i; 

	while (abs(ok - ng) > 1) {
		Int mid = (ok + ng) / 2;

		if (isOK_R(mid, i)) ok = mid;
		else ng = mid;
	}
	return ok;
}

bool isOK_L(Int x,Int i) {

	if (s[x]-s[0]<s[i]-s[x]) {
		return true;
	}
	else {
		return false;
	}
}

Int binary_search_L(Int i) {
	Int ng = i; 
	Int ok = 0; 

	while (abs(ok - ng) > 1) {
		Int mid = (ok + ng) / 2;

		if (isOK_L(mid,i)) ok = mid;
		else ng = mid;
	}
	return ok;
}

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	cin >> N;

	vector<Int> A(N);
	for (Int i = 0; i < N; i++) {
		cin >> A[i];
	}

	s.resize(N + 1);
	for (Int i = 0; i < N; i++) {
		s[i + 1] = s[i] + A[i];
	}

	Int ans = INF;
	Int tempL, tempR;
	Int mx, mn;
	for (Int i = 2; i <= N - 2; i++) {//真ん中の切れ目
		//左半分の最適化
		tempL = binary_search_L(i);
		if (abs(s[tempL] - (s[i] - s[tempL])) > abs(s[tempL + 1] - (s[i] - s[tempL + 1]))) {
			tempL++;
		}

		//右半分の最適化
		tempR = binary_search_R(i);
		if (abs((s[N]-s[tempR]) - (s[tempR] - s[i])) > abs((s[N]-s[tempR+1]) - (s[tempR+1] - s[i]))) {
			tempR++;
		}

		mx = max({ s[tempL],s[i] - s[tempL],s[tempR] - s[i],s[N] - s[tempR] });
		mn = min({ s[tempL],s[i] - s[tempL],s[tempR] - s[i],s[N] - s[tempR] });

		ans = min(ans, mx - mn);

	}

	cout << ans << "\n";

}

