int main(){

	int N;
	scanf("%d",&N);

	int i;
	for(i=0;i<N;i++){
	scanf(" %lld",&A[i]);
	}

	for(i=1;i<N;i++){
	A[i]+=A[i-1];
	}

	ll ans=LLONG_MAX;

	for(i=1;i<=N-3;i++){
	ll sum_l=A[i];
	ll sum_r=A[N-1]-A[i];

	int l,r;

	l=1;
	r=i;

	while(l<r){
	int mid=(l+r)/2;
	if(A[mid]>sum_l-A[mid]){
	r=mid;
	}
	else{
	l=mid+1;
	}
	}

	ll ma,mi;

	ll s11,s12,s21,s22;

	s11=llabs(A[l]-(sum_l-A[l]));
	s12=llabs(A[l-1]-(sum_l-A[l-1]));

	if(s11<s12){
	ma=max(A[l],sum_l-A[l]);
	mi=min(A[l],sum_l-A[l]);
	}
	else{
	ma=max(A[l-1],sum_l-A[l-1]);
	mi=min(A[l-1],sum_l-A[l-1]);
	}

	l=i+2;
	r=N-1;

	while(l<r){
	int mid=(l+r)/2;
	if(A[mid]-sum_l>sum_r-(A[mid]-sum_l)){
	r=mid;
	}
	else{
	l=mid+1;
	}
	}

	s21=llabs(A[l]-sum_l-(sum_r-(A[l]-sum_l)));
	s22=llabs(A[l-1]-sum_l-(sum_r-(A[l-1]-sum_l)));

	if(s21<s22){
	ma=max(ma,max(A[l]-sum_l,sum_r-(A[l]-sum_l)));
	mi=min(mi,min(A[l]-sum_l,sum_r-(A[l]-sum_l)));
	}
	else{
	ma=max(ma,max(A[l-1]-sum_l,sum_r-(A[l-1]-sum_l)));
	mi=min(mi,min(A[l-1]-sum_l,sum_r-(A[l-1]-sum_l)));
	}

	if(ans>ma-mi){ans=ma-mi;}

	}

	printf("%lld\n",ans);

	return 0;
}

