const int maxn = 200100;
ll n, arr[maxn];

ll pref[maxn][2];
ll suff[maxn][2];

ll prefsum[maxn];

ll bruteforce() {
    ll diff = LLONG_MAX;
    for(int i=1;i<=n-3;i++) {
        for(int j=i+1;j<=n-2;j++) {
            for(int k=j+1;k<=n-1;k++) {
                ll a = prefsum[i];
                ll b = prefsum[j] - prefsum[i];
                ll c = prefsum[k] - prefsum[j];
                ll d = prefsum[n] - prefsum[k];

                ll maxv = max(max(a, b), max(c, d));
                ll minv = min(min(a, b), min(c, d));
                ll curr = maxv - minv;
                if(curr < diff) {
                    diff = curr;
                }
            }
        }
    }
    return diff;
}

ll checkprefdiff(int x, int y) {
    ll li = prefsum[x];
    ll ri = prefsum[y] - prefsum[x];
    ll diff = max(li, ri) - min(li, ri);
    return diff;
}

ll checksuffdiff(int x, int y) {
    ll ri = prefsum[n] - prefsum[y-1];
    ll li = prefsum[y-1] - prefsum[x-1];
    ll diff = max(li, ri) - min(li, ri);
    return diff;
}

int main() {
    cin>>n;
    for(int i=1;i<=n;i++) {
        cin>>arr[i];
        prefsum[i] = prefsum[i-1] + arr[i];
    }

    ll splitpoint = 1;
    for(int i=2;i<=n;i++) {
        while(splitpoint + 1 < i && checkprefdiff(splitpoint, i) > checkprefdiff(splitpoint + 1, i)) splitpoint++;
        ll li = prefsum[splitpoint];
        ll ri = prefsum[i] - prefsum[splitpoint];
        if(ri < li) swap(li, ri);
        pref[i][0] = ri;
        pref[i][1] = li;
    }

    splitpoint = n;
    for(int i=n-1;i>=1;i--) {
        while(splitpoint - 1 > i &&  checksuffdiff(i, splitpoint) > checksuffdiff(i, splitpoint - 1)) splitpoint--;
        ll li = prefsum[splitpoint-1] - prefsum[i-1];
        ll ri = prefsum[n] - prefsum[splitpoint-1];
        if(ri < li) swap(li, ri);
        suff[i][0] = ri;
        suff[i][1] = li;
    }

    ll diff = LLONG_MAX;
    for(int i=3;i<=n-1;i++) {
        ll a = pref[i-1][0];
        ll b = pref[i-1][1];
        ll c = suff[i][0];
        ll d = suff[i][1];
        ll maxv = max(max(a,b), max(c,d));
        ll minv = min(min(a,b), min(c,d));
        diff = min(maxv - minv, diff);
    }

    cout<<diff<<"\n";

    return 0;
}

