const int MAX=2e5+5;

lli A[MAX], cum[MAX];

int part(int start, int last) {
    int L = start, R = last;
    lli deduct = cum[start-1], least = (lli)(1e15); int ind = -1;
    while(start<last) {
        int mid = (start+last)>>1;
        if(cum[mid]-deduct == cum[last]-cum[mid])
            return mid;
        if(cum[mid]-deduct < cum[last]-cum[mid]) {
            if(least > abs(cum[last]-2*cum[mid]+deduct)) {
                least = abs(cum[last]-2*cum[mid]+deduct); ind = mid;
            }
            start = mid+1;
        }
        else {
            if(least > abs(cum[last]-2*cum[mid]+deduct)) {
                least = abs(cum[last]-2*cum[mid]+deduct); ind = mid;
            }
            last = mid-1;
        }
    }
    lli other = (lli)(1e15);
    if(start == last) {
        other = abs(cum[start]-cum[L-1] - (cum[R]-cum[start]));
        //cout << "Start = Last \tother = " << other << "\n";
    }
    if(other < least)
        ind = start;
    //cout << L << " " << R << " ind = " << ind << "\n";
    return ind;
}

