template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    vector<ll> A(N); for(auto& in:A) cin >> in;

    vector<ll> cusum(N+1);
    for(int i = 0; i < N;i++){
        cusum[i+1] = cusum[i] + A[i];
    }


    ll ans = LINF;
    for(int m = 2; m < N-1; m++){
        ll PQ = cusum[m];
        ll RS = cusum[N] - cusum[m];

        ll it_l = lower_bound(cusum.begin(),cusum.end(),PQ/2) - cusum.begin();
        ll it_r = lower_bound(cusum.begin(),cusum.end(),PQ + RS/2) - cusum.begin();

        for(int dl = -20; dl <= 20; dl++){
            for(int dr = -20; dr <= 20; dr++){

                ll l_idx = it_l + dl;

                if(l_idx < 1) continue;
                if(l_idx >= m) continue;

                ll r_idx = it_r + dr;

                if(r_idx <= m) continue;
                if(r_idx >= N) continue;


                ll P = cusum[l_idx];
                ll Q = PQ - P;
                ll R = cusum[r_idx] - cusum[m];
                ll S = RS - R;

                ans = min(ans,max({P,Q,R,S})-min({P,Q,R,S}));
            }
        }
    }
    cout << ans << endl;
    return res;
}


