            if(ri < li) swap(li, ri);
            if(ri - li < mindiff) {
                mindiff = ri - li;
                pref[i][0] = ri;
                pref[i][1] = li;
            }
        }
    }

    for(int i=n-2;i>=1;i--) {
        // split interval [i, n] -> [i, j] U [j+1, n]
        ll mindiff = LLONG_MAX;
        for(int j=i;j<n;j++) {
            ll li = prefsum[j] - prefsum[i-1];
            ll ri = prefsum[n] - prefsum[j];
            if(ri < li) swap(li, ri);
            if(ri - li < mindiff) {
                mindiff = ri - li;
                suff[i][0] = ri;
                suff[i][1] = li;
            }
        }
    }
    ll diff = LLONG_MAX;
    for(int i=3;i<=n-1;i++) {
        ll a = pref[i-1][0];
        ll b = pref[i-1][1];
        ll c = suff[i][0];
        ll d = suff[i][1];
        ll maxv = max(max(a,b), max(c,d));
        ll minv = min(min(a,b), min(c,d));
        if(maxv - minv < diff) diff = maxv - minv;
    }
    cout<<diff<<"\n";
    return 0;
}

