int main()
{
    int N;
    cin >> N;

    vector<long> A(N, 0);
    for (int i = 0; i < N; ++i)
        cin >> A[i];

    vector<long> S(N, 0);
    for (int i = 0; i < N; ++i)
        S[i] = A[i] + ((i > 0) ? S[i - 1] : 0);

    auto R = [&](int i, int j) -> long
    {
        return S[j - 1] - S[i - 1];
    };
    auto delta = [&](array<int, 3> &C) -> long
    {
        array<long, 4> sums({ S[C[0] - 1], R(C[0], C[1]), R(C[1], C[2]), R(C[2], N) });
        long s_min(0), s_max(0);
        for (auto s : sums)
        {
            if (s < s_min || s_min == 0) s_min = s; 
            if (s > s_max || s_max == 0) s_max = s;
        }
        return (s_max - s_min);        
    };

    array<int, 3> C({ 1, 2, 3 });
    long d_min = -1;

    for (; C[1] < N - 1; C[1] += 1)
    {
        long d1 = abs(S[C[0] - 1] - R(C[0], C[1]));
        for (int i = C[0] + 1; i < C[1]; ++i)
        {
            long d2 = abs(S[i - 1] - R(i, C[1]));
            if (d2 < d1)
            {
                d1 = d2;
                C[0] = i;
            }
        }
        long d3 = abs(R(C[1], C[2]) - R(C[2], N));
        for (int i = C[1] + 1; i < N; ++i)
        {
            long d4 = abs(R(C[1], i) - R(i, N));
            if (d4 < d3)
            {
                d3 = d4;
                C[2] = i;
            }
        }

        long d = delta(C);
        if (d_min > d || d_min < 0) d_min = d;
    }

    cout << d_min << endl;
}

