        cin >> A[i];
        A[i] += A[i - 1];
    }
    ll ans = INF;
    for (int i = 2; i <= N - 2; i++) {
        ll sub_ans = 0;
        int idx1 = lower_bound(A + 1, A + i + 1, A[i] / 2) - A;
        if (idx1 == i) idx1--;
        int idx2 = lower_bound(A + i + 1, A + N + 1, A[i] + ((A[N] - A[i]) / 2)) - A;
        if (idx2 == N) idx2--;
        for (int j = -1; j <= 1; j++) {
            for (int k = -1; k <= 1; k++) {
                if (idx1 + j == 0 || idx1 + j == N + 1 || idx2 + k == 0 || idx2 + k == N + 1) continue;
                ll P = A[idx1 + j], Q = A[i] - A[idx1 + j], R = A[idx2 + k] - A[i], S = A[N] - A[idx2 + k];
                ans = min(ans, abs(max(P, max(Q, max(R, S)))) - min(P, min(Q, min(R, S))));
            }
        }
    }
    cout << ans << endl;
    return 0;
}

