class Monoid {
public:
    // 単位元
    ll unit;

    Monoid() {
        // 単位元
        unit = 0;
    }

    // 演算関数
    ll calc(ll a, ll b) {
        return a + b; 
    }
};

class SegmentTree {
public:
    // セグメント木の葉の要素数
    ll n;

    // セグメント木
    vector<ll> tree;

    // モノイド
    Monoid mono;

    SegmentTree(vector<ll> &v) {
        n = 1 << (ll)ceil(log2(v.size()));
        tree = vector<ll>(n << 1);
        for(ll i = 0; i < v.size(); i++) {
            update(i, v[i]);
        }
        for(ll i = v.size(); i < n; i++) {
            update(i, mono.unit);
        }
    }

    // k番目の値(0-indexed)をxに変更
    void update(ll k, ll x) {
        k += n;
        tree[k] = x;
        for(k = k >> 1; k > 0; k >>= 1){
            tree[k] = mono.calc(tree[k << 1 | 0], tree[k << 1 | 1]);
        }
    }

    // [l, r)の最小値(0-indexed)を求める．
    ll query(ll l, ll r) {
        ll res = mono.unit;
        l += n;
        r += n;
        while(l < r) {
            if(l & 1) {
                res = mono.calc(res, tree[l++]);
            }
            if(r & 1) {
                res = mono.calc(res, tree[--r]);
            }
            l >>= 1;
            r >>= 1;
        }
        return res;
    }
    ll operator[](ll k) {
        // st[i]で添字iの要素の値を返す
        if(k - n >= 0 || k < 0) {
            return -INF;
        }
        return tree[tree.size()-n+k];
    }

    void show() {
        ll ret = 2;
        for(ll i = 1; i < 2*n; i++) {
            cout << tree[i] << " ";
            if(i == ret - 1) {
                cout << endl;
                ret <<= 1;
            }
        }
        cout << endl;
    }
};

ll diff(ll a, ll b) {
    return abs(a - b);
}
pair<int,int> binarysearch(int l, int r, ll s, ll t, SegmentTree st) {
    int ok = l - 1; //これがx以下 
    int ng = r + 1; //x以上 
    // 問題によってokとngを入れ替える
    for(int j = 0; j < 35; j++) {
        int mid = (ok + ng)/2;
        ll nowdiff = diff(s, t);
        ll lsum = st.query(l, mid + 1);
        ll rsum = st.query(mid + 1, r + 1);
        ll nextdiff = diff(lsum, rsum);
        // cout<<lsum<<" "<<rsum<<endl;
        if(nowdiff >= nextdiff){
            s = lsum;
            t = rsum;
        }
        if(lsum < rsum) {
            ok = mid;
        }
        else ng = mid;
    }
    // cout<<"&&&"<<s<<" "<<t<<endl;
    return mp(s, t);
}

int main(void) {

    int n;
    scanf("%d", &n);
    vll a(n);
