void solve() {
  int n;
  cin >> n;
  vi a(n);
  vl cum(n + 1);
  rep(i, n) cin >> a[i];
  rep(i, n) cum[i + 1] = cum[i] + a[i];
  dump(n, a, cum);
  auto calc = [&](int left, int right) {
    ll base = cum[left];
    ll total = cum[right + 1] - base;
    while (right - left > 1) {
      int mid = left + (right - left) / 2;
      if (total / 2 < cum[mid + 1] - base)
        right = mid;
      else
        left = mid;
    }
    return left;
  };
  ll ans = INF;
  for (int m = 2; m <= n - 2; m++) {
    int m1 = calc(0, m - 1);
    int m2 = calc(m, n - 1);
    rep(i, 2) rep(j, 2) {
      if (m1 + i == m - 1) continue;
      if (m2 + j == n - 1) continue;
      ll b = cum[m1 + i + 1];
      ll c = cum[m] - cum[m1 + i + 1];
      ll d = cum[m2 + j + 1] - cum[m];
      ll e = cum[n] - cum[m2 + j + 1];
      if (b + c + d + e != cum[n]) {
        dump(m, m1, m2, b, c, d, e);
        return;
      }
      ll minVal = min(min(b, c), min(d, e));
      ll maxVal = max(max(b, c), max(d, e));
      dump(m, m1, m2, b, c, d, e, minVal, maxVal);
      ans = min(ans, abs(maxVal - minVal));
    }
  }
  cout << ans << endl;
}

