static int
cut(vector<int> const &A, int top, int bot, int reserve, long sum, long *sum0_ret, long *sum1_ret)
{
  int const *data = A.data();
  long sum0 = 0;
  long sum1 = 0;
  for (int i = 0; i < reserve; i++)
  {
    sum0 += data[top++];
    sum1 += data[--bot];
  }
  while (top < bot)
  {
    if (sum0 < sum1)
    {
      sum0 += data[top++];
    }
    else
    {
      sum1 += data[--bot];
    }
  }
  *sum0_ret = sum0;
  *sum1_ret = sum1;
  return top;
}

static long
calc_diff(vector<int> const &A, int N, int center, long sum0, long sum1)
{
  long a = 0;
  long b = 0;
  long c = 0;
  long d = 0;
  int center0 = cut(A, 0, center, 1, sum0, &a, &b);
  int center1 = cut(A, center, N, 1, sum1, &c, &d);
  return max<long>({a, b, c, d}) - min<long>({a, b, c, d});
}

int
main()
{
  int N;
  cin >> N;
  vector<int> A(N);
  long sum = 0;
  for (int i = 0; i < N; i++)
  {
    int tem;
    cin >> tem;
    A[i] = tem;
    sum += tem;
  }
  long sum0 = 0;
  long sum1 = 0;
  int center = cut(A, 0, N, 2, sum, &sum0, &sum1);
  long diff = calc_diff(A, N, center, sum0, sum1);
  int c0 = center;
  long s0 = sum0;
  long s1 = sum1;
  while (1 < c0)
  {
    int tem = A[c0 - 1];
    long diff0 = calc_diff(A, N, c0 - 1, s0 - tem, s1 + tem);
    if (diff <= diff0)
    {
      break;
    }
    c0--;
    s0 -= tem;
    s1 += tem;
    diff = diff0;
  }
  if (c0 == center)
  {
    while (c0 < N - 1)
    {
      int tem = A[c0];
      long diff0 = calc_diff(A, N, c0 + 1, s0 + tem, s1 - tem);
      if (diff < diff0)
      {
        break;
      }
      c0++;
      s0 += tem;
      s1 -= tem;
      diff = diff0;
    }
  }
  cout << diff << endl;
  return 0;
}

