    rep(i, n)
    {
        cin >> dp[i + 1];
        dp[i + 1] += dp[i];
    }
    ll ans = 1LL<<62;
    // しゃくとりで前計算
    // [0,r)
    vector<P> before(n + 1);
    int l = 0;
    int r = 1;
    for(r = 1;r<n;r++){
        while (l + 1 < r && abs(dp[l] - dp[0] - (dp[r] - dp[l])) > abs(dp[l + 1] - dp[0] - (dp[r] - dp[l + 1])))
        {
            l++;
        }
        P p;
        p.first = max(dp[l] - dp[0], dp[r] - dp[l]);
        p.second = min(dp[l] - dp[0], dp[r] - dp[l]);
        before[r] = p;
    }
    // [l,n)
    r = 1;
    vector<P> later(n+1);
    for (l = 0; l < n; l++)
    {
        while(r+1<n && abs(dp[r]-dp[l] - (dp[n]-dp[r]))>abs(dp[r+1]-dp[l] - (dp[n]-dp[r+1]))){
            r++;
        }
        P p;
        p.first = max(dp[r] - dp[l], dp[n] - dp[r]);
        p.second = min(dp[r] - dp[l], dp[n] - dp[r]);
        later[l] = p;
    }
    for(int i = 2;i<n-1;i++){
        ll mx = max(before[i].first,later[i].first);
        ll mn = min(before[i].second,later[i].second);
        ans = min(ans,mx-mn);
    }
    cout << ans << endl;
    return 0;
}

