    auto f = [&s](lint lb, lint rb, lint p) -> lint {
        if (p < lb)  return -(s[rb] - s[lb-1]);
        if (rb <= p) return +(s[rb] - s[lb-1]);
        lint x = s[p] - s[lb-1];
        lint y = s[rb] - s[p];
        return x - y;
    };


    auto negmax_search = [&s, &f](lint lb, lint rb) -> pair<lint, lint> {
        lint lpos = lb - 1;
        lint rpos = rb;
        assert (f(lb, rb, lpos) < 0 and f(lb, rb, rpos) > 0);
        lint mpos = (lpos + rpos) / 2;
        rep (100) {
            if (f(lb, rb, mpos) < 0) lpos = mpos;
            else rpos = mpos;
            mpos = (lpos + rpos) / 2;
            //dump(lpos); dump(mpos); dump(rpos); el;
        }
        lint x = s[mpos] - s[lb-1];
        lint y = s[rb] - s[mpos];
        assert (f(lb, rb, mpos) == x - y);
        if (x == 0) {
            x = s[mpos+1] -s[lb-1];
            y = s[rb] - s[mpos+1];
        }
        return make_pair(x, y);
    };

    auto posmin_search = [&s, &f, &negmax_search](lint lb, lint rb) -> pair<lint, lint> {
        lint lpos = lb - 1;
        lint rpos = rb;
        assert (f(lb, rb, lpos) < 0 and f(lb, rb, rpos) > 0);
