        }
        lint x = s[mpos+1] - s[lb-1];
        lint y = s[rb] - s[mpos+1];
        assert (f(lb, rb, mpos+1) == x - y);
        if (y == 0) {
            x = s[mpos] - s[lb-1];
            y = s[rb] - s[mpos];
        }
        return make_pair(x, y);
    };

    lint ans = 1e18;
    //1
    repeat_from_to (p, 2, n-2) {
        {
            vector<lint> x(4);
            tie(x[0], x[1]) = negmax_search(1, p);
            tie(x[2], x[3]) = negmax_search(p+1, n);
            //vdump(x);
            sort(x.begin(), x.end());
            ans = min(ans, x[3] - x[0]);
        }
    }
    //2
    repeat_from_to (p, 2, n-2) {
        {
            vector<lint> x(4);
            tie(x[0], x[1]) = posmin_search(1, p);
            tie(x[2], x[3]) = negmax_search(p+1, n);
            //vdump(x);
            sort(x.begin(), x.end());
            ans = min(ans, x[3] - x[0]);
        }
    }
    //3
    repeat_from_to (p, 2, n-2) {
        {
            vector<lint> x(4);
            tie(x[0], x[1]) = negmax_search(1, p);
            tie(x[2], x[3]) = posmin_search(p+1, n);
            //vdump(x);
            sort(x.begin(), x.end());
            ans = min(ans, x[3] - x[0]);
        }
    }
    //4
    repeat_from_to (p, 2, n-2) {
        {
            vector<lint> x(4);
