int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n; cin >> n;
  vector<int64> a(n); cin >> a;

  CumulativeSum<int64> cs(a);

  int64 ans = inf;

  for (int i = 0; i < n - 3; ++i) {
    int64 s1 = cs.get(0, i + 1);
    int64 s2 = cs.get(i + 2, n - 1);

    int p1 = cs.upper_bound(s1 / 2);
    int p2 = cs.upper_bound(s1 + s2 / 2);

    int64 t1 = cs.get(0, p1 - 1), t2 = cs.get(p1, i + 1);
    int64 t3 = cs.get(0, p1), t4 = cs.get(p1 + 1, i + 1);
    int64 ans1, ans2, ans3, ans4;
    if (abs(t1 - t2) < abs(t3 - t4)) {
      ans1 = t1, ans2 = t2;
    } else {
      ans1 = t3, ans2 = t4;
    }
    t1 = cs.get(i + 2, p2 - 1), t2 = cs.get(p2, n - 1);
    t3 = cs.get(i + 2, p2), t4 = cs.get(p2 + 1, n - 1);
    if (abs(t1 - t2) < abs(t3 - t4)) {
      ans3 = t1, ans4 = t2;
    } else {
      ans3 = t3, ans4 = t4;
    }
    ans = min(ans, max({ans1, ans2, ans3, ans4}) - min({ans1, ans2, ans3, ans4}));
  }

  cout << ans << endl;

  return 0;
}

