void solve(){
  ini(N);
  vl a(N); in(a);

  vl rui(N + 1 , 0);
  rep(i , N) rui[i + 1] = rui[i] + a[i];

  auto q = [&](int l,int r)->ll{return rui[r] - rui[l];};

  //　ある区間を二等分すると？
  auto f = [&](int l,int r) -> P{
    ll s = q(l , r);
    auto it = upper_bound(begin(rui) + l , begin(rui) + r , s / 2 + rui[l]);
    if(it == begin(rui) + l) return P(s - *it + rui[l] , *it - rui[l]);
    if(it == begin(rui) + r) return P(s - *(it - 1) + rui[l], *(it - 1) - rui[l]);
    P a = P(s - *it + rui[l], *it - rui[l]) , b = P(s - *(it - 1) + rui[l], *(it - 1) - rui[l]);
    return abs(a.fi - a.se) < abs(b.fi - b.se) ? a : b;
  };

  // 答えを返す関数
  auto g = [&](P a,P b){
    vl v ({a.fi , a.se , b.fi , b.se});
    sort(all(v));
    return v.back() - *begin(v);
  };

  ll ans = infLL;
  // 分断位置は[0, i) [i , N)とする
  rep1(i , N - 1){
    auto l = f(0 , i) , r = f(i , N);
    amin(ans , g(l , r) );
    trc( i , l , r , g(l , r));
  }

  out(ans);

}

