struct AccSum{
    vector<ll> Ac;
    ll L;
    AccSum(vector<ll> &A){
        L = A.size();
        Ac.resize(L+1);
        FOR(i, 0, L){
            Ac[i+1] = Ac[i] + A[i];
        }
    }
    // sum of [a, b]
    ll sum(ll a, ll b){
        if(a<0) return -1;
        if(b>L-1) return -1;
        return Ac[b+1] - Ac[a];
    }
};

ll f(ll a, ll b, ll c, ll d){
  VI V;
  V.push_back(a);
  V.push_back(b);
  V.push_back(c);
  V.push_back(d);
  SORT(V);
  return V[3] - V[0];
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N; 
    cin >> N;

    VI A(N);
    rep(i, N){
        cin >> A.at(i);
    }

    AccSum Acc(A);

    ll a = A[0];
    ll b = A[1];
    ll left_cut = 0;
    ll right_cut = 2;
    {
      ll min_diff = abs(A[2] - Acc.sum(3, N-1));
      FOR(i, 3, N-1){
        ll left = Acc.sum(2, i);
        ll right = Acc.sum(i+1, N-1);
        ll diff = abs(left-right);
        if(diff<min_diff){
          right_cut = i;
          min_diff = diff;
        }
      }
    }
    debug(right_cut);
    ll c = Acc.sum(2, right_cut);
    ll d = Acc.sum(right_cut+1, N-1);
    ll mi = f(a, b, c, d);
    debug(a,b,c,d);
    debug(mi);

    // 中央カット位置
    FOR(cut, 2, N-2){
      while(1){
        // 今の左右の差
        ll a = Acc.sum(0, left_cut);
        ll b = Acc.sum(left_cut+1, cut);

        // 一歩進めた左右の差
        ll a2 = Acc.sum(0, left_cut+1);
        ll b2 = Acc.sum(left_cut+2, cut);

        if(abs(a-b) >= abs(a2-b2)){
          left_cut++;
        }else{
          break;
        }
      }

      while(1){
        ll c = Acc.sum(cut+1, right_cut);
        ll d = Acc.sum(right_cut+1, N-1);

        ll c2 = Acc.sum(cut+1, right_cut+1);
        ll d2 = Acc.sum(right_cut+2, N-1);

        if(abs(c-d) >= abs(c2-d2)){
          right_cut++;
        }else{
          break;
        }
      }


      debug(cut, left_cut, right_cut);

      ll a = Acc.sum(0, left_cut);
      ll b = Acc.sum(left_cut+1, cut);
      ll c = Acc.sum(cut+1, right_cut);
      ll d = Acc.sum(right_cut+1, N-1);
      chmin(mi, f(a,b,c,d));
    }
    p(mi);

    return 0;
}

