  long long result = pow(10,15);

  for(int i=1;i<N-2;i++){ //中央の区切り
    Q[1] = i;

    long long tmp_left = abs( ( S[Q[1]] - S[Q[0]] ) - S[Q[0]] );
    for(int j=Q[0] + 1; j<i; j++){ //左の区間の区切り
      long long tmp = abs( ( S[Q[1]] - S[j] ) - S[j] );
      if(tmp < tmp_left){
        tmp_left = tmp;
        Q[0] = j;
      }else{ // 左の区間の差が開いたらやめる
        break;
      }
    }

    //cout << Q[0] << " " << Q[1] << " " << Q[2] << " " << Q[3] <<endl;

    long long tmp_right = abs( ( S[N-1] - S[Q[2]] ) - (S[Q[2]] - S[Q[1]]) );
    for(int j=Q[2] + 1; j < N-1; j++){ //右の区間の区切り
      long long tmp = abs( ( S[N-1] - S[j] ) - (S[j] - S[Q[1]]) );
      if(tmp < tmp_right){
        tmp_right = tmp;
        Q[2] = j;
      }else{ // 左の区間の差が開いたらやめる
