    P[3] = S[Q[3]] - S[Q[2]];
    long long R[6] = {};
    int count = 0;
    for(int i=0;i<4;i++){
      for(int j=i+1;j<4;j++){
        R[count] = abs(P[i] - P[j]);
        count++;
      }
    }

    long long tmp_result = max(R[0],max(R[1],max(R[2],max(R[3],max(R[4],R[5])))));
    if(tmp_result < result) result = tmp_result;

    //cout << Q[0] << " " << Q[1] << " " << Q[2] << " " << Q[3] <<endl;
  }

  cout << result << endl;
  return 0;
}

