int n;
vll arr;

int bsearch(int lo, int hi, ll target) {
    int res = hi;
    ll sub = (lo) ? arr[lo - 1] : 0;
    while(lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (arr[mid] - sub >= target && (hi - mid) >= 1) {
            res = min(res, mid);
            hi = mid - 1;
        } else lo = mid + 1;
    }
    return res;
}

ll max4(ll a, ll b, ll c, ll d) {
    return max(max(a,b), max(c, d));
}

ll min4(ll a, ll b, ll c, ll d) {
    return min(min(a,b), min(c, d));
}

int main(){
    std::ios::sync_with_stdio(false);cin.tie(NULL); cout.tie(NULL);
