    // freopen("output.txt", "w", stdout);

    cin>>n; arr.resize(n);
    FOR(i, 0, n) {
        cin>>arr[i];
        arr[i] += (i) ? arr[i - 1] : 0;
    }

    ll res = 1E18 + 1;

    // [1, n - 3]
    FOR(mid, 1, n - 2) {
        ll lsum = arr[mid];
        ll rsum = arr[n - 1] - arr[mid];

        int lgidx = bsearch(0, mid, lsum / 2);
        int rgidx = bsearch(mid + 1, n - 1, rsum / 2);

        // cerr << mid << " " << lgidx << " " << rgidx << " " << lsum << " " << rsum << endl;

        if (lgidx < mid) {
            ll asum = arr[lgidx];
            ll bsum = lsum - asum;

            if (rgidx < n - 1) {
                ll csum = arr[rgidx] - arr[mid];
                ll dsum = rsum - csum;

                res = min(res, max4(asum, bsum, csum, dsum) - min4(asum, bsum, csum, dsum));
            } 

            if(rgidx - 1 >= mid + 1) {
                ll csum = arr[rgidx - 1] - arr[mid];
                ll dsum = rsum - csum;

                res = min(res, max4(asum, bsum, csum, dsum) - min4(asum, bsum, csum, dsum));
            }
        }

        int lsidx = lgidx - 1;
        if (lsidx >= 0) {
            ll asum = arr[lsidx];
            ll bsum = lsum - asum;

            if (rgidx < n - 1) {
                ll csum = arr[rgidx] - arr[mid];
                ll dsum = rsum - csum;

                res = min(res, max4(asum, bsum, csum, dsum) - min4(asum, bsum, csum, dsum));
            } 

            if(rgidx - 1 >= mid + 1) {
