long long d(int l, int r, const vector<long long>& v)
{
	return v[r] - v[l];
}

long long dLR(int l, int mid, int r, const vector<long long>& v)
{
	return abs(d(mid, r, v) - d(l, mid, v));
}

int main(void)
{
	int N;
	cin >> N;

	vector<long long> A(N+1);
	for(int i=0; i<N; i++)
		cin >> A[i+1];

	for(int i=0; i<N; i++)
		A[i+1] += A[i];

	long long ret = LLONG_MAX;
	int left, right;
	left = 0;
	right = 1;
	vector<long long> v(4, 0);
	for(int i=1; i<N; i++){
		while(left < i && dLR(0, left+1, i, A) <= dLR(0, left, i, A))
			left++;

		while(right < N && dLR(i, right+1, N, A) <= dLR(i, right, N, A))
			right++;

		v[0] = d(0, left, A);
		v[1] = d(left, i, A);
		v[2] = d(i, right, A);
		v[3] = d(right, N, A);

		long long diff = *max_element(v.begin(), v.end()) - *min_element(v.begin(), v.end());
		ret = min(ret, diff);
	}

	cout << ret << endl;

	return 0;
}

