    DPQ = 200000000000000;
    DRS = 200000000000000;
    for(j=jm;j<i;j++){
      P = F.at(j) - F.at(0);
      Q = F.at(i) - F.at(j);
      if(abs(P-Q)<DPQ){
        DPQ = abs(P-Q);
        jm = j;
        Pm = P;
        Qm = Q;
