    int n; cin >> n;
    vector<ll> a(n + 1);
    ll cumSum[n + 1];
    cumSum[0] = 0;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        cumSum[i] = cumSum[i - 1] + a[i];
    }
    ll ans = 1LL<<60;
    for (int i = 2; i <= n - 2; i++) {
        ll lsum = cumSum[i];
        ll rsum = cumSum[n] - lsum;

        int lb = lower_bound(cumSum, cumSum + i, lsum / 2) - cumSum;
        ll p;
        if (lb == 0 || abs(lsum - 2 * cumSum[lb]) < abs(lsum - 2 * cumSum[lb - 1])) p = cumSum[lb];
        else p = cumSum[lb - 1];
        ll q = lsum - p;

        int rb = lower_bound(cumSum + i, cumSum + n, lsum + rsum / 2) - cumSum;
        ll r;
        if (rb == i || abs(rsum - 2 * (cumSum[rb] - cumSum[i])) < abs(rsum - 2 * (cumSum[rb - 1] - cumSum[i]))) r = cumSum[rb] - cumSum[i];
        else r = cumSum[rb - 1] - cumSum[i];
        ll s = rsum - r;

        ll mx = p;
        ll mn = p;
        for (auto& x : { q, r, s }) {
            mx = max(mx, x);
            mn = min(mn, x);
        }
        ans = min(ans, mx - mn);
    }
    cout << ans << endl;
    return 0;
}

