using namespace std;
typedef long long ll;

int sum(vector<int> v) {
	int temp = 0;
	REP(i, v.size()) {
		temp += v[i];
	}
	return temp;
}

int main() {
	int N;
	cin >> N;
	vector<int> A(N);
	REP(i, N) cin >> A[i];
	int i, j, k;
	int res = sum(A);
	for (i = 0;i < N - 3;i++) {
		for (j = i + 1;j < N - 2;j++) {
			for (k = j + 1;k < N - 1;k++) {
				vector<int> B, C, D, E;
				REP(l,i+1) B.push_back(A[l]);
				FOR(l,i+1,j+1) C.push_back(A[l]);
				FOR(l,j+1,k+1) D.push_back(A[l]);
				FOR(l,k+1,N) E.push_back(A[l]);
				int P = sum(B);
				int Q = sum(C);
				int R = sum(D);
				int S = sum(E);
				int M = max(max(P, Q), max(R, S));
				int m = min(min(P, Q), min(R, S));
				if (res > M - m) res = M - m;
			}
		}
	}
	cout << res << endl;
	return 0;
}

