		cin >> A[i] ;
		if (i > 0) sum[i] += sum[i - 1] + A[i];
		else sum[i] += A[i];
	}
	ll res = sum[N - 1];
	For(i, 1, N - 2) {
		For(j, 0, i) {
			ll Ml = max({ sum[j],sum[i] - sum[j] });
			ll ml = min({ sum[j],sum[i] - sum[j] });
			For(k, i + 1, N - 1) {
				ll Mr = max({ sum[k] - sum[i],sum[N - 1] - sum[k] });
				ll mr = min({ sum[k] - sum[i],sum[N - 1] - sum[k] });
				ll dis = max(Ml, Mr) - min(ml, mr);
				if (res > dis) res = dis;
			}
		}
	}
	cout << res << endl;
