ll calc(ll a, ll b, ll c, ll d){
  ll mi=a;
  ll ma=a;
  mi = min(mi, b);
  mi = min(mi, c);
  mi = min(mi, d);
  ma = max(ma, b);
  ma = max(ma, c);
  ma = max(ma, d);

  return ma-mi;
}

