        l = f(0, i, l);
        if (r < i + 1) r = i + 1;
        r = f(i + 1, N - 1, r);
        ll P = A[l];
        ll Q = A[i] - P;
        ll R = A[r] - A[i];
        ll S = A[N - 1] - A[r];
        ll mx = max(max(max(P, Q), R), S);
        ll mn = min(min(min(P, Q), R), S);
        if (mx - mn < sm)
        {
            sm = mx - mn;
        }
    }

    cout << sm << endl;
    return 0;
}

