using lli = long long;

int div(int l, int r, const std::vector<lli>& Ac_arr){
  int b=l, e=r;
  while(e-b > 1){
    int med=(b+e)/2;
    lli diff = Ac_arr[r]-Ac_arr[med]-Ac_arr[med]+Ac_arr[l];
    if(diff >= 0){
      b = med;
    }else{
      e = med;
    }
  }
  return b;
}

int main(){
  int N;
  std::cin >> N;

  std::vector<int> A_arr(N);
  std::vector<lli> Ac_arr(N+1);
  lli tmp = 0;
  for(int i = 0; i < N; i++){
    std::cin >> A_arr[i];
    tmp += A_arr[i];
    Ac_arr[i+1] = tmp;
  }

  lli ans = std::numeric_limits<lli>::max();
  for(int i = 2; i < N-1; i++){
    int ldiv = div(0, i, Ac_arr);
    int rdiv = div(i, N, Ac_arr);
    for(int ld = ldiv; ld < ldiv+2; ld++){
      for(int rd = rdiv; rd < rdiv+2; rd++){
        std::vector<lli> ABCD = {Ac_arr[ld], Ac_arr[i]-Ac_arr[ld], Ac_arr[rd]-Ac_arr[i], Ac_arr[N]-Ac_arr[rd]};
        std::sort(ABCD.begin(), ABCD.end());
        ans = std::min(ans, ABCD[3]-ABCD[0]);
      }
    }
  }

  std::cout << ans << std::endl;

  return 0;
}

