int main()
{
    int n;
    cin >> n;
    int a[n] = {};
    long long sum[n] = {};
    for(int i=0; i<n; i++){
        cin >> a[i];
        if(i==0){ 
            sum[i] = a[i];
        }else{
            sum[i] = sum[i-1] + a[i];
        }
    }

    int i = 0;
    int j = 0;
    int k = 0;
    int left = 0;
    int right = n-1;
    long long ans = 1e15;
    for(j = 1; j<n-1; j++){
        int l = 0;
        int r = j;
        long long P = sum[i];
        long long Q = sum[j] - sum[i];
        long long R = sum[k] - sum[j];
        long long S = sum[n-1] - sum[k];
        long long dis = 1e15;
        while(l <= r){
            i = (l+r)/2;
            long long w = sum[i];
            long long e = sum[j] - sum[i];
            if(dis > abs(w-e)){
                P = w;
                Q = e;
                dis = abs(w-e);
            }
            if(w == e){
                break;
            }else if(w < e){
                l = i+1;
            }else{
                r = i-1;
            }
        }
        l = j+1;
        r = n-2;
        dis = 1e15;
        while(l <= r){
            k = (l+r)/2;
            long long w = sum[k] - sum[j];
            long long e = sum[n-1] - sum[k];
            if(dis > abs(w-e)){
                R = w; 
                S = e;
                dis = abs(w-e);
            }
            if(w == e){ 
                break;
            }else if(w < e){
                l = k+1;
            }else{
                r = k-1;
            }
        }
        long long cur = max({P,Q,R,S}) - min({P,Q,R,S});
        ans = min(ans, cur);
        if(sum[j] < sum[n-1] - sum[j]){
            left = j+1;
        }else{
            right = j-1; 
        }
    }
    cout << ans << endl;
    return 0;
}

