    //しきりiはA[i-1]とA[i]との間にある
    ll left = 0LL; ll right = i;
    while( right - left > 1){
      ll mid = left + (right-left)/2;
      if(sum[mid] >= sum[i] - sum[mid]){ //左側が大き過ぎた
        right = sum[mid];}
      else{ left = sum[mid];}
    }
      ll P,Q;
      ll P1 = min(sum[left],sum[i]-sum[left]); 
      ll Q1 = max(sum[left],sum[i]-sum[left]);
      ll P2 = min(sum[right],sum[i]-sum[right]);
      ll Q2 = max(sum[right],sum[i]-sum[right]);

      if( P1-Q1 <= P2-Q2){ P = P1; Q = Q1;}
      else{ P = P2; Q = Q2;}

      left = i; right = N;

      while(right - left > 1){
        ll mid = left + (right-left)/2;
        if( sum[mid] - sum[i] >= sum[N]-sum[mid]){ right = mid;}
        else{ left = mid;}
