    ll sum1 = S[m] - S[l];
    ll sum2 = S[r] - S[m];
    ll sum3 = S[N-1] - S[r];
    ll sum = abs(sum0-sum1) + abs(sum0-sum2) + abs(sum0-sum3)
                + abs(sum1-sum2) + abs(sum1-sum3) + abs(sum2-sum3);
    return sum;
}

