int n, arr[2 * maxx];
long long pref[2 * maxx];

long long res = INFLL;
void rec(int p, int pos, vector<long long> v) {
    //cout << p << " " << pos << endl;
    if (p == 4) {
        v.pb(pref[n] - v[0] - v[1] - v[2]);
        sort(all(v));
        res = min(res, v[3] - v[0]);
        return;
    }
    long long sum = 0, ok = 0;
    for (int i = pos; i <= n - 4 + p; i++) {
        sum += arr[i];
        if (sum * (5 - p) >= pref[n] - pref[pos - 1]) {
            if (i > pos + 1) {
                v.pb(sum - arr[i] - arr[i - 1]);
                rec(p + 1, i - 1, v);
                v.pop_back();
            }
            if (i != pos) {
                v.pb(sum - arr[i]);
                rec(p + 1, i, v);
                v.pop_back();
            }
            v.pb(sum);
            rec(p + 1, i + 1, v); v.pop_back();
            if (n - i - 1 >= 4 - p) {
                v.pb(sum + arr[i + 1]);
                rec(p + 1, i + 2, v);
                v.pop_back();
            }
            if (n - i - 2 >= 4 - p) {
                v.pb(sum + arr[i + 1] + arr[i + 2]);
                rec(p + 1, i + 3, v);
                v.pop_back();
            }
            ok = 1;
            break;
        }
    }
    if (ok == 0) {
        v.pb(sum);
        rec(p + 1, n - 3 + p, v);
        v.pop_back();
    }
}

