int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N; cin >> N;
  vector<ll> cs(N+1);
  for (int i = 1; i <= N; i++) {
    cin >> cs[i];
    cs[i] += cs[i-1];
  }

  auto f = [&](int x, int y, int z) {
    return abs((cs[y] - cs[x]) - (cs[z] - cs[y]));
  };

  int bc = 1, cd = 2, de = 3;
  while (de < N) {
    if (f(cd, de, N) < f(cd, de+1, N)) break;
    de++;
  }

  auto g = [&]() {
    initializer_list<ll> l = {cs[bc]-cs[0], cs[cd]-cs[bc],
                              cs[de]-cs[cd], cs[N]-cs[de]};
    return max(l) - min(l);
  };

  ll ans = g();
  for (cd = 3; cd < N; cd++) {
    while (bc < cd) {
      if (f(0, bc, cd) < f(0, bc+1, cd)) break;
      bc++;
    }
    while (de < N) {
      if (f(cd, de, N) < f(cd, de+1, N)) break;
      de++;
    }
    ans = min(ans, g());
  }
  cout << ans << "\n";
}

