}

int main() {
    int n;
    cin >> n;
    vector<int64_t> A(n);
    vector<int64_t> acc(n+1);
    for (int i = 0; i < n; i++) {
        cin >> A[i];
        if (i == 0) {
            acc[0] = 0;
        } else {
            acc[i] = acc[i - 1] + A[i - 1];
        }
    }
    acc[n] = acc[n-1] + A[n-1];
    int l = 0;
    int r = 0;
    int64_t ans = INT64_MAX;
    for (int m = 0; m < n; m++) {
        int64_t l_sum = calc(acc, 0, m);
        int64_t r_sum = calc(acc, m, n);
        while (l+1 < m && abs(calc(acc, 0, l+1) - calc(acc, l+1, m)) < abs(calc(acc, 0, l) - calc(acc, l, m))) {
            l++;
        }
        while (r < n && abs(calc(acc, m, r+1) - calc(acc, r+1, n)) < abs(calc(acc, m, r) - calc(acc, r, n))) {
            r++;
        }
        int64_t tmp = max({calc(acc, 0, l), calc(acc, l, m), calc(acc, m, r),
                           calc(acc, r, n)}) -
                      min({calc(acc, 0, l), calc(acc, l, m), calc(acc, m, r),
                           calc(acc, r, n)});
        ans = min(ans, tmp);
    }
    cout << ans << endl;
}

