    int N;cin >> N;
    vector<long long> retu(N);
    for(int i = 0;i<N;i++) cin >> retu.at(i);
    vector<long long> rui(N+1);
    for(int i = 0;i<N;i++){
        rui.at(i+1) = rui.at(i)+retu.at(i);
    }
    //中央切りを全探索
    long long ans = INF;
    for(int i = 0;i<=N;i++){
        //左側
        long long PQ = rui.at(i);
        int left = 0,right = i;
        while(right - left > 1){
            int mid = left+(right-left)/2;
            if(rui.at(mid) < rui.at(i)-rui.at(mid)){
                left = mid;
            }
            else{
                right = mid;
            }
        }
        long long P = rui.at(left);long long Q = PQ-P;
        //一応left,rightの両方見ておく
        long long P2 = rui.at(right);long long Q2 = PQ-P2;
        long long LEFT_MAX = 0,LEFT_MIN = INF;
        if(abs(P-Q) > abs(P2-Q2)){
            LEFT_MAX = max(P2,Q2);
            LEFT_MIN = min(P2,Q2);
        }
        else{
            LEFT_MAX = max(P,Q);
            LEFT_MIN = min(P,Q);
        }
        //右側
        long long RS = rui.at(N)-PQ;
        left = i,right = N;
        while(right - left > 1){
            int mid = left+(right-left)/2;
            if(rui.at(mid)-rui.at(i) < rui.at(N)-rui.at(left)){
                left = mid;
            }
            else{
                right = mid;
            }
