            RIGHT_MIN = min(R2,S2);
        }
        else{
            RIGHT_MAX = max(R,S);
            RIGHT_MIN = min(R,S);
        }
        ans = min(ans,max(LEFT_MAX,RIGHT_MAX) - min(LEFT_MIN,RIGHT_MIN));
    }
    cout << ans << endl;
}

