    B = sum[idx1];
    C = sum[i] - sum[idx1];
    D = sum[idx2] - sum[i];
    E = sum[N-1] - sum[idx2];
    ans = min(ans,calc(B,C,D,E));

    B = sum[max(0,idx1-1)];
    C = sum[i] - sum[max(0,idx1-1)];
    D = sum[idx2] - sum[i];
    E = sum[N-1] - sum[idx2];
    ans = min(ans,calc(B,C,D,E));

    B = sum[max(0,idx1-1)];
    C = sum[i] - sum[max(0,idx1-1)];
    D = sum[idx2-1] - sum[i];
    E = sum[N-1] - sum[idx2-1];
    ans = min(ans,calc(B,C,D,E));

    B = sum[idx1];
    C = sum[i] - sum[idx1];
    D = sum[idx2-1] - sum[i];
    E = sum[N-1] - sum[idx2-1];
    ans = min(ans,calc(B,C,D,E));
  }
  cout << ans << endl;
}

