using namespace std;

const int INF = (int)1e9;

int solve(const int low, const std::vector<int>& ls)
{
    const int n = ls.size();
    std::vector<int> dp(n + 1);
    dp[0] = low;

    for(int position = 0; position < n; position++) {

        int piece_length = 0;
        int& value = dp[position + 1];

        value = INF;

        for(int piece_left = position; piece_left >= 0; piece_left--) {

            piece_length += ls[piece_left];

            if(position == n - 1 && piece_left == 0) {
                continue;
            }

            if(piece_length >= low) {
                const int high = std::max(piece_length, dp[piece_left]);
                value = std::min(value, high);
            }
        }
    }

    return dp[n] - low;
}

int main()
{
    int n;
    std::vector<int> ls;

    std::cin >> n;
    ls.resize(n);
    for(int i = 0; i < n; i++) {
        std::cin >> ls[i];
    }

    int answer = INF;

    for(int left = 0; left < n; left++) {
        int total_length = 0;
        for(int right = left; right < n; right++) {
            total_length += ls[right];
            int temp = solve(total_length, ls);
            answer = std::min(answer, temp);
        }
    }

    std::cout << answer << std::endl;

    return 0;
}

