pair<ll, ll> bin_search(vector<ll> &acc, int begin, int end) {

  ll sum = acc[end] - acc[begin];
  int i = begin+1;
  int j = end-1;
  int k;

  while(1){
    k = (i + j)/2;
    if( j - i < 2 || acc[k] - acc[begin] == sum/2)
      break;
    if(acc[k] - acc[begin] >= sum/2)
      j = k;
    else
      i = k;
  } 
  ll tmp1 = acc[k] - acc[begin]; 
  ll tmp2 = acc[k+1] - acc[begin]; 
  if(abs((sum-tmp1) - tmp1) > abs((sum-tmp2) - tmp2) )
    return make_pair(sum-tmp2,tmp2);
  else
    return make_pair(sum-tmp1,tmp1);
}

int main(int argc, char const *argv[]) {

  int n;
  ll tmp, ret;
  cin >> n;
  vector<ll> acc(n+1, 0);
  acc[0] = 0;
  for (int i = 1; i <= n; i++) {
    cin >> acc[i];
    if (i > 0)
      acc[i] += acc[i - 1];
  }
  // (0,i], (i,n]
  ret = acc[n - 1];
  for (int i = 2; i < n - 1; i++) {
    auto p1 = bin_search(acc, 0, i);
    auto p2 = bin_search(acc, i, n);
    tmp = 0;
    tmp = max(tmp, abs(p1.first - p1.second));
    tmp = max(tmp, abs(p2.first - p2.second));
    tmp = max(tmp, abs(p1.first - p2.second));
    tmp = max(tmp, abs(p2.first - p1.second));
    tmp = max(tmp, abs(p1.first - p2.first));
    tmp = max(tmp, abs(p1.second - p2.second));
    ret = min(ret, tmp);
  }
  cout << ret << endl;

  return 0;
}

