#include <bits/stdc++.h>
#define MOD 1000000007
typedef long long ll;
using namespace std;

int main()
{
  int n;
  cin >> n;
  // long long 型は64ビット以上の値を表現できる
  ll a[n+1] = {};
  ll p[n+1] = {};
  p[0] = 0;
  for(int i=1;i<=n;++i)
  {
    cin >> a[i];
    // 累積和を求める
    p[i] = p[i-1] + a[i];
  }
  ll ans = 1e16; // 1*10^16
  ll dif[4];
  int l=1,r=3;
  for(int i=2;i<=n-2;i++)
  {
    // iを仕切りに左右に分けて考えている
    // 各領域の和を累積和から計算し, その和の差がより少ないものが見つかったら領域の区切りを1つずつずらしていくという方式
    // l<i : 左の区切りlは真ん中の区切りiよりも左にいなければならない
    while( l<i && abs(p[l]-(p[i]-p[l])) >= abs(p[l+1]-(p[i]-p[l+1])) )
    l++;

    // r<n : 右の区切りは当然nよりも左
    while( r<n && abs(p[r]-p[i]-(p[n]-p[r])) >= abs(p[r+1]-p[i]-(p[n]-p[r+1])) )
    r++;

    // 4つの区間の値を計算する
    dif[0]=p[l];dif[1]=p[i]-p[l];dif[2]=p[r]-p[i];dif[3]=p[n]-p[r];

    // 配列を昇順に並べ替える
    sort(dif,dif+4);

    // 一番小さいものを出力
    ans=min(ans,dif[3]-dif[0]);
  }
  cout << ans << endl;
  return 0;
}

