    int abs;

    for (int p = 0; p < N-1; ++p){
        sumP = cum[p];
        for (int q = p+1; q < N-1; ++q){
            sumQ = cum[q] - sumP;
            for (int r = q+1; r < N-1; ++r){
                sumR = cum[r] - cum[q];
                sumS = cum[N-1] - cum[r];
                abs = max(max(sumP, sumQ), max(sumR, sumS)) - min(min(sumP, sumQ), min(sumR, sumS));
                min_abs = min(min_abs, abs);
            }
        }
    }


    cout<< min_abs <<endl;


    delete cum;
    return 0;
}

