        return (a[R] - a[L - 1]);
    };

    // X[L, point],Y(point, R]
    auto BinSerch = [&](int L, int R){
        int l = L, r = R; 
        while(r - l > 1){
            int mid = (r + l) / 2;
            if(sum(L, mid) <= sum(mid + 1, R)){
                l = mid; 
            }else{
                r = mid;
            }
        }
        return (l);
    };

    int res = LINF;

