        int rp = BinSerch(mid + 1, n);
        rep(i,2){
            rep(j,2){
                if(lp + i == mid || rp + j == n) continue;
                int B = sum(1, lp + i);
                int C = sum(lp + i + 1, mid);
                int D = sum(mid + 1, rp + j);
                int E = sum(rp + j + 1, n);
                chmin(res, max({B, C, D, E}) - min({B, C, D, E}));
            }
        }
    }

