int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0); cout.setf(ios::fixed); cout.precision(20);
    int n; cin >> n;
    vector<int> a(n);
    vector<ll> pref(n);
    for (int &x : a) {
        cin >> x;
    }
    pref[0] = a[0];
    for (int i = 1; i < n; i++) {
        pref[i] = a[i] + pref[i - 1];
    }
    ll tot = pref[n - 1];
    ll res = LONG_LONG_MAX;
    for (int i = 0; i < n; i++) {
        ll x = pref[i];
        int next = upper_bound(pref.begin(), pref.end(), 2 * x) - pref.begin();
        for (int j : {next - 2, next - 1, next, next + 1, next + 2}) {
            if (j <= i || n - j < 3) {
                continue;
            }
            ll y = pref[j] - x;
            int next2 = upper_bound(pref.begin(), pref.end(), 2 * y) - pref.begin();
            for (int k : {next2 - 2, next2 - 1, next2, next2 + 1, next2 + 2}) {
                if (k <= j || k >= n - 1) {
                    continue;
                }
                ll z = pref[k] - pref[j];
                ll left = tot - x - y - z;
                assert(left > 0);
                ll mx = max({x, y, z, left});
                ll mn = min({x, y, z, left});
                res = min(res, abs(mx - mn));
            }
        }
    }
    cout << res << "\n";
}

