    unsigned N;
    cin >> N;
    vector<unsigned> A;
    vector<unsigned> C;
    unsigned s = 0;
    for (unsigned i = 0; i < N; ++i) {
        unsigned a;
        cin >> a;
        A.push_back(a);
        s += a;
        C.push_back(s);
    }
    unsigned ans = 999999999;
    for (unsigned i = 1; i < N - 2; ++i) {
        unsigned P, Q, R, S;

        unsigned Ls = 0;
        unsigned Lm = 999999999;
        for (unsigned j = 0; j < i; ++j) {
            P = C[j];
            Q = C[i] - C[j];
            unsigned d = P > Q ? P - Q : Q - P;
            if (d < Lm) {
                Ls = j;
                Lm = d;
            }
        }
        P = C[Ls];
        Q = C[i] - C[Ls];
        unsigned Rs = i + 1;
        unsigned Rm = 999999999;
        for (unsigned k = i + 1; k < N - 1; ++k) {
            R = C[k] - C[i];
            S = C[N - 1] - C[k];
            unsigned d = R > S ? R - S : S - R;
            if (d < Rm) {
                Rs = k;
                Rm = d;
            }
        }
        R = C[Rs] - C[i];
        S = C[N - 1] - C[Rs];

        unsigned d = max(max(max(P, Q), R), S) - min(min(min(P, Q), R), S);
        if (ans > d) {
            ans = d;
        }
    }
    cout << ans << endl;
}

