    long long int res = 1000000000;
    for(int i = 0;i < n;i++) {
        long long int ct[4];
        for(int i = 0;i < 4;i++ ) {
            ct[i] = imos(cut[i],cut[i+1]);
        }
        long long int maxn = max(max(ct[0],ct[1]),max(ct[2],ct[3]));
        long long int minn = min(min(ct[0],ct[1]),min(ct[2],ct[3]));
        int mini = -1;
        int maxi = -1;
        res = min(res,maxn-minn);
        for(int i = 0;i < 4;i++) {
            if(ct[i] == maxn)
                maxi = i;
            if(ct[i] == minn)
                mini = i;
        }
        if(maxi > mini && cut[maxi+1] - 1 != cut[maxi]) {
            for(int i = mini+1;i <= maxi;i++)
                cut[i]++;
        }
        if(mini > maxi && cut[maxi+1] - 1 != cut[maxi])
        {
            for(int i = maxi+1;i <= mini;i++)
                cut[i]--;
        }
    }
    cout << res << endl;
    return 0;
}

