    vector<ll> pq(N-3); pq[0] = 1;
    ll l = 1, B = A[0], C = A[1];
    FOR(i,3,N-1){
        C += A[i-1];
        while(l < i-1 && abs(S[l+1]-(S[i]-S[l+1])) < abs(B-C)){
            l++;
            B = S[l];
            C = S[i]-S[l];
        }
        pq[i-2] = l;
    }

    vector<ll> rs(N-3); rs[N-4] = N-1;
    ll r = N-1, D = A[N-2], E = A[N-1];
    RFOR(i,N-2,2){
        D += A[i];
        while(i < r-1 && abs((S[r-1]-S[i])-(S[N]-S[r-1])) < abs(D-E)){
            r--;
            D = S[r]-S[i];
            E = S[N]-S[r];
        }
        rs[i-2] = r;
    }

    ll ans = LL_INF;
    REP(i,N-3){
        B = S[pq[i]];
        C = S[i+2]-S[pq[i]];
        D = S[rs[i]]-S[i+2];
        E = S[N]-S[rs[i]];
        chmin(ans, abs(max(max(B,C),max(D,E)) - min(min(B,C),min(D,E))));
    }

    cout << ans << endl;
    return 0;
}

