        cumSum[i] = cumSum[i - 1] + a[i];
    }
    ll ans = 1LL<<60;
    for (int i = 2; i <= n - 2; i++) {
        ll lsum = cumSum[i];
        ll rsum = cumSum[n] - lsum;

        int lb = upper_bound(cumSum, cumSum + i, lsum / 2) - cumSum;
        ll p;
        if (lb == 0 || abs(lsum - 2 * cumSum[lb]) < abs(lsum - 2 * cumSum[lb - 1])) p = cumSum[lb];
        else p = cumSum[lb - 1];
        ll q = lsum - p;

        int rb = upper_bound(cumSum + i, cumSum + n, lsum + rsum / 2) - cumSum;
        ll r;
        if (rb == i || abs(rsum - 2 * (cumSum[rb] - cumSum[i])) < abs(rsum - 2 * (cumSum[rb - 1] - cumSum[i]))) r = cumSum[rb] - cumSum[i];
        else r = cumSum[rb - 1] - cumSum[i];
        ll s = rsum - r;

        ll mx = p;
        ll mn = p;
        for (auto& x : { q, r, s }) {
            mx = max(mx, x);
            mn = min(mn, x);
        }
        ans = min(ans, mx - mn);
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long int INF = 1e18;

int main(){
    int n;
    cin >> n;

    vector<long long int> a(n);
    for(int i=0; i<n; i++){
        cin >> a[i];
    }

    // cumulative sum
    for(int i=1; i<n; i++){
        a[i] += a[i-1];
    }

    vector<int> left(n-2), right(n-2);// left-cut, center-cut, right-cut
    // left[0] and right[0] have no meaning
    left[1] = 0;
    right[n-3] = n-2;// n >= 4

    int c = 2;
    int i = 0;
    while(true){
        if(abs((a[c] - a[i])   - a[i]) 
        <= abs((a[c] - a[i+1]) - a[i+1])
        ){
            left[c] = i;
            c += 1;
        }else{
            if(i <= c-2) i += 1;
            else{
                left[c] = i;
                c += 1;
            }
        }
        if(c == n-2) break;
    }

    c = 1;// reset
    i = 2;
    while(true){
        if(abs((a[n-1] - a[i])   - (a[i] - a[c])) 
        <= abs((a[n-1] - a[i+1]) - (a[i+1] - a[c]))
        ){
            right[c] = i;
            c += 1;
        }
        else{
            if(i <= n-3) i += 1;
            else{
                right[c] = i;
                c += 1;
            }
        }
        if(c == n-3) break;
    }

    /*
     for(int c=1; c<=n-3; c++){
         cout << a[left[c]] << " " 
              << a[c] - a[left[c]] << " "
              << a[right[c]]- a[c] << " "
              << a[n-1]- a[right[c]] << endl;
     }
     */

    long long int ans = INF;
    for(int ci=1; ci<=n-3; ci++){// center
        long long int diff
        = abs(
          max({ a[left[ci]], a[ci] - a[left[ci]], a[right[ci]]- a[ci], a[n-1]- a[right[ci]] })
        - min({ a[left[ci]], a[ci] - a[left[ci]], a[right[ci]]- a[ci], a[n-1]- a[right[ci]] })
        );
        if(diff < ans) ans = diff;
    }
    cout << ans << endl;

    return 0;
}

