    ll sa,sb,sc,sd, a,b,c,d, ans=inf;
    for(int i=2; i<n-1; ++i){
        sa=0; sb=0; sc=0; sd=0;
        auto it=lower_bound(s.begin(), s.begin()+i, *(s.begin()+i-1)/2);
        a=*it; b=*(s.begin()+i-1)-*it; c=*(it-1); d=*(s.begin()+i-1)-*(it-1);
