        a=*itt-*(s.begin()+i-1); b=s[n-1]-*itt; c=*(itt-1)-*(s.begin()+i-1); d=s[n-1]-*(itt-1);
        if(abs(a-b)<abs(c-d)){
            sc=a; sd=b;
        }
