    }
    for(int i = 2; i <= N - 2; i++) {
        int j = lower_bound(sum.begin(), sum.end(), sum[i] / 2) - sum.begin();
        int k = lower_bound(sum.begin(), sum.end(), sum[i] + (sum[N] - sum[i] / 2)) - sum.begin();
        ll P1 = sum[j], Q1 = sum[i] - sum[j];
        ll P2 = sum[j + 1], Q2 = sum[i] - sum[j + 1];
        ll R1 = sum[k] - sum[i], S1 = sum[N] - sum[k];
        ll R2 = sum[k + 1] - sum[i], S2 = sum[N] - sum[k + 1];
        ll P, Q, R, S;
