int main () {

  int N; cin >> N;

  vector<long long> s(N + 1);

  for (int i = 0; i < N; i++) {
    long long a; cin >> a;
    s[i + 1] = s[i] + a;
  }

  int l = 1, r = 3;

  long long res = 2000000000000000;

  for (int a = 2; a <= N - 2; a++) {

    long long lsum = s[a];
    long long rsum = s[N] - s[a];

    // 左の処理

    while (l < a - 1 && 2 * s[l] < lsum) l++;

    if (l > 1 && max(s[l], lsum - s[l]) - min(s[l], lsum - s[l]) > max(s[l - 1], lsum - s[l - 1]) - min(s[l - 1], lsum - s[l - 1])) l--;

    long long P = s[l], Q = lsum - s[l];

    // 右の処理

    while(r < N - 1 && 2 * (s[r] - s[a]) < rsum) r++;

    if (r > a && max(s[r] - lsum, s[N] - s[r]) - min(s[r] - lsum, s[N] - s[r]) > max(s[r - 1] - lsum, s[N] - s[r - 1]) - min(s[r - 1] - lsum, s[N] - s[r - 1])) r--;

    long long R = s[r] - lsum, S = s[N] - s[r];

    //4つの数の差を比較

    long long x = max(P, max(Q, max(R, S))) - min(P, min(Q, min(R, S)));
    if(x < res) res = x;

  }

  cout << res << endl;

}

