int main() {
    int N;
    cin >> N;
    vector<ll> A(N);
    rep(i, N) cin >> A[i];
    vector<ll> sum(N + 1);
    ll res = LINF;
    rep(i, N) { sum[i + 1] = A[i] + sum[i]; }
    for(int i = 0; i <= N; i++) {
        int lb = 0, ub = i;
        while(ub - lb > 1) {
            int mid = (ub + lb) / 2;
            if(sum[mid] > sum[i] - sum[mid]) {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        ll P1 = sum[lb];
        ll P2 = sum[ub];
        ll Q1 = sum[i] - sum[lb];
        ll Q2 = sum[i] - sum[ub];
        lb = i, ub = N;
        while(ub - lb > 1) {
            int mid = (ub + lb) / 2;
            if(sum[mid] - sum[i] > sum[N] - sum[mid]) {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        ll R1 = sum[lb] - sum[i];
        ll R2 = sum[ub] - sum[i];
        ll S1 = sum[N] - sum[lb];
        ll S2 = sum[N] - sum[ub];
        ll tmp = LINF;
        tmp = min(tmp, abs(max(P1, max(Q1, max(R1, S1))) -
                           min(P1, min(Q1, min(R1, S1)))));
        tmp = min(tmp, abs(max(P1, max(Q1, max(R2, S2))) -
                           min(P1, min(Q1, min(R2, S2)))));
        tmp = min(tmp, abs(max(P2, max(Q2, max(R1, S1))) -
                           min(P2, min(Q2, min(R1, S1)))));
        tmp = min(tmp, abs(max(P2, max(Q2, max(R2, S2))) -
                           min(P2, min(Q2, min(R2, S2)))));
        res = min(tmp, res);
    }
    cout << res << endl;
    return 0;
}

