    vector<int> F(N), G(N);
    int j = 1;
    for (int i = 2; i <= N - 2; i++) {
        while (j < i && abs(S[i - 1] - 2 * S[j - 1]) >= abs(S[i - 1] - 2 * S[j])) {
            j++;
        }
        F[i] = j;
    }
    j = N - 1;
    for (int i = N - 2; i >= 2; i--) {
        while (i < j && abs(S[N - 1] - 2 * S[j - 1] + S[i - 1]) >= abs(S[N - 1] - 2 * S[j - 2] + S[i - 1])) {
            j--;
        }
        G[i] = j;
    }
    int ans = INT_MAX;
    for (int i = 2; i <= N - 2; i++) {
        int j = F[i];
        int k = G[i];
        int S1 = S[i - 1] - S[j - 1];
        int S2 = S[j - 1];
        int S3 = S[N - 1] - S[k - 1];
        int S4 = S[k - 1] - S[i - 1];
        int diff = max(S1, max(S2, max(S3, S4))) - min(S1, min(S2, min(S3, S4)));
        ans = min(ans, diff);
    }
    cout << ans << endl;
    return 0;
}

