    std::cin >> a[0];
    s[0] = a[0];
    for (long long i = 1; i < n; i++) {
        std::cin >> a[i];
        s[i] = s[i-1] + a[i];
    }
    sum = s[n-1];

    f[0] = 0;
    g[0] = 2;
    for (long long mid = 1; mid < n - 2; mid++) {
        for (long long l = f[mid-1]; l <= mid; l++) {
            if (s[l] * 2 >= s[mid]) {
                if (std::abs(s[l-1] - (s[mid] - s[l-1])) > std::abs(s[l] - (s[mid] - s[l]))) f[mid] = l;
                else f[mid] = l - 1;
                break;
            }
        }
        if (f[mid] == -1 || f[mid] < f[mid-1]) f[mid] = f[mid-1];
        if (f[mid] == mid) f[mid]--; 

        for (long long r = g[mid-1]; r <= n; r++) {
            if ((s[r] - s[mid]) * 2 >= s[n-1] - s[mid]) {
                if (std::abs(s[r-1] - (s[n-1] - s[r-1])) > std::abs(s[r] - (s[n-1] - s[r]))) g[mid] = r;
                else g[mid] = r - 1;
                break;
            }
        }
        if (g[mid] == -1 || g[mid] < g[mid-1]) g[mid] = g[mid-1];
        if (g[mid] == n) g[mid]--;
    }

    long long ret = -1;

    for (long long mid = 1; mid < n - 2; mid++) {
        auto diff = std::max({s[f[mid]], s[mid] - s[f[mid]], s[g[mid]] - s[mid], s[n-1] - s[g[mid]]}) - std::min({s[f[mid]], s[mid] - s[f[mid]], s[g[mid]] - s[mid], s[n-1] - s[g[mid]]});
        if (diff < ret || ret == -1) {
            ret = diff;
        }
    }

    std::cout << ret << std::endl;

    return 0;
}

