template<class T>bool chmax(T& a, const T& b) { if (a < b) { a = b; return 1; } return 0; }
template<class T>bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }

using namespace std;


class D {
	int n;
	vector<int> a;
	vector<ll> cum;

public:
	D()
	{
		cin >> n;
		a.resize(n);
		cum.resize(n, 0);

		int ai;
		cin >> ai;
		a[0] = cum[0] = ai;

		REP(i, n - 1)
		{
			cin >> ai;
			a[i + 1] = ai;
			cum[i + 1] = cum[i] + ai;
		}
	}

	void solve()
	{
		ll ans{ 9223372036854775807 };
		ll tmp[4];

		// for all middle partitions
		for (int second{ 1 }; second <= n - 3; second++)
		{
			ll mindiff{ 9223372036854775807 };

			// for both left and right sections
			// find best partition for the section
			for (int first{ 0 }; first < second; first++)
			{
				ll left{ cum[first] };
				ll right{ cum[second] - cum[first] };

				if (chmin(mindiff, abs(left - right)))
				{
					tmp[0] = left;
					tmp[1] = right;
				}
			}
			mindiff = 9223372036854775807;
			for (int third{ second + 1 }; third <= n - 2; third++)
			{
				ll left{ cum[third] - cum[second] };
				ll right{ cum[n - 1] - cum[third] };

				if (chmin(mindiff, abs(left - right)))
				{
					tmp[2] = left;
					tmp[3] = right;
				}

			}
			// calculate temp and update ans
			ll ma{ tmp[0] };
			chmax(ma, tmp[1]); chmax(ma, tmp[2]); chmax(ma, tmp[3]);
			ll mi{ tmp[0] };
			chmin(mi, tmp[1]); chmin(mi, tmp[2]); chmin(mi, tmp[3]);

			chmin(ans, abs(ma - mi));
		}

		cout << ans << endl;
	}
};


int main()
{
	D solution;
	solution.solve();

	return 0;
}

