void solve(int n, vi a) {
  vi c(n + 1);
  rep(i, n)c[i + 1] = c[i] + a[i];
  int ans = INF;
  rep(mid, 2, n - 1) {
    int f_i = lower_bound(begin(c), begin(c) + mid - 1, c[mid] / 2) - begin(c);
    int p = abs(c[f_i] * 2 - c[mid]) < abs(c[f_i - 1] * 2 - c[mid]) ? c[f_i] : c[f_i - 1];
    int q = c[mid] - p;
    int b_i = lower_bound(begin(c) + mid - 2, end(c), c[mid] + (c[n] - c[mid]) / 2) - begin(c);
    int r = abs((c[b_i] - c[mid]) * 2 - (c[n] - c[mid])) < abs((c[b_i - 1] - c[mid]) * 2 - (c[n] - c[mid])) ? c[b_i] - c[mid] : c[b_i - 1] - c[mid];
    int s = c[n] - (r + c[mid]);
    amin(ans, max({p, q, r, s}) - min({p, q, r, s}));
    // CVEC(vi({p,q,r,s}));
  }
  COUT(ans);
}


