        }else{
            R -= a[i2];
            sub = abs(R-S);
            while(1){
                R += a[i3];
                S -= a[i3];
                if(abs(R-S)<sub && S != 0){
                    sub = abs(R-S);
                }else{
                    R -= a[i3];S += a[i3];
                    break;
                }
                i3 ++;
            }
        }
        m = min(min(P,Q),min(R,S));
        M = max(max(P,Q),max(R,S));
        //cout << P << "," << Q << "," << R << "," << S << endl;
        if(ans>M-m)ans = M-m;
    }
    cout << ans << endl;
    return 0;
}

