int main() {
    int n; cin >> n;
    vector<int> a(n);
    for (auto &ai: a) cin >> ai;
    vector<long long> acc(n + 1);
    for (int i = 0; i < n; i++) acc[i + 1] = acc[i] + a[i];
    auto binary_search = [&](long long ok, long long ng, auto check) {
        assert(check(ok) == true);
        assert(check(ng) == false);
        while (abs(ng - ok) > 1) {
            long long mid = (ng + ok) / 2;
            (check(mid) ? ok : ng) = mid;
        }
        return ok;
    };
    long long mi = INF;
    for (int mid = 1; mid < n - 1; mid++) {
        int left = binary_search(0, mid, [&](long long k) {
            return acc[k] - acc[0] <= acc[mid] - acc[k];
        });
        int right = binary_search(mid, n, [&](long long k) {
            return acc[k] - acc[mid] <= acc[n] - acc[k];
        });
        for (int l: {left, left + 1}) for (int r: {right, right + 1}) {
            long long P = acc[l] - acc[0], Q = acc[mid] - acc[l];
            long long R = acc[r] - acc[mid], S = acc[n] - acc[r];
            mi = min(mi, max({P, Q, R, S}) - min({P, Q, R, S}));
        }
    }
    cout << mi << endl;
    return 0;
}

