int cari(int l, int r)
{
	LL tmp = ps[r]-ps[l-1];
	int cl = l;
	int cr = r;
	int ret = cr;
	while(cl<=cr)
	{
		int mid = (cl+cr)/2;
		LL now = ps[mid] - ps[l-1];
		LL kan = tmp - now;
		if(now>=kan)
		{
			cr=mid-1;
			ret = mid;
		}
		else
		{
			cl=mid+1;
		}
	}
	return ret;
}

