using namespace std;

int N;
int A[200001];
int sum_A[200001];

int diff(int start, int end, int i){
  i = max(min(i, end), start);
  int right = sum_A[end - 1] - sum_A[i - 1];
  int left = sum_A[i - 1] - (start == 0 ? 0 : sum_A[start - 1]);
  return abs(right - left);
}



int find_pos(int start, int end){
  int l = start + 1;
  int r = end - 1;
  while(1){
    if(r - l <= 3){
      break;
    }
    int halfleft_id = (l*2 + r*1)/3;
    int halfright_id = (l*1 + r*2)/3;
    int halfleft_diff = diff(start, end, halfleft_id);
    int halfright_diff = diff(start, end, halfright_id);
    if(halfleft_diff <= halfright_diff){
      r = halfright_id;
    }else{
      l = halfleft_id;
    }

  }
  int x[4];
  x[0] = diff(start, end, min(l, end - 1));
  x[1] = diff(start, end, min(l + 1, end - 1));
  x[2] = diff(start, end, min(l + 2, end - 1));
  x[3] = diff(start, end, min(l + 3, end - 1));  
  return min((int)(l + (min_element(x, x+4) - x)), end - 1);

}

int main(){
  scanf("%d", &N);
  int sum = 0;
  for(int i=0; i < N; i++){
    scanf("%d", A + i);
    sum += A[i];
    sum_A[i] = sum;
  }

  int res = 2000000000;
  for(int center = 2; center <= N - 2; center++){
  int left = find_pos(0, center);
  int right = find_pos(center, N);
  int x[4];
  x[0] = sum_A[left - 1];
  x[1] = sum_A[center - 1] - sum_A[left - 1];
  x[2] = sum_A[right - 1] - sum_A[center - 1];
  x[3] = sum_A[N - 1] - sum_A[right - 1];
  res = min(res, *max_element(x, x+4) - *min_element(x, x+4));
  }
  // printf("%d %d %d\n", left, center, right);
  // printf("%d %d %d %d\n", x[0], x[1], x[2], x[3]);  
  printf("%d\n", res);
  return 0;
}

