using namespace std;

int main() {
    int N;
    cin >> N;
    vector< int > A(N);
    vector< long long > tot(N + 1);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        if (i == 0)
            tot[i] = A[i];
        else
            tot[i] = tot[i - 1] + A[i];
    }

    long long ans = 1e16;
    for (int i = 1; i < N - 2; i++) {
        // cout << i << endl;
        int l, mid, r;
        long long l_sum, r_sum, P, Q, R, S;
        // left
        // cout << "left" << endl;
        l = 0, r = i;
        while (l != r) {
            mid = (l + r) / 2;
            l_sum = tot[mid];
            r_sum = tot[i] - tot[mid];

            if (l_sum < r_sum)
                l = mid + 1;
            else
                r = mid;
        }

        if (abs(tot[r] - (tot[i] - tot[r])) <
            abs(tot[r - 1] - (tot[i] - tot[r - 1]))) {
            P = tot[r];
            Q = tot[i] - tot[r];
        } else {
            P = tot[r - 1];
            Q = tot[i] - tot[r - 1];
        }

        // cout << "P: " << P << ", Q: " << Q << endl;

        // right
        // cout << "right" << endl;
        l = i + 1, r = N - 1;
        while (l != r) {
            mid = (l + r) / 2;
            l_sum = tot[mid] - tot[i];
            r_sum = tot[N - 1] - tot[mid];

            if (l_sum < r_sum)
                l = mid + 1;
            else
                r = mid;
        }

        // cout << "r: " << r << ", " << tot[r] << endl;
        if (abs(tot[r] - tot[i] - (tot[N - 1] - tot[r])) <
            abs(tot[r - 1] - tot[i] - (tot[N - 1] - tot[r - 1]))) {
            R = tot[r] - tot[i];
            S = tot[N - 1] - tot[r];
        } else {
            R = tot[r - 1] - tot[i];
            S = tot[N - 1] - tot[r - 1];
        }

        // cout << "R: " << R << ", S: " << S << endl;

        long long tmp = max({P, Q, R, S}) - min({P, Q, R, S});
        ans = min(ans, tmp);
    }

    cout << ans << endl;
}

