using namespace std;

int     Pos(long AA, vector<long> &A) {
        int a=0;
        int b=A.size()-1;
        while (1<b-a) {
                int c=(a+b)/2;
                if (AA>=A.at(c))
                        a=c;
                else b=c;
        }
        return a;
}

int     Mid(int a, int b, vector<long> &A) {
        long T=(A.at(a)+A.at(b))/2;
        return Pos(T, A);
}

int     main() {
        int N;
        cin >>N;
        vector<long> A(N);
        long AAA=0;
        for (int i=0; i<N; i++) {
                long AA;
                cin >>AA;
                AAA += AA;
                A.at(i)=AAA;
        }
        long S=AAA;
        int N1=Pos(AAA/4, A);
        int N3=Pos(AAA*3/4, A);
        int RNG=100;
        for (int i=N1-RNG; i<=N+RNG; i++) {
                if (i<0) continue;
                for (int j=N3-RNG; j<=N3+RNG; j++) {
                        if (j-i<2) continue;
                        if (N<=j) continue;
                        int N2=Mid(i, j, A);
                        long D1=A.at(i);
                        long D4=AAA-A.at(j);
                        for (int k=N2-RNG; k<=N2+RNG; k++) {
                                if (k<=i) continue;
                                if (k>=j) continue;
                                long D2=A.at(k)-D1;
                                long D3=A.at(j)-D2-D1;
                                S=min(S, max(max(D4, D3), max(D2, D1))-min(min(D4, D3), min(D2, D1)));
                        }
                }
        }
        cout <<S <<endl;
        return 0;
};

