        S[3] += A[i];
    }

    ll min = 10000000000000000;

    for(int i = 1; i <= N - 3; i++){
        ll v = cut(A, N, i, il, ir, S);
        if(v < min) min = v;
        S[1] += A[i + 1];
        S[2] -= A[i + 1];
    }


    cout << min;


    return 0;

}

