    int N, A[MAX_N + 1];
    ll B[MAX_N + 1];
    cin >> N;
    B[0] = 0;
    FOR(i, 1, N + 1, 1) {
        cin >> A[i];
        B[i] = B[i - 1] + A[i];
    }
    ll res = 2 * 100000000000000 + 1;
    int l = 1, r = 3;
    FOR(i, 2, N - 1, 1) {
        while (l < i && abs(2 * B[l] - B[i]) >= abs(2 * B[l + 1] - B[i])) {
            l++;
        }
        while (r < N &&
               abs(2 * B[r] - B[i] - B[N]) >= abs(2 * B[r + 1] - B[i] - B[N])) {
            r++;
        }
        ll P = B[l], Q = B[i] - B[l], R = B[r] - B[i], S = B[N] - B[r];
        ll _max = max({P, Q, R, S});
        ll _min = min({P, Q, R, S});
        amin(res, _max - _min);
    }
    cout << res << endl;
    return 0;
}

