    #endif
    cin >> n;
    FOR(i,1,n)cin >> ara[i];
    LL ans = solve();
    reverse(ara + 1,ara + n + 1);
    ans = min(ans,solve());
    cout << ans << "\n";
    #ifdef VAMP
        fprintf(stderr, "\n>> Runtime: %.10fs\n", (double) (clock() - tStart) / CLOCKS_PER_SEC);
    #endif
}

