pair<ll, ll> min_max(vector<ll> &sum, int l, int r) {
    int left = l;
    int right = r-1;
    // cout << "l = " << l;
    // cout << ", r = " << r;
    // cout << endl;

    pair<ll, ll> ret;
    ll min_abs = 1000L * 1000L * 1000L * 1000L * 1000L;
    while (left <= right) {
        int mid = (left + right) >> 1;
        ll l_sum = sum[mid] - sum[l-1];
        ll r_sum = sum[r] - sum[mid];

        // cout << "left = " << left;
        // cout << ", right = " << right;
        // cout << ", mid = " << mid;
        // cout << ", l_sum = " << l_sum;
        // cout << ", r_sum = " << r_sum;
        // cout << endl;

        if (abs(r_sum - l_sum) < min_abs) {
            min_abs = abs(r_sum - l_sum);
            ret.first = min(r_sum, l_sum);
            ret.second = max(r_sum, l_sum);
        }

        if (l_sum < r_sum) {
            left = max(mid, left+1);
        } else {
            right = min(mid, right-1);
        }
    }

    return ret;
}

