const ll mod = 1e9 + 7;
const ll inf = 1e18;
const double PI = acos(-1);

struct AccSum{
    vector<ll> Ac;
    ll L;
    AccSum(){}
    AccSum(vector<ll> &A){
        L = A.size();
        Ac.resize(L+1);
        FOR(i, 0, L){
            Ac[i+1] = Ac[i] + A[i];
        }
    }
    // sum of [a, b]
    ll sum(ll a, ll b){
        if(a<0) return -1;
        if(b>L-1) return -1;
        return Ac[b+1] - Ac[a];
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N; 
    cin>>N;

    // 左からの累積和
    VI A(N);
    rep(i, N) cin >> A[i];
    AccSum Acc(A);

    // 右からの累積和
    reverse(ALL(A));
    AccSum Acc2(A);

    ll mi = inf;
    FOR(i, 1, N-1){
      // i : cut of center
      cerr << endl;
      debug("cut pos", i);

      // 左について
      ll sum = Acc.sum(0, i);
      auto it = lower_bound(ALL(Acc.Ac), sum/2);

      ll a = *it;
      ll b = sum-a;
      debug(sum, a, b);

      if(it!=Acc.Ac.begin()){
        it--;
        ll a2 = *it;
        ll b2 = sum-a2;
        if(abs(a2-b2)<abs(a-b)){
          a = a2;
          b = b2;
        }
      }

      // 右について
      ll r = N-(i+1);
      sum = Acc2.sum(0, r);
      it = lower_bound(ALL(Acc2.Ac), sum/2);

      ll c = *it;
      ll d = sum-c;

      if(it!=Acc2.Ac.begin()){
        it--;
        ll c2 = *it;
        ll d2 = sum-c2;
        if(abs(c2-d2)<abs(c-d)){
          c = c2;
          d = c2;
        }
      }

      ll v = max({a,b,c,d}) - min({a,b,c,d});
      chmin(mi, v);
    }
    p(mi);

    return 0;
}

