int main()
{
    int N;
    cin >> N;
    long long A[100100];
    long long res = 1LL << 60;
    rep(i, 0, N)
    {
        cin >> A[i];
    }

    long long sum[100100];
    sum[0] = A[0];
    rep(i, 1, N)
    {
        sum[i] = sum[i - 1] + A[i];
    }

    int le = 1;
    int ri = 3;
    rep(i, 2, N)
    {
        // cout << "start:" << i << endl;
        bool pqflg = true;
        while (pqflg)
        {
            // cout << "in,le:" << le << endl;
            if (le == i - 1)
            {
                pqflg = false;
            }
            else
            {

                long long p1 = sum[le - 1];
                long long q1 = sum[i - 1] - p1;
                long long p2 = sum[le];
                long long q2 = sum[i - 1] - p2;
                long long di1 = max({p1, q1}) - min({p1, q1});
                long long di2 = max({p2, q2}) - min({p2, q2});
                if (di2 < di1)
                {
                    le++;
                    // cout << "++" << endl;
                }
                else
                {
                    pqflg = false;
                    // cout << "di1:" << di1 << ",di2:" << di2 << endl;
                    // cout << p1 << "," << q1 << "," << p2 << "," << q2 << endl;
                }
            }
        }
        bool rsflg = true;
        while (rsflg)
        {
            if (ri == N - 1)
            {
                rsflg = false;
                continue;
            }

            long long r1 = sum[ri - 1] - sum[i - 1];
            long long s1 = sum[N - 1] - sum[i - 1] - r1;
            long long r2 = sum[ri] - sum[i - 1];
            long long s2 = sum[N - 1] - sum[i - 1] - r2;
            long long di1 = max({r1, s1}) - min({r1, s1});
            long long di2 = max({r2, s2}) - min({r2, s2});
            if (di2 < di1)
            {
                ri++;
                // cout << "i:" << i << "ri:" << ri << endl;
                // cout << r1 << "," << s1 << "," << r2 << "," << s2 << endl;
            }
            else
            {
                rsflg = false;
            }
        }
        long long p = sum[le - 1];
        long long q = sum[i - 1] - p;
        long long r = sum[ri - 1] - p - q;
        long long s = sum[N - 1] - p - q - r;
        long long di = max({p, q, r, s}) - min({p, q, r, s});
        if (di < res)
        {
            // cout << "i:" << i << endl;
            // cout << p << "," << q << "," << r << "," << s << endl;
            res = di;
        }
    }
    cout << res << endl;
}

