    }
    long long b[4];
    long long ans = sum[n-1];
    for(int i=1; i<n-2; i++){
        int p,q;
        p = sum[i]/2.0;
        q = (sum[n-1]-sum[i])/2.0;
        for(int j=1; j<i+1; j++){
            if(sum[j] > p){
                if(sum[j]-p<p-sum[j-1]){
                    b[0] = sum[j];
                    b[1] = sum[i]-sum[j];
                }
                else {
                    b[0] = sum[j-1];
                    b[1] = sum[i]-sum[j-1];
                }
                break;
            }
        }
        for(int j=i+2; j<n; j++){
            if(sum[j]-sum[i] > q){
                if(sum[j]-sum[i]-q<q-sum[j-1]+sum[i]){
                    b[2] = sum[j]-sum[i];
                    b[3] = sum[n-1]-sum[j];
