using namespace std;

using uint = unsigned int;
using ll = long long;

// #define OUTPUT_LOG

void getLeftPos(vector<ll>& B, uint& l, uint& c) {
  ll cval = B[c];
  ll pre_diff = abs((B[l - 1] - 0) - (cval - B[l - 1]));
  ll lsum, rsum;

#ifdef OUTPUT_LOG
  cout << "search left pos" << endl;
  cout << l - 1 << ":" << pre_diff << endl;
#endif

  while(l < c) {
    lsum = B[l] - 0;
    rsum = cval - B[l];

#ifdef OUTPUT_LOG
    cout << l << ":" << abs(lsum - rsum) << endl;
#endif

    if (lsum - rsum > 0) {
      if (pre_diff < abs(lsum - rsum)) {
        --l;
      }
      return;
    }

    ++l;
    pre_diff = abs(lsum - rsum);
  }

  --l;
  return;
}

void getRightPos(vector<ll>& B, uint& r, uint& c) {
  uint len = B.size() - 1;
  ll cval = B[c];
  ll eval = B[len];
  ll pre_diff = abs((B[r - 1] - cval) - (eval - B[r - 1]));
  ll lsum, rsum;

#ifdef OUTPUT_LOG
  cout << "search right pos" << endl;
  cout << r - 1 << ":" << pre_diff << endl;
#endif

  while(r < len) {
    lsum = B[r] - cval;
    rsum = eval - B[r];

#ifdef OUTPUT_LOG
    cout << r << ":" << abs(lsum - rsum) << endl;
#endif

    if (lsum - rsum > 0) {
      if (pre_diff < abs(lsum - rsum)) {
        --r;
      }
      return;
    }
    ++r;
    pre_diff = abs(lsum - rsum);
  }

  --r;
  return;
}

ll getVal(vector<ll>& B, uint l, uint c, uint r) {
  vector<ll> sum(4);
  sum[0] = B[l] - 0;
  sum[1] = B[c] - B[l];
  sum[2] = B[r] - B[c];
  sum[3] = B[B.size() - 1] - B[r];
#ifdef OUTPUT_LOG
  cout << "l: " << l << ", c: " << c << ", r: " << r << endl;
  cout << "sum[0]: " << sum[0] << endl;
  cout << "sum[1]: " << sum[1] << endl;
  cout << "sum[2]: " << sum[2] << endl;
  cout << "sum[3]: " << sum[3] << endl;
#endif
  ll maxval = *max_element(sum.begin(), sum.end());
  ll minval = *min_element(sum.begin(), sum.end());

  return maxval - minval;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  uint N;
  cin >> N;

  vector<ll> B(N+1);
  B[0] = 0;
#ifdef OUTPUT_LOG
  cout << "B: 0, ";
#endif
  ll buf;
  for (int i = 1; i <= N; ++i) {
    cin >> buf;
    B[i] = B[i-1] + buf;

#ifdef OUTPUT_LOG
    cout << B[i] << ", ";
#endif

  }

#ifdef OUTPUT_LOG
  cout << endl;
#endif

  ll minval = numeric_limits<ll>::max();
  uint l = 1, r = 3;
  for (uint c = 2; c <= N - 2; ++c) {
    if (r <= c) r = c + 1;

    getLeftPos(B, l, c);
    getRightPos(B, r, c);

    ll val = getVal(B, l, c, r);
    if (val < minval) minval = val;
  }

  cout << minval << endl;

  return 0;
}

