constexpr long INF = 1LL << 62;

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n; 
    long a[200000]; for(int i=0; i < n; ++i) cin >> a[i];

    // sum [l, r) => s[r] - s[l]
    vector<long> s(n + 1);
    for(int i=0; i < n; ++i) s[i+1] = s[i] + a[i];


    // center : しきり a[c-1] : a[c]
    // l : しきり sum(a[0] ~ a[l-1]), sum(a[l] ~ a[c-1])
    // r : しきり sum(a[c] ~ a[r-1]), sum(a[r] ~ a[n-1])
    long ans = INF;
    int l = 1, r = 3;

    // 区間 a1 a2 a3 a4
    // c が　右へ動く -> a2が増加することでa1, a2の差が増加, a3が減少することでa3, a4の差が増加
    // 差が単調増加なので、l, rは右へ動かすことのみ考えればよい? 差が減少する場合のみスライドする尺取り法
    for(int c = 2; c < n-1; ++c) {
        while(l < c && abs((s[c] - s[l]) - (s[l] - s[0])) > abs((s[c] - s[l+1]) - (s[l+1] - s[0]))) ++l;
        while(r < n && abs((s[n] - s[r]) - (s[r] - s[c])) > abs((s[n] - s[r+1]) - (s[r+1] - s[c]))) ++r;

        long a1 = s[l] - s[0], a2 = s[c] - s[l], a3 = s[r] - s[c], a4 = s[n] - s[r];

        ans = min(ans, max(a1, max(a2, max(a3, a4))) - min(a1, min(a2, min(a3, a4))));
    }

    cout << ans << '\n';
    return 0;
}

