ll my_max(ll a, ll b)
{
  return max(a, b);
}

ll my_min(ll a, ll b)
{
  return min(a, b);
}

ll my_add(ll a, ll b)
{
  return a + b;
}

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << setprecision(20) << setiosflags(ios::fixed);

  int n;
  cin >> n;
  ll a[200010];
  rep(i, n) cin >> a[i];
  SegmentTree<ll> sg(n, my_add, 0);
  rep(i, n) sg.update(i, a[i]);

  auto binary_search = [&](int l, int r) {
    ll lo = l, hi = r;
    while (hi - lo > 1)
    {
      ll mi = (lo + hi) / 2;
      if (sg.query(l, mi) <= sg.query(mi, r))
        lo = mi;
      else
        hi = mi;
    }
    return lo;
  };

  ll ans = LINF;

  //[0,i)と[i,n)に分ける
  REP(i, 2, n - 1)
  {

    //[0,x)の和<=[x,i)の和を満たす最大のx
    int l = binary_search(0, i);
    ll P1 = sg.query(0, l), P2 = sg.query(0, l + 1);
    ll Q1 = sg.query(l, i), Q2 = sg.query(l + 1, i);
    ll P, Q;
    if (abs(P1 - Q1) <= abs(P2 - Q2))
      P = P1, Q = Q1;
    else
      P = P2, Q = Q2;

    //[i,x)の和<=[x,n)の和を満たす最大のx
    int r = binary_search(i, n);
    ll R1 = sg.query(i, r), R2 = sg.query(i, r + 1);
    ll S1 = sg.query(r, n), S2 = sg.query(r + 1, n);
    ll R, S;
    if (abs(R1 - S1) <= abs(R2 - S2))
      R = R1, S = S1;
    else
      R = R2, S = S2;

    ll score = max({P, Q, R, S}) - min({P, Q, R, S});
    ans = min(ans, score);
  }
  cout << ans << endl;
  return 0;
}

