int main() {
    ll n;
    vector<ll> a;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int t;
        cin >> t;
        if (i == 0)a.pb(t);
        else a.pb(t + a[i - 1]);
    }
    ll ans = INF, l=0,r=2;
    for (int middle = 1; middle <= n - 3; middle++) {
        while (l < middle && abs((a[middle] - a[l]) - a[l]) >= abs((a[middle] - a[l + 1]) - a[l + 1])) {
            l++;
        }
        while (r < n - 1 && abs((a[n - 1] - a[r]) - (a[r] - a[middle])) >= abs((a[n - 1] - a[r + 1]) - (a[r + 1] - a[middle]))) {
            r++;
        }
        ans = min(ans, max({ a[l],a[middle] - a[l],a[r] - a[middle],a[n-1] - a[r] }) - min({ a[l],a[middle] - a[l],a[r] - a[middle],a[n-1] - a[r] }));
    }
    cout << ans << endl;
    return 0;
}

