        }
        if(abs(c-d) > abs(s[n]-2*(*r1)+s[i])){
            c = *r1-s[i];
            d = s[n]-*r1;
        }
        int maxi = max({a,b,c,d});
        int mini = min({a,b,c,d});

        ans = min(ans,maxi-mini);
        //cerr << i << " " << *l1 << " " << s[i] << " " << *r1 << " " << ans << endl;
    }
