  for (int cut = 1; cut < n - 2; cut++) {
    int before = a[cut];
    int after = sum - a[cut];
    int be_half = before / 2;
    auto ite = lower_bound(a, a + n, be_half);
    int b1 = *ite;
    int c1 = a[cut] - b1;
    int b2 = -1;
    int c2 = 1000000010;
    if (ite != a) {
      b2 = *(ite - 1);
      c2 = a[cut] - b2;
    }
    int B, C;
    if (abs(c1 - b1) >= abs(c2 - b2)) {
      B = b2;
      C = c2;
    } else {
      B = b1;
      C = c1;
    }
    int af_half = after / 2;
    auto ite2 = lower_bound(a, a + n, af_half + a[cut]);
    int d1 = *ite2 - a[cut];
    int e1 = sum - d1 - a[cut];
    int d2 = -1;
    int e2 = 1000000010;
    if (ite2 != a + cut + 1) {
      d2 = *(ite2 - 1) - a[cut];
      e2 = sum - d2 - a[cut];
    }
    int D, E;
    if (abs(e1 - d1) >= abs(e2 - d2)) {
      D = d2;
      E = e2;
    } else {
      D = d1;
      E = e1;
    }
    //cerr << B << ", " << C << ", " << D << ", " << E << endl;
    int max_ = max({B, C, D, E});
    int min_ = min({B, C, D, E});
    ans = min(ans, max_ - min_);
  }
