/*

最大値と最小値の差の絶対値x以下は実現できるか?でにぶたん

とりまAの前からと後ろからの累積和をとる

列Bを前から取っていく この和+x以下でにぶたん +x以下でにぶたん +残り これらが実際x以下ならOK  
列Bを前から取っていく この和-x以上でにぶたん +x以下でにぶたん これらが実際x以下ならOK
列Bを前から取っていく この和+x以下でにぶたん -x以上でにぶたん これらが実際x以下ならOK
列Bを前から取っていく この和-x以上でにぶたん -x以上でにぶたん これらが実際x以下ならOK
*/
bool f(ll x, vector<ll> S) {
    ll N = S.size(), B, C, D, M = S[N-2];
    for (int i = 1; i < N-4; i++) {
        B = S[i];

        auto cd = lower_bound(S.begin(),S.end(),max(B+B-x, B+1));
        auto de = lower_bound(S.begin(),S.end(),max(*cd+B-x, *cd+1));
        //cout << *cd << " " << *de << endl;
        //cout << abs(M-*de-B) << endl;
        if (abs(M - *de - B) <= x && 
            abs(M - *de - (*cd-B)) <= x && 
            abs(M - *de - (*de-*cd)) <= x) return true;

        cd = upper_bound(S.begin(),S.end(),B+B+x)-1;
        de = upper_bound(S.begin(),S.end(),*cd+B+x)-1;
        if (abs(M - *de - B) <= x && 
            abs(M - *de - (*cd-B)) <= x && 
            abs(M - *de - (*de-*cd)) <= x) return true;

        cd = lower_bound(S.begin(),S.end(),max(B+B-x,B+1));
        de = upper_bound(S.begin(),S.end(),*cd+*cd-B+x)-1;
        if (abs(M - *de - B) <= x && 
            abs(M - *de - (*cd-B)) <= x && 
            abs(M - *de - (*de-*cd)) <= x) return true;

        cd = upper_bound(S.begin(),S.end(),B+B+x)-1;
        de = lower_bound(S.begin(),S.end(),max(*cd+*cd-B-x, *cd+1));
        if (abs(M - *de - B) <= x && 
            abs(M - *de - (*cd-B)) <= x && 
            abs(M - *de - (*de-*cd)) <= x) return true;
    }
    return false;
}

