ll solve(ll B,ll C,ll D,ll E){
  ll ans=0;
  ans=max<ll>(ans,abs<ll>(B-C));
  ans=max<ll>(ans,abs<ll>(B-D));
  ans=max<ll>(ans,abs<ll>(B-E));
  ans=max<ll>(ans,abs<ll>(C-D));
  ans=max<ll>(ans,abs<ll>(C-E));
  ans=max<ll>(ans,abs<ll>(D-E));
  return ans;
}

int main(){
  int N;
  cin>>N;
  vector<ll> A(N);
  for(int i=0;i<N;i++){
    cin>>A.at(i);
  }

  vector<ll> sum(N+1,0);
  for(int i=0;i<N;i++){
    sum.at(i+1)=sum.at(i)+A.at(i);
  }

  ll ans=INF;
  for(int i=2;i<=N-2;i++){
    int k1=upper_bound(sum.begin(),sum.end(),sum.at(i)/2)-sum.begin();
    ll B,C,D,E;
    ll B2,C2,D2,E2;
    if(k1==i){
      B=sum.at(k1-1);
      C=sum.at(i)-sum.at(i-1);
      B2=B;
      C2=C;
    }else{
      B=sum.at(k1);
      C=sum.at(i)-sum.at(k1);
      if(k1>1){
        B2=sum.at(k1-1);
        C2=sum.at(i)-sum.at(k1-1);
      }else{
        B2=B;
        C2=C;
      }
    }

    int k2=upper_bound(sum.begin(),sum.end(),sum.at(i)+(sum.at(N)-sum.at(i))/2)-sum.begin();
    if(k2==N){
      D=sum.at(k2-1)-sum.at(i);
      E=sum.at(N)-sum.at(k2-1);
    }else{
      D=sum.at(k2)-sum.at(i);
      E=sum.at(N)-sum.at(k2);
      if(k2>i+1){
        D2=sum.at(k2-1)-sum.at(i);
        E2=sum.at(N)-sum.at(k2-1);
      }else{
        D2=D;
        E2=E;
      }
    }
    ll cand=INF;
    cand=min<ll>(cand,solve(B,C,D,E));
    cand=min<ll>(cand,solve(B2,C2,D,E));
    cand=min<ll>(cand,solve(B,C,D2,E2));
    cand=min<ll>(cand,solve(B2,C2,D2,E2));
    ans=min<ll>(ans,cand);
  }
  cout<<ans<<endl;
}

