std::vector<std::vector<int> > vector_devide(int a1, int a2, int a3, std::vector<int> v) {
	std::vector<std::vector<int> > result;
	result.push_back(extract_vector(0, a1, v));
	result.push_back(extract_vector(a1, a2, v));
	result.push_back(extract_vector(a2, a3, v));
	result.push_back(extract_vector(a3, v.size(), v));
	return result;
}

std::vector<int> extract_vector(int begin, int end, std::vector<int> v) {
	std::vector<int> result;
	for (int i = 0; i+begin < end; i++) {
		result.push_back(v[i+begin]);
	}
	return result;
}

