VEC(Pll) bestSplits(VEC(lint)& A)
{
    const int N = SZ(A);


    VEC(lint) Sum(N + 1, 0LL);
    partial_sum(ALL(A), BEGIN(Sum) + 1);

    VEC(Pll) Ret(N + 1);

    // Need atleast 2 elements to split.
    FOR(i, 2, N + 1) {
        lint sum = Sum[i];
        // among Sum[1] ... Sum[i - 1], pick one closest to sum / 2
        int x = lower_bound(BEGIN(Sum), BEGIN(Sum) + i, sum / 2) - BEGIN(Sum);
        Ret[i] = Pll(Sum[x], Sum[i] - Sum[x]);
        if (x >= 1) {
            Pll ret2(Sum[x - 1], Sum[i] - Sum[x - 1]);
            if (abs(ret2.FIR - ret2.SEC) < abs(Ret[i].FIR - Ret[i].SEC))
                swap(Ret[i], ret2);
        }
        if (Ret[i].FIR < Ret[i].SEC)
            swap(Ret[i].FIR, Ret[i].SEC);
    }

    return Ret;
};

void solveSingleCase(int caseNo)
{
    int N;
    cin >> N;
    VEC(lint) A(N);
    READVEC(A);
    VEC(Pll) left = bestSplits(A);
    reverse(ALL(A));
    VEC(Pll) right = bestSplits(A);
    reverse(ALL(A));

    lint ret = 1LL << 60;
    FOR(i, 2, N - 1) {
        int l = i, r = N - i;
        // l >= 2, r >= 2
        lint cand = left[l].FIR - left[l].SEC;
        cand = max(cand, right[r].FIR - right[r].SEC);
        cand = max(cand, abs(left[l].FIR - right[r].SEC));
        cand = max(cand, abs(left[l].SEC - right[r].FIR));
        ret = min(ret, cand);
    }

    cout << ret << endl;
};

int main(int argc, char **argv)
{
    io_init();

    // Actual program code starts here.
    int T = 1;
    // cin >> T;
    FOR(tcase, 1, T + 1) {
        solveSingleCase(tcase);
    }
    return 0;
};

