struct cumsum1d{
    int n;
    vector<int> arr;

    cumsum1d(int len){
        n = len;
        rep(i,0,n) arr.push_back(0);
    }

    void init(vector<int> vec){
        arr = vec;
        n = arr.size();
    }

    void add(int a, int b, int val = 1){
        arr[a] += val;
        if(b + 1 < n) arr[b + 1] -= val;
    }

    void build(){
        rep(i,1,n) arr[i] += arr[i-1];
    }

    int query(int from, int to){
        int ret = arr[to];
        if(from) ret -= arr[from - 1];
        return ret;
    }

};

signed main(){

    cin.tie(0);
    ios::sync_with_stdio(false);

    int n = input();

    vi arr; rep(i,0,n) arr.push_back(input());

    cumsum1d left = cumsum1d(10);

    left.init(arr);

    left.build();

    vi maxleft(n);
    vi minleft(n);

    maxleft[1] = max(arr[0], arr[1]);
    minleft[1] = min(arr[0], arr[1]);

    rep(i,2,n - 2){
        auto ptr = upper_bound(all(left.arr), left.arr[i] / 2);
        int d = distance(left.arr.begin(), ptr);
        if(d + 1 <= i && abs(left.query(0,d) - left.query(d + 1, i)) < abs(left.query(0,d - 1) - left.query(d, i))) d++;
        if(d - 1 >= 1 && abs(left.query(0, d - 2) - left.query(d - 1, i)) < abs(left.query(0, d - 1) - left.query(d, i))) d--;
        int mx = max(left.query(0, d - 1), left.query(d, i));
        int mi = min(left.query(0, d - 1), left.query(d, i));
        maxleft[i] = mx;
        minleft[i] = mi;

    }

    vi maxright(n);
    vi minright(n);

    reverse(all(arr));
    cumsum1d right = cumsum1d(10);
    right.init(arr);
    right.build();



    maxright[n - 2] = max(arr[0], arr[1]);
    minright[n - 2] = min(arr[0], arr[1]);



    rep(i,2,n - 2){
        auto ptr = upper_bound(all(right.arr), right.arr[i] / 2);
        int d = distance(right.arr.begin(), ptr);
        if(d + 1 <= i && abs(right.query(0, d) - right.query(d + 1, i)) < abs(right.query(0, d - 1) - right.query(d, i))) d++;
        if(d - 1 >= 1 && abs(right.query(0, d - 2) - right.query(d - 1, i)) < abs(right.query(0, d - 1) - right.query(d, i))) d--;
        int mx = max(right.query(0, d - 1), right.query(d, i));
        int mi = min(right.query(0, d - 1), right.query(d, i));
        maxright[n - i - 1] = mx;
        minright[n - i - 1] = mi;
