typedef long long ll;
const int N=2e5+100;
ll mm[N],L[N],R[N];

void go(int l,int r,ll &X,ll &Y){//intervalos cerrados
	ll here=L[r];
	if(l-1>=0)here-=L[l-1];
	ll mid=here/2;
	if(l-1>=0)mid+=L[l-1];
	int pos=lower_bound(L+l,L+r,mid)-L;
	assert(pos>=l&&pos<=r);
	X=L[pos];
	if(l-1>0)X-=L[l-1];
	Y=here-X;
	int Xaux=X-mm[pos],Yaux=Y+mm[pos];
	if(abs(Y-X)>abs(Xaux-Yaux)){
		X=Xaux,Y=Yaux;
	}

}

int main(){
	int n;cin>>n;
	for(int i=0;i<n;i++)cin>>mm[i];
	L[0]=mm[0];
	for(int i=1;i<n;i++)L[i]=mm[i]+L[i-1];
	R[n-1]=mm[n-1];
	for(int i=n-2;i>+0;i--)R[i]=mm[i]+R[i+1];
	ll ans=LLONG_MAX;
	for(int i=1;i<n-2;i++){
		ll B,C,D,E;
		go(0,i,B,C);
		go(i+1,n-1,D,E);
		ll mx=max({B,C,D,E});
		ll mn=min({B,C,D,E});
		ans=min(ans,mx-mn);
	}
	cout<<ans<<endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long int INF = 1e12;

int main(){
    int n;
    cin >> n;

    vector<long long int> a(n);
    for(int i=0; i<n; i++){
        cin >> a[i];
    }

    // cumulative sum
    for(int i=1; i<n; i++){
        a[i] += a[i-1];
    }

    vector<int> left(n-2), right(n-2);// left-cut, center-cut, right-cut
    // left[0] and right[0] have no meaning
    left[1] = 0;
    right[n-3] = n-2;// n >= 4

    int c = 2;
    int i = 0;
    while(true){
        if(abs((a[c] - a[i])   - a[i]) 
        >  abs((a[c] - a[i+1]) - a[i+1])){
            i += 1;
        }
        if(abs((a[c] - a[i])   - a[i]) 
        <= abs((a[c] - a[i+1]) - a[i+1])){
            left[c] = i;
            c += 1;
        }
        if(c == n-2) break;
    }

    c = 1;// reset
    i = 2;
    while(true){
        if(abs((a[n-1] - a[i])   - (a[i] - a[c])) 
        >  abs((a[n-1] - a[i+1]) - (a[i+1] - a[c]))
        ){
            i += 1;
        }
        if(abs((a[n-1] - a[i])   - (a[i] - a[c])) 
        <= abs((a[n-1] - a[i+1]) - (a[i+1] - a[c]))
        ){
            right[c] = i;
            c += 1;
        }
        if(c == n-2) break;
    }

    /*
     for(int c=1; c<=n-3; c++){
         cout << a[left[c]] << " " 
              << a[c] - a[left[c]] << " "
              << a[right[c]]- a[c] << " "
              << a[n-1]- a[right[c]] << endl;
     }
     */

    long long int ans = INF;
    for(int c=1; c<=n-3; c++){// center
        long long int diff
        = abs(
          max({a[left[c]], a[c] - a[left[c]], a[right[c]]- a[c], a[n-1]- a[right[c]]})
        - min({a[left[c]], a[c] - a[left[c]], a[right[c]]- a[c], a[n-1]- a[right[c]]})
        );
        if(diff < ans) ans = diff;
    }
    cout << ans << endl;
    return 0;
}

