	ll right;
	ll sub;
	ll left2;
	ll right2;
	ll sub2;
	rep(i, 1, N-2) {
		do{
			left = A[num];
			right = A[i]-A[num];
			sub = abs(left - right);
			left2 = A[num + 1];
			right2 = A[i] - A[num+1];
