			if (sub > sub2) {
				num++;
			}
		} while (sub>sub2);
		L[i] = num;
	}
	num = 2;
	rep(i, 1, N-2) {
		do {
			left = A[num] - A[i];
			right = A[N-1]-A[num];
			sub = abs(left - right);
			left2 = A[num + 1]-A[i];
			right2 = A[N-1] - A[num + 1];
			sub2 = abs(left2 - right2);
			if (sub > sub2) {
				num++;
			}
		} while (sub>sub2);
