ll calc1(int l, int m, int r){
    ll sum0 = S[l];
    ll sum1 = S[m] - S[l];
    ll sum2 = S[r] - S[m];
    ll sum3 = S[N-1] - S[r];
    ll high = max(max(sum0, sum1), max(sum2, sum3));
    ll low = min(min(sum0, sum1), min(sum2, sum3));
    return high - low;
}

ll calc2(int l, int m, int r){
    ll sum0 = S[l];
    ll sum1 = S[m] - S[l];
    ll sum2 = S[r] - S[m];
    ll sum3 = S[N-1] - S[r];
    ll sum = abs(sum0-sum1) + abs(sum0-sum2) + abs(sum0-sum3)
                + abs(sum1-sum2) + abs(sum1-sum3) + abs(sum2-sum3);
    return sum;
}

