    int mid = 1;
    int right = 2;
    ll ans = LLONG_MAX;

    for(int mid = 1; mid < N-1; mid++){
        if(mid == right) right++;
        ll C = calc2(left, mid, right);
        while(left < mid){
            ll cost = calc2(left+1, mid, right);
            if(C > cost){
                C = cost;
                left++;
            }
            else break;
        }

        while(right < N){
            ll cost = calc2(left, mid, right+1);
            if(C > cost){
                C = cost;
                right++;
            }
