void solve() {

	int N;
	cin >> N;
	vi A(N);
	vector<ll> sum(N);
	for (int i = 0; i < N; i++){
		cin >> A[i];
		sum[i] = (i ? sum[i - 1] : 0) + A[i];
	}

	ll ans = 1e15;
	int l = 1, r = 3;
	for (int i = 1; i < N - 2; i++) {
		while (l < i && sum[l] <= sum[i] - sum[l]) {
			l++;
		}
		while (r < N - 1 && sum[r] - sum[i] <= sum[N - 1] - sum[r]) {
			r++;
		}
		if (sum[l] - (sum[i] - sum[l]) < sum[i] - sum[l - 1] - sum[l - 1]) {
			l++;
		}
		if (sum[r] - sum[i] - (sum[N - 1] - sum[r]) < sum[N - 1] - sum[r - 1] - (sum[r - 1] - sum[i])) {
			r++;
		}
		ll P = sum[l - 1], Q = sum[i] - sum[l - 1], R = sum[r - 1] - sum[i], S = sum[N - 1] - sum[r - 1];
		ll _max = max({ P, Q, R, S });
		ll _min = min({ P, Q, R, S });
		ans = min(ans, _max - _min);
	}


	cout << ans << endl;

	return;

}

