pair<LL, LL>divide(LL b, LL e) {
	LL ok = b, ng = e;
	LL ds = rui[e] - rui[b - 1];
	while (ng - ok > 1) {
		LL mid = (ok + ng) / 2;
		LL ps = rui[mid] - rui[b - 1];
		if (ps * 2 <= ds) {
			ok = mid;
		}
		else {
			ng = mid;
		}
	}

	pair<LL, LL> ret1 = make_pair(rui[ok] - rui[b - 1], rui[e] - rui[ok]);
	pair<LL, LL> ret2 = make_pair(rui[ok + 1] - rui[b - 1], rui[e] - rui[ok + 1]);

	if (ret1.first - ret1.second > ret2.second - ret2.first) {
		return ret1;
	}
	else {
		return ret2;
	}
}

LL calc(LL it) {
	vector<pair<LL, LL>>psum(2);
	psum[0] = divide(1, it);
	psum[1] = divide(it + 1, n);
	return max({ psum[0].first, psum[0].second, psum[1].first, psum[1].second }) - min({ psum[0].first, psum[0].second, psum[1].first, psum[1].second });
}

