		if (abs(R2 - S2) < abs(R - S)) {
			right_min = min(R2, S2), right_max = max(R2, S2);
		}

		ans = min(ans, max(left_max, right_max) - min(left_min, right_min));

	}

	cout << ans << endl;


	return 0;
}

