pll judge(int l, int r) {
	int s = l, e = r;
	while (e - s > 1) {
		int m = (e + s) / 2;
		if (S[m] >= (long double)(S[r] + S[l - 1]) / 2)e = m;
		else s = m;
	}
	long long p1 = 2 * S[e] - S[r] - S[l - 1];
	long long p2 = S[r] + S[l - 1] - 2 * S[s];
	if (p1 < p2) return pll(S[e] - S[l - 1], S[r] - S[e]);
	else return pll(S[e - 1] - S[l - 1], S[r] - S[e - 1]);
}

