  }

  REP(i,n) {
    if(i == 0) {
      sum[i] = a[i];
      continue;
    }
    sum[i] = sum[i-1] + a[i];
  }

  ll p, q, r, s;

  ll ans = -1;
  for(int i = 2; i < n-1; i++) {
    int ls = 0, le = i;
    while(le - ls > 1) {
      int j = (le+ls)/2;
      p = sum[j-1];
      q = sum[i-1] - p;
      if(p - q <= 0) {
        ls = j;
      } else {
        le = j;
      }
    }
    int rs = i, re = n;
    while(re - rs > 1) {
      int j = (re+rs)/2;
      r = sum[j-1] - sum[i-1];
      s = sum[n-1] - sum[j-1];
      if(r - s <= 0) {
        rs = j;
      } else {
        re = j;
      }
    }

    ll smax, smin;


    for(int j = -1; j < 2; j++) {
      if(ls + j < 0 || i-1 <= ls + j) continue;
      p = sum[ls+j];
      q = sum[i-1] - sum[ls+j];
      for(int k = -1; k < 2; k++) {
        if(rs + k < 0 || n - 1 <= rs + k) continue;
        r = sum[rs + k] - sum[i-1];
        s = sum[n-1] - sum[rs + k];

        smax = max(max(p,q), max(r,s));
        smin = min(min(p,q), min(r,s));
        if(ans >= abs(smax - smin) || ans == -1) {
          ans = abs(smax - smin);
        }
      }
    }
  }
  cout << ans << endl;
}

