            R = B[right] - B[center];
            S = B[N-1] - B[right];
            memoR = absR;
            absR = S - R;
            if(absR < 0 && right > center + 1) {
                right--;
                if(abs(memoR) < abs(absR)) {
                    R = B[right] - B[center];
                    S = B[N-1] - B[right];
                }
                break;
            }
            right++;
        }

        ll ax = max(P,Q);
        ax = max(ax, R);
        ax = max(ax, S);
        ll ix = min(P,Q);
        ix = min(ix, R);
        ix = min(ix, S);
        res = min(res, ax - ix);
    }
    cout << res << endl;
    return 0;
}

