void solve(){
    ll n;
    cin >> n;
    Vi sum(n);
    Vi a(n);
    rp(i,n){
        cin >> a.at(i);
        if(i==0) sum[0]=a[0];
        else sum[i]=sum[i-1]+a[i];
    }
    ll ans=INF;
    //ll dai,syou;
    repi(i,2,n-1){
        ll fr,ba;
        ll frmax,frmin,bamax,bamin;
        fr=sum[i-1]; ba=sum[n-1]-fr;
        ll ok=0,ng=i-1,mid=(ok+ng)/2;
        while(ng-ok>1){
            if(sum[mid]*2<=fr) ok=mid;
            else ng=mid;
            mid=(ok+ng)/2;
        }
        if(fr-sum[ok]*2>sum[ng]*2-fr){
            frmax=sum[ng]; frmin=fr-sum[ng];
        }else{
            frmax=fr-sum[ok]; frmin=sum[ok];
        }
        if(frmin>frmax) swap(frmin,frmax);
        ok=i; ng=n-1; mid=(ok+ng)/2;
        while(ng-ok>1){
            if((sum[mid]-sum[i-1])*2<=ba) ok=mid;
            else ng=mid;
            mid=(ok+ng)/2;
        }
        if(ba-(sum[ok]-sum[i-1])*2>(sum[ng]-sum[i-1])*2-ba){
            bamax=sum[ng]-sum[i-1]; bamin=ba-sum[ng]+sum[i-1];
        }else{
            bamax=ba-sum[ok]+sum[i-1]; bamin=sum[ok]-sum[i-1];
        }
        if(bamax<bamin) swap(bamin,bamax);
        chmin(ans,max(frmax,bamax)-min(frmin,bamin));
    }
    print(ans);
    //cout << dai << " " << syou << endl;
    return;
}
