template <typename T>
class SegmentTree
{
private:
  int N;
  vector<T> dat;

public:
  SegmentTree(int n_)
  {
    N = 1;
    while (N < n_)
      N *= 2;
    dat.assign(2 * N - 1, 0);
  }

  void update(int k, T a)
  {
    k += N - 1;
    dat[k] = a;
    while (k > 0)
    {
      k = (k - 1) / 2;
      dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
    }
  }

  T query(int a, int b, int k = 0, int l = 0, int r = -1)
  {
    if (r < 0)
      r = N;
    if (r <= a || b <= l)
      return 0;
    if (a <= l && r <= b)
      return dat[k];
    else
    {
      ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return vl + vr;
    }
  }
};

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << setprecision(20) << setiosflags(ios::fixed);

  ll n;
  cin >> n;
  ll a[200010];
  rep(i, n) cin >> a[i];
  SegmentTree<ll> sg(n);
  rep(i, n) sg.update(i, a[i]);

  auto binary_search = [&](ll l_, ll r_) {
    ll lo = l_, hi = r_;
    while (hi - lo > 1)
    {
      ll mi = (lo + hi) / 2;
      if (sg.query(l_, mi) <= sg.query(mi, r_))
        lo = mi;
      else
        hi = mi;
    }
    return lo;
  };

  ll ans = LINF;

  //[0,i)と[i,n)に分ける
  REP(i, 2, n - 1)
  {

    //[0,x)の和<=[x,i)の和を満たす最大のx
    ll l = binary_search(0, i);
    ll P1 = sg.query(0, l), Q1 = sg.query(l, i);
    ll P2 = sg.query(0, l + 1), Q2 = sg.query(l + 1, i);
    ll P, Q;
    if (abs(P1 - Q1) <= abs(P2 - Q2))
      P = P1, Q = Q1;
    else
      P = P2, Q = Q2;

    //[i,x)の和<=[x,n)の和を満たす最大のx
    ll r = binary_search(i, n);
    ll R1 = sg.query(i, r), S1 = sg.query(r, n);
    ll R2 = sg.query(i, r + 1), S2 = sg.query(r + 1, n);
    ll R, S;
    if (abs(R1 - S1) <= abs(R2 - S2))
      R = R1, S = S1;
    else
      R = R2, S = S2;

    ll score = max({P, Q, R, S}) - min({P, Q, R, S});
    ans = min(ans, score);
  }
  cout << ans << endl;
  return 0;
}

