	double ave = A[N] / 4.0;

	queue<pair<lint, vector<lint>>> que;
	que.push(make_pair(0, vector<lint>()));
	lint lft, rgt, ans = numeric_limits<lint>::max() / 2 - 1;
	while (!que.empty()) {

		auto tmp = que.front();
		que.pop();
