		}

		while (rgt <= N && A[rgt] - A[lft] <= ave) rgt++;
		if (tmp.second.size() < 4 && rgt <= N) {
			tmp.second.emplace_back(A[rgt] - A[lft]);
			que.push(make_pair(rgt, tmp.second));
