int main(){
    int N;cin>>N;
    vector<int> A(N,0);
    REP(i,N) cin>>A[i];
    vector<ll> accum(N+1,0);//index iを含む和
    accum[0] = A[0];
    FOR(i,0,N){
        accum[i+1] = accum[i] + A[i];
    }
    ll ans = INF;
    //PQRSに分割する
    //ある真ん中の切れ込み位置について，残り二つの切れ込みの位置は自動的に決まる
    //それぞれ切り込みの位置をもとめたあとN通りについて答えを計算する
    REP(i,N){
        //PとQについて
        // 1.P<Qとなる最も右の切れ目
        // 2.P>=Qとなる最も左の切れ目
        int low = 0,high = i;
        while(high - low>1){
            int mid = (low + high) /2 ;
            if(accum[mid] >= accum[i] -accum[mid]) high = mid;//midを左にすすめる
            else low = mid;
        }
        ll P = accum[low],Q = accum[i] - accum[low];//候補1
        ll P2 = accum[high],Q2 = accum[i] - accum[high];//候補2
        ll left_min = min(P,Q),left_max = max(P,Q);
        if(abs(P2-Q2)<abs(P-Q)){
            left_min = min(P2,Q2);
            left_max = max(P2,Q2);
        }
        //R<Sとなる最大の切れ目
        low = i,high = N;
        while(high - low>1){
            int mid = (low+high)/2;
            if(accum[mid]-accum[i]>=accum[N]-accum[mid]) high = mid;
            else low = mid;
        }
        ll R = accum[low] - accum[i],S =accum[N] - accum[low];
        ll R2 = accum[high] - accum[i],S2 = accum[N] - accum[high];
        ll right_min = min(R,S),right_max = max(R,S);
        if(abs(R2-S2)<abs(R-S)){
            right_min =min(R2,S2);
            right_max = max(R2,S2);
        }
        ll tmp = max(left_max,right_max) - min(left_min,right_min);
        ans = min(ans,tmp);
    }
    cout<<ans<<endl;
}

