using lli = long long;

int div(int l, int r, const std::vector<lli>& Ac_arr){
  int b=l, e=r;
  while(e-b > 1){
    int med=(b+e)/2;
    lli diff = Ac_arr[r]-Ac_arr[med]-Ac_arr[med]+Ac_arr[l];
    if(diff >= 0){
      b = med;
    }else{
      e = med;
    }
  }
  return b;
}

int main(){
  int N;
