ll f(ll mid)
{
    if(mid < 1 || mid >= n-2) return INF + abs(mid);
    ll first = g(0,mid);
    int i = 0;
    while(i < mid && 2*g(0,i) < first) i++;
    if(i > 0 && abs(g(0,i)-g(i+1,mid)) > abs(g(0,i-1)-g(i,mid))) i--;
    ll second = g(mid+1, n-1);
    int j = mid+1;
    while(j < n-1 && 2*g(mid+1,j) < second) j++;
    if(j > mid+1 && abs(g(mid+1,j)-g(j+1,n-1)) > abs(g(mid+1,j-1)-g(j,n-1))) j--;
    ll a = g(0,i), b = g(i+1, mid), c = g(mid+1, j), d = g(j+1, n-1);
    //cout << a << " " << b << " " << c << " " << d << endl;
    return max(max(a,b), max(c,d)) - min(min(a,b), min(c,d));
}

