	vector<lint> A(N);
	for (int i = 0; i < N; i++) cin >> A[i];

	CuSum<lint> sufA(A);

	auto BiSearch = [&](int l, int r) {
		return partition_point(sufA.begin() + l, sufA.begin() + r + 1, 
			[&](int n) {DMP(n); return (n - sufA[r - 1]) - (sufA[l] - n) <= 0 ; }) - sufA.begin() - 1;
	};

	lint ans = INF;
	for (int center = 2; center < N; center++) {

		auto cut1 = BiSearch(0, center);
		DMP(cut1);
		auto cut2 = BiSearch(center, N);
		DMP(cut2);

		vector<int> d{ -1,0 };
		for (const auto &e1 : d) {
			for (const auto &e2 : d) {
				auto tmp = minmax({ sufA(0, cut1 + e1), sufA(cut1 + e1, center), sufA(center, cut2 + e2), sufA(cut2 + e2, N) });
				ans = min(ans, tmp.second - tmp.first);
			}
		}
	}

	cout << ans << "\n";

	return 0;
}

