			hf[1]=i+1;
			break;
		}
	}
    for(int i=0;i<3;i++)
        if(hf[i]>n-3)hf[i]=n-3;
	for (int i = hf[1]; i < n; i++) {
		if (a[i] >= (a[n - 1] * 3) / 4) {
			qu2[1] = i;
			qu2[0] = i - 1;
		    qu2[2]=i+1;
			break;
		}
	}
	for(int i=0;i<3;i++)
