			for (int m = 0; m<=2; m++) {
//			    cout<<qu1[i]<<" "<<hf[j]<<" "<<qu2[m]<<" "<<i<<j<<m<<endl;
				if (qu1[i] >= hf[j] || hf[j] >= qu2[m])break;
				A = a[qu1[i]];
				B = a[hf[j]] - a[qu1[i]];
				C = a[qu2[m]] - a[hf[j]];
				D = a[n - 1] - a[qu2[m]];
				mem = max({abs(A-B),abs(A-C),abs(A-D),abs(B-C),abs(B-D),abs(C-D)});
				if (mem < min)min = mem;
		    }
		}
	}

	cout << min << endl;
	return 0;
}

