void calc_mm( long n, std::vector<long long>& s, std::vector<std::pair<long long, long long> >& mm )
{
    long i;
    long j = 0;
    long k;
    for(i=0; i<n; i++) {
        long id_min = j;
        long long min = s[n-1];
        for(k=j; k<i; k++) {
            long long tmp = abs(s[i] - s[k]*2);
            if(min > tmp) {
                min = tmp;
                id_min = k;
            }
            if(s[k]*2 > s[i]) {
                break;
            }
        }
        j = id_min;
        mm[i] = (s[i]-s[j]>s[j]? std::make_pair( s[j], s[i]-s[j]): std::make_pair( s[i]-s[j], s[j]));
    }

    return;
}

int main(int argc, char* argv[])
{
    long n;
    scanf("%ld", &n);

    std::vector<long> a(n);
    std::vector<long long> s(n);
    std::vector<long long> t(n);
    long i;
    for(i=0; i<n; i++) {
        scanf("%ld", &(a[i]));
        s[i] = a[i];
        t[n-1-i] = a[i];
    }
    for(i=1; i<n; i++) {
        s[i] = s[i-1] + a[i];
        t[i] = t[i-1] + a[n-1-i];
    }

    std::vector<std::pair<long long, long long> > smm(n);
    calc_mm( n, s, smm );

    std::vector<std::pair<long long, long long> > tmm(n);
    calc_mm( n, t, tmm );

    long long ans = 10000000000;
    for(i=1; i<n-1; i++) {
        long long tmpmin = MIN( smm[i].first, tmm[n-2-i].first );
        long long tmpmax = MAX( smm[i].second, tmm[n-2-i].second );
        if(ans > tmpmax - tmpmin) {
            ans = tmpmax - tmpmin;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

