int main() {
  ll N;
  cin >> N;

  vector<ll> acc;
  for (int i = 0; i < N; i++) {
    ll tmp;
    cin >> tmp;
    if (i == 0)
      acc.emplace_back(tmp);
    else
      acc.emplace_back(tmp + acc[i - 1]);
  }

  ll ans = acc[acc.size() - 1];
  for (int i = 1; i <= N - 3; i++) {
    ll sum0 = acc[i];
    auto pos0 = upper_bound(acc.begin(), acc.begin() + i - 1, sum0 / 2);
    if( pos0 != acc.begin() && abs(sum0 - 2*(*pos0)) >  abs(sum0 - 2*(*(pos0-1)) ))
      pos0--;

    ll sum1 = acc[acc.size() - 1] - acc[i];
