      pos1--;

    ll v0 = *pos0;
    ll v1 = acc[i] - *pos0;
    ll v2 = *pos1 - acc[i];
    ll v3 = acc[acc.size() - 1] - *pos1;
    vector<ll> cands = {v0, v1, v2, v3};
    ll max = *max_element(cands.begin(), cands.end());
    ll min = *min_element(cands.begin(), cands.end());
    if (max - min < ans) ans = max - min;
  }

