template <class _Tp>
class CumulativeSum {
 public:
  CumulativeSum(const std::vector<_Tp>& vec) : vec_(vec) { build(); }

  // return sum of [l, r]
  inline _Tp get(int l, int r) { return sum_[r + 1] - sum_[l]; }

  // return the first k where sum of [0, k] >= value
  int lower_bound(_Tp value) {
    //assert(all_of(vec_.begin(), vec_.end(), [](_Tp e) { return e >= 0; }));
    int high = vec_.size(), low = -1;
    while (high - low > 1) {
      int mid = (high + low) >> 1;
      if (this->get(0, mid) < value) {
        low = mid;
      } else {
        high = mid;
      }
    }
    return high;
  }

  // return the first k where sum of [0, k] > value
  int upper_bound(_Tp value) {
    //assert(all_of(vec_.begin(), vec_.end(), [](_Tp e) { return e >= (_Tp)0; }));
    int high = vec_.size(), low = -1;
    while (high - low > 1) {
      int mid = (high + low) >> 1;
      if (this->get(0, mid) <= value) {
        low = mid;
      } else {
        high = mid;
      }
    }
    return high;
  }

 private:
  std::vector<_Tp> vec_;
  std::vector<_Tp> sum_;

  void build() {
    sum_.assign(vec_.size() + 1, static_cast<_Tp>(0));
    for (size_t i = 0; i < vec_.size(); ++i) {
      sum_[i + 1] = sum_[i] + vec_[i];
    }
  }
};

