template <class T>
struct CumulativeSum {
   private:
    ::std::vector<T> data;

   public:
    CumulativeSum(){};
    CumulativeSum(int sz) : data(sz, 0){};
    CumulativeSum(::std::vector<T> v) { build(v); }

   private:
    T query(int k) {
        if(k < 0) return (0);
        return (data[std::min(k, (int)data.size() - 1)]);
    }

   public:
    T query(int l, int r) {
        if(l < 0 || r > data.size()) return (0);
        return query(r - 1) - query(l - 1);
    }
    void add(int k, T x) { data[k] += x; }
    void build() {
        for(int i = 1; i < data.size(); i++) data[i] += data[i - 1];
    }
    void build(::std::vector<T> &v) {
        data = v;
        for(int i = 1; i < data.size(); i++) data[i] += data[i - 1];
    }
};

void solve() {
    int n;
    scanf("%d", &n);
    std::vector<i64> a(n);
    rep(i, n) scanf("%lld", &a[i]);
    CumulativeSum<i64> s(a);
    std::vector<std::pair<i64, i64>> left(n), right(n);
    int ok, ng;
    std::vector<int> ans;
    repeat(i, 2, n - 1) {  // iで真ん中をぶった切る
        i64 sum_of_left = s.query(0, i);
        i64 sum_of_right = s.query(i, n);
        ok = i, ng = -1;
        while(ok - ng > 1) {
            int mid = ng + (ok - ng) / 2;
            if(s.query(0, mid) > sum_of_left / 2) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        if(abs(s.query(0, ok) - (sum_of_left - s.query(0, ok))) > abs(s.query(0, ng) - (sum_of_left - s.query(0, ng)))) {
            left[i].first = s.query(0, ng);
            left[i].second = sum_of_left - s.query(0, ng);
        } else {
            left[i].first = s.query(0, ok);
            left[i].second = sum_of_left - s.query(0, ok);
        }
        ok = n, ng = i;
        while(ok - ng > 1) {
            int mid = ng + (ok - ng) / 2;
            if(s.query(i, mid) > sum_of_right / 2) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        if(abs(s.query(i, ok) - (sum_of_right - s.query(i, ok))) > abs(s.query(i, ng) - (sum_of_right - s.query(i, ng)))) {
            right[i].first = s.query(i, ng);
            right[i].second = sum_of_right - s.query(i, ng);
        } else {
            right[i].first = s.query(i, ok);
            right[i].second = sum_of_right - s.query(i, ok);
        }
        // printf("%lld %lld %lld %lld\n", left[i].first, left[i].second, right[i].first, right[i].second);
        ans.emplace_back(std::max({left[i].first, left[i].second, right[i].first, right[i].second}) - std::min({left[i].first, left[i].second, right[i].first, right[i].second}));
    }
    printf("%lld\n", *std::min_element(begin(ans), end(ans)));
}

