const int MAX = 200000;
ll sum[MAX];
ll binary(ll s,ll e){
    ll l = s+1,r = e-1;

    ll mini = INT_MAX;

    while(r-l > 1){
        ll m = (l+r)/2;
        if(abs(sum[m] - sum[s]-(sum[e]-sum[m])) < mini){
            l = m;
            mini = abs(sum[m] - sum[s]-(sum[e]-sum[m]);
        }else {
            r = m;
        }
    }
    return l;
}


int main(){

    int n;
    cin>>n;

    ll a[n];

    for(int i=0;i<n;i++){
        cin>>a[i];
    }

    sum[0] = 0;
    for(int i=1;i<=n;i++){
        sum[i] = sum[i-1] + a[i-1];
    }

    ll ans = LLONG_MAX;

    for(int i=1;i<n;i++){
        ll pq = binary(0,i);
        ll rs = binary(i,n);

        ll pqrs[4] = {sum[pq]-sum[0],sum[i]-sum[pq],sum[rs]-sum[i],sum[n]-sum[rs]};

        sort(pqrs,pqrs+4);

        ans = min(ans,pqrs[3] - pqrs[0]);

    }

    cout<<ans<<endl;
}


