template<typename T> bool chmax(T& a, const T& b){if(a < b){a = b; return true;} return false;}


ll sep(const vector<ll>& v, int left, int right) {
    int ng = left, ok = right - 1;
    ll sum = v[right] - v[left];

    while(ok - ng > 1){
        int mid = (ok + ng) / 2;
        if((v[mid] - v[left])*2 >= sum){
            ok = mid;
        }else{
            ng = mid;
        }
    }

    if(ok == left + 1){
        return ok;
    }else{
        int a = ok - 1, b = ok;
        if(abs(sum - 2*(v[a] - v[left])) < abs(sum - 2*(v[b] - v[left]))){
            return a;
        }else{
            return b;
        }
    }
}

