ll LINF = numeric_limits<ll>::max() / 2;

int main()
{
    std::cin.sync_with_stdio(false);
    std::cin.tie(0);

    int n;
    cin >> n;
    vector<int> a(n);
    vector<int> ruisekiwa(n);
    for(int i = 0; i < n; i++){
        cin >> a[i];
        if(i == 0) ruisekiwa[i] = a[i];
        else ruisekiwa[i] = ruisekiwa[i-1] + a[i];
    }
    ll ans = LINF;
    for(int i = 1; i < n-2;i++){
        ll fdif = ruisekiwa[i];
        ll p,q;
        for(int j = 0; j < i; j++){
            if(abs(ruisekiwa[j] - (ruisekiwa[i]-ruisekiwa[j])) < fdif){
                p = ruisekiwa[j];
                q = ruisekiwa[i] - ruisekiwa[j];
                fdif = abs(p-q);
            }
        }
        ll bdif = ruisekiwa[n-1] - ruisekiwa[i];
        ll r,s;
        for(int j = i+1; j < n-1; j++){
            ll tr = ruisekiwa[j] - ruisekiwa[i];
            ll ts = ruisekiwa[n-1] - ruisekiwa[j];
            if(abs(tr - ts) < bdif){
                r = tr; s = ts;
                bdif = abs(r - s);
            }
        }
        ll ma = 0;
        ll mi = LINF;
        ll temp[] = {p,q,r,s};
        for(int i = 0; i < 4; i++){
            if(temp[i] > ma) ma = temp[i];
            if(temp[i] < mi) mi = temp[i];
        }
        if(ma - mi < ans) ans = ma - mi;
    }
    cout << ans << endl;
    return 0;
}

