using namespace std;

std::vector<std::vector<int> > vector_devide(int a1, int a2, int a3, std::vector<int> v);
std::vector<int> extract_vector(int begin, int end, std::vector<int> v);

int main(int argc, char const *argv[]) {
	int n;
	cin >> n;
	vector<int> a(n);
	int tmp;
	for (int i = 0; i < n; i++) {
		cin >> tmp;
		a[i] = tmp;
	}
	int min_diff = INT_MAX;
	for (int a1 = 1; a1 < a.size()-3; a1++) {
		for (int a2 = a1+1; a2 < a.size()-2; a2++) {
			for (int a3 = a2+1; a3<a.size()-1; a3++) {
				std::vector<std::vector<int> > tmp = vector_devide(a1, a2, a3, a);
				std::vector<int> sum;
				for (int i = 0; i < tmp.size(); i++) {
					sum.push_back(std::accumulate(tmp[i].begin(), tmp[i].end(), 0));
				}
				int min = *min_element(sum.begin(), sum.end());
				int max = *max_element(sum.begin(), sum.end());
				int diff = abs(max-min);
				if (diff < min_diff) min_diff = diff;
			}
		}
	}
	std::cout << min_diff << '\n';
	return 0;
}

std::vector<std::vector<int> > vector_devide(int a1, int a2, int a3, std::vector<int> v) {
	std::vector<std::vector<int> > result;
	result.push_back(extract_vector(0, a1, v));
	result.push_back(extract_vector(a1, a2, v));
	result.push_back(extract_vector(a2, a3, v));
	result.push_back(extract_vector(a3, v.size(), v));
	return result;
}

std::vector<int> extract_vector(int begin, int end, std::vector<int> v) {
	std::vector<int> result;
	for (int i = 0; i+begin < end; i++) {
		result.push_back(v[i+begin]);
	}
	return result;
}

