    for(x=1;x<N-2; x++){
        //左、右の総和を計算する
        ll leftsum = sum[x];
        ll rightsum = sum[N-1]-sum[x];

        for(j=y;j<=x;j++){
            //もし端っこまで行ったらその手前で切らないといけない
            if(j==x){
               y=x-1;
               break;
            }
            //全体の半分超えたところを覚えておく
            if(sum[j] > leftsum/2){
                y=j;
            }
        }
        for(k=z;k<N;k++){
            if(k==N-1){
                z=N-2;
                break;
            }

            if(sum[k]-sum[x] > rightsum/2){
                z=k;
            }
        }
        for(int j=y-1;j<=y;j++){
            if(j>=0){
                for(int k=z-1;k<=z;k++){
                    result[0] = sum[j];
                    result[1] = sum[x]-sum[j];
                    result[2] = sum[k]-sum[x];
                    result[3] = sum[N-1]-sum[k];                
                    sort(result.begin(), result.end());
                    value.push_back(result[3]-result[0]);                  
                }
            }
        }

    }
    sort(value.begin(), value.end());
    cout << value[0] << endl;
}

