pair<int64_t, int64_t> Split(const vector<int64_t> &vec, int left, int right, int64_t offset)
{
    int64_t sum = vec[right] - offset;
    int64_t half = sum / 2;

    int index = left;
    int power = (1 << 25);

    while (power > 0) {
        int next_index = index + power;
        power >>= 1;

        if (next_index < right && vec[next_index] - offset <= half) {
            index = next_index;
        }
    }

    if (index + 1 < right) {
        int64_t curr_diff = abs(vec[index] - offset - (vec[right] - vec[index]));
        int64_t next_diff = abs(vec[index + 1] - offset - (vec[right] - vec[index + 1]));

        if (next_diff < curr_diff) {
            index += 1;
        }
    }

    int64_t sum_left = vec[index] - offset;
    int64_t sum_right = vec[right] - vec[index];

    return {sum_left, sum_right};
}

int64_t Diff(const vector<int64_t> &vec, size_t mid)
{
    auto left = Split(vec, 0, mid, 0);
    auto right = Split(vec, mid + 1, vec.size() - 1, vec[mid]);

    auto big = max(max(left.first, left.second), max(right.first, right.second));
    auto small = min(min(left.first, left.second), min(right.first, right.second));

    return big - small;
}

int64_t Solve(vector<int64_t> &vec)
{
    for (size_t i = 1; i < vec.size(); i += 1) {
        vec[i] += vec[i - 1];
    }

    int64_t res = (1LL << 50);
    for (size_t i = 1; i + 2 < vec.size(); i += 1) {
        res = min(res, Diff(vec, i));
    }
    return res;
}

