#define INF 98765431219876543
#define bitcnt(a) (ll) __builtin_popcount((a))
#define lb(a, b) lower_bound((a).begin(), (a).end(), (b))
#define ub(a, b) upper_bound((a).begin(), (a).end(), (b))
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
typedef pair<string, string> PS;

vector<ll> v, imos;

P calc(P val, ll now) {
  return P(min(val.first, now), max(val.second, now));
}

ll ret = INF;
ll DFS(ll now, P val, ll dep) {
  if (dep == 3)
    return calc(val, imos.back() - imos[now]).second - calc(val, imos.back() - imos[now]).first;

  ll ok = now, ng = imos.size();
  while (ng - ok > 2) {
    ll m1 = (2 * ok + ng) / 3, m2 = (ok + ng * 2) / 3;

    ll m1Ans = DFS(m1, calc(val, imos[m1] - imos[now]), dep + 1);

    ll m2Ans = DFS(m2, calc(val, imos[m2] - imos[now]), dep + 1);

    if (m1Ans > m2Ans) {
      ok = (2 * ok + ng) / 3;
      ret = min(ret, m2Ans);
    } else {
      ng = (ok + 2 * ng) / 3;
      ret = min(ret, m1Ans);
    }
    // cout << ng << " " << ok << endl;
  }

  ret = min(ret, DFS(ok + 2, calc(val, imos[ok + 2] - imos[now]), dep + 1));
  ret = min(ret, DFS(ok, calc(val, imos[ok] - imos[now]), dep + 1));
  ret = min(ret, DFS(ok + 1, calc(val, imos[ok + 1] - imos[now]), dep + 1));
  return ret;
}

