void getLeftPos(uint& l, uint& c) {
  ll cval = B[c];
  ll pre_diff = abs((B[l - 1] - 0) - (cval - B[l - 1]));
  ll lsum, rsum;

  while(l < c) {
    lsum = B[l] - 0;
    rsum = cval - B[l];

    if (lsum - rsum > 0) {
      if (pre_diff < abs(lsum - rsum)) {
        --l;
      }
      return;
    }

    ++l;
    pre_diff = abs(lsum - rsum);
  }

  --l;
  return;
}

void getRightPos(uint& r, uint& c) {
  uint len = B.size() - 1;
  ll cval = B[c];
  ll eval = B[len];
  ll pre_diff = abs((B[r - 1] - cval) - (eval - B[r - 1]));
  ll lsum, rsum;

  while(r < len) {
    lsum = B[r] - cval;
    rsum = eval - B[r];

    if (lsum - rsum > 0) {
      if (pre_diff < abs(lsum - rsum)) {
        --r;
      }
      return;
    }
    ++r;
    pre_diff = abs(lsum - rsum);
  }

  --r;
  return;
}

ll getVal(uint l, uint c, uint r) {
  vector<ll> sum(4);
  sum[0] = B[l] - 0;
  sum[1] = B[c] - B[l];
  sum[2] = B[r] - B[c];
  sum[3] = B[B.size() - 1] - B[r];

  ll maxval = *max_element(sum.begin(), sum.end());
  ll minval = *min_element(sum.begin(), sum.end());

  return maxval - minval;
}

