template< typename T >
struct ruiseki{
    vector <T> s;
    int size;
    ruiseki(vector <T> &a){
        size = a.size()+1;
        s.resize(size);
        for(int i=1;i<size;i++) s[i] = s[i-1] + a[i-1];
    }
    ruiseki(){}
    T get(int a, int b){
        if(b > size-1) b = size-1;
        return s[b] - s[a];
    }
};
struct halve{
    struct ruiseki <int> r;
    halve(vector <int> &a){
        struct ruiseki <int> tmp(a);
        r = tmp;
    }
    tuple <int,int,int> get(int a, int b){ //半分わける場所、右側、左側を返す
        if(b > r.size) b = r.size;
        if(abs(a-b)<=1) return make_tuple(a,0,r.get(a, a+1));
        int sum = r.get(a, b);
        int left = a, right = b;
        while(abs(left - right)>1){
            int mid = (left +right)/2;
            r.get(a, mid+1) < sum/2 ? left = mid : right = mid;
        }
        int lsum1 = r.get(a, left+1),lsum2 = r.get(a, right+1);
        int rsum1 = sum - lsum1, rsum2 = sum - lsum2;
        if(abs(lsum1-rsum1)<abs(rsum2-lsum2)) return make_tuple(left+1, lsum1, rsum1);
        else return make_tuple(right+1, lsum2, rsum2);
    }
};
