            ll u = abs((csum[N] - csum[right]) - (csum[right] - csum[i]));
            ll v = abs((csum[N] - csum[right - 1]) - (csum[right - 1] - csum[i]));
            if (v < u) {
                --right;
            }
        }
        s[0] = csum[left];
        s[1] = csum[i] - csum[left];
        s[2] = csum[right] - csum[i];
        s[3] = csum[N] - csum[right];
        sort(s.begin(), s.end());
        ans = min(ans, abs(s[3] - s[0]));
    }

    cout << ans << endl;

    return 0;
}

