void solve() {

	ll N;
	cin >> N;
	vector<ll> vec(N);
	rep(i, N) cin >> vec[i];

	vector<ll> subsum(N + 1);
	rep(i, N + 1) {
		if (i == 0) subsum[i] = 0;
		else subsum[i] = subsum[i - 1] + vec[i - 1];
	}

	debug(subsum);

	vector<ll> L(N, 0);
	vector<ll> F(N, 0);

	F[0] = 0;
	L[0] = 2;

	for (ll i = 1; i <= N - 3; i++) {

		ll tmp = F[i - 1];

		while (1) {
			if (tmp == i - 1) break;
			if (abs(subsum[tmp + 1] - subsum[0] - subsum[i + 1] + subsum[tmp + 1]) < abs(subsum[tmp + 2] - subsum[0] - subsum[i + 1] + subsum[tmp + 2])) break;
			tmp++;
		}

		F[i] = tmp;

		tmp = L[i - 1];

		while (1) {
			if (tmp == N - 2) break;
			if (abs(subsum[tmp + 1] - subsum[i + 1] - subsum[N] + subsum[tmp + 1]) < abs(subsum[tmp + 2] - subsum[i + 1] - subsum[N] + subsum[tmp + 2])) break;
			tmp++;
		}

		L[i] = tmp;
	}

	debug(F);
	debug(L);

	ll ans = LLONG_MAX;

	for (ll i = 1; i <= N - 3; i++) {

		ll el1 = subsum[F[i] + 1] - subsum[0];
		ll el2 = subsum[i + 1] - subsum[F[i] + 1];
		ll el3 = subsum[L[i] + 1] - subsum[i + 1];
		ll el4 = subsum[N] - subsum[L[i] + 1];

		ll mx = max(el1, max(el2, max(el3, el4)));
		ll mn = min(el1, min(el2, min(el3, el4)));

		ans = min(ans, mx - mn);
	}

	cout << ans;

}


int main(int argc, char* argv[]) {
	if (argc == 2 && string(argv[1]) == "debug") debugFlag = true;
	solve();
	return 0;
}

