ll getDiff(ll N, ll i, ll j, ll k, vector<ll> *sum)
{
    ll p = (*sum)[i];
    ll q = (*sum)[j] - (*sum)[i];
    ll r = (*sum)[k] - (*sum)[j];
    ll s = (*sum)[N - 1] - (*sum)[k];

    ll minimam = min(min(p, q), min(r, s));
    ll maximam = max(max(p, q), max(r, s));

    return maximam - minimam;
}

