  for(int i = 0; i < N; i++){
    av += data[i];
  }
  av /= 2;

  for(int i = 0; i < N; i++){
  	if(tmp + data[i] >= av){
      if(av - tmp > tmp + data[i] - av) return i;
      else return i-1;
    }
    else{
      tmp += data[i];
    }
  }
}

