int find_index(const vector<long>& sum, long v)
{
  for (size_t i = 0; i < sum.size(); ++i) {
    if (sum[i] >= v) return i;
  }
  return sum.size();
}

int main()
{
  int N;
  cin >> N;
  vector<long> A(N, 0);
  vector<long> sum(N, 0);
  for (int i = 0; i < N; ++i) {
    cin >> A[i];
    sum[i] = i == 0 ? A[i] : sum[i - 1] + A[i];
  }

  long total = sum[sum.size() - 1];
  int b = find_index(sum, total / 4);
  int c = find_index(sum, 2 * total / 4);
  int d = find_index(sum, 3 * total / 4);

  /*
  cerr << total << endl;
  for (auto s: sum) cerr << s << " ";
  cerr << endl;
  cerr << b << " " << c << " " << d << endl;
  */

  const int delta = N / 4;
  long min_diff = -1;
  for (int i1 = b - delta; i1 <= b + delta; ++i1) {
    if (i1 < 0) continue;
    for (int i2 = c - delta; i2 <= c + delta; ++i2) {
      if (i1 >= i2) continue;
      for (int i3 = d - delta; i3 <= d + delta; ++i3) {
        if (i2 >= i3 or i3 >= sum.size() - 1) continue;

        vector<long> pqrs{
          sum[i1],
          sum[i2] - sum[i1],
          sum[i3] - sum[i2],
          total - sum[i3],
        };
        sort(pqrs.begin(), pqrs.end());
        long diff = pqrs[3] - pqrs[0];
        if (min_diff < 0 or min_diff > diff) {
          // cerr << " " << i1 << " " << i2 << " " << i3 << " " << diff << endl;
          min_diff = diff;
        }
      }
    }
  }

  cout << min_diff << endl;
  return 0;
}

