using namespace std;

long long int N;

long long int A[200005];
vector<long long int> S;


long long int min4(long long int p, long long int q, long long int r, long long int s) {

	long long int ret = p;
	if (ret > q) { ret = q; }
	if (ret > r) { ret = r; }
	if (ret > s) { ret = s; }

	return ret;
}

long long int max4(long long int p, long long int q, long long int r, long long int s) {

	long long int ret = p;
	if (ret < q) { ret = q; }
	if (ret < r) { ret = r; }
	if (ret < s) { ret = s; }

	return ret;
}

int main(void) {

	cin >> N;

	long long int tmp;
	for (int i = 1; i <= N; i++) {
		cin >> tmp;
		A[i] = tmp;
	}

	S.push_back(0);
	for (int i = 1; i <= N; i++) {
		S.push_back(A[i] + S[i - 1]);
	}
	S.push_back(999999999999999);

	long long int ans = 9999999999999999;

	long long int value;

	long long int P, Q, R, T;

	int J1, J2;
	J1 = 1; J2 = 3;
	for (int M = 2; M <= N - 2; M++) {
		while (J1 <= M - 1 && abs(S[M] - 2 * S[J1 + 1]) < abs(S[M] - 2 * S[J1])) { J1++; }

		while (J2 <= N - 1 && abs(S[N] - 2 * S[J2 + 1] + S[M]) < abs(S[N] - 2 * S[J2] + S[M])) { J2++; }

		//cout << "J1= " << J1 << " M= " << M << " J2= " << J2 << endl;

		P = S[J1] - S[0];
		Q = S[M] - S[J1];
		R = S[J2] - S[M];
		T = S[N] - S[J2];

		value = max4(P, Q, R, T) - min4(P, Q, R, T);

		if (ans > value) { ans = value; }

	}//M-loop fin

	//cout << ans << endl;

	system("pause");
	return 0;
}

