ll d(int n, vector<ll> a) {
  vector<ll> sum(n);
  sum[0] = a[0];
  for(int i=1;i<n;i++) {
    sum[i] = sum[i-1] + a[i]; 
  }

  ll result = numeric_limits<ll>::max();

  int c = 1;
  int d = 2;
  int e = 3;
  while(e<n-1) {
    ll r = sum[e-1] - sum[d-1]; // 2 - 1;
    ll s = sum[n-1] - sum[e-1]; // n-1 - 2;
    //cout << e << "-> " << r << ", " << s << endl;
    ll next_r = sum[e] - sum[d-1];
    ll next_s = sum[n-1] - sum[e];

    if(abs(r-s) < abs(next_s - next_r)) {
      break;
    }
    e++;
  }
  ll p = sum[c-1];
  ll q = sum[d-1] - sum[c-1];
  ll r = sum[e-1] - sum[d-1];
  ll s = sum[n-1] - sum[e-1];

  result = min(
      abs(max(p, max(q, max(r, s)))- min(p, min(q, min(r, s))))
      , result);
  //  cout << " b -> 0-" << c-1 << " c -> " << c << "-" << d-1 << " d -> " << d << "-" << e-1 << " e-> " << e << "-" << n-1 <<endl;
  //cout << " p -> " << sum[c-1] << " q -> " << sum[d-1] - sum[c-1] << " r -> " << sum[e-1] - sum[d-1] << " e-> " << sum[n-1] - sum[e-1] << endl;
  //  cout << " result " << result << endl;

  for(d=2;d<n-2;d++) {
    while(c<d-1) {
      if(abs(sum[c-1] - (sum[d-1] - sum[c-1])) < abs(sum[c] - (sum[d-1] - sum[c]))) {
	break;
      }
      c++;
    }
    while(e<n-1) {
      if(abs((sum[n-1] - sum[e-1]) - (sum[e-1] - sum[d-1])) < 
	  abs((sum[n-1] - sum[e]) - (sum[e] - sum[d-1]))) {
	break;
      }
      e++;
    }
    p = sum[c-1];
    q = sum[d-1] - sum[c-1];
    r = sum[e-1] - sum[d-1];
    s = sum[n-1] - sum[e-1];
    result = min(
	abs(max(p, max(q, max(r, s)))- min(p, min(q, min(r, s))))
	, result);
    //cout << " b -> 0-" << c-1 << " c -> " << c << "-" << d-1 << " d -> " << d << "-" << e-1 << " e-> " << e << "-" << n-1 <<endl;
    //cout << " p -> " << sum[c-1] << " q -> " << sum[d-1] - sum[c-1] << " r -> " << sum[e-1] - sum[d-1] << " e-> " << sum[n-1] - sum[e-1] << endl;
    //cout << " result " << result << endl;
  }

  return result;

}
