void check(ll sum[],ll i,ll j,ll k){
	if(i<0 || i>j || j>k || k>n-1){
		return;
	}
	ll a = sum[i];
	ll b = sum[j]-sum[i];
	ll c = sum[k]-sum[j];
	ll d = sum[n-1]-sum[k];
	ll mx = max(max(a,b),max(c,d));
	ll mn = min(min(a,b),min(c,d));
	if(ans > (mx-mn)){
		//cout<<ans<<" ";
		ans = mx-mn;
		//cout<<ans<<"\n";
	}
}

