		ll i = lower_bound(sum,sum+n,(sum[j]+1)/2)-sum;
		ll k = lower_bound(sum,sum+n,(sum[n-1]+sum[j]+1)/2)-sum;
		//cout<<i<<" "<<j<<" "<<k<<"\n";
		check(sum,i-1,j,k-1);
