                mn = min(dp[i] - dp[first + j], mn);
                mn = min(dp[first + j] - dp[0], mn);
                mn = min(dp[n] - dp[second + k], mn);
                mn = min(dp[second + k] - dp[i], mn);
                ans = min(ans, mx - mn);
            }
