ll ecut(int from, int to)
{
    if (to - from <= 1)
        return -1;

    int s = from + 1, t = to, mid;
    ll target = (a[t] + a[s]) / 2;
    // cout << s << ' ' << t << ' '<< a[s] << ' ' << a[t] <<  " target " << target << endl;
    while (s != t)
    {
        mid = (s + t) / 2;
        if (a[mid] == target)
            s = t = mid;
        else if(a[mid] > target)
            t = mid;
        else
            s = mid + 1;
        // cout << s << ' ' << t<< endl;
    }
    // cout << "**************" << endl;

    ll ans = a[to];
    rep(i, 3)
    {
        int p = s - 1 + i;
        // cout << p << ' ' << from << endl;
        if (p <= from or p > to) continue;
        ll cand = max(a[p] - a[from], a[to] - a[p]);
        ans = min(ans, cand);
        // cout << p << ' ' << from << ' ' << to << endl;
    }
    return ans;
}
