int find_position(int start,int end) {
	int slash = start + 1;
	long long difference = abs(diff(start, slash) - diff(slash, end));
	//cout << difference << endl;
	while (difference >= abs(diff(start, slash) - diff(slash, end))) {
		difference = abs(diff(start, slash) - diff(slash, end));
		slash++;
	}
	slash--;
	//cout << slash << endl;
	return slash;
}

