  int n;
  cin>>n;
  long long a[n];
  REP(i,n){
    cin>>a[i];
  }
  long long s[n];
  long long rs[n];
  REP(i,n){
    if(i==0){
      s[i] = a[i];
    }else{
      s[i] = s[i-1]+a[i];
    }
  }

  for(int i=n-1;i>=0;i--){
    if(i==n-1){
      rs[i] = a[i];
    }else{
      rs[i] = rs[i+1]+a[i];
    }
  }

  int b[n];//0~iまでの要素をB,Cとして取った時の最適なBの右端
  int e[n];//i~n-1までの要素をD,Eとして取った時の最適なEの左端
  //多分このbとeの計算がおかしい...
  int temp;
  REP(i,n){
    if(i==0){
      b[i] = -1;
    }else if(i==1){
      b[i] = 0;
    }else{
      temp = b[i-1];
      while(temp+1<n){
        if(s[i]-2*s[temp+1]>=0){
          temp++;
        }else{
          break;
        }
      }
      while(temp-1>=0){
        if(s[i]-2*s[temp]<0){
          temp--;
        }else{
          break;
        }
      }
      if(temp+1<n){
        if(abs(s[i]-2*s[temp+1])<abs(s[i]-2*s[temp])){
          b[i] = temp+1;
        }else{
          b[i] = temp;
        }
      }else{
        b[i] = temp;
      }
    }
  }

  for(int i=n-1;i>=0;i--){
    if(i==n-1){
      e[i] = -1;
    }else if(i==n-2){
      e[i] = n-1;
    }else{
      temp = e[i+1];
      while(temp-1>=0){
        if(rs[i]-2*rs[temp-1]>=0){
          temp--;
        }else{
          break;
        }
      }

      while(temp+1<n){
        if(rs[i]-2*rs[temp]<0){
          temp--;
        }else{
          break;
        }
      }

      if(temp-1>=0){
        if(abs(rs[i]-2*rs[temp-1])<abs(rs[i]-2*rs[temp])){
          e[i] = temp-1;
        }else{
          e[i] = temp;
        }
      }else{
        e[i] = temp;
      }
    }
  }

  long long ans=-1;
  vector<long long> sums;
  REP(i,n){
    if(i==0 || i>=n-2)continue;
    sums.clear();
    sums.push_back(s[b[i]]);
    sums.push_back(rs[e[i+1]]);
    sums.push_back(s[i]-s[b[i]]);
    sums.push_back(rs[i+1]-rs[e[i+1]]);
    sort(sums.begin(), sums.end());
    if(ans<0){
      ans = sums[3]-sums[0];
    }else{
      ans = min(ans,sums[3]-sums[0]);
    }
  }

  cout<<ans<<endl;

  return 0;
}

