long long diff(int start, int end) {
	long long diff = 0;

	diff = sum_A[end - 1] - sum_A[start - 1];

	return diff;
}

int find_position(int start,int end) {
	int slash = start + 1;
	while (abs(diff(start, slash) - diff(slash, end)) >= abs(diff(start, slash+1) - diff(slash+1, end)) && slash < end) {
		slash++;
	}
	//cout << slash << endl;
	return slash;
}

int main() {
	long long ans;

	int N;
