			sum_A[i] = A[i];
		}
		else {
			sum_A[i] = sum_A[i - 1] + A[i];
		}
		//cout << sum_A[i] << endl;
	}

	for (int middle = 2;middle <= N - 2;middle++) {
		int left = find_position(0, middle);
		int right = find_position(middle, N);
		vector<long long> P_Q_R_S(4);
		P_Q_R_S[0] = sum_A[left - 1];
		P_Q_R_S[1] = sum_A[middle - 1] - sum_A[left - 1];
