ll N;
ll bit[1000010];

void bit_init(vector<ll> v){
	if(!v.empty()){
		N=v.size();
		for(ll x=1; x <= N; ++x) bit[x] = v[x];
		for(ll x=1; x < N; ++x) bit[x+(x&-x)] += bit[x];
	}
}
void bit_add(ll a, ll w){
		for(ll x=a; x <= N; x+=x&-x)bit[x]+=w;
}
ll bit_sum(ll a){
	ll ret=0;
	for(ll x=a;x>0;x-=x&-x) ret+=bit[x];
	return ret;
}

int main(){
	ll n;cin>>n;
	vector<ll> a(n+1);

	rep(i,n){
	  cin>>a[i+1];
	}
	bit_init(a);
  ll left,right,mid,ans=1e10,B,C,D,E,max_num,min_num;
  FOR(i,2,n-1){
  	// 前半部分は1~i
  	left = 1,right= i;
  	while (right!=left+1) {
  	    mid =(right+left)/2;
  	    // i~mid+1までの和　midまでの和
  	    if(bit_sum(i)-bit_sum(mid)>=bit_sum(mid)){
  	    	left=mid;
  	    }else right=mid;
  	}

  	if(abs(bit_sum(i)-bit_sum(left)-bit_sum(left))<abs(bit_sum(i)-bit_sum(right)-bit_sum(right))){
  		B=bit_sum(i)-bit_sum(left);
  		C=bit_sum(left);
  	}else{
  		B=bit_sum(i)-bit_sum(right);
  		C=bit_sum(right);
  	}

  	left = i+1,right= n;
  	// 後半部分はi+1~n
  	while (right!=left+1) {
  	    mid =(right+left)/2;
  	    // n~mid+1までの和, mid~i+1までの和
  	    if(bit_sum(n)-bit_sum(mid)>=bit_sum(mid)-bit_sum(i)){
  	    	left=mid;
  	    }else right=mid;
  	}
  	if(abs(bit_sum(n)-bit_sum(left)-bit_sum(left)+bit_sum(i))<abs(bit_sum(n)-bit_sum(right)-bit_sum(right)+bit_sum(i))){
  		D=bit_sum(n)-bit_sum(left);
  		E=bit_sum(left)-bit_sum(i);
  	}else{
  		D=bit_sum(n)-bit_sum(right);
  		E=bit_sum(right)-bit_sum(i);
  	}
  	max_num=max(B,max(C,max(D,E)));
  	min_num=min(B,min(C,min(D,E)));
  	ans=min(max_num-min_num,ans);
  }
  cout<<ans<<endl;
  return 0;
}

