#define INF (1ll<<60)
using namespace std;

int main(){

	int n; cin >> n;
	vector<ll> a(n);
	// S(n) = Σ[0, n);
	vector<ll> sum(n+1);
	sum[0] = 0;
	for( int i = 0; i < n; ++i ){
		ll k; cin >> k;
		a[i] = k;
		sum[i+1] = sum[i] + k;
	}

	ll ans = INF;
	// 空ではない部分列なので最初の二分割（Q と R の間）の位置は 2 <= x <= n-2
	for( int x = 2; x <= n-2; ++x ){
		auto pitr = lower_bound( sum.begin(), (sum.begin()+=x), sum[x]/2 );
		// 二分探索したあとにその 1 つ前の要素も見てどちらのほうが sum[x]/2 近いか見る
		// f <= sum[x]/2 <= g
		ll g = *pitr, f = *(--pitr);
		ll presum1 = sum[x]/2;
		ll p = ( abs(presum1-f) >= abs(presum1-g) ) ? g : f;
		ll q = sum[x] - p;

		// (sum[n]-sum[x])/2 + sum[x] = (sum[n]+sum[x])/2 
		auto ritr = lower_bound( (sum.begin()+=x), sum.end(), (sum[n]+sum[x])/2 );
		// f <= (sum[n]+sum[x])/2 <= g
		ll i = *ritr, h = *(--ritr);
		ll presum2 = (sum[n]+sum[x])/2;
		ll r = ( abs(presum2-h) >= abs(presum2-i) ) ? i : h;
		ll s = sum[n] - r;
		r -= ( p + q );

		// cout << p << " " << q << " " << r << " " << s << endl;
		ans = min( ans, abs(max({p, q, r, s})-min({p, q, r, s})) );
	}

	cout << ans << endl;
	return 0;
}

