int cal(int l, int r) {
    int mid1, mid2;
    LL val1, val2;
    int L = l, R = r;
    while(l < r) {
        mid1 = (l + r) / 2;
        mid2 = (mid1 + r + 1) / 2;
        val1 = abs(pre[mid1] - pre[L - 1] - pre[R] + pre[mid1]);
        val2 = abs(pre[mid2] - pre[L - 1] - pre[R] + pre[mid2]);
        if(val1 <= val2) r = mid2 - 1;
        else l = mid1 + 1;
    }
    if(l == R) l = R - 1;
    if(r == R) r = R - 1;
    //cout << "cal1 " << L << " " << R << " " << l << " " << r << endl;
    if(abs(pre[R] - pre[l] - pre[l] + pre[L - 1]) < abs(pre[R] - pre[r] - pre[r] + pre[L - 1])) return l;
    else return r;
}

int cal1(int l, int r) {
    LL minn = abs(pre[r] - pre[l] - pre[l] + pre[l - 1]);
    int pos = l;
    for(int i = l;i < r;i++) {
        LL t = abs(pre[r] - pre[i] - pre[i] + pre[l - 1]);
        if(t < minn) pos = i, minn = t;
    }
    return pos;
}

