using namespace std;

int main(void){

    int n;
    cin >> n;
    int m[1000000000];
    int sum = 0;

    for(int a = 0; a < n; a++){
        cin >> m[a];
        sum += m[a];
    }

    int o[4] = {0, 0, 0, 0};
    int oo[3];
    int b = 0;
    for(int c = 0; c < 3; c++){
        while(sum/4 >= o[c]){
            o[c] += m[b];
            b++;
        }
        oo[c] = m[b + 1];
    }
    o[3] = sum - o[0] - o[1] - o[2];

    int ans[8] = {0, 0, 0, 0, 0, 0, 0, 0};
    for(int f = 0; f < 2; f++){
        for(int g = 0; g < 2; g++){
            for(int h = 0; h < 2; h++){
                if(f){
                    o[0] += oo[0];
                    o[1] -= oo[0];
                }
                if(g){
                    o[1] += oo[1];
                    o[2] -= oo[1];
                }
                if(h){
                    o[2] += oo[2];
                    o[3] -= oo[2];
                }
                for(int d = 0; d < 3; d++){
                    for(int e = d + 1; e < 4; e++){
                        if(ans[4*f+2*g+h] < abs(o[d] - o[e]))ans[4*f+2*g+h] = abs(o[d] - o[e]);
                    }
                }
                if(f){
                    o[0] -= oo[0];
                    o[1] += oo[0];
                }
                if(g){
                    o[1] -= oo[1];
                    o[2] += oo[1];
                }
                if(h){
                    o[2] -= oo[2];
                    o[3] += oo[2];
                }
            }
        }
    }

    int answer = 2000000;
    for(int i = 0; i < 8; i++){
        if(answer > ans[i])answer = ans[i];
    }
    cout << answer;
    return 0;    
}

