using namespace std;
typedef long long ll;
typedef vector<int> vi;
typedef vector<long long> vl;

int main() {
    int N;
    cin >> N;
    vl A(N);
    vl sum(N + 2);
    rep(i, N) {
        cin >> A[i];
        sum[i + 1] = A[i];
    }
    for (int i = 0; i < N; i++) {
        sum[i + 1] += sum[i];
    }
    sum[N + 1] = __LONG_LONG_MAX__;


    ll ans = __LONG_LONG_MAX__;
    for (int i = 0; i < N; i++) {
        if (i < 2) continue;
        if (i > N - 2) continue;

        // 右
        ll X = sum[i];
        int l = 0;
        int r = i + 1;
        while (r - l >= 1) {
            int mid = (r + l) / 2;
            if (2 * sum[mid] >= X) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        // r or r-1がX/2にもっとも近い
        ll P, Q;
        ll P1 = sum[r]; ll Q1 = X - P1;
        ll P2 = sum[r - 1]; ll Q2 = X - P2;
        if (abs(Q1 - P1) > abs(Q2 - P2)) {
            P = P2; Q = Q2;
        } else {
            P = P1; Q = Q1;
        }

        // 左
        ll Y = sum[N] - sum[i];
        l = i + 1;
        r = N + 1;
        while (r - l >= 1) {
            int mid = (r + l) / 2;
            if (2 * (sum[mid] - sum[i]) >= Y) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        ll R, S;
        ll R1 = sum[r] - sum[i]; ll S1 = Y - R1;
        ll R2 = sum[r - 1] - sum[i]; ll S2 = Y - R2;
        if (abs(S1 - R1) > abs(S2 - R2)) {
            R = R2; S = S2;
        } else {
            R = R1; S = S1;
        }

        ans = min(ans, abs(max(P, max(Q, max(R, S))) - min(P, min(Q, min(R, S)))));
    }
    cout << ans << endl;
}

