long long solve(long long a, long long b, long long c,long long d){
    long long myArray[4];
    myArray[0]=a; myArray[1]=b; myArray[2]=c; myArray[3]=d;
    sort(myArray,myArray+4);
    long long ret = myArray[3]-myArray[0];
    return ret;
}

int main(){
    int N;
    long long A[200000];
    vector<long long> sum;
    cin>>N;
    for(int i=0;i<N;i++){
        cin>>A[i];
        if(i!=0){
            sum.push_back(A[i]+sum[i-1]);
        }else{
            sum.push_back(A[i]);
        }
    }
    long long ans=INF;
    long long total=sum[N-1];
    //cout<<"debug"<<endl;
    //cout<<total<<endl;
    for(int i=1;i<N-2;i++){//0からiまでが左2つの列に属する．
        long long left=sum[i];//左半分の和
        long long right=total-left;
        //cout<<left<<' '<<right<<endl;
        auto lower_left=lower_bound(sum.begin(), sum.end(), ((left+1)/2) );
        long long pattern1a, pattern1b, pattern2a, pattern2b;
        if(*lower_left != sum[i] && *lower_left != sum[0]){
            pattern1a=*lower_left;
            pattern1b=left-pattern1a;
            lower_left--;
            pattern2a=*lower_left;
            pattern2b=left-pattern2a;
        }else if(*lower_left == sum[i]){
            pattern1a=sum[i-1];
            pattern1b=left-pattern1a;
            pattern2a=INF;
            pattern2b=0;
        }else{
            pattern1a=A[0];
            pattern1b=left-pattern1a;
            pattern2a=INF;
            pattern2b=0;
        }
        auto lower_right=lower_bound(sum.begin(), sum.end(), (left+(right+1)/2) );
        long long pattern1c, pattern1d, pattern2c, pattern2d;
        if(*lower_right != total && *lower_right != sum[i+1]){
            pattern1c=*lower_right-left;
            pattern1d=right-pattern1c;
            lower_right--;
            pattern2c=*lower_right-left;
            pattern2d=right-pattern2c;
        }else if(*lower_right == total){
            pattern1c=sum[N-2]-left;
            pattern1d=right-pattern1c;
            pattern2c=INF;
            pattern2d=0;
        }else{
            pattern1c=A[i+1];
            pattern1d=right-pattern1c;
            pattern2c=INF;
            pattern2d=0;
        }
        //cout<<pattern1a<<' '<<pattern1b<<' '<<pattern1c<<' '<<pattern1d<<endl;
        //cout<<pattern2a<<' '<<pattern2b<<' '<<pattern2c<<' '<<pattern2d<<endl;
        ans=min(ans,solve(pattern1a,pattern1b,pattern1c,pattern1d));
        ans=min(ans,solve(pattern1a,pattern1b,pattern2c,pattern2d));
        ans=min(ans,solve(pattern2a,pattern2b,pattern1c,pattern1d));
        ans=min(ans,solve(pattern2a,pattern2b,pattern2c,pattern2d));
    }

    cout<<ans<<endl;

    return 0;
}

