int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<int> a(n), s(n+1);
  REP(i, n) cin >> a[i];
  FORE(i, 1, n) s[i] = s[i-1] + a[i-1];

  auto aux1 = [&](int m, int x){return s[m]<=x-s[m];};
  auto aux2 = [&](int m, int x, int y){return s[m]-y<=x-s[m];};

  int m = 1000000000;

  FORE(b, 2, n-2){

    int l = 1, r = b;
    int a;

    while(1){
      if(l == r){ a = l; break; }
      else if(l+1 == r){ a = aux1(r,s[b]) ? r : l; break; }
      else{
	a = (l+r)/2;
	if(aux1(a,s[b])) l = a;
	else r = a;
      }
    }

    if(a<b-1) if(abs(2*s[a]-s[b]) > abs(2*s[a+1]-s[b])) ++a;

    l = b+1;
    r = n;
    int c;

    while(1){
      if(l == r){ c = l; break; }
      else if(l+1 == r){ c = aux2(r,s[n],s[b]) ? r : l; break; }
      else{
	c = (l+r)/2;
	if(aux2(c,s[n],s[b])) l = c;
	else r = c;
      }
    }

    if(c<n-1) if(abs(2*s[c]-s[b]-s[n]) > abs(2*s[c+1]-s[b]-s[n])) ++c;

    m = min(m, max({s[a], s[b]-s[a], s[c]-s[b], s[n]-s[c]}) - min({s[a], s[b]-s[a], s[c]-s[b], s[n]-s[c]}));    
  }

  cout << m << endl;

  return 0;
}

