ll calc(int idx1, int idx2, ll left, ll right, const vector<ll> acc){
    ll b = acc[idx1];
    ll c = left - acc[idx1];
    ll d = acc[idx2] - left;
    ll e = acc[n] - acc[idx2];
    ll mn = min({b, c, d, e});
