        ll rmax = max(D,E);
        if (abs(D2-E2) < abs(D-E)) {
            rmin = min(D2,E2);
            rmax = max(D2,E2);
        }
        answer = min(answer, max(lmax, rmax) - min(lmin, rmin));
    }
    cout << answer << endl;
}

