LL getSum(int l,int r)
{
    return sum[r] - sum[l - 1];
}

LL minisolve(int l,int ptr,int r)
{
    vector<LL>vec;
    vec.push_back(sum[l]);
    vec.push_back(sum[ptr] - sum[l]);
    vec.push_back(sum[r] - sum[ptr]);
    vec.push_back(sum[n] - sum[r]);
    LL mx = 0 , mn = 1e18;
    for(LL i : vec)mx = max(mx,i),mn = min(mn,i);

    return ABS(mx - mn);
}

LL job(int lptr,int rptr)
{
    LL ans = 1e18;
    if(rptr - lptr < 3 or rptr > n)return ans;

    int l = lptr + 1, r = rptr - 1;

    int lo = l , hi = r - 1, ptr = -1;
    while(lo <= hi){
        int mid = (lo + hi) >> 1;
        if(getSum(l,mid) <= getSum(mid + 1,r)){
            ptr = mid;
            lo = mid + 1;
        }else{
            hi = mid - 1;
        }
    }

    if(ptr != -1){
        ans = min(ans,minisolve(lptr,ptr,rptr - 1));
    }
    lo = l , hi = r - 1;
    while(lo <= hi){
        int mid = (lo + hi) >> 1;
        if(getSum(l,mid) >= getSum(mid + 1,r)){
            ptr = mid;
            hi = mid - 1;
        }else{
            lo = mid + 1;
        }
    }
    if(ptr != -1){
        ans = min(ans,minisolve(lptr,ptr,rptr - 1));
    }
    return ans;
}
LL solve()
{
    FOR(i,1,n)sum[i] = sum[i - 1] + ara[i];

    int rptr = n + 1;
    LL lsum = 0,rsum = 0;
    LL ans = 1e18;
    for(int lptr = 1;lptr <= n;lptr++){
        lsum += ara[lptr];
        ans = min(ans,job(lptr,rptr));

        while(rptr - 1 > lptr and rsum + ara[rptr - 1] <= lsum){
            rptr--;
            rsum += ara[rptr];
            ans = min(ans,job(lptr,rptr));
        }
        ans = min(ans,job(lptr,rptr));


    }
    return ans;
}
