template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
typedef long long ll;

ll N;
ll A[200010];

ll get_sum (int l, int r) 
{
    ll p = A[r - 1];
    ll m = (l == 0) ? 0 : A[l - 1];
    return p - m;
}

// first = min, second = max
pair < ll, ll > get_diff (int l, int r)
{
    int lt = l + 1, rt = r - 1;
    ll sum = get_sum(l, r);
    sum = sum / 2 + sum % 2;
    while (rt - lt > 1) {
        int mid = (lt + rt) / 2;
        ll suml = get_sum(l, mid);
        ll sumr = get_sum(mid, r);
        if (suml >= sum) rt = mid;
        else lt = mid;
    }
    return get_sum(l, lt);
}

int main ()
{
    cin >> N;
    REP(i,N) cin >> A[i];
    REP(i,N) A[i + 1] = A[i] + A[i + 1];

    ll ans = 1e18;
    for (int i = 2; i <= N - 2; i++) {
        pair < ll,ll > diff_l = get_diff(0, i);
        pair < ll,ll > diff_r = get_diff(i, N);
        ans = min(ans, abs(min(diff_l.first, diff_r.first) - max(diff_l.second, diff_r.second)));
    }

    cout << ans << endl;

    return 0;
}

