    {
      int ind1=upper_bound(pre+1,pre+n+1,pre[i]/2)-pre;
      int ind2=ind1-1;
      int ind3=upper_bound(pre+1,pre+n+1,pre[i]+(pre[n]-pre[i])/2)-pre;
      int ind4=ind3-1;
      ll p1,p2,p3,p4,diff=(ll)1e15,diff2=(ll)1e15;
      if(ind1!=i) p1=pre[ind1],p2=pre[i]-pre[ind1],diff=abs(p1-p2);
      if(ind2)
	{
	  if(abs(pre[i]-pre[ind2]-pre[ind2])<=diff)
	    p1=pre[ind2],p2=pre[i]-pre[ind2],diff=abs(p1-p2);
	}
      if(ind3!=n) p3=pre[ind3]-pre[i],p4=pre[n]-pre[ind3],diff2=abs(p3-p4);
      if(ind4!=i)
	{
	  if(abs(pre[n]-pre[ind4]-(pre[ind4]-pre[i]))<=diff2)
	    p3=pre[ind4]-pre[i],p4=pre[n]-pre[ind4],diff2=abs(p3-p4);
	}
      vector<ll> tmp;
      tmp.pb(p1); tmp.pb(p2); tmp.pb(p3); tmp.pb(p4);
      sort(all(tmp));
      ans=min(ans,tmp.back()-tmp[0]);
    }
  cout<<ans<<endl;
