        for(int j = i_lsep; j < i-1; j++){
            if(abs(sumA[i] - sumA[j+1] - sumA[j+1]) > tmp_l){
                break;
            }else{
                tmp_l = abs(sumA[i] - sumA[j+1] - sumA[j+1]);
                i_lsep = j+1;
            }
