		right = (high + low) / 2;

		for (int j = left - 1; j <= left + 1; ++j) {
			for (int k = right - 1; k <= right + 1; ++k) {
				P = B[j] - B[0];
				Q = B[i] - B[j];
				S = B[k] - B[i];
				R = B[N] - B[k];
				cnt = abs(max({ P,Q,R,S }) - min({ P,Q,R,S }));
				ans = min(ans, cnt);
			}
		}

	}
	cout << ans << endl;

	return 0;
}

