int n;

ll pre[200001];

ll get(int a, int b)
{
    if (a > b) return 0; //flag
    return pre[b]-pre[a-1];
}

ll diff(ll2 p) { return p.second-p.first;}

ll getMin(ll2 p)
{
    return min(p.first, p.second);
}

ll getMax(ll2 p)
{
    return max(p.first, p.second);
}

ll2 solve(int a, int b) //try to best balance [a,b] > size 1
{
    ll2 ret1, ret2;

    //find best k s.t [a, mid] and [mid+1, b] are balanced
    int lo = a;
    int hi = b-1;

    //favors the left >= right
    while (hi > lo)
    {
        int mid = (lo+hi)/2;
        if (get(a, mid) < get(mid+1, b)) lo = mid+1; //shift to the right
        else hi = mid; //shift to the left
    }

    ret1 = make_pair(get(a, lo), get(lo+1, b));
    if (ret1.first > ret1.second) swap(ret1.first, ret1.second);
    assert(diff(ret1) >= 0);

    lo = a;
    hi = b-1;

    //favors the right >= left
    while (hi > lo)
    {
        int mid = (lo+hi+1)/2;
        if (get(a, mid) > get(mid+1, b)) hi = mid-1; //shift to the left
        else lo = mid; //shift to the right
    }

    ret2 = make_pair(get(a, lo), get(lo+1, b));
    if (ret2.first > ret2.second) swap(ret2.first, ret2.second);
    assert(diff(ret2) >= 0);

    if (diff(ret2) < diff(ret1)) return ret2;
    return ret1;
}

