    cin >> n;

    for (int i = 1; i <= n; i++) cin >> pre[i];
    for (int i = 1; i <= n; i++) pre[i] += pre[i-1];


    ll ret = 1e18;
    for (int i = 2; i <= n-2; i++) // [1, i] and [i+1, n]
    {
        ll2 leftAns = solve(1, i);
        ll2 rightAns = solve(i+1, n);

        ll mn = min(getMin(leftAns), getMin(rightAns));
        ll mx = max(getMax(leftAns), getMax(rightAns));

        ret = min(ret, mx-mn);

    }

    cout << ret << endl;

    return 0;

}

