const int INF = INT_MAX / 2;
const ll LLINF = 1LL<<60;
constexpr ll MOD = 1000000007;
const double EPS = 1e-9;

//[b, e)
void solve(vll& A, vll& acc, int b, int e, ll& sum1, ll& sum2) {
  ll targetSum2 = acc[e] - acc[b];
  ll ub = e;
  ll lb = b;
  while(ub - lb > 1) {
    ll mid = (ub + lb) / 2;
    ll msum = acc[e] - acc[mid];
    if(msum * 2 >= targetSum2) {
      //見たのがより上
      lb = mid;
    } else {
      ub = mid;
    }
  }

  //以上の時
  if(abs((acc[e] - acc[ub]) - (acc[ub] - acc[b])) < abs((acc[e] - acc[lb]) - (acc[lb] - acc[b]))) {
    sum1 = acc[ub] - acc[b];
    sum2 = acc[e] - acc[ub];
  } else {
    sum1 = acc[lb] - acc[b];
    sum2 = acc[e] - acc[lb];
  }

  if(sum1 > sum2) swap(sum1, sum2);
}

