    s2 = static_cast<long long int>(upper_bound(s + s1, s + n, sum*2)-1 - s);

    s2 = max(s1+1,min(n-3,s2));
    s3 = static_cast<long long int>(upper_bound(s + s2, s + n, sum*3)-1 - s);

    s3 = max(s2+1,min(n-2,s3));

    s4 = n-1;

    ll x = max(s[s1],max(s[s2]-s[s1],max(s[s3]-s[s2],s[s4]-s[s3])));
    ll y = min(s[s1],min(s[s2]-s[s1],min(s[s3]-s[s2],s[s4]-s[s3])));

    if(x-y <= ans){
        ans = x-y;
        return true;
    }
    return false;
}

