            r2 = prer2;
        }
    }
    long long minl = min(l1, l2);
    long long maxl = max(l1, l2);
    long long minr = min(r1, r2);
    long long maxr = max(r1, r2);
    long long t = max(maxl, maxr) - min(minl, minr);
    if (t == 0) {
        printf("0\n");
        return 0;
    }
    long long ans = t;
    for (int i = 4; i < n - 1; ++i) {
        l2 += a[i - 1];
        if (l1 < l2) {
            int j;
            for (j = left + 1; j < i; ++j) {
                l1 += a[j];
                l2 -= a[j];
                if (l1 >= l2) {
                    break;
                }
            }
            if (l1 < l2) {
                left = i - 1;
                minl = l1;
                maxl = l2;
            }
            else {
                long long prel1 = l1 - a[j];
                long long prel2 = l2 + a[j];
                if (prel2 - prel1 < l1 - l2) {
                    left = j - 1;
                    l1 = prel1;
                    l2 = prel2;
                    minl = l1;
                    maxl = l2;
                }
                else {
                    left = j;
                    minl = l2;
                    maxl = l1;
                }
            }
        }
        else {
            minl = l2;
            maxl = l1;
        }
        r1 -= a[i - 1];
        if (r1 < r2) {
            int j;
            for (j = right + 1; j < n; ++j) {
                r1 += a[j];
                r2 -= a[j];
                if (r1 >= r2) {
                    break;
                }
            }
            if (r1 < r2) {
                right = n - 1;
                minr = r1;
                maxr = r2;
            }
            else {
                long long prer1 = r1 - a[j];
                long long prer2 = r2 + a[j];
                if (prer2 - prer1 < r1 - r2) {
                    right = j - 1;
                    r1 = prer1;
                    r2 = prer2;
                    minr = r1;
                    maxr = r2;
                }
                else {
                    right = j;
                    minr = r2;
                    maxr = r1;
                }
            }
        }
        else {
            minr = r2;
            maxr = r1;
        }
        t = max(maxr, maxl) - min(minr, minl);
        if (t == 0) {
            printf("0\n");
            return 0;
        }
        ans = min(t, ans);
    }
    printf("%lld\n", ans);
    return 0;
}

