const int mod = 1e9 + 7;
const long double pi = 3.141592653589793238462643383279502884197;
const long double eps = 1e-7;

int main() {
	int N;
	cin >> N;
	vector<ll> A(N),sum_l2r(N), sum_r2l(N);

	// 累積和を計算
	sum_l2r[0] = 0, sum_r2l[0] = 0;
	REP(i, N) {
		cin >> A[i];
		if (i > 0) {
			sum_l2r[i] += (sum_l2r[i - 1] + A[i]);
		}
		else sum_l2r[0] = A[0];
	}
	REP(i, N) {
		if (i > 0) {
			sum_r2l[i] += (sum_r2l[i - 1] + A[N - 1 - i]);
		}
		else sum_r2l[0] = A[N - 1];
	}

	// 真ん中の仕切りがi番目にあるときの最適な仕切り方
	// 0番目とN-1番目は定義されない
	vector<int> left_cutter(N - 1), right_cutter(N - 1);

	// 真ん中の仕切りの位置をずらしたときの左右の仕切りの最適な位置を求める
	// しゃく取り法
	// mid:[1]から[N-3]まで
	REPS(mid_ix, 1, N - 2) 
	{
		if (mid_ix > 1) {

			// 左方向
			left_cutter[mid_ix] = left_cutter[mid_ix - 1]; // 引継ぎ

			ll diff_l = abs(sum_l2r[mid_ix] - 2 * sum_l2r[left_cutter[mid_ix - 1]]);
			REPS(left_ix, left_cutter[mid_ix - 1] + 1, mid_ix) {
				if (diff_l > abs(sum_l2r[mid_ix] - 2*sum_l2r[left_ix])) {
					left_cutter[mid_ix] = left_ix;
					diff_l = abs(sum_l2r[mid_ix] - 2 * sum_l2r[left_ix]);
				}
				else break;
			}

			// 右方向
			right_cutter[mid_ix] = right_cutter[mid_ix - 1]; // 引継ぎ

			ll diff_r = abs(sum_r2l[mid_ix] - 2 * sum_r2l[right_cutter[mid_ix - 1]]);
			REPS(right_ix, right_cutter[mid_ix - 1] + 1, mid_ix) {
				if (diff_r > abs(sum_r2l[mid_ix] - 2 * sum_r2l[right_ix])) {
					right_cutter[mid_ix] = right_ix;
					diff_r = abs(sum_r2l[mid_ix] - 2 * sum_r2l[right_ix]);
				}
				else break;
			}

		}
		else {
			// mid_ix = 1のときは強制的に決まる
			left_cutter[1] = 0;
			right_cutter[1] = 0;
		}
	}

	ll ans = mod;
	REPS(mid_ix, 1, N - 2)
	{
		ll min_L = min(sum_l2r[mid_ix] - sum_l2r[left_cutter[mid_ix]], sum_l2r[left_cutter[mid_ix]]);
		ll max_L = max(sum_l2r[mid_ix] - sum_l2r[left_cutter[mid_ix]], sum_l2r[left_cutter[mid_ix]]);

		ll min_R = min(sum_r2l[N - 2 - mid_ix] - sum_r2l[right_cutter[N - 2 - mid_ix]], sum_r2l[right_cutter[N - 2 - mid_ix]]);
		ll max_R = max(sum_r2l[N - 2 - mid_ix] - sum_r2l[right_cutter[N - 2 - mid_ix]], sum_r2l[right_cutter[N - 2 - mid_ix]]);

		//cout << min_L << " " << max_L << " " << min_R << " " << max_R << endl;
		ans = min(max(max_L, max_R) - min(min_L, min_R), ans);
	}
	cout << ans << endl;
	system("pause");
	return 0;
}

