int find_cutpoint(int start,int end, std::vector<int> A){
    int rightsum = 0;
    for(int i = start; i <= end; i++) rightsum+=A[i];
    int leftsum = 0;
    int cutpoint = 0;
    for(int i = start; i <= end, i++){
        int sted = rightsum - leftsum;
        rightsum -= A[i];
        leftsum += A[i];
        if(leftsum > rightsum){
            if(sted < leftsum - rightsum) cutpoint = i-1;
            else cutpoint = i;
            break;
        }
    }
    return cutpoint;
}


