pair<lli, lli> split(int _min, int _max) {
    pair<lli, lli> res(-1e+15, 1e+15);

    int l = _min, r = _max, mid;
    lli ls, rs;
    do {
        mid = l + (r-l) / 2;
        ls = s[mid+1] - s[_min];
        rs = s[_max+1] - s[mid+1];

        if (ls > rs) r = mid;
        else l = mid;

        if (abs(rs-ls) < abs(res.second-res.first)) {
            res.first = ls;
            res.second = rs;
        }
    } while (r-l > 1);

    // cout << ls << " " << rs << endl;

    mid = l + (r-l) / 2;
    ls = s[mid+1] - s[_min];
    rs = s[_max+1] - s[mid+1];

    // cout << ls << " " << rs << endl;

    if (ls > rs) r = mid;
    else l = mid;

    if (abs(rs-ls) < abs(res.second-res.first)) {
        res.first = ls;
        res.second = rs;
    }

    return res;
}

