    cin.tie(0);

    int n;
    cin >> n;
    vector<int> A(n);
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
    }

    vector<long long> acc(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        acc[i + 1] = acc[i] + A[i];
    }

    auto summation = [&](int l, int r) -> long long {
        if (l > r) {
            return 0;
        }
        return acc[r + 1] - acc[l];
    };
    const long long INF = 1LL << 60;
    auto calc = [&](int l, int r) -> pair<long long, long long> {
        if (r - l + 1 < 2) {
            return {-INF, INF};
        }
        long long total = summation(l, r);
        long long tar = total / 2 + summation(0, l - 1);
        auto it = lower_bound(acc.begin() + l, acc.begin() + r + 1, tar);
        int x = it - acc.begin();

        long long diff = INF * 2;
        long long mn = -INF;
        long long mx = INF;
        for (int i = -1; i < 2; ++i) {
            int p = x + i - 1;
            if (p >= l && p < r) {
                long long L = summation(l, p);
                long long R = summation(p + 1, r);
                if (L > R) {
                    swap(L, R);
                }
                if (R - L < diff) {
                    diff = R - L;
                    mn = L;
                    mx = R;
                }
            }
        }
        return {mn, mx};
    };

    long long res = INF;
    for (int i = 1; i + 2 < n; ++i) {
        auto P = calc(0, i);
        auto Q = calc(i + 1, n - 1);

        long long mn = min(P.first ,Q.first);
        long long mx = max(P.second, Q.second);
        res = min(res, mx - mn);
    }

    cout << res << '\n';

    return 0;
}

