const int dx[8] = {-1, 1, 0, 0, -1, -1, 1, 1}, dy[8] = {0, 0, -1, 1, -1, 1, -1, 1};

int N;
ll A[200100], B[200100];

tuple<ll, ll, ll, ll> f(int n, ll (&A)[200100]){
    int64_t lb = -1, ub = n;

    while(std::abs(ub - lb) > 1){
        int64_t mid = (lb + ub) / 2;

        if(A[mid] <= A[n - 1] - A[mid]){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    ll mn1 = -1, mx1 = -1,
       mn2 = -1, mx2 = -1;
    if(lb >= 0){
        mn1 = A[lb];
        mx1 = A[n - 1] - A[lb];
    }

    if(lb + 1 < n - 1){
        mx2 = A[lb + 1];
        mn2 = A[n - 1] - A[lb + 1];
    }

    return std::make_tuple(mn1, mx1, mn2, mx2);
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        std::cin >> A[i];
    }

    copy(A, A+N, B);
    reverse(B, B+N);

    for(int i=0;i<N;++i){
        A[i + 1] += A[i];
    }

    for(int i=0;i<N;++i){
        B[i + 1] += B[i];
    }

    ll res = numeric_limits<ll>::max();
    for(int n=2;n<=N-2;++n){
        ll mns[4], mxs[4];

        tie(mns[0], mxs[0], mns[1], mxs[1]) = f(n, A);
        tie(mns[2], mxs[2], mns[3], mxs[3]) = f(N - n, B);

        for(int i=0;i<2;++i){
            for(int j=0;j<2;++j){
                if(mns[i] == -1 || mns[j+2] == -1){
                    continue;
                }

                ll diff = abs(max(mxs[i], mxs[j+2]) - min(mns[i], mns[j+2]));
                res = min(res, diff);
            }
        }
    }

    std::cout << res << std::endl;
}

