long long int min4(long long int p, long long int q, long long int r, long long int s) {

	long long int ret = p;
	if (ret > q) { ret = q; }
	if (ret > r) { ret = r; }
	if (ret > s) { ret = s; }

	return ret;
}

long long int max4(long long int p, long long int q, long long int r, long long int s) {

	long long int ret = p;
	if (ret < q) { ret = q; }
	if (ret < r) { ret = r; }
	if (ret < s) { ret = s; }

	return ret;
}

int main(void) {

	cin >> N;

	long long int tmp;
	for (int i = 1; i <= N; i++) {
		cin >> tmp;
		A[i] = tmp;
	}

	S.push_back(0);
	for (int i = 1; i <= N; i++) {
		S.push_back(A[i] + S[i - 1]);
	}
	S.push_back(999999999999999);

	long long int ans = 9999999999999999;

	long long int P, Q, R, T;

	for (int M = 2; M <= N - 2; M++) {
		int J1 = upper_bound(S.begin(),S.end(), S[M] / 2)-S.begin();
		if (J1 == 1) { J1++; }
		P = S[J1 - 1] - S[0];
		Q = S[M] - S[J1 - 1];

		if (J1+1 <M) {
			long long int tP, tQ;
			tP = S[J1] - S[0];
			tQ = S[M] - S[J1];
			if (abs(P - Q) > abs(tP - tQ)) { P = tP; Q = tQ; }
		}

		int J2 = upper_bound(S.begin(), S.end(), 1.0*(S[N] - S[M]) / 2.0+S[M]) - S.begin();
		if (J2 -1== M) { J2++; }
		if (J2 == N+1 ) { J2--; }
		R = S[J2-1 ] - S[M];
		T = S[N] - S[J2-1];

		if (J2 <= N - 1) {
			long long int tR, tT;
			tR = S[J2] - S[M];
			tT = S[N] - S[J2];
			if (abs(R - T) > abs(tR - tT)) { R = tR; T = tT; }
		}

		long long int value = max4(P, Q, R, T) - min4(P, Q, R, T);

		//cout << "J1= " << J1 <<"  M= " << M << "  J2= " << J2 << endl;
		//cout << "P=" << P << " Q= " << Q << " R= " << R << "  T= " << T << endl;
