        curr_diff = abs(arr[mid] - arr[i] - arr[i]);
        if (curr_diff >= pre_diff) {
            l = i - 1;
            break;
        }
        pre_diff = curr_diff;
    }
    pre_diff = numeric_limits<ull>::max();
    for (int j = mid + 1; j < n; ++j) {
        curr_diff = abs(arr[n] - arr[j] - (arr[j] - arr[mid]));
        if (curr_diff >= pre_diff) {
            r = j-1;
            break;
        }
        pre_diff = curr_diff;
    }
    ull sum[4];
    sum[0] = arr[l];
    sum[1] = arr[mid] - arr[l];
    sum[2] = arr[r] - arr[mid];
    sum[3] = arr[n] - arr[r];
    ull mi, ma;
    ma = *max_element(sum, sum + 4);
    mi = *min_element(sum, sum + 4);
    return ma - mi;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        scanf("%lld", arr + i);
        arr[i] += arr[i - 1];
    }
    ull mi = numeric_limits<ull>::max();
    for (int i = 2; i <= n - 2; ++i) {
        ull ans = solve(i);
        mi = mi < ans ? mi : ans;
    }
    printf("%lld", mi);
    return 0;
}

