int main() {
    int N;
    cin >> N;
    vector<long long> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (int i = 1; i < N; i++) {
        A[i] += A[i - 1];
    }

    long long res = 1e18;
    int left = 0, mid = 1, right = 2;
    while (mid < N - 2) {

        while (left < mid - 1) {
            long long prev = abs(A[mid] - 2 * A[left]);
            long long next = abs(A[mid] - 2 * A[left + 1]);
            if (prev > next) left++;
            else break;
        }

        while (right < N - 2) {
            long long prev = abs(A[N - 1] - 2 * A[right] + A[mid]);
            long long next = abs(A[N - 1] - 2 * A[right + 1] + A[mid]);
            if (prev > next) right++;
            else break;
        }

        long long P = A[left];
        long long Q = A[mid] - A[left];
        long long R = A[right] - A[mid];
        long long S = A[N - 1] - A[right];

        res = min(res, max({P, Q, R, S}) - min({P, Q, R, S}));
        mid++;
    }

    cout << res << endl;
    return 0;
}

