int midsearch(ll s[],int l,int r,ll obj){
	if(l >= r) return -1;
	int upper = r; 
	int lower = l;
	while(upper-lower > 1){
		int mid = (upper+lower)/2;
		if(s[mid] < obj) lower = mid;
		else upper = mid;
	}
	return lower;
}

