          if (MAX - MIN <= m) {
            ok = true;
            m = MAX - MIN;
            // cout << s1 << SP << s2 << SP << s3 << SP << s4 << BR;
            // cout << m << SP << i << SP << j << SP << k << BR;
          }
        }
      }
    }
    if (ok) r = m; else l = m;
  }
  cout << (l + 1) << BR;

  return 0;
}

