  }
  long p[n-3][4];
  int l = 1;
  for(int r=2; r<n-1; r++){
    while(l<r-1 && sum[l+1]*2<=sum[r]) l++;
    p[r-2][0] = sum[l];
    p[r-2][1] = sum[r] - sum[l];
    if(l<r-2 && abs(sum[r]-2*sum[l+1])<abs(p[r-2][1]-p[r-2][0])){
      p[r-2][0] = sum[l+1];
      p[r-2][1] = sum[r] - sum[l+1];
      l++;
    }
  }

  rep(i, n/2) swap(a[i], a[n-i-1]);
  rep(i, n) sum[i+1] = sum[i] + a[i];
  l = 1;
  for(int r=2; r<n-1; r++){
    while(l<r-1 && sum[l+1]*2<=sum[r]) l++;
    p[n-r-2][3] = sum[l];
    p[n-r-2][2] = sum[r] - sum[l];
