typedef long long ll;
int find_lower_bound_index(vector<long long>& pref,int low, int high,long long val){
	int ans = high+1;
	while(low<=high){
		int mid = (low+high)/2;

		if(pref[mid] >= val){
			ans = min(ans,mid);
			high = mid -1;
		}
		else
		{
			low = mid +1;
		}
	}
	return ans;
}
ll find_ans(vector<ll>& pref,int i,int j,int k,int n){
	if(i<0 || i > j || j > k || k > n-1)
		return LONG_MAX;
	ll p =pref[i];

	ll q = pref[j] - pref[i];

	ll r = pref[k] - pref[j];

	ll s= pref[n-1] - pref[k];
		//cout<<i<<" "<<j<<" "<<k<<endl;
		//cout<<p<<" "<<q<<" "<<r<<" "<<s<<endl;
		return abs( max(max(p,q),max(r,s)) - min(min(p,q),min(r,s)) );
}
int main(){
	int n;
	cin>>n;

	vector<ll> v(n);

	for(int i =0;i<n;i++){
		cin>>v[i];
	}

	vector<ll> pref(n);

	pref[0] = v[0];

	for(int i = 1;i<n;i++){
		pref[i] = pref[i-1] + v[i];
	}

	ll ans = LONG_MAX;
	//fix middle cut
	for(int j =1;j<n-1;j++){
		int i = find_lower_bound_index(pref,0,j-1,(pref[j]+1)/2);
		//if(i == j)
		//	continue;
		int k = find_lower_bound_index(pref,j+1,n-2,(pref[n-1] + pref[j]+1)/2);
		//if(k == n-1)
		//	continue;

		ans  = min(ans,find_ans(pref,i,j,k,n));
		ans  = min(ans,find_ans(pref,i-1,j,k,n));
		ans  = min(ans,find_ans(pref,i,j,k-1,n));
		ans  = min(ans,find_ans(pref,i-1,j,k-1,n));

	}
	cout<<ans;
	return 0;
}

