using namespace std;


template <class It> string join(It begin, It end)
{
    ostringstream ss;
    for (auto it = begin; it != end; ++it)
        ss << ((it == begin) ? "" : ", ") << (*it);
    return ss.str();
}

#define Show(x) cerr << #x << " = " << x << endl;
#define Shows(x) cerr << #x << " : { " << join(x.begin(), x.end()) << " }" << endl;


int main()
{
    int N;
    cin >> N;

    vector<long> A(N, 0);
    for (int i = 0; i < N; ++i)
        cin >> A[i];

    vector<long> S(N, 0);
    for (int i = 0; i < N; ++i)
        S[i] = A[i] + ((i > 0) ? S[i - 1] : 0);

    auto R = [&](int i, int j) -> long
    {
        if (i == 0)
            return S[j - 1];
        else
            return S[j - 1] - S[i - 1];
    };
    auto delta = [&](array<int, 3> &C) -> long
    {
        array<long, 4> sums({ R(0, C[0]), R(C[0], C[1]), R(C[1], C[2]), R(C[2], N) });
        long s_min(0), s_max(0);
        for (auto s : sums)
        {
            if (s < s_min || s_min == 0) s_min = s; 
            if (s > s_max || s_max == 0) s_max = s;
        }
        return (s_max - s_min);        
    };
    auto search = [&](int i, int j, int k)
    {
        long d0 = abs(R(i, j) - R(j, k));
        long d_min = d0;
        int j_min = j;
        for (++j; j < k; ++j)
        {
            long d = abs(R(i, j) - R(j, k));
            if (d < d_min)
            {
                d_min = d;
                j_min = j;
            }
            if (d > d0)
                break;
        }
        return j_min;
    };

    array<int, 3> C({ 1, 2, 3 });
    long d_min = -1;

    for (; C[1] < N - 1; ++C[1])
    {
        C[0] = search(0, C[0], C[1]);
        C[2] = search(C[1], C[2], N);

        long d = delta(C);
        if (d_min > d || d_min < 0)
            d_min = d;

        Show(d);
        Shows(C);
    }

    cout << d_min << endl;
}

