    }

    // 累積和
    vector<ll> AC(N);
    AC[0] = A[0];
    FOR(i, 1, N){
        AC[i] = A[i] + AC[i-1];
    }

    ll minDiff = AC[N-1];
    ll lastLeftCut = 0;
    ll lastRightCut = 2;

    // c : 中央カット位置
    FOR(c, 1, N-2){
        ll P, Q, R, S;
        // pn(c); ///

        // l : 左カット位置
        FOR(l, lastLeftCut, c){
            ll leftSum = AC[l];
            ll rightSum = AC[c] - AC[l];
            ll sumDiff = abs(leftSum - rightSum);

            // 一歩先を見る
            ll leftSumNext = leftSum + A[l+1];
            ll rightSumNext = rightSum - A[l+1];
            ll sumDiffNext = abs(leftSumNext - rightSumNext);

            // diffが減るなら続ける
            if(sumDiff > sumDiffNext){
                continue;
            }else{
                // pn(l); /// 
                P = leftSum;
                Q = rightSum;
                lastLeftCut = l;
                break;
            }
        }

        // r : 右カット位置
        FOR(r, lastRightCut, N-1){
            ll leftSum = AC[r] - AC[c];
            ll rightSum = AC[N-1] - AC[r];
            ll sumDiff = abs(leftSum - rightSum);

            // 一歩先を見る
            ll leftSumNext = leftSum + A[r+1];
            ll rightSumNext = rightSum - A[r+1];
            ll sumDiffNext = abs(leftSumNext - rightSumNext);

            // diffが減るなら続ける
            if(sumDiff > sumDiffNext){
                continue;
            }else{
                // pn(r); ///
                R = leftSum;
                S = rightSum;
                lastRightCut = r;
                break;
            }
        }


        // cを決めたときにl, rを最適化した
        // ここで
        // cout << "PQRS " << P << " " << Q << " " << R << " " << S << endl; ///
        vector<ll> temp;
        temp.push_back(P);
