Int N;

bool isOK_R(Int x, Int i) {//x回の攻撃で全滅するかどうか

	if (s[x] - s[i] < s[N] - s[x]) {
		return true;
	}
	else {
		return false;
	}
}

Int binary_search_R(Int i) {
	Int ng = N;
	Int ok = i+1; 

	/* ok と ng のどちらが大きいかわからないことを考慮 */
	while (abs(ok - ng) > 1) {
		Int mid = (ok + ng) / 2;

		if (isOK_R(mid, i)) ok = mid;
		else ng = mid;
	}
	return ok;
}

bool isOK_L(Int x,Int i) {//x回の攻撃で全滅するかどうか

	if (s[x]-s[0]<s[i]-s[x]) {
		return true;
	}
	else {
		return false;
	}
}

Int binary_search_L(Int i) {
	Int ng = i; // 0が条件を満たすこともあるので、初期値は -1
	Int ok = 1; // 考えられる答えの上限

	/* ok と ng のどちらが大きいかわからないことを考慮 */
	while (abs(ok - ng) > 1) {
		Int mid = (ok + ng) / 2;

		if (isOK_L(mid,i)) ok = mid;
		else ng = mid;
	}
	return ok;
}

int main() {

	cin.tie(nullptr);
