		int low = 0, high = i;
		while (high - low > 1) {
			int mid = (high + low) / 2;
			if (c[mid] >= c[i] - c[mid]) high = mid;
			else low = mid;
		}

		ll p = c[low], q = c[i] - c[low];
		ll p2 = c[high], q2 = c[i] - c[high];
