    c3 = c2+1;
    while (c3<n-1 && abs((vsum[c3]-vsum[c2])*2 - (vsum[n-1]-vsum[c2])) > abs((vsum[c3+1]-vsum[c2])*2 - (vsum[n-1]-vsum[c2]))){
      c3 ++;
    }
    sum[2] = vsum[c3]-vsum[c2];
    sum[3] = vsum[n-1] - vsum[c3];

    sort(rng(sum));
    ans = min(ans, sum[3]-sum[0]);
  }

  cout << ans << endl;
  return 0;
}

