using namespace std;

vector<long long> su(200000);

long long binary_search(int le, int ri, long long mid,int st,int ed) {
	if (ri - le == 1) {
		if (ri == ed) {
			return su[le];
		}
		if (su[ri]*2 - mid > mid - su[le]*2) {
			return su[le];
		}
		else {
			return su[ri];
		}
	}
	else {
		int ce = (le + ri) / 2;
		if (su[ce]*2 > mid) {
			return binary_search(le, ce, mid,st,ed);
		}
		else {
			return binary_search(ce, ri, mid,st,ed);
		}
	}
}

long long min(long long x,long long y) {
	if (x > y) {
		return y;
	}
	else {
		return x;
	}
}

long long max(long long x, long long y) {
	if (x > y) {
		return x;
	}
	else {
		return y;
	}
}

long long cal(long long  a, long long b, long long c, long long d) {
	return max(max(a, b), max(c, d)) - min(min(a, b), min(c, d));
}

int main() {
	int n;
	cin >> n;
	vector<int> da(n);
	for (int i = 0;i < n;i++) {
		cin >> da[i];
	}
	su[0] = da[0];
	for (int i = 1;i < n;i++) {
		su[i] = su[i - 1] + da[i];
	}
	long long ans = LLONG_MAX;
	for (int i = 1;i < n - 2;i++) {
		long long  x = binary_search(0, i, su[i] , 0, i),
			y = binary_search(i + 1, n - 1, su[i] + su[n - 1], i + 1, n - 1);
		ans = min(ans, cal(x, su[i] - x, y - su[i], su[n - 1] - y));
	}
	cout << ans << endl;
}

