        auto second = lower_bound(dp.begin()+i, dp.end(), dp[n] / 2) - dp.begin();
        // 近傍探索して
        for(int j = -20;j<=20;j+=1){
            if (first + j >= i || first + j<=0)
            {
                continue;
            }
            for(int k = -20;k<=20;k+=1){
                if (second + k >= n || second + j <= i)
                {
                    continue;
                }
                ll mx = 0;
                ll mn = 1e18;
                mx = max(dp[i]-dp[first+j],mx);
                mx = max(dp[first+j] - dp[0], mx);
                mx = max(dp[n] - dp[second + k], mx);
                mx = max(dp[second+k] - dp[i], mx);
                mn = min(dp[i] - dp[first + j], mn);
                mn = min(dp[first + j] - dp[0], mn);
                mn = min(dp[n] - dp[second + k], mn);
                mn = min(dp[second + k] - dp[i], mn);
                ans = min(ans,mx-mn);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
template <typename T, typename Function>
T bsearch(T L, T R, const Function& can, bool left_feasible = true) {
#ifdef DEBUG
    using actual_type = typename callable_traits<Function>::function_type;
    using expected_type = typename callable_traits<bool(T)>::function_type;
    static_assert(is_same<actual_type, expected_type>::value, "bsearch 'can' must be bool(T)");
#endif
    T& feasible = left_feasible ? L : R;
    T& infeasible = left_feasible ? R : L;
    while(R - L > 1) {
        T M = (L + R) / 2;
        (can(M) ? feasible : infeasible) = M;
    }
    return feasible;
}
int main() {
	int n;
	cin >> n;
	vector<ll> a(n);
	for(int i = 0; i < n; i++) {
		cin >> a[i];
	}
	vector<ll> s(n);
	partial_sum(a.begin(), a.end(), s.begin());
	auto rsq = [&](int L, int R) {
		return s[R - 1] - (L ? s[L - 1] : 0);
	};
	ll ans = accumulate(a.begin(), a.end(), 0);
	for(int i = 2; i <= n - 2; i++) {
		int lcut = rsq(0, 1) > rsq(1, i) ? 1 : bsearch(1, i, [&](int j) {
			return rsq(0, j) <= rsq(j, i);
		});
		int rcut = rsq(i, i + 1) > rsq(i + 1, n) ? i + 1 : bsearch(i + 1, n, [&](int j) {
			return rsq(i, j) <= rsq(j, n);
		});
		for(int llcut = max(lcut - 1, 1); llcut <= min(lcut + 1, i - 1); llcut++) {
			for(int rrcut = max(rcut - 1, i + 1); rrcut <= min(rcut + 1, n - 1); rrcut++) {
				ll mini = min({rsq(0, llcut), rsq(llcut, i), rsq(i, rrcut), rsq(rrcut, n)});
				ll maxi = max({rsq(0, llcut), rsq(llcut, i), rsq(i, rrcut), rsq(rrcut, n)});
				ans = min(ans, abs(maxi - mini));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

