int main() {
	ll N; cin >> N;
	repe(i, 1, N) {
		ll a; cin >> a;
		A[i] = a;
		if (i == 0)S[i] = A[i];
		else S[i] += S[i - 1] + A[i];
	}

	//left side
	ll l = N - 2, r = N - 2;
	while (r > 1) {
		while (l > 1 && abs(abs(S[r] - S[l - 1]) - abs(S[l - 1] - S[0])) > abs(abs(S[r] - S[l - 2]) - abs(S[l - 2] - S[0]))) {
			l--;
		}
		//cout << "L: " << l << ":" << abs(S[l - 1] - S[0]) << "R: " << r << ":" << abs(S[r] - S[l - 1]) << endl;
		L[r] = l;
