	//	L[r] = l;
	//	r--;
	//}

	//right side
	l = 3, r = 3;
	while (l < N) {
		while (r < N  && abs(abs(S[N] - S[r]) - abs(S[r] - S[l - 1])) > abs(abs(S[N] - S[r + 1]) - abs(S[r + 1] - S[l - 1])))
		{
			r++;
		}
		//cout << "L: " << l << ":" << abs(S[r] - S[l - 1]) << "R: " << r << ":" << abs(S[N] - S[r]) << endl;
		R[l - 1] = r;
		l++;
	}

	ll minV = LL_MAX;
	rep(k, 0, N) {
		ll p = S[L[k] - 1];
		ll q = S[k] - S[L[k] - 1];
		ll r = S[R[k]] - S[k];
		ll s = S[N] - S[R[k]];

		ll ma = max(p, max(q, max(r, s)));
		ll mi = min(p, min(q, min(r, s)));
		//cout << "k: " << k << " p: " << p << " q: " << q << " r: " << r << " s: " << s << " max: " << ma << " min: " << mi << endl;

		minV = min(abs(max(p, max(q, max(r, s))) - min(p, min(q, min(r, s)))), minV);
	}
	cout << minV << endl;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

class Problem {
public:
    Problem(int _n) : n(_n), a(_n) {}
    ll Solve() {
        for (int i = 0; i < n; ++i) cin >> a[i];
        for (int i = 1; i < n; ++i) a[i] += a[i - 1];


        vector<ll> l(n);
        for (int i = 2; i < n; ++i) {
            l[i] = l[i - 1];
            while (l[i] + 1 < i &&
                   abs(2 * a[l[i]] - a[i]) >= abs(2 * a[l[i] + 1] - a[i]))
                ++l[i];
        }

        vector<ll> r(n);
        r[n - 3] = n - 2;
        for (int i = n - 4; 0 <= i; --i) {
            r[i] = r[i + 1];
            while (i < r[i] - 1 && abs(2 * a[r[i]] - a[i] - a[n - 1])
                   >= abs(2 * a[r[i] - 1] - a[i] - a[n - 1]))
                --r[i];
        }

        ll ans = a[n - 1];
        for (int i = 1; i <= n - 3; ++i) {
            ll s1 = a[l[i]], s2 = a[i] - a[l[i]],
                s3 = a[r[i]] - a[i], s4 = a[n - 1] - a[r[i]];
            ans = min(ans, max({s1, s2, s3, s4}) - min({s1, s2, s3, s4}));
        }


        return ans;
    }

private:
    int n;
    vector<ll> a;
