            sum[l],
            sum[m] - sum[l],
            sum[r] - sum[m],
            sum[n] - sum[r]
        };
        sort(a, a + 4);
        ans = min(ans, a[3] - a[0]);
    }
    cout << ans << endl;
    return 0;
}

