//二分探索
//main関数で呼び出す前に，l, rの一方が条件を満たし他方が満たさないことを確認すること
//配列を引数にするときは原則として参照渡しすること
long long bs1(long long l, long long r, ll i, vll &b, ll n) {
	//解近傍の処理
	if (l == r) return l;
	bool x = (abs(2 * b[l + 1] - b[i + 1]) < abs(2 * b[r + 1] - b[i + 1]));
	if (l + 1 == r) {
		if (x) return l;
		else return r;
	}

	//再帰
	long long mid = (l + r) / 2;
	if (b[mid + 1] < b[i + 1] - b[mid + 1]) return bs1(mid, r, i, b, n);
	else return bs1(l, mid, i, b, n);
}

long long bs2(long long l, long long r, ll i, vll &b, ll n) {
	//解近傍の処理
	if (l == r) return l;
	bool x = (abs(2 * b[l + 1] - b[i + 1] - b[n]) < abs(2 * b[r + 1] - b[i + 1] - b[n]));
	if (l + 1 == r) {
		if (x) return l;
		else return r;
	}

	//再帰
	long long mid = (l + r) / 2;
	if (b[mid + 1] - b[mid + 1] < b[n] - b[mid + 1]) return bs2(mid, r, i, b, n);
	else return bs2(l, mid, i, b, n);
}

int main() {
	//ios::sync_with_stdio(false);
