	for (ll i = 0; i < n; i++) cin >> a[i];
	vll b(n + 1, 0);
	for (ll i = 0; i < n; i++) b[i + 1] = b[i] + a[i];

	ll ans = inf;

	for (ll i = 1; i <= n - 3; i++) { // a[i] | a[i + 1]
		ll j = bs1(-1, i - 1, i, b, n), k = bs2(i, n - 2, i, b, n);
		ll p = b[j + 1] - b[0], q = b[i + 1] - b[j + 1], r = b[k + 1] - b[i + 1], s = b[n] - b[k + 1];
		ll x = max({p, q, r, s}) - min({p, q, r, s});
		ans = min(ans, x);
	}
	cout << ans << endl;
}

