    seg.build();
    ll ans = 1e+17;
    for(int i = 2; i + 1 < n; ++i){
        ll leftsum = seg.query(0, i), rightsum = seg.query(i, n);
        leftsum >>= 1, rightsum >>= 1;
        ll maxe = 0, mine = 1e+17;
        int lb = 1, ub = i;
        while(ub - lb > 1){
            int mid = (lb + ub) >> 1;
            if(seg.query(0, mid) < leftsum)    lb = mid;
            else    ub = mid;
        }
        ll left = seg.query(0, lb), right = seg.query(lb, i);
        chmax(maxe, max(left, right));
        chmin(mine, min(left, right));
        if(lb + 1 > 0 && lb + 1 < i){
            left = seg.query(0, lb + 1), right = seg.query(lb + 1, i);
            if(abs(left - right) < maxe - mine){
                maxe = max(left, right);
                mine = min(left, right);
            }
        }
        if(lb - 1 > 0 && lb + 1 < i){
            left = seg.query(0, lb - 1), right = seg.query(lb - 1, i);
            if(abs(left - right) < maxe - mine){
                maxe = max(left, right);
                mine = min(left, right);
            }
        }

        lb = i + 1, ub = n;
        while(ub - lb > 1){
            int mid = (lb + ub) >> 1;
            if(seg.query(mid, n) >= rightsum)   lb = mid;
            else    ub = mid;
        }
        left = seg.query(i, lb), right = seg.query(lb, n);
        ll maxe2 = 0, mine2 = 1e+17;
        chmax(maxe2, max(left, right));
        chmin(mine2, min(left, right));
        if(lb + 1 > i && lb + 1 < n){
            left = seg.query(i, lb + 1), right = seg.query(lb + 1, n);
            if(abs(left - right) < maxe2 - mine2){
                maxe2 = max(left, right);
                mine2 = min(left, right);
            }
        }
        if(lb - 1 > i && lb + 1 < n){
            left = seg.query(i, lb - 1), right = seg.query(lb - 1, n);
            if(abs(left - right) < maxe2 - mine2){
                maxe2 = max(left, right);
                mine2 = min(left, right);
            }
        }

        chmin(ans, max(maxe, maxe2) - min(mine, mine2));
    }
    cout << ans << endl;
}

