using namespace std;

int     Pos(long AA, vector<long> &A) {
        int a=0;
        int b=A.size()-1;
        while (1<b-a) {
                int c=(a+b)/2;
                if (AA>=A.at(c))
                        a=c;
                else b=c;
        }
        return a;
}

int     Mid(int a, int b, vector<long> &A) {
        long T=(A.at(a)+A.at(b))/2;
        return Pos(T, A);
}

int     main() {
        int N;
        cin >>N;
        vector<long> A(N);
        long AAA=0;
        for (int i=0; i<N; i++) {
                long AA;
                cin >>AA;
                AAA += AA;
                A.at(i)=AAA;
        }
        long S=AAA;
        int N1=Pos(AAA/4, A);
        int N3=Pos(AAA*3/4, A);
        int RNG=10000;
        for (int i=N1-RNG; i<=N+RNG; i++) {
                if (i<0) continue;
                for (int j=N3-RNG; j<=N3+RNG; j++) {
                        if (j-i<2) continue;
                        if (N<=j) continue;
                        int N2=Mid(i, j, A);
                        long D1=A.at(i);
                        long D4=AAA-A.at(j);
                        for (int k=N2-RNG; k<=N2+RNG; k++) {
                                if (k<=i) continue;
                                if (k>=j) continue;
                                long D2=A.at(k)-D1;
                                long D3=A.at(j)-D2-D1;
                                S=min(S, max(max(D4, D3), max(D2, D1))-min(min(D4, D3), min(D2, D1)));
                        }
                }
        }
        cout <<S <<endl;
        return 0;
};

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

ll N, A[200000], ruiseki[200000];
int index;

ll nibun1(ll x, ll y, ll sum){
	if(2*A[0] >= sum){
		return sum - A[0];
	}
	if(y-x == 1){
		if(sum - 2*ruiseki[x] < 2*ruiseki[y] - sum){
			return ruiseki[x];
		}else{
			return sum - ruiseki[y];
		}
	}
	ll med = (x+y)/2;
	if(2*ruiseki[med] == sum){
		return sum/2;
	}else if(2*ruiseki[med] > sum){
		return nibun1(x, med, sum);
	}else{
		return nibun1(med, y, sum);
	}
}

ll nibun2(ll x, ll y, ll sum){
	if(2*A[index] >= sum){
		return sum - A[index];
	}
	if(y-x == 1){
		if(2*ruiseki[N-1] - 2*ruiseki[x] - sum < sum - 2*ruiseki[N-1] + 2*ruiseki[y]){
			return sum - ruiseki[N-1] + ruiseki[x];
		}else{
			return ruiseki[N-1] - ruiseki[y];
		}
	}
	int med = (x+y)/2;
	if(2*ruiseki[N-1] - 2*ruiseki[med] == sum){
		return ruiseki[N-1] - ruiseki[med];
	}else if(2*ruiseki[N-1] - 2*ruiseki[med] > sum){
		return nibun2(med, y, sum);
	}else{
		return nibun2(x, med, sum);
	}
}

int main(){
	cin >> N;
	ll ans[N-3];
	for(int i=0; i<N; i++){
		cin >> A[i];
		if(i == 0){
			ruiseki[0] = A[0];
		}else{
			ruiseki[i] = ruiseki[i-1] + A[i];
		}
	}
	ll n = ruiseki[N-1];
	index = 2;
	for(int i=1; i<N-2; i++){
		ll a = ruiseki[i];
		ans[i-1] = max(a - nibun1(0, i, a), n - a - nibun2(i+1, N-1, n-a)) - min(nibun1(0, i, a), nibun2(i+1, N-1, n-a));
		index++;
	}
	sort(ans, ans+N-3);
	cout << ans[0] << endl;
	return 0;
}

