int N = 0;
ull A[2*100000] = {0};

ull lsum[2*100000] = {0};
ull rsum[2*100000] = {0};

int main(void) {
  std::cin >> N;

  for (int i = 0; i < N; i++) {
    std::cin >> A[i];
  }
  lsum[0] = A[0];
  rsum[N-1] = A[N-1];
  for (int i = 1; i < N; i++) {
    lsum[i] += lsum[i-1] + A[i];
    auto ri = N - 1 - i;
    rsum[ri] += rsum[ri+1] + A[ri];
  }

  //for (int i = 0; i < N; i++) {
  //  std::cout << lsum[i] << "," << rsum[N-1-i] << std::endl;
  //}

  ull group[4] = {0};
  ull result_diff = LLONG_MAX;
  size_t blidx = 1;
  size_t bridx = 3;
  for (size_t i = 2; i < N-1; i++) {

    //std::cout << "IDX:" << i << std::endl;
    ull llsum = lsum[blidx - 1];
    ull lrsum = lsum[i-1] - lsum[blidx - 1];
    group[0] = llsum;
    group[1] = lrsum;
    if (lrsum > llsum) {
      ull ldiff = lrsum - llsum;
      //for (size_t l = 1; l < i - 1; l++) {
      for (size_t l = blidx + 1; l < i; l++) {
        ull diff = ldiff - (2 * A[l-1]);
        diff = diff > 0 ? diff : -diff;
        //std::cout << "   " << ldiff << " " << diff << std::endl;
        if (ldiff > diff) {
          //std::cout << "     -->" << diff << std::endl;
          ldiff = diff;

          blidx = l;
          group[0] = lsum[blidx - 1];
          group[1] = lsum[i-1] - lsum[blidx -1];
        } else {
          break;
        }
      }
    }
    //std::cout << group[0] << "," << group[1] << std::endl;

    //std::cout << "IDX:" << i << "," << bridx << std::endl;
    if (bridx <= i) {
      bridx = i + 1;
    }
    ull rlsum = rsum[i] - rsum[bridx];
    ull rrsum = rsum[bridx];
    group[2] = rlsum;
    group[3] = rrsum;
    //std::cout << "  bridx   -->" << bridx <<  " w " << rlsum << " " << rrsum << std::endl;
    if (rrsum > rlsum) {
      ull rdiff = rrsum - rlsum;
      for (size_t r = bridx + 1; r < N; r++) {
        ull diff = rdiff - (2 * A[r-1]);
        diff = diff > 0 ? diff : -diff;
        //std::cout << r <<  "   " << rdiff << " " << diff << " w/ " << A[r+1] << std::endl;
        if (rdiff > diff) {
          //std::cout << "     -->" << diff << std::endl;
          rdiff = diff;

          bridx = r;
          group[2] = rsum[i] - rsum[bridx];
          group[3] = rsum[bridx];
        } else {
          break;
        }
      }
    }

    //std::cout << " " << group[0] << " " << group[1] << " " << group[2] << " " << group[3] << std::endl;
    std::sort(group, group + 4);
    ull diff = group[3] - group[0];
    if (result_diff > diff) {
      result_diff = diff;
    }
  }

  std::cout << result_diff << std::endl;

  return 0;
}

