    cin >> a[i];
  }
  asum[0] = a[0];
  for(int i = 1; i < n; i++){
    asum[i] = asum[i-1] + a[i];
  }

  long long ans = 1LL << 60;
  int lc = 1, rc = 3;
  for(int i = 2; i < n - 1; i++){

    if(rc <= i) rc = i + 1;
    long long ll = asum[lc-1];
    long long lr = asum[i-1] - asum[lc-1];
    long long ld = abs(ll-lr);
    while(lc < i-1){
      long long nll = asum[lc];
      long long nlr = asum[i-1] - asum[lc];
      long long nld = abs(nll-nlr);
      if(nld < ld) {
        lc++;
        ll = nll; lr = nlr; ld = nld;
      }else{
        break;
      }
    }

    long long rl = asum[rc-1] - asum[i-1];
    long long rr = asum[n-1] - asum[rc-1];
    long long rd = abs(rl-rr);
    while(rc < n-1){
      long long nrl = asum[rc] - asum[i-1];
      long long nrr = asum[n-1] - asum[rc];
      long long nrd = abs(nrl-nrr);
      if(nrd < rd) {
        rc++;
        rl = nrl; rr = nrr; rd = nrd;
      }else{
        break;
      }
    }
    vector<long long> comp(4);
    comp[0] = ll; comp[1] = lr; comp[2] = rl; comp[3] = rr;
    sort(comp.begin(), comp.end());
    ans = min(ans, comp[3] - comp[0]);
  }

  cout << ans << endl;
}

