ll dfs(int c = 0, int i = 0, ll mi = 1e18, ll ma = -1e18){
  if(i==n) return -1;
  if(c==3) {
    ll d = s[n] - s[i];
    return max(ma,d) - min(mi,d);
  }
  auto f = [&](int idx){
    ll d = s[idx] - s[i];
    return dfs(c+1, idx, min(mi,d), max(ma,d));
  };
  int idx = upper_bound(s.begin(),s.end(),s[n]/4+s[i]) - s.begin();
  ll res = 1e18;
  for(int ni=idx;i<ni;--ni){
    ll temp = f(ni);
    if(temp==-1) continue;
    res = min(res,temp);
    if(idx-2>=ni) break;
  }
  return res;
} 

