struct BlockSum
{
	ll b1;
	ll b2;
	ll b3;
	ll b4;
};

pair<ll, ll> Diff(ll x1, ll x2, ll x3, ll x4)
{
	pair<ll, ll> res;
	vt<ll> test = { x1, x2, x3, x4 };
	rep(i, 0, 3) rep(j, i + 1, 4)
	{
		res.first = min(res.first, abs(test[i] - test[j]));
		res.second = max(res.second, abs(test[i] - test[j]));
	}
	return res;
}

int main()
{
	ll N; cin >> N;
	vt<ll> A = InputVT<ll>(N);

	vt<ll> asum(N); asum[0] = A[0];
	rep(i, 0, N) if (i != 0) asum[i] = asum[i - 1] + A[i];

	ll borderB12 = 1;
	vt<BlockSum> blockSum(N);
	rep(mid, 2, Size(asum) - 1)
	{	// 尺取法で任意のmidに対するb1とb2の合計最適解を求める
		while(1)
		{
			blockSum[mid].b1 = asum[borderB12-1];
			blockSum[mid].b2 = asum[mid - 1] - asum[borderB12 - 1];
			if (borderB12 == mid - 1) break;
			ll ltest = asum[borderB12];
			ll rtest = asum[mid - 1] - asum[borderB12];
			if (abs(blockSum[mid].b1 - blockSum[mid].b2) < abs(ltest - rtest)) break;
			borderB12++;
		}
	}

	ll borderB34 = 3;
	rep(mid, 2, Size(asum) - 1)
	{	// 尺取法で任意のmidに対するb3とb4の合計最適解を求める
		while (1)
		{
			blockSum[mid].b3 = asum[borderB34 - 1] - asum[mid - 1];
			blockSum[mid].b4 = asum.back() - asum[borderB34 - 1];
			if (borderB34 == Size(asum) - 1) break;
			ll ltest = asum[borderB34] - asum[mid - 1];
			ll rtest = asum.back() - asum[borderB34];
			if (abs(blockSum[mid].b3 - blockSum[mid].b4) < abs(ltest - rtest)) break;
			borderB34++;
		}
	}

	ll ans = LLONG_MAX;
	rep(mid, 2, Size(asum) - 1)
	{
		pair<ll, ll> test;
		test = Diff(blockSum[mid].b1, blockSum[mid].b2, blockSum[mid].b3, blockSum[mid].b4);
		ans = min(ans, abs(test.first - test.second));
	}
	cout << ans;
	return 0;
}

