// [i, j]
inline ll sumRange(int i, int j) {
  assert(i <= j);
  return i == 0 ? preSum[j] : preSum[j] - preSum[i-1];
}

ll getBest(ll k) {
  ll sum = sumRange(0, k);
  int lo = 0;
  int hi = k;
  while (hi - lo > 1) {
    int mid = (hi + lo) / 2;
    if (sumRange(0, mid) >= sum/2) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  int i = hi;

  sum = sumRange(k+1, n-1);
  lo = k+1;
  hi = n-1;
  while (hi - lo > 1) {
    int mid = (hi + lo) / 2;
    if (sumRange(k+1, mid) >= sum/2) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  int j = hi;

  ll res = 1e18;
  // cerr << "i: " << i << " k: " << k << " j: " << j << endl;
  for (int izq = i-2; izq <= i+1; izq++) {
    for (int der = j-2; der <= j+1; der++) {
      if (izq > 0 && der > k+1 && izq <= k && der <= n-1) {
        ll P = sumRange(0, izq-1);
        ll Q = sumRange(izq, k);
        ll R = sumRange(k+1, der-1);
        ll S = sumRange(der, n-1);
        ll mx = max({P, Q, R, S});
        ll mn = min({P, Q, R, S});
        res = min(res, mx - mn);
        // cerr << izq << "  " << der << endl;
        // cerr << P << " " << Q << " " << R << " " << S << endl;
        // cerr << mx - mn << endl;
      }
    }
  }
  return res;
}


