  for (int i = 0; i < n; i++) cin >> a[i];
  preSum[0] = a[0];
  for (int i = 1; i < n; i++) preSum[i] = preSum[i-1] + a[i];

  ll ans = 1e18;
  for (int k = 1; k < n-2; k++) {
    ll op = getBest(k);
    ans = min(ans, op);
  }
  cout << ans << endl;
  return 0;
}

