        abs(sum[k] - sum[i] - (right - (sum[k] - sum[i]))) > 
        abs(sum[k + 1] - sum[i] - (right - (sum[k + 1] - sum[i])))){
      ++k;
    }
    ll p = sum[j];
    ll q = sum[i] - sum[j];
    ll r = sum[k] - sum[i];
    ll s = sum[n] - sum[k];
    ll mx = max(max(p, q), max(r, s));
    ll mi = min(min(p, q), min(r, s));
    ans = min(ans, mx - mi);
    ++i;
  }

  cout << ans << endl;

  return 0;
}

