// A[i]~A[j] を2つに分ける位置を探す
void divideHalf( long long& F, long long& S, int i, int j, vector<long long>& A )
{
    // それぞれの和が同じくらいになる位置を二部探索
    long long s = A[j]-A[i];
    auto itr_l = lower_bound(A.begin()+i, A.begin()+j+1, s/2+A[i]);
    auto itr_s = itr_l--;
    // abs(F-S) = abs( 2*(*itr) - (A[i]+A[j]) ) を小さくする方を採用する
    if( abs( 2*(*itr_l)-(A[i]+A[j]) ) < abs( 2*(*itr_s)-(A[i]+A[j]) ) ){
        F = *itr_l-A[i];
        S = A[j]-*itr_l;
    }else{
        F = *itr_s-A[i];
        S = A[j]-*itr_s;
    }
}


int main()
{
    int N;
    cin >> N;
    vector<long long> A(N+1, 0);
    for( int i = 1; i <= N; ++i ) cin >> A[i];


    // 累積話
    for( int i = 1; i <= N; ++i ) A[i] += A[i-1];

    long long ans = 1e+15;
    // 真ん中の分割点について全探索
    for( int i = 2; i <= N-2; ++i ){
        long long P, Q, R, S;
        divideHalf(P, Q, 0, i, A);  // 左側
        divideHalf(R, S, i, N, A);  // 右側
        ans = min( ans, max({P,Q,R,S}) - min({P,Q,R,S}) );
    }
    cout << ans << endl;

    return 0;
}

