    ll res = LONG_LONG_MAX;
    for (int i = 0; i < n - 3; i++) {
        ll x = pref[i];
        int next = upper_bound(pref.begin(), pref.end(), 2 * x) - pref.begin();
        for (int j : {next - 2, next - 1, next, next + 1, next + 2}) {
            if (j <= i || n - j < 3) {
                continue;
            }
            ll y = pref[j] - x;
            int next2 = upper_bound(pref.begin(), pref.end(), pref[j] + x) - pref.begin();
            for (int k : {next2 - 2, next2 - 1, next2, next2 + 1, next2 + 2}) {
                if (k <= j || k >= n - 1) {
                    continue;
                }
                ll z = pref[k] - pref[j];
                ll left = tot - x - y - z;
                assert(left > 0);
                ll mx = max({x, y, z, left});
                ll mn = min({x, y, z, left});
//                cerr << x << " " << y << " " << z << " " << left << "\n";
                res = min(res, mx - mn);
            }
        }
    }
    cout << res << "\n";
}

