void solve() {
	int l = 1, r = 3;
	for (int i = 2; i < n - 1; i++) {
		r = max(r, i + 1);
		while (1) {
			if (l + 1 == i || abs(s[l] - (s[i] - s[l])) <= abs((s[l + 1]) - (s[i] - s[l + 1]))) break;
			l++;
		}
		while (1) {
			if (r + 1 == n || abs((s[r] - s[i]) - (s[n] - s[r])) <= abs((s[r + 1] - s[i]) - (s[n] - s[r + 1]))) break;
			r++;
		}
		ans = min(ans, max({s[l], s[i] - s[l], s[r] - s[i], s[n] - s[r]}) - min({s[l], s[i] - s[l], s[r] - s[i], s[n] - s[r]}));
	}
}

