template< typename T >
struct ruiseki{
    vector <T> s;
    int size;
    ruiseki(vector <T> &a){
        size = a.size()+1;
        s.resize(size);
        for(int i=1;i<size;i++) s[i] = s[i-1] + a[i-1];
    }
    ruiseki(){}
    T get(int a, int b){
        if(b > size-1) b = size-1;
        return s[b] - s[a];
    }
};
struct halve{
    struct ruiseki <int> r;
    halve(vector <int> &a){
        struct ruiseki <int> tmp(a);
        r = tmp;
    }
    tuple <int,int,int> get(int a, int b){ //半分わける場所、右側、左側を返す
        if(b > r.size) b = r.size;
        if(abs(a-b)<=1) return make_tuple(a,0,r.get(a, a+1));
        int sum = r.get(a, b);
        int left = a, right = b;
        while(abs(left - right)>1){
            int mid = (left +right)/2;
            if(r.get(a, mid+1) < sum/2){
                left = mid;
            }else right = mid;
        }
        int lsum1 = r.get(a, left+1);
        int rsum1 = sum - lsum1;
        int lsum2 = r.get(a, right+1);
        int rsum2 = sum - lsum2;
        if(abs(lsum1-rsum1)<abs(rsum2-lsum2)){
            return make_tuple(left+1, lsum1, rsum1);
        }else return make_tuple(right+1, lsum2, rsum2);
    }
};
signed main(void) { cin.tie(0); ios::sync_with_stdio(false);
    int n; cin>>n;
    vector <int> a(n);
    rep(i,n) cin>>a[i]; 
    struct halve half(a);
    int ans = INF;
    for(int i=0;i<n-1;i++){
        auto tmp = half.get(0,i);
        auto tmp2 = half.get(i,n);
        int n1=get <1>(tmp), n2 = get <2>(tmp),n3=get <1>(tmp2),n4=get <2>(tmp2);
        chmin(ans,max({n1,n2,n3,n4}) - min({n1,n2,n3,n4}));
    }
    cout<<ans<<endl;
}

