ll po[POW_MAX + 2];
ll mod_pow(ll x, ll n) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res = res * x % MOD;
    x = x * x % MOD;
    n >>= 1;
  }
  return res;
}
ll mod_inv (ll x) {
  return mod_pow(x, MOD - 2) % MOD;
}
ll comb(int n, int r) {
  return (((po[n] * mod_inv(po[r])) % MOD) * mod_inv(po[n - r])) % MOD;
}
// greatest common divisor
ll gcd(ll a, ll b) {
  while (a % b != 0) {
    ll tmp = a;
    a = b;
    b = tmp % b;
  }
  return b;
}

int const N_MAX = 2 * 1e5;

int N;
ll A[N_MAX + 1];
ll sums[N_MAX + 1];
int f[N_MAX + 1], g[N_MAX + 1];

ll get_d(int right, int center, int left) {
  ll r = sums[right];
  ll c = sums[center];
  ll l = left == -1 ? 0 : sums[left];
  return abs((r - c) - (c - l));
}

int main() {
  scanf("%d", &N);

  rep(i, N) {
    scanf("%lld", &A[i]);
    sums[i] = sums[i - 1] + A[i];
  }

  FOR(l, 1, N - 2) {
    int i = f[l - 1];
    while (i < l - 1 && get_d(l, i, -1) > get_d(l, i + 1, -1)) {
      i++;
    }
    f[l] = i;

    int j = max(l + 1, g[l - 1]);
    while (j < N - 2 && get_d(N - 1, j, l) > get_d(N - 1, j + 1, l)) {
      j++;
    }
    g[l] = j;
  }
  ll d = INF;
  FOR(l, 1, N - 2) {
    ll p = sums[f[l]];
    ll q = sums[l] - sums[f[l]];
    ll r = sums[g[l]] - sums[l];
    ll s = sums[N - 1] - sums[g[l]];
    d = min(d, max({p, q, r, s}) - min({p, q, r, s}));
  }
  printf("%lld\n", d);
}

