int main() {
    int N;
    cin >> N;
    vector<ll> A(N), sum(N);
    cin >> A;
    sum[0] = A[0];
    for (int i = 1; i < N; i++) sum[i] = sum[i - 1] + A[i];
    auto calc = [&](int left, int right) {
        ll allSum = sum[right];
        ll minus = 0;
        if (left != 0) minus = sum[left - 1];
        while (right - left > 1) {
            int mid = left + (right - left) / 2;
            ll leftSum = sum[mid] - minus;
            ll rightSum = allSum - leftSum - minus;
            if (leftSum < rightSum) left = mid;
            else right = mid;
        }
        ll leftSum = sum[left] - minus;
        ll rightSum = allSum - leftSum - minus;
        return make_pair(left, right);
    };
    ll ans = INFLL;
    for (int i = 1; i + 2 < N; i++) {
        auto left = calc(0, i);
        auto right = calc(i + 1, N - 1);
        for (int a = 0; a <= 1; a++) {
            if (left.first + a >= i) continue;
            for (int b = 0; b <= 1; b++) {
                if (right.first + b >= N - 1) continue;
                vector<ll> temp(4);
                temp[0] = sum[left.first + a];
                temp[1] = sum[i] - temp[0];
                temp[2] = sum[right.first + b] - (temp[0] + temp[1]);
                temp[3] = sum[N - 1] - (temp[0] + temp[1] + temp[2]);
                sort(temp.begin(), temp.end());
                ans = min(ans, temp[3] - temp[0]);
            }
        }
    }
    cout << ans << endl;
}

