#include<bits/stdc++.h>

using namespace std;

#define INF 1000000007
#define LINF (1LL << 62)
#define PI 3.14159265358979

typedef long long i64;
typedef pair<i64,i64> P;

inline i64 mod(i64 a, i64 m) { return (a % m + m) % m; }

template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }



int n, a[202020];
i64 d[202020];
i64 point(int p, int l, int r){
	if(p > r || p < 0) return LINF;
	return abs((d[p]-d[l])-(d[r]-d[p]));
}
void solve(){
	cin >> n;
	for(int i = 0; i < n; i++){
		cin >> a[i];
		d[i+1] = d[i]+a[i];
	}

	i64 ans = LINF;
	for(int i = 2; i < n-1; i++){
		i64 l1 = 0,l2 = 0, r1 = 0,r2 = 0;
		//l = d[i], r = d[n]-d[i]

		i64 mid = d[i]/2;
		int p = lower_bound(d+1,d+i,mid)-d;
		if(point(p,0,i) == min({point(p,0,i),point(p+1,0,i),point(p-1,0,i)})){
			l1 = d[p]; l2 = d[i]-d[p];
		}
		if(point(p+1,0,i) == min({point(p,0,i),point(p+1,0,i),point(p-1,0,i)})){
			l1 = d[p+1]; l2 = d[i]-d[p+1];
		}
		if(point(p-1,0,i) == min({point(p,0,i),point(p+1,0,i),point(p-1,0,i)})){
			l1 = d[p-1]; l2 = d[i]-d[p-1];
		}

		mid = (d[n]+d[i+1])/2;
		p = lower_bound(d+i+1,d+n,mid)-d;
		if(point(p,i,n) == min({point(p,i,n),point(p+1,i,n),point(p-1,i,n)})){
			r1 = d[p]-d[i]; r2 = d[n]-d[p];
		}
		if(point(p+1,i,n) == min({point(p,i,n),point(p+1,i,n),point(p-1,i,n)})){
			r1 = d[p+1]-d[i]; r2 = d[n]-d[p+1];
		}
		if(point(p-1,i,n) == min({point(p,i,n),point(p+1,i,n),point(p-1,i,n)})){
			r1 = d[p-1]-d[i]; r2 = d[n]-d[p-1];
		}

		chmin(ans, max({l1,l2,r1,r2})-min({l1,l2,r1,r2}));
	}
	cout << ans << endl;
}

int main(){
	std::cin.tie(0);
	std::ios::sync_with_stdio(false);
	int t = 1;
	//cin >> t;
	while(t--){
		solve();
	}

	return 0;
}

