int main(){
    int N;
    cin>>N;
    vector<ll> A(N);
    REP(i,N) cin>>A[i];
    vector<ll> A_SUM(N+1,0);
    REP(i,N){
        A_SUM[i+1]=A_SUM[i]+A[i];
    }

    ll ans=INF;
    REP2(i,2,N-1){
        int p,q,r,s;
        q=i;
        ll L=INF;
        ll R=INF;
        //1～i
        int j=upper_bound(A_SUM.begin(),A_SUM.end(),A_SUM[i]/2)-A_SUM.begin();
        if(j<i){
            if(abs(A_SUM[i]-2*A_SUM[j])<L){
                p=j;
                L=abs(A_SUM[i]-2*A_SUM[j]);
            } 
        }
        j--;
        if(j>=1){
            if(abs(A_SUM[i]-2*A_SUM[j])<L){
                p=j;
                L=abs(A_SUM[i]-2*A_SUM[j]);
            } 

        }

        //i+1～N
        j=upper_bound(A_SUM.begin(),A_SUM.end(),(A_SUM[N]+A_SUM[i])/2)-A_SUM.begin();

        if(j<N){
            if(abs(A_SUM[N]-2*A_SUM[j]+A_SUM[i])<R){
                r=j;
                R=abs(A_SUM[N]-2*A_SUM[j]+A_SUM[i]);
            } 
        }

        j--;
        if(j>=i+1){
            if(abs(A_SUM[N]-2*A_SUM[j]+A_SUM[i])<R){
                r=j;
                R=abs(A_SUM[N]-2*A_SUM[j]+A_SUM[i]);
            } 
        }

        s=N;
        ll ans_min=INF;
        ll ans_max=0;

        ans_min=min(ans_min,A_SUM[p]);
        ans_min=min(ans_min,A_SUM[q]-A_SUM[p]);
        ans_min=min(ans_min,A_SUM[r]-A_SUM[q]);
        ans_min=min(ans_min,A_SUM[s]-A_SUM[r]);

        ans_max=max(ans_max,A_SUM[p]);
        ans_max=max(ans_max,A_SUM[q]-A_SUM[p]);
        ans_max=max(ans_max,A_SUM[r]-A_SUM[q]);
        ans_max=max(ans_max,A_SUM[s]-A_SUM[r]);

        ans=min(ans,ans_max-ans_min);
    }
    cout<<ans<<endl;
}

