//[b, e)
void solve(vll& A, vll& acc, int b, int e, ll& sum1, ll& sum2) {
  ll targetSum = (acc[e] - acc[b]) / 2 + acc[b];
  auto f = lower_bound(&acc[b], &acc[e], targetSum);
  if(f == &acc[e]) {
    //全て以下 => 最後とする
    sum1 = acc[e-1] - acc[b];
    sum2 = acc[e] - acc[e-1];
    if(sum1 > sum2) swap(sum1, sum2);
    return;
  }
  // 0 2 5 9 14
  // 2 3 4 5
  // [0, 2)
  // [2, 4)

  if(f == &acc[b]) {
    sum1 = acc[b+1] - acc[b];
    sum2 = acc[e] - acc[b+1];
    if(sum1 > sum2) swap(sum1, sum2);
    return;
  }

  if(abs(*f - targetSum) < abs(*(f - 1) - targetSum)) {
    sum1 = *f - acc[b];
    sum2 = acc[e] - *f;
    if(sum1 > sum2) swap(sum1, sum2);
    return;
  } else {
    sum1 = *(f - 1) - acc[b];
    sum2 = acc[e] - *(f - 1);
    if(sum1 > sum2) swap(sum1, sum2);
    return;
  }
}

