template<typename T> T lminimum(const std::vector< T >& v) {return *std::min_element(v.begin(), v.end());}
template<typename T> T lmaximum(const std::vector< T >& v) {return *std::max_element(v.begin(), v.end());}


std::pair<ll, ll> divide(std::vector< ll >& vsum, ll s, ll e)
{
  ll ok = s, ng = e;
  ll section_sum = vsum[e] - vsum[s-1];


  while (ng - ok > 1) {
    ll mid = (ok + ng) / 2;
    if ((vsum[mid] - vsum[s-1]) * 2 < section_sum) {
      ok = mid;
    } else {
      ng = mid;
    }
  }

  std::pair<ll, ll> former = std::make_pair(vsum[ok+0] - vsum[s-1], vsum[e] - vsum[ok+0]);
  std::pair<ll, ll> later  = std::make_pair(vsum[ok+1] - vsum[s-1], vsum[e] - vsum[ok+1]);

  if (std::fabs(former.first - former.second) < std::fabs(later.first - later.second)) {
    return former;
  } else {
    return later;
  }
}

int main(int argc, char* argv[])
{
  ll N;
  std::cin >> N;
  std::vector< ll > va(N, 0LL);
  std::vector< ll > vsum(N+1, 0LL);
  vsum[0] = 0;
  for (ll i = 0; i < N; i++) {
    std::cin >> va[i];
    vsum[i+1] = va[i] + vsum[i];
  }

  ll ans = INF;

  // vsum は [0, N] の配列
  // 最も左端の例だと, 区間の和は vsum[1] - vsum[0], vsum[2] - vsum[1]
  // なので, 2 が最小
  // 最も右端の例だと, 区間の和は vsum[N] - vsum[N-1], vsum[N-1] - vsum[N-2]
  // の分を考慮する必要があるので, N-2 が最大
  for (ll i = 2; i <= N-2; i++) {
    std::vector< ll > v4(4);
    std::pair<ll, ll> p1 = divide(vsum, 1, i);
    std::pair<ll, ll> p2 = divide(vsum, i+1, N);
    v4[0] = p1.first;
    v4[1] = p1.second;
    v4[2] = p2.first;
    v4[3] = p2.second;
    ans = std::min(ans, lmaximum(v4) - lminimum(v4));
  }

  print(ans);
  return 0;
}

