        for (int l = 0; l < k; l++) {
            long ll = sum[l];
            long lr = sum[k] - sum[l];
            if (abs(ll - lr) <= maxl - minl) {
                minl = min(ll, lr);
                maxl = max(ll, lr);
            }
        }
        long minr = min(sum[k + 1] - sum[k], sum[n - 1] - sum[k + 1]);
