        for (int r = k + 1; r < n - 1; r++) {
            long rl = sum[r] - sum[k];
            long rr = sum[n - 1] - sum[r];
            if (abs(rl - rr) <= maxr - minr) {
                minr = min(rl, rr);
                maxr = max(rl, rr);
            }
        }
        if (max(maxl, maxr) - min(minl, minr) < mind) {
            mind = max(maxl, maxr) - min(minl, minr);
        }
    }
    cout << mind << endl;
}

