  }

  long long int answer = 1LL << 60, l = 1, r = 3;

  for (int i = 2; i < N - 1; i++) {
    while (check(0, l, i)) l++;
    while (check(i, r, N)) r++;

    // std::cout << l << " " << i << " " << r << " " << maximum(l, i, r) << " " << minimum(l, i, r) << std::endl;

    answer = std::min(answer, maximum(l, i, r) - minimum(l, i, r));
