  cout << setprecision(20) << setiosflags(ios::fixed);

  ll n;
  cin >> n;
  ll a[200010];
  rep(i, n) cin >> a[i];
  ll csum[200010];
  csum[0] = 0;
  rep(i, n) csum[i + 1] = csum[i] + a[i];

  //[l, r)の和
  auto sum = [&](ll l__, ll r__) {
    return csum[r__] - csum[l__];
  };

  auto binary_search = [&](ll l_, ll r_) {
    ll lo = l_, hi = r_;
    while (hi - lo > 1)
    {
      ll mi = (lo + hi) / 2;
      if (sum(l_, mi) <= sum(mi, r_))
        lo = mi;
      else
        hi = mi;
    }
    return lo;
  };

  ll ans = LINF;

  //[0,i)と[i,n)に分ける
  REP(i, 2, n - 1)
  {

    //[0,x)の和<=[x,i)の和を満たす最大のx
    ll l = binary_search(0, i);
    ll P1 = sum(0, l), Q1 = sum(l, i);
    ll P2 = sum(0, l + 1), Q2 = sum(l + 1, i);
    ll P, Q;
    if (abs(P1 - Q1) <= abs(P2 - Q2))
      P = P1, Q = Q1;
    else
      P = P2, Q = Q2;

    //[i,x)の和<=[x,n)の和を満たす最大のx
    ll r = binary_search(i, n);
    ll R1 = sum(i, r), S1 = sum(r, n);
    ll R2 = sum(i, r + 1), S2 = sum(r + 1, n);
    ll R, S;
    if (abs(R1 - S1) <= abs(R2 - S2))
      R = R1, S = S1;
    else
      R = R2, S = S2;

    ll score = max({P, Q, R, S}) - min({P, Q, R, S});
    ans = min(ans, score);
  }
  cout << ans << endl;
  return 0;
}

