        while (l <= m - 2 && diff(0, l, m, A) > diff(0, l + 1, m, A)) {
            l++;
        }
        while (r <= N - 2 && diff(m, r, N, A) > diff(m, r + 1, N, A)) {
            r++;
        }

        vector<int> p(4);
        p[0] = A[l] - A[0];
        p[1] = A[m] - A[l];
        p[2] = A[r] - A[m];
        p[3] = A[N] - A[r];
        int diff = *max_element(p.begin(), p.end()) - *min_element(p.begin(), p.end());
        mindiff = min(mindiff, diff);
    }
    cout << mindiff << endl;
    return 0;
}

