        if (sum * (5 - p) >= pref[n] - pref[pos - 1]) {
            if (i > pos + 1) {
                v.pb(sum - arr[i] - arr[i - 1]);
                rec(p + 1, i - 1, v);
                v.pop_back();
            }
            if (i != pos) {
                v.pb(sum - arr[i]);
                rec(p + 1, i, v);
                v.pop_back();
            }
            v.pb(sum);
            rec(p + 1, i + 1, v); v.pop_back();
            if (n - i - 1 >= 4 - p) {
                v.pb(sum + arr[i + 1]);
                rec(p + 1, i + 2, v);
                v.pop_back();
