	vector<ll> A(N+2), leftsum(N+2, 0), rightsum(N+2, 0);//leftsumは左から足した和
	ll sum=0;
	for(int i=1; i<=N; i++){
		cin >> A[i];
		sum+=A[i];
		leftsum[i]=sum;
	}
	leftsum[N+1]=sum;
	for(int i=1; i<=N; i++){
		rightsum[i]=rightsum[i-1]+A[N-i+1];
	}
	rightsum[N+1]=sum;
	ll ans=100000000000;

	for(int mid=3; mid<=N-1; mid++){
		ll sum1=leftsum[mid-1];
		ll sum2=rightsum[N-mid+1];

		auto iter1=lower_bound(leftsum.begin()+1, leftsum.begin()+mid-1, (double)sum1/2);//key以上のうちもっとも小さい値
		auto iter2=iter1-1;
		auto iter3=lower_bound(rightsum.begin()+1, rightsum.begin()+N-mid+1, (double)sum2/2);
		auto iter4=iter3-1;

		if(iter1>=leftsum.begin()+1 && iter1<=leftsum.begin()+mid-1){
			if(iter3>=rightsum.begin()+1 && iter3<=rightsum.begin()+N-mid+1){//rightsum.end()-1
				ans=min(ans, max(*iter1, *iter3)-min(sum1-*iter1, sum2-*iter3));//rightsum.end()-mid+1
			}
			if(iter4>=rightsum.begin()+1 && iter4<=rightsum.begin()+N-mid+1){
				ans=min(ans, max(*iter1, sum2-*iter4)-min(sum1-*iter1, *iter4));
			}
		}
		if(iter2>=leftsum.begin()+1 && iter2<=leftsum.begin()+mid-1){
			if(iter3>=rightsum.begin()+1 && iter3<=rightsum.begin()+N-mid+1){
				ans=min(ans, max(sum1-*iter2, *iter3)-min(*iter2, sum2-*iter3));
			}
			if(iter4>=rightsum.begin()+1 && iter4<=rightsum.begin()+N-mid+1){
				ans=min(ans, max(sum1-*iter2, sum2-*iter4)-min(*iter2, *iter4));
			}
		}
	}

	cout << ans << endl;


    return 0;
}

