using namespace std;

int cut(vector<int64_t>& sumA, int c)
{
  cerr << "sumA:";
  for (const auto& a : sumA)
    cerr << a << ' ';
  cerr << endl;

  cerr << sumA.back() - sumA.front() << endl;

  int64_t min_diff = INT64_MAX;
  while(c<sumA.size()-1) {
    int64_t sumA1 = sumA[c] - sumA.front();
    int64_t sumA2 = sumA.back() - sumA[c];

    if (min_diff < abs(sumA2 - sumA1))
      break;

    min_diff = abs(sumA2 - sumA1);
    ++c;
  }
  --c;

  return c;
}

int main()
{
  int N;
  cin >> N;
  vector<int64_t> sumA = {0};

  int64_t sum = 0;
  for (int64_t n=0; n<N; ++n) {
    int64_t a;
    cin >> a;
    sum += a;
    sumA.push_back(sum);
  }

  int64_t ans = INT64_MAX;
  int c1 = 1;
  int c2 = 2;
  int c3 = 3;
  for (; c2 < N-1; ++c2) {
    vector<int64_t> sumB(sumA.begin(),sumA.begin()+c2+1), sumC(sumA.begin()+c2,sumA.end());
    c1 = cut(sumB,c1), c3 = c2 + cut(sumC,max(c3-c2-1,1));

    int64_t sum1 = sumA[c1], sum2 = sumA[c2] - sumA[c1], sum3 = sumA[c3] - sumA[c2], sum4 = sumA.back() - sumA[c3];

    int64_t sumMAX = max(max(sum1,sum2),max(sum3,sum4));
    int64_t sumMin = min(min(sum1,sum2),min(sum3,sum4));

    int64_t sub = sumMAX - sumMin;
    if (sub < ans)
      ans = sub;
    else
      break;
  }
  cout << ans << endl;

  return 0;
}

