ll getmin(int sc, int n) {
    int newlc, newrc;

    int i = lc;
    while(i < sc && abs(a[sc] - 2 * a[i]) >= abs(a[sc] - 2 * a[i + 1])) {
        i++;
    }
    newlc = i;

    i = rc;
    while(i < n && abs(a[sc] + a[n] - 2 * a[i]) >= abs(a[sc] + a[n] - 2 * a[i + 1])) {
        i++;
    }
    newrc = i;

    lc = newlc;
    rc = newrc;
    ll q[4];
    q[0] = a[lc];
    q[1] = a[sc] - a[lc];
    q[2] = a[rc] - a[sc];
    q[3] = a[n] - a[rc];
    ll min = q[0];
    ll max = q[0];
    for (int i = 1; i < 4; i++) {
        if (min > q[i])
            min = q[i];
        if (max < q[i])
            max = q[i];
    }
    ll ans = max - min;
    return ans;
}

