ll sum[N];


bool chk(int a, int b, int c) {
    ll diff = llabs(sum[c] - sum[b] - sum[b] + sum[a]);
    b++;
    ll diff1 = llabs(sum[c] - sum[b] - sum[b] + sum[a]);
    if(diff1 < diff) return true;
    return false;
}

