    }

    ll res = 1e18;
    for(int a = 1, b = 2, c = 3; b <= n - 2; b++) {
        while(chk(0, a, b)) a++;
        while(chk(b, c, n)) c++;
        ll mx = max({sum[a], sum[b] - sum[a], sum[c] - sum[b], sum[n] - sum[c]});
        ll mn = min({sum[a], sum[b] - sum[a], sum[c] - sum[b], sum[n] - sum[c]});
        res = min(mx - mn, res);
    }

    printf("%lld\n", res);
}

