    partial_sum(A.begin(), A.end(), s.begin()+1);

    ll ans = LLONG_MAX;
    for (int c = 2; c <= N-2; c++) {
        auto it_l = upper_bound(s.begin(), s.begin() + c + 1, s[c]/2);
        int l = max(1, (int)distance(s.begin(), it_l)-1);
        if (l + 1 != c) {
            ll d1 = abs(s[c] - s[l  ] - s[l  ]);
            ll d2 = abs(s[c] - s[l+1] - s[l+1]);
            if (d2 < d1) l++;
        }

        auto it_r = upper_bound(s.begin() + c + 1, s.end(), (s[c]+s.back())/2);
        int r = max(c+1, (int)distance(s.begin(), it_r)-1);
        if (r + 1 != N) {
            ll d1 = abs((s[r  ] - s[c]) - (s.back() - s[r  ]));
            ll d2 = abs((s[r+1] - s[c]) - (s.back() - s[r+1]));
            if (d2 < d1) r++;
        }
        vector<ll> pqrs = { s[l], s[c]   - s[l], s[r]   - s[c], s.back() - s[r] };
        ll a = *max_element(pqrs.begin(), pqrs.end()) - *min_element(pqrs.begin(), pqrs.end());

        ans = min(ans, a);
    }

    cout << ans << endl;
}

