int n;
LL l,r,ans;
LL c[5];
LL check(LL d){
    LL hi=(a[n]-d+3)/4;
    LL low=(a[n]>3*d) ? (a[n]-3*d+3)/4 : 1 ;
//    cout<<"d="<<d<<" low="<<low<<" hi="<<hi<<"  mx="<<hi+d<<endl;

    int i=1,j=2,k=3;
    LL dis=a[n];
    i=lower_bound(a+1,a+1+n,low)-(a+1);
    while (i+3<=n){
        if (a[i]-a[0]<low) {i++;continue;}
        if (a[i]-a[0]>hi+d) break;
        j=lower_bound(a+1+i,a+1+n,a[i]+low)-(a+1+i);
        while (j+2<=n){
            if (a[j]-a[i]<low) {j++;continue;}
            if (a[j]-a[i]>hi+d) break;

            k=lower_bound(a+1+j,a+1+n,a[j]+low)-(a+1+j);
            while (k+1<=n){
                if (a[k]-a[j]<low) {k++;continue;}
                if (a[k]-a[j]>hi+d) break;
//                cout<<"i="<<i<<" j="<<j<<" k="<<k<<endl;
                c[0]=a[i]-a[0];
                c[1]=a[j]-a[i];
                c[2]=a[k]-a[j];
                c[3]=a[n]-a[k];
                sort(c,c+4);
//                cout<<c[0]<<" "<<c[1]<<" "<<c[2]<<" "<<c[3]<<" --- "<<c[3]-c[0]<<endl;

                if (c[3]-c[0]<=d) dis=min(dis,c[3]-c[0]);
                k++;
            }
            j++;
        }
        i++;
    }
    return dis;
}
