    a[0]=0;
    l=0;r=a[n];
    for (int i=1;i<=n;i++) {cin>>a[i];l=min(l,a[i]);r=max(r,a[i]);a[i]+=a[i-1];}

    while (l<=r){
        LL mid=(l+r)>>1;
        LL tmp=check(mid);
        if (tmp<=mid) {ans=tmp;r=tmp-1;}else l=mid+1;
    }
    cout<<ans<<endl;
    return 0;
}

