        // r : 右カット位置
        FOR(r, c+1, N-1){
            ll leftSum = AC[r] - AC[c];
            ll rightSum = AC[N-1] - AC[r];
            ll sumDiff = abs(leftSum - rightSum);

            // 一歩先を見る
            ll leftSumNext = leftSum + A[r+1];
            ll rightSumNext = rightSum - A[r+1];
            ll sumDiffNext = abs(leftSumNext - rightSumNext);

            // diffが減るなら続ける
            if(sumDiff > sumDiffNext){
                continue;
            }else{
                // pn(r); ///
                R = leftSum;
                S = rightSum;
                break;
            }
        }


        // cを決めたときにl, rを最適化した
        // ここで
        // cout << "PQRS " << P << " " << Q << " " << R << " " << S << endl; ///
        vector<ll> temp;
        temp.push_back(P);
        temp.push_back(Q);
        temp.push_back(R);
        temp.push_back(S);
        sort(ALL(temp));
        ll diff = temp[3] - temp[0];
        // pn(diff); ///
        if(diff < minDiff){
            minDiff = diff;
        }

        //p(""); /// 
    }

    p(minDiff);

    return 0;
}

