using namespace std;
const long long inf = 1234567891234567891;
int main() {
	int N;
	cin >> N;
	vector<long long> A(N), S(N + 1);
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
		S[i + 1] = S[i] + A[i];
	}
	vector<long long> pl(N + 1, -inf), pr(N + 1, inf); // ---> A[i]
	vector<long long> ql(N + 1, -inf), qr(N + 1, inf); // A[i] <---
	set<long long> s;
	for (int i = 2; i <= N; ++i) {
		s.insert(S[i - 1]);
		set<long long>::iterator it = s.lower_bound((S[i] + 1) / 2);
		long long mindiff = inf;
		if (it != s.end()) {
			mindiff = 2 * (*it) - S[i];
		}
		if (it != s.begin()) {
			--it;
			mindiff = min(mindiff, S[i] - 2 * (*it));
		}
		pl[i] = (S[i] - mindiff) / 2;
		pr[i] = (S[i] + mindiff) / 2;
	}
	s.clear();
	for (int i = N - 2; i >= 0; --i) {
		s.insert(S[N] - S[i + 1]);
		set<long long>::iterator it = s.lower_bound((S[N] - S[i] + 1) / 2);
		long long mindiff = inf;
		if (it != s.end()) {
			mindiff = 2 * (*it) - (S[N] - S[i]);
		}
		if (it != s.begin()) {
			--it;
			mindiff = min(mindiff, (S[N] - S[i]) - 2 * (*it));
		}
		ql[i] = (S[N] - S[i] - mindiff) / 2;
		qr[i] = (S[N] - S[i] + mindiff) / 2;
	}
	long long ans = inf;
	for (int i = 2; i <= N - 2; ++i) {
		ans = min(ans, max(pr[i], qr[i]) - min(pl[i], ql[i]));
	}
	cout << ans << endl;
	return 0;
}

