typedef long long s64;

int main()
{
    s64 sumArray[200000];
    int N;
    cin >> N;
    for (int i = 0; i < N; ++i)
    {
        int a;
        cin >> a;
        if (i == 0)
        {
            sumArray[i] = a;
        }
        else
        {
            sumArray[i] = sumArray[i - 1] + a;
        }
    }

    auto calc = [sumArray](int first, int last, s64* min, s64* max) {
        int leftLast = (first + last) / 2;

        auto calcLR = [sumArray](int first, int last, int leftLast, s64* left,
                                 s64* right) {
            *left = sumArray[leftLast];
            if (first != 0)
            {
                *left -= sumArray[first - 1];
            }
            *right = sumArray[last] - sumArray[leftLast];
        };

        s64 left, right;
        calcLR(first, last, leftLast, &left, &right);
        if (left < right)
        {
            while (leftLast + 1 < last)
            {
                *min = left;
                *max = right;
                ++leftLast;
                calcLR(first, last, leftLast, &left, &right);
                if (left >= right)
                {
                    if (left - right < *max - *min)
                    {
                        *min = right;
                        *max = left;
                    }
                    return;
                }
            }
            *min = left;
            *max = right;
        }
        else
        {
            while (first <= leftLast - 1)
            {
                *min = right;
                *max = left;
                --leftLast;
                calcLR(first, last, leftLast, &left, &right);
                if (left < right)
                {
                    if (right - left < *max - *min)
                    {
                        *min = left;
                        *max = right;
                    }
                    return;
                }
            }
            *min = right;
            *max = left;
        }
    };

    s64 diffMin = -1;
    for (int leftLast = 1; leftLast <= N - 3; ++leftLast)
    {
        s64 leftMin, leftMax, rightMin, rightMax;
        calc(0, leftLast, &leftMin, &leftMax);
        calc(leftLast + 1, N - 1, &rightMin, &rightMax);
        s64 diff = max(leftMax, rightMax) - min(leftMin, rightMin);
        if (diffMin == -1 || diff < diffMin)
        {
            diffMin = diff;
        }
    }
    cout << diffMin << endl;

    return 0;
}

