ll binary_search(ll start,ll border,ll sub) {
	//P>=Qとなる最小のindexを返す
    ll ng = start-1; 
    ll ok = border+1; 
    while (abs(ok - ng)>1) {
        ll mid = (ok + ng) / 2;
        if (check(mid,border,sub)) ok = mid;
        else ng = mid;
    }
    return ok;
}

