            i++;
        }

        while(i < n){
            S += a[i];
            if(mid < S){
                S -= a[i];
                break;
            }
            i++;
        }

        if(i != n){
            lb = mid;
            continue;
        }

        if(Q == 0 || R == 0 || S == 0){
            ub = mid;
            continue;
        }

        ll nmax = max({P, Q, R, S});
        ll nmin = min({P, Q, R, S});

        chmin(ans, nmax - nmin);
        ub = mid;
    }

    cout << ans << endl;
}

