int div(int s, int t, int a[]){
  ll sum = 0;
  for(int i = s; i < t; i++){
    sum += a[i];
  }
  int i = s;
  ll s0 = 0;
  while(true){
    ll s1 = s0 + a[i];
    if(abs(s0 - (sum - s0)) < abs(s1 - (sum - s1))) break;
    s0 = s1;
    ++i;
  }
  return i;
}

