int countt(int h,int e)
{
	int w,l,r;
	int ww;
	ll de=INF;
	l = h;
	r = e;
	while(l+2 <= r)
	{
		w = (l+r)/2;
		if(abs(ns[w]-ns[h]-(ns[e]-ns[w])) < de)
		{
			de = abs(ns[w]-ns[h]-(ns[e]-ns[w]));
			ww = w;
		}
		if(ns[w]-ns[h] < ns[e]-ns[w])
		{
			l = w;
		}
		else
		{
			r = w;
		}
	}
	return ww;
}
