	}
	for(i=2;i<=n-2;i++)
	{
		int wl,wr;
		ll l1,l2,r1,r2;
		wl = countt(0,i);
		wr = countt(i,n);
		l1 = ns[wl]-ns[0];
		l2 = ns[i]-ns[wl];
		r1 = ns[wr]-ns[i];
		r2 = ns[n]-ns[wr];
		if(l1 > l2)
		{
			ll t;
			t = l1;
			l1 = l2;
			l2 = t;
		}
