using namespace std;

class SegTree {
private:
	SINT64 size;
	vector<SINT64> node;

	SINT64 jugdement(SINT64 a, SINT64 b) {
		SINT64 ans = 0;
		ans = a+b;
		return ans;
	}

public:

	//コンストラクタ
	SegTree(vector<SINT64> data) {
		SINT64 ori_size;
		ori_size = data.size();
		size = 1;
		while (size < ori_size) {
			size *= 2;
		}
		node.resize(2*size-1, 0);

		rep(i,0,ori_size) {
			node[size-1+i] = data[i];
		}
		rrep(i,size-2,0) {
			node[i] = jugdement(node[2*i+1], node[2*i+2]);
		}
	}


	//データ取得 [a,b)
	SINT64 getdata(SINT64 a, SINT64 b, SINT64 k = 0, SINT64 l = 0, SINT64 r = -1) {
		if (r < 0) {
			r = size;
		}

		//要求範囲外
		if ((r <= a) || (b <= l)) {
			return 0;
		}
		//完全要求区間内
		if ((a <= l) && (r <= b)) {
			return node[k];
		}

    	SINT64 vl = getdata(a, b, 2*k+1, l, (l+r)/2);
    	SINT64 vr = getdata(a, b, 2*k+2, (l+r)/2, r);
    	return jugdement(vl, vr);
	}

	//表示
	void disp() {
		rep(i,0,size) {
			puts(node[size-1+i]);
		} cout << endl;
	}

	void alldisp() {
		SINT64 cnt = 0;
		SINT64 end = 2;

		while (1) {
			puts(node[cnt]);
			if (cnt == end-2) {
				end *= 2;
				cout << endl;
			}
			cnt++;
			if (cnt == size*2-1) {
				break;
			}
		}	
	}
};



int main() {

	SINT64 N;	cin >> N;

	vector<SINT64> data(N);

	SINT64 ans = INF64;

	rep(i,0,N) {
		cin >> data[i];
	}
	SegTree seg(data);

	rep(i,2,N-1) {

		SINT64 a,b,c,d;
		SINT64 buf = INF64;
		rep(j,1,i) {
			a = seg.getdata(0,j);
			b = seg.getdata(j,i);
			if (ABS(a-b) <= buf) {
				buf = ABS(a-b);
			} else {
				a = seg.getdata(0,j-1);
				b = seg.getdata(j-1,i);
				break;
			}
		}
		buf = INF64;
		rep(j,i+1,N) {
			c = seg.getdata(i,j);
			d = seg.getdata(j,N);
			if (ABS(c-d) <= buf) {
				buf = ABS(c-d);
			} else {
				c = seg.getdata(i,j-1);
				d = seg.getdata(j-1,N);
				break;
			}
		}

		ans = MIN(ans,max({a,b,c,d})-min({a,b,c,d}));
//		puts(a);puts(b);puts(c);put(d);

	}

	put(ans);
	return 0;
}


