#include<bits/stdc++.h>
#define BRUTE_FORCE 100
using namespace std;
int main(){
  vector<int> v;
  int cd, n, lp, rp, p;
  long lsum = 0, rsum = 0, b, c, d, e;
  vector<long> res(BRUTE_FORCE);
  cin >> n;
  v.resize(n);
  for(int i=0;i<n;i++)cin >> v[i];
  lp=0,rp=n-1,lsum=v[0],rsum=v[n-1];
  for(int i=0;lp+1<rp;i++){
    if(lsum>rsum)rsum+=v[--rp];
    else if(lsum<rsum)lsum+=v[++lp];
    else if(v[lp+1]>=v[rp-1])rsum+=v[--rp];
    else lsum+=v[++lp];
  }
  cerr << "[1]:" << lp << " " << rp << "|" << lsum << " " << rsum << endl;
  cd = rp;
  for(p=0;p<BRUTE_FORCE;p++){
    int t = cd + ((p+1)/2)*(p%2?-1:1);
    if(t<2 || n-3<t)break;
    lp=0,rp=t-1,lsum=v[0],rsum=v[t-1];
    for(int i=0;lp+1<rp;i++){
      if(lsum>rsum)rsum+=v[--rp];
      else if(lsum<rsum)lsum+=v[++lp];
      else if(v[lp+1]>=v[rp-1])rsum+=v[--rp];
      else lsum+=v[++lp];
    }
    cerr << "[2]:" << lp << " " << rp << "|" << lsum << " " << rsum << endl;
    b = lsum, c = rsum,lp=t,rp=n-1,lsum=v[t],rsum=v[n-1];
    for(int i=0;lp+1<rp;i++){
      if(lsum>rsum)rsum+=v[--rp];
      else if(lsum<rsum)lsum+=v[++lp];
      else if(v[lp+1]>=v[rp-1])rsum+=v[--rp];
      else lsum+=v[++lp];
    }
    cerr << "[3]:" << lp << " " << rp << "|" << lsum << " " << rsum << endl;
    d = lsum, e = rsum;
    res[p] = max({b,c,d,e})-min({b,c,d,e});
    cerr << "res[" << p << "]:" << res[p] << endl;
  }

  cout << *(min_element(res.begin(),res.begin()+p)) << endl;
  return 0;
}

