#define ALL(a) (a).begin(),(a).end()
#define vi vector<int>
#define vii vector<vi>
#define pii pair<int,int>
#define priq priority_queue<int>
#define disup(A,key) distance(A.begin(),upper_bound(ALL(A),(int)(key)))
#define dislow(A,key) distance(A.begin(),lower_bound(ALL(A),(int)(key)))
#define tii tuple<int,int,int>
#define Priq priority_queue<int,vi,greater<int>>
#define pb push_back
#define mp make_pair
#define INF (1ll<<60)
signed main(){
  int N; cin>>N;
  vi A(N);
  rep(i,0,N) cin>>A[i];
  vi dp(N+1);
  rep(i,0,N) dp[i+1]=dp[i]+A[i];
  vi B(3);
  int B[0]=disup(dp,dp[N]/2),B[1]=dislow(dp,dp[N]/2),B[2]=B[1]-1;
  int ans=INF;
  rep(i,0,3){
    vi C(3),D(3);
    int C[0]=disup(dp,dp[B[i]]/2),C[1]=dislow(dp,dp[B[i]]/2),C[2]=C[1]-1;
    int D[0]=disup(dp,(dp[B[i]]+dp[N])/2),D[1]=dislow(dp,(dp[B[i]]+dp[N])/2),D[2]=C[1]-1;
    rep(j,0,3){
      rep(k,0,3){
        if(0<C[j]&&C[j]<B[i]&&B[i]<D[k]&&D[k]<N){
          int E=dp[C[j]];
          int F=dp[B[i]]-E;
          int G=dp[D[k]]-dp[B[i]];
          int H=dp[N]-dp[D[k]];
          int I=max({E,F,G,H})-min({E,F,G,H});
          ans=min(I,ans);
        }
      }
    }
  }
  cout<<ans<<endl;
  }

