using namespace std;
typedef long long ll;
#define rep(i,n) for(int i=0;i<n;i++)

ll maxx(ll x,ll y,ll z,ll w){
  return max(x,max(y,max(z,w)));
}
ll minn(ll x,ll y,ll z,ll w){
  return min(x,min(y,min(z,w)));
}
int main() {
  ll N; cin>>N;
  ll ans=10000000000000;
  vector<ll> s(N+1,0);
  rep(i,N){
    ll a; cin>>a;
    s[i+1]=s[i]+a;
  }
  ll i=2;//真ん中の分割
  ll l=1;//l:1~i-1
  ll r=3;//r:i+1~N-1
  ll P,Q,R,S;
  while(i<=N-2){
    while(1){//lを決定する
      if(l<i-1 && abs(s[l]-(s[i]-s[l]))>abs((s[l+1])-(s[i]-s[l+1]))){
        l++;
        continue;
      }
      break;
    }
    while(1){//rを決定する
      if(r<N-1 && abs((s[r]-s[i])-(s[N]-s[r]))>abs((s[r+1]-s[i])-(s[N]-s[r+1]))){
        r++;
        continue;
      }
      break;
    }

    P=s[l];
    Q=s[i]-s[l];
    R=s[r]-s[i];
    S=s[N]-s[r];
    ans=min(ans,maxx(P,Q,R,S)-minn(P,Q,R,S));

    i++;
  }
  cout<<ans<<endl;
}

