int N = 0;
ull A[2*100002] = {0};

ull lsum[2*100001] = {0};
ull rsum[2*100001] = {0};

int main(void) {
  std::cin >> N;

  for (int i = 0; i < N; i++) {
    std::cin >> A[i];
  }
  lsum[0] = A[0];
  rsum[N-1] = A[N-1];
  for (int i = 1; i < N; i++) {
    lsum[i] += lsum[i-1] + A[i];
    auto ri = N - 1 - i;
    rsum[ri] += rsum[ri+1] + A[ri];
  }

  //for (int i = 0; i < N; i++) {
  //  std::cout << lsum[i] << "," << rsum[N-1-i] << std::endl;
  //}

  ull group[4] = {0};
  ull result_diff = LLONG_MAX;
  size_t blidx = 1;
  size_t bridx = 3;
  for (size_t i = 2; i < N-1; i++) {

    ull llsum = group[0] = lsum[blidx - 1];
    ull lrsum = group[1] = lsum[i-1] - lsum[blidx - 1];
    ull ldiff = abs(lrsum - llsum);
    for (size_t l = blidx + 1; l < i; l++) {
      ull diff = abs(lsum[i - 1] - 2 * lsum[l - 1]);
      if (ldiff > diff) {
        ldiff = diff;

        blidx = l;
        group[0] = lsum[blidx - 1];
        group[1] = lsum[i-1] - lsum[blidx -1];
      } else {
        break;
      }
    }

    ull rdiff = abs(rsum[i] - 2 * rsum[bridx]);
    while(bridx < N + 1) {
      ull diff = abs(rsum[i] - 2 * rsum[bridx + 1]);
      if (rdiff > diff) {
        rdiff = diff;

        bridx++;
      } else {
        break;
      }
    }
    group[2] = rsum[i] - rsum[bridx];
    group[3] = rsum[bridx];

    //std::cout << " " << group[0] << " " << group[1] << " " << group[2] << " " << group[3] << std::endl;
    std::sort(group, group + 4);
    ull diff = group[3] - group[0];
    if (result_diff > diff) {
      result_diff = diff;
    }
  }

  std::cout << result_diff << std::endl;

  return 0;
}

