int main(){
    int N;
    cin >> N;
    ll A[N], S[N], T[N];
    rep(i, N){
        cin >> A[i];
    }
    S[0] = A[0], T[0] = A[N-1];
    rep2(i, 1, N-1) S[i] = S[i-1]+A[i];
    rep2(i, 1, N-1) T[i] = T[i-1]+A[N-1-i];
    //[0,i]を[0,a[i]]と(a[i], i]に分ける
    int a[N];
    rep(i, N){
        int n = upper_bound(S, S+N, S[i]/2) - S;
        if(n != 0){
            if(S[n] > S[i]-S[n-1]) n--;
        }
        a[i] = n;
    }
    //[N-1-i,N-1]を[N-1-i,N-1-b[i])と[N-1-b[i],N-1]
    int b[N];
    rep(i, N){
        int n = upper_bound(T, T+N, T[i]/2) - T;
        if(n != 0){
            if(T[n] > T[i]-T[n-1]) n--;
        }
        b[i] = n;
    }
    ll ans = INF;
    //まず[0, N)を[0,i)と[i,N)に分ける
    rep2(i, 2, N-2){
        ll tmp[4];
        tmp[0] = S[a[i-1]];
        tmp[1] = S[i-1] - tmp[0];
        tmp[2] = T[b[N-1-i]];
        tmp[3] = T[N-1-i] - tmp[2];
        sort(tmp, tmp+4);
        ans = min(ans, tmp[3]-tmp[0]);
    }
    cout << ans << endl;
}

