	// なかをいい感じに分割することである
	ans = LINF;
	FOR(c, 2, N - 1) { // cの位置
		// [A,B]:[1:c]
		PLL ab = f(csum, 1, c);
		// [C,D]:[c+1,N]
		PLL cd = f(csum, c + 1, N);
		LL Max = max({ ab.first,ab.second,cd.first,cd.second });
		LL Min = min({ ab.first,ab.second,cd.first,cd.second });
		ans = min(ans, Max - Min);
	}

	cout << ans << "\n";

	return 0;
}

