        lsum = l > 0 ? sum[i] - sum[l - 1] : sum[i];
        rsum = sum[r] - sum[i];
        if (mind > abs(rsum - lsum)) {
            mid = i;
            mind = abs(rsum - lsum);
        }
    }
    return mid;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    cin >> N;
    REP(i, N) { cin >> A[i]; }

    sum[0] = A[0];
    FOR(i, 1, N - 1) { sum[i] = sum[i - 1] + A[i]; }

    int ans = INF;
    REP(mid, N) {
        int lmid = solve(0, mid);
        int rmid = solve(mid + 1, N - 1);
        int sum1 = sum[lmid];
        int sum2 = sum[mid] - sum[lmid];
        int sum3 = sum[rmid] - sum[mid];
        int sum4 = sum[N - 1] - sum[rmid];
        int minsum = min({sum1, sum2, sum3, sum4});
        int maxsum = max({sum1, sum2, sum3, sum4});

        ans = min(ans, abs(maxsum - minsum));
    }
    cout << ans << endl;

    return 0;
}

