//segtreeの葉の先頭の添え字はN-1
void Solve(){
  ll n;
    cin>>n;
  vll A(n+1);
  ll ans=0;
  FOR(i,0,n){
    cin>>A[i+1];
    ans+=A[i+1];
  }

  FOR(i,0,n){
    A[i+1]+=A[i];
  }

  //真ん中を決める
  FOR(i,2,n-1){
    //A[i]/2を超えるところを探す
    //その前後がLの分け目
    auto itr1=lower_bound(ALL(A),A[i]/2);
    ll Lpoint=itr1-A.begin();
    Lpoint=min(Lpoint,i-1);
    if(Lpoint-1>0 and abs(A[i]-2*A[Lpoint-1])<abs(A[i]-2*A[Lpoint])){
      Lpoint--;
    }

    auto itr2=lower_bound(ALL(A),(A[n]+A[i])/2);
    ll Rpoint=itr2-A.begin();
    Rpoint=min(Rpoint,n-1);
    if(Rpoint-1>i and abs(A[n]-2*A[Rpoint-1]+A[i])<abs(A[n]-2*A[Rpoint]+A[i])){
      Rpoint--;
    }


    ll low=min({A[Lpoint],A[i]-A[Lpoint],A[Rpoint]-A[i],A[n]-A[Rpoint]});
    ll high=max({A[Lpoint],A[i]-A[Lpoint],A[Rpoint]-A[i],A[n]-A[Rpoint]});
    chmin(ans,high-low);
  }

  cout<<ans<<"\n";
}

