ll N, A[200000], ruiseki[200000];

ll nibun1(ll x, ll y, ll sum){
	if(2*A[0] >= sum){
		return sum - A[0];
	}
	if(y-x == 1){
		if(sum - 2*ruiseki[x] < 2*ruiseki[y] - sum){
			return ruiseki[x];
		}else{
			return sum - ruiseki[y];
		}
	}
	ll med = (x+y)/2;
	if(2*ruiseki[med] == sum){
		return sum/2;
	}else if(2*ruiseki[med] > sum){
		return nibun1(x, med, sum);
	}else{
		return nibun1(med, y, sum);
	}
}

ll nibun2(ll x, ll y, ll sum){
	if(y-x == 1){
		if(2*ruiseki[N-1] - 2*ruiseki[x] - sum < sum - 2*ruiseki[N-1] + 2*ruiseki[y]){
			return sum - ruiseki[N-1] + ruiseki[x];
		}else{
			return ruiseki[N-1] - ruiseki[y];
		}
	}
	int med = (x+y)/2;
	if(2*ruiseki[N-1] - 2*ruiseki[med] == sum){
		return ruiseki[N-1] - ruiseki[med];
	}else if(2*ruiseki[N-1] - 2*ruiseki[med] > sum){
		return nibun2(med, y, sum);
	}else{
		return nibun2(x, med, sum);
	}
}

