  }

  int res = 2000000000;
  for(int center = 2; center <= N - 2; center++){
  int left = find_pos(0, center);
  int right = find_pos(center, N);
  int x[4];
  x[0] = sum_A[left - 1];
  x[1] = sum_A[center - 1] - sum_A[left - 1];
  x[2] = sum_A[right - 1] - sum_A[center - 1];
  x[3] = sum_A[N - 1] - sum_A[right - 1];
  res = min(res, *max_element(x, x+4) - *min_element(x, x+4));
  }
