/* typedef */

typedef long long ll;

/* global variables */

ll asums[MAX_N + 1];

/* subroutines */

inline ll maxll(ll a, ll b) { return (a > b) ? a : b; }
inline ll minll(ll a, ll b) { return (a < b) ? a : b; }

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++) {
    int ai;
    scanf("%d", &ai);
    asums[i + 1] = asums[i] + ai;
  }

  ll mind = LINF;
  for (int k = 2; k + 2 <= n; k++) {
    ll av0 = (asums[0] + asums[k]) / 2, av1 = (asums[k + 1] + asums[n]) / 2;
    int i0 = lower_bound(asums, asums + k + 1, av0) - asums;
    int i1 = lower_bound(asums + k + 1, asums + n + 1, av1) - asums;

    for (int i = i0 - 1; i <= i0 + 1; i++)
      if (i > 0 && i < k) {
	ll b0 = asums[i] - asums[0], b1 = asums[k] - asums[i];
	ll maxb01 = maxll(b0, b1);
	ll minb01 = minll(b0, b1);
	for (int j = i1 - 1; j <= i1 + 1; j++)
	  if (j > k && j < n) {
	    ll b2 = asums[j] - asums[k], b3 = asums[n] - asums[j];
	    ll maxb23 = maxll(b2, b3);
	    ll minb23 = minll(b2, b3);
	    ll d = maxll(maxb01, maxb23) - minll(minb01, minb23);
	    if (mind > d) mind = d;
	  }
      }
  }

  printf("%lld\n", mind);
  return 0;
}

