        sum[i + 1] = sum[i] + a[i];
    }

    ll res = INF;
    int left, right;
    for(int i = 3; i < n; ++i){     // 真ん中の切り込み
        ll p, q, r, s;

        double S = (double)sum[i - 1] / 2;
        left = upper_bound(sum + 2, sum + i, (ll)S) - sum;
        double temp1 = abs(S - sum[left - 1]);
        double temp2 = INF;
        double temp3 = INF;
        if(left - 1 > 2){
            temp2 = abs(S - sum[left - 2]);
        }
        if(left + 1 <= i - 1){
            temp3 = abs(S - sum[left]);
        }
        if(min({temp1, temp2, temp3}) == temp2){
            --left;
        }
        else if(min({temp1, temp2, temp3}) == temp3){
            ++left;
        }

        S = (double)((sum[n] - sum[i - 1]) / 2);
        right = upper_bound(sum + i + 1, sum + n + 1, (ll)(S + sum[i - 1])) - sum;
        temp1 = abs(S - (sum[right - 1] - sum[i - 1]));
        temp2 = INF;
        temp3 = INF;
        if(right - 1 > i){
            temp2 = abs(S - (sum[right - 2] - sum[i - 1]));
        }
        if(right + 1 <= n){
            temp3 = abs(S - (sum[right] - sum[i - 1]));
        }
        if(min({temp1, temp2, temp3}) == temp2){
            --right;
        }
        else if(min({temp1, temp2, temp3}) == temp3){
            ++right;
        }

        p = sum[left - 1];
        q = sum[i - 1] - sum[left - 1];
        r = sum[right - 1] - sum[i - 1];
        s = sum[n] - sum[right - 1];

        ll temp = abs(max({p, q, r, s}) - min({p, q, r, s}));

        res = min(res, temp);
    }

    cout << res << endl;
}

