typedef long long s64;
s64 sumArray[200000];
int N;

void calcLR(int first, int last, int leftLast, s64* left, s64* right)
{
    *left = sumArray[leftLast];
    if (first != 0)
    {
        *left -= sumArray[first - 1];
    }
    *right = sumArray[last] - sumArray[leftLast];
}

int findLeftLast(int first, int last, int candFirst, int candLast, int depth)
{
    if (depth > 200000)
    {
        return 0;
    }
    if (candLast - candFirst == 1)
    {
        s64 left, right;
        calcLR(first, last, candFirst, &left, &right);
        s64 diff1 = abs(left - right);
        calcLR(first, last, candLast, &left, &right);
        s64 diff2 = abs(left - right);
        if (diff1 < diff2)
        {
            return candFirst;
        }
        else
        {
            return candLast;
        }
    }
    int llast = (candFirst + candLast) / 2;
    s64 left, right;
    calcLR(first, last, llast, &left, &right);
    if (left == right)
    {
        return llast;
    }
    else if (left < right)
    {
        if (llast == last - 1)
        {
            return llast;
        }
        return findLeftLast(first, last, llast, candLast, depth + 1);
    }
    else
    {
        if (llast == 0)
        {
            return llast;
        }
        return findLeftLast(first, last, candFirst, llast, depth + 1);
    }
}

