const int N = 100005;
LL n , ara[N] , sum[N];

LL getDif(int l,int i,int r)
{
    LL s1 = sum[i] - sum[l - 1];
    LL s2 = sum[r] - sum[i];
    return ABS(s1 - s2);
}
LL solve()
{
    FOR(i,1,n)sum[i] = sum[i - 1] + ara[i];

    int rptr = n + 1;
    LL lsum = 0,rsum = 0;
    LL ans = 1e18;
    for(int lptr = 1;lptr <= n;lptr++){
        lsum += ara[lptr];
        while(rptr - 1 > lptr and rsum + ara[rptr - 1] <= lsum){
            rptr--;
            rsum += ara[rptr];
        }
        if(rptr - lptr < 3 or rptr > n)continue;

        int l = lptr + 1, r = rptr - 1;
        int lo = l , hi = r;
        while(hi - lo > 3){
            int m1 = (hi - lo)/3 + lo;
            int m2 = (hi- lo)/3 + m1;
//            debug(l,r,lo,hi,m1,m2);
            if(getDif(l,m1,r) <= getDif(l,m2,r)){
                hi = m2;
            }else{
                lo = m1;
            }
        }
        for(int i = lo;i <= hi;i++){
            vector<LL>sums;
            sums.push_back(lsum);
            sums.push_back(rsum);
            sums.push_back(sum[i] - sum[l - 1]);
            sums.push_back(sum[r] - sum[i]);
            LL mx = 0 , mn = 1e18;
            for(LL j : sums)mx = max(mx,j) , mn = min(mn,j);
            ans = min(ans,ABS(mx - mn));
        }
    }
    return ans;
}
