int find_cutpoint(int start,int end, std::vector<int> A){
    int sum = 0;
    for(int i = start; i <= end; i++) sum+=A[i];
    int subsum = 0;
    int cutpoint = 0;
    for(int i = start; i <= end; i++) {
        subsum += A[i];
        if(subsum > sum){
            cutpoint = i;
            break;
        }
    }
    if(abs(sum-2*subsum) > abs(sum-2*subsum +2*A[cutpoint])) return cutpoint;
    else return cutpoint-1;

}


int main(void) {
    int N;
    std::cin >> N;
    std::vector<int> A(N);

    for(int i = 0; i < N; i++) {
        std::cin >> A[i];
    }

    int cut2 = find_cutpoint(0, N-1, A);
    int cut1 = find_cutpoint(0, cut2, A);
    int cut3 = find_cutpoint(cut2+1, N-1, A);

    int sum1 = 0;
    int sum2 = 0;
    int sum3 = 0;
    int sum4 = 0;
    for(int i = 0; i <= cut1; i++)
        sum1+=A[i];
    for(int i = cut1+1; i <=cut2; i++)
        sum2+=A[i];
    for(int i = cut2+1; i <=cut3; i++)
        sum3+=A[i];
    for(int i = cut3+1;i<N;i++)
        sum4+=A[i];
    int maximum = max(sum1, max(sum2, max(sum3, sum4)));
    int minimum = min(sum1, min(sum2, min(sum3, sum4)));
    std::cout << maximum-minimum << std::endl;
    return 0;
}

