//[b, e)
void solve(vll& A, vll& acc, int b, int e, ll& sum1, ll& sum2) {
  ll targetSum2 = acc[e] - acc[b];
  ll ub = e;
  ll lb = b;
  while(ub - lb > 1) {
    ll mid = (ub + lb) / 2;
    ll msum = acc[e] - acc[mid];
    if(msum * 2 >= targetSum2) {
      //見たのがより上
      lb = mid;
    } else {
      ub = mid;
    }
  }

  int res = ub;
  //以上の時
  if(abs((acc[e] - acc[res]) - (acc[res] - acc[b])) < abs((acc[e] - acc[res-1]) - (acc[res-1] - acc[b]))) {
    sum1 = acc[res] - acc[b];
    sum2 = acc[e] - acc[res];
  } else {
    sum1 = acc[res-1] - acc[b];
    sum2 = acc[e] - acc[res-1];
  }

  if(sum1 > sum2) swap(sum1, sum2);
}

