  vector<ll> acc;
  for (int i = 0; i < N; i++) {
    ll tmp;
    cin >> tmp;
    if (i == 0)
      acc.emplace_back(tmp);
    else
      acc.emplace_back(tmp + acc[i - 1]);
  }

  ll ans = acc[acc.size() - 1];
  for (int i = 1; i <= N - 3; i++) {
    ll sum0 = acc[i];
    auto pos0 = upper_bound(acc.begin(), acc.begin() + i - 1, sum0 / 2);
    if( abs(sum0 - 2*(*pos0)) >  abs(sum0 - 2*(*(pos0-1)) ))
      pos0--;

    ll sum1 = acc[acc.size() - 1] - acc[i];
    auto pos1 = upper_bound(acc.begin() + i + 1, acc.end(), sum1 / 2 + acc[i]);
    if( abs(sum1 - 2*((*pos1)-acc[i])) >  abs(sum1 - 2*((*(pos1-1)-acc[i]))) )
      pos1--;

    ll v0 = *pos0;
    ll v1 = acc[i] - *pos0;
    ll v2 = *pos1 - acc[i];
    ll v3 = acc[acc.size() - 1] - *pos1;
    vector<ll> cands = {v0, v1, v2, v3};
    ll max = *max_element(cands.begin(), cands.end());
    ll min = *min_element(cands.begin(), cands.end());
    if (max - min < ans) ans = max - min;
  }

  cout << ans << endl;

  return 0;
}

