int main(){
  fastio;
  ll N;
  cin >> N;
  auto A = mdeq<ll>(N+1);
  rep(i, 0, N){
    cin >> A[i+1];
    A[i+1] = A[i] + A[i+1];
  }
  ll sp1{0}, sp2{0}, sp3{0};
  ll ans{MOD};
  auto P = [&](){return A[sp1] - A[0];};
  auto Q = [&](){return A[sp2] - A[sp1];};
  auto R = [&](){return A[sp3] - A[sp2];};
  auto S = [&](){return A[N] - A[sp3];};
  auto write = [&](){
    // cout << sp1 << sp2 << sp3 << sp << P() << sp << Q() << sp << R() << sp << S() << rt;
    ans = min(ans, max({P(),Q(),R(),S()}) - min({P(),Q(),R(),S()}));
  };
  auto rule = [&](){
    return 0 < sp1 && sp1 < sp2 && sp2 < sp3 && sp3 < N;
  };
  while(max({sp1, sp2, sp3}) < N){
    while(P() <= Q()){
      sp1++;
    }
    while(R() <= S()){
      sp3++;
    }
    sp1--;
    if(rule()) write();
    sp3--;
    if(rule()) write();
    sp1++;
    if(rule()) write();
    sp3++;
    if(rule()) write();
    sp2++;
    if(rule()) write();
  }
  cout << ans << rt;
}

