typedef long long ll;

vector<ll> v(200005),w(200005);

int ft(ll l, ll r, ll &m, vector<ll> &vctr){
  ll x = w[m-1] - w[l-1];
  ll y = w[r-1] - w[m-1];

  ll d = abs(x-y);

  while(x <= y){
    ++m;
    x += v[m-2];
    y -= v[m-2];

    if(d >= abs(x-y)){
      continue;
    }else{
      x -= v[m-2];
      y += v[m-2];
      --m;
      break;
    }
  }

  vctr[0] = max(x,y);
  vctr[1] = min(x,y);
  return 0;
}


int main(){
  ll n;
  cin >> n;

  for(ll i=0; i<n; i++) cin >> v[i];
  w[0] = 0;
  w[1] = v[0];
  for(ll i=1; i<n; i++) w[i+1] = w[i] + v[i];

  vector<ll> tmp1(2);
  vector<ll> tmp2(2);

  ll left = 1;
  ll right = n;

  ll m_l = left + 1;
  ll sep = m_l + 1;
  ll m_r = sep + 1;

  ll tr = 100000000000000;

  for(sep = 3; sep <= n-1; sep++){
    ft(left, sep, m_l, tmp1);
    ft(sep, right+1, m_r, tmp2);

    tr = min(tr,max(tmp1[0],tmp2[0]) - min(tmp1[1],tmp2[1]));

  }

  cout << tr << endl;
}

