#define FOR(i, a, b) for(int (i) = (a); (i) < (b); ++(i))
#define REP(i, n) FOR(i, 0, n)

using lli = long long int;
constexpr lli inf = 2e18;
constexpr int N = 2e5;
std::array<int, N> A;
std::array<lli, N+1> S;

lli score(lli a, lli b, lli c, lli d){
    lli mx = -1, mn = inf;
    if(a < mn) mn = a; if(a > mx) mx = a;
    if(b < mn) mn = b; if(b > mx) mx = b;
    if(c < mn) mn = c; if(c > mx) mx = c;
    if(d < mn) mn = d; if(d > mx) mx = d;
    return mx - mn;
}

int main(void){
    int n; scanf("%d", &n);
    S[0] = 0;
    REP(i, n){
        scanf("%d", &A[i]);
        S[i+1] = S[i] + A[i];
    }
    lli score_ = inf;
    for(int x = 2; x + 1 <= n; ++x){
        int l = 0, r = x;
        while(r - l > 1){
            int mid = (l + r) / 2;
            lli P = S[mid];
            lli Q = S[x] - S[mid];
            if(P <= Q) l = mid;
            else r = mid;
        }
        lli P, Q;
        if(S[x] - 2 * S[l] < 2 * S[r] - S[x]) P = S[l], Q = S[x] - S[l];
        else P = S[r], Q = S[x] - S[r];
        l = x, r = n;
        while(r - l > 1){
            int mid = (l + r) / 2;
            lli R = S[mid] - S[x];
            lli S_ = S[n] - S[mid];
            if(R <= S_) l = mid;
            else r = mid;
        }
        lli R, S_;
        if(S[n] + S[x] - 2 * S[l] < 2 * S[r] - S[n] - S[x]) R = S[l] - S[x], S_ = S[n] - S[l];
        else R = S[r] - S[x], S_ = S[n] - S[r];
        lli scr = score(P, Q, R, S_);
        if(score_ > scr) score_ = scr;
    }
    printf("%lld\n", score_);
    return 0;
}

