int n;
vi a, sum;

void solve() {
  cin >> n;
  rep(i, 0, n) {
    int A;
    cin >> A;
    a.pb(A);
    if (i == 0) {
      sum.pb(A);
      continue;
    } else {
      sum.pb(sum[i - 1] + A);
    }
  }

  int res = 1LL << 60;
  for (int i = 2; i <= n - 2; i++) {  // i番目の切れ目で切る
    int low = 0, high = i - 1;
    while (high - low > 1) {
      int mid = (high + low) / 2;
      if (sum[mid] >= sum[i - 1] - sum[mid]) {
        high = mid;
      } else {
        low = mid;
      }
    }
    int P = sum[low], Q = sum[i - 1] - sum[low];
    int P2 = sum[high], Q2 = sum[i - 1] - sum[high];
    int left_min = min(P, Q), left_max = max(P, Q);
    if (abs(P2 - Q2) < abs(P - Q)) {
      left_min = min(P2, Q2);
      left_max = max(P2, Q2);
    }

    low = i, high = n - 1;
    while (high - low > 1) {
      int mid = (high + low) / 2;
      if (sum[mid] - sum[i - 1] >= sum[n - 1] - sum[mid]) {
        high = mid;
      } else {
        low = mid;
      }
    }
    int R = sum[low] - sum[i - 1],T = sum[n - 1] - sum[low];
    int R2 = sum[high] - sum[i - 1], T2 = sum[n - 1] - sum[high];
    int right_min = min(R, T), right_max = max(R, T);
    if (abs(R - T) > abs(R2 - T2)) {
      right_min = min(R2, T2);
      right_max = max(R2, T2);
    }

    int tmp = max(left_max, right_max) - min(left_min, right_min);
    res = min(res, tmp);
  }
  cout << res << endl;
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  // cout << fixed << setprecision(10);

  solve();

  return 0;
}

