using namespace std;
int main(){
  int n; cin >> n;
  vector<long long> a(n), le(n), ri(n);
  for(int i = 0; i < n; i++) cin >> a[i];
  for(int i = 1; i < n; i++) a[i] += a[i - 1];
  int l = -1, r = n - 1;
  auto query = [&](int x, int y){
    if(x > y) return 0ll;
    long long ans = a[y];
    if(x) ans -= a[x - 1];
    return ans;
  };
  auto fdx = [&](int x, int y, int z){
  	return abs(query(x, y) - query(y + 1, z));
  };
  for(int i = 0; i < n; i++){
  	while(l + 1 < i && fdx(0, l, i) >= fdx(0, l + 1, i)) l++;
    le[i] = l;
  }
  for(int i = n - 1; i >= 0; i--){
    while(r - 1 > i && fdx(i, r, n - 1) >= fdx(i, r - 1, n - 1)) r--;
    ri[i] = r;
  }
  long long ans = 1ll<<60;
  for(int i = 0; i < n - 1; i++){
  	long long a = query(0, le[i]);
    long long b = query(le[i] + 1, i);
    long long c = query(i + 1, ri[i + 1] - 1);
    long long d = query(ri[i + 1], n - 1);
    ans = min(ans, max({a, b, c, d}) - min({a, b, c, d}));
  }
  cout << ans << endl;
  return 0;
}

