      ll R2 = min(sum[right]-sum[i], sum[N]-sum[right]);
      ll S2 = max(sum[right]-sum[i], sum[N]-sum[right]);

      if(S1-R1 <= S2-R2){ R = R1; S = S1;}
      else{ R = R2; S = S2;}

      ll M = max(Q,S); ll m = min(P,R);
      ll tmp = M-m;
      res = min(res, tmp);
    }

    cout << res << endl; return 0;}

