  for(auto&x:A)cin>>x;
  // print(A);
  for(int i=1;i<N;++i)A[i]+=A[i-1];
  // print(A);
  for(int mid=2;mid<=N-2;++mid){  // middle.
    if(mid==2){
      F_left[mid]=1;
    }else{
      int left=F_left[mid]=F_left[mid-1];
      int P=A[left-1];
      int Q=A[mid-1]-A[left-1];
      int diff_prev=abs(P-Q);  // difference previous.
      while(true){
        left=F_left[mid]+1;
        if(left>=mid)break;
        P=A[left-1];
        Q=A[mid-1]-A[left-1];
        int diff_next=abs(P-Q);
        if(diff_next<diff_prev){
          ++F_left[mid];
          diff_prev=diff_next;
        }else{
          break;
        }
      }
    }
  }
  for(int mid=N-2;mid>=2;--mid){
    if(mid==N-2){
      F_right[mid]=N-1;
    }else{
      int right=F_right[mid]=F_right[mid+1];
      int R=A[right-1]-A[mid-1];
      int S=A[N-1]-A[right-1];
      int diff_prev=abs(R-S);  // difference previous.
      while(true){
        right=F_right[mid]-1;
        if(right<=mid)break;
        R=A[right-1]-A[mid-1];
        S=A[N-1]-A[right-1];
        int diff_next=abs(R-S);
        // printf("mid, right, prev, next=%d, %d, %d, %d\n",mid,right,diff_prev,diff_next);
        if(diff_next<diff_prev){
          --F_right[mid];
          diff_prev=diff_next;
        }else{
          break;
        }
      }
    }
  }
  // print(F_left);
  // print(F_right);
  int answer=0x3f3f3f3f;
  for(int mid=2;mid<=N-2;++mid){
    const int left=F_left[mid];
    const int right=F_right[mid];
    const int P=A[left-1];
    const int Q=A[mid-1]-A[left-1];
    const int R=A[right-1]-A[mid-1];
    const int S=A[N-1]-A[right-1];
    const int n_max=max(max(P,Q),max(R,S));
    const int n_min=min(min(P,Q),min(R,S));
    const int difference=abs(n_max-n_min);
    // printf("P, Q, R, S=%d, %d, %d, %d\n",P,Q,R,S);
    if(difference<answer){
      // printf("update %d,%d,%d\n",left,mid,right);
    }
    answer=min(answer,difference);
  }
  cout<<answer<<endl;
}

