lint cumsum[MAXN];

// [l, r) の和
lint get_sum(int l, int r) {
    return cumsum[r] - cumsum[l];
}

// [l, r) 区間でなるべく差が小さくなるようにする
int get_center(const int l, const int r) {
    const auto f = [&](const int c) {
        const lint left = get_sum(l, c);
        const lint right = get_sum(c, r);
        return abs(right - left);
    };
    // [L, R)
    int L = l+1, R = r;
    while (R - L > 2) {
        const int m1 = (2*L+R) / 3;
        const int m2 = (L+2*R) / 3;
        if (f(m1) < f(m2)) {
            R = m2;
        } else {
            L = m1;
        }
    }
    int ret = -1;
    lint mini = 1e18;
    for (int i = L; i < R; i++) {
        lint diff = f(i);
        if (diff < mini) {
            mini = diff;
            ret = i;
        }
    }
    return ret;
    // tle
    //int ret = -1;
    //lint mini = 1e18;
    //for (int c = l+1; c < r; c++) {
    //    const lint left = get_sum(l, c);
    //    const lint right = get_sum(c, r);
    //    const lint diff = abs(right - left);
    //    if (diff < mini) {
    //        mini = diff;
    //        ret = c;
    //    }
    //}
    //return ret;
}

int main() {
    int N;
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    for (int i = 1; i <= N; i++) {
        cumsum[i] = cumsum[i-1] + A[i-1];
    }
    lint mini = 1e18;
    // [0, c), [c, N) で区切る
    // c >= 2, N-c >= 2 より 2 <= c <= N-2
    for (int c = 2; c <= N-2; ++c) {
        // 二つの区間で差が最小になるところを探す
        const int c1 = get_center(0, c);
        const int c2 = get_center(c, N);
        vector<lint> pqrs(4);
        pqrs[0] = get_sum(0, c1);
        pqrs[1] = get_sum(c1, c);
        pqrs[2] = get_sum(c, c2);
        pqrs[3] = get_sum(c2, N);
        sort(pqrs.begin(), pqrs.end());
        mini = min(mini, pqrs[3] - pqrs[0]);
    }
    cout << mini << endl;
    return 0;
}

