vector<int> a(200005);
iterable_stack<ll> S;
ll ans=INFll;

ll minstack(iterable_stack<ll> s){
  ll maxs=0, mins=INFll;
  for(ll p:s){
    maxs=max(maxs, p);
    mins=min(mins, p);
  }
  return maxs-mins;
}

void dfs(int index, int num){
