      sum+=a[i];
      i++;
    }
  }
  if(num==3){
    S.push(sum);
    ans=min(ans, minstack(S));
    S.pop();
  } else {
    S.push(sum);
    dfs(i, num+1);
    S.pop();
    i--;
    sum-=a[i];
    S.push(sum);
    dfs(i, num+1);
    S.pop();
  }
}

