using namespace std;
typedef long long ll;

ll range_total(const vector<ll>& cs, ll i, ll j){
    assert(i <= j);
    return cs.at(j) - cs.at(i);
}

pair<ll, ll> search(const vector<ll>& cs, ll s, ll e){
    assert(s + 1 < e);
    ll lo = s + 1;
    ll hi = e - 1;

    ll best_idx = lo;
    ll best = abs(range_total(cs, s, lo) - range_total(cs, lo, e));

    while(lo <= hi){
        ll mid = (lo + hi) / 2;
        ll diff = abs(range_total(cs, s, mid) - range_total(cs, mid, e));
        if(best > diff){
            best_idx = mid;
            best = diff;
        }
        if(range_total(cs, s, mid) < range_total(cs, mid, e)){
            lo = mid + 1;
        }else if(range_total(cs, s, mid) > range_total(cs, mid, e)){
            hi = mid - 1;
        }else{
            break;
        }
    }
    assert(s < best_idx && best_idx < e);
    ll x1 = range_total(cs, s, best_idx);
    ll x2 = range_total(cs, best_idx, e);
    return make_pair(x1, x2);
}

int main(){
    ll n;
    cin >> n;
    vector<ll> a(n);
    for(int i = 0; i < n; ++i){
        cin >> a.at(i);
    }

    vector<ll> cs(n + 1, 0);
    for(int i = 0; i < n; ++i){
        cs.at(i + 1) = a.at(i) + cs.at(i);
    }

    ll ans = cs.back();
    for(int i = 2; i < n - 1; ++i){
        ll l1, l2, r1, r2;
        tie(l1, l2) = search(cs, 0, i);
        tie(r1, r2) = search(cs, i, n);
        ans = min(
            ans,
            abs(max({l1, l2, r1, r2}) - min({l1, l2, r1, r2}))
        );
    }
    cout << ans << endl;
    return 0;
}

