        ll f = abs(b[e] + b[e] - b[i]), g = abs(b[e - 1] + b[e - 1] - b[i]);
        //cout << e << ' ' << f << ' ' << g << ' ';
        if (f < g) c[i] = min(b[e], b[i] - b[e]), d[i] = max(b[e], b[i] - b[e]);
        else c[i] = min(b[e - 1], b[i] - b[e - 1]), d[i] = max(b[e - 1], b[i] - b[e - 1]);
        //cout << c[i] << ' ' << d[i] << '\n';
    }
    reverse(a + 1, a + n + 1);
    reverse(c + 1, c + n + 1);
    reverse(d + 1, d + n + 1);
    for (int i = 1; i <= n; i++) b[i] = b[i - 1] + a[i];
    e = 1;
    for (int i = 2; i < n; i++) {
        while (b[e] + b[e] < b[i]) e++;
        ll f = abs(b[e] + b[e] - b[i]), g = abs(b[e - 1] + b[e - 1] - b[i]), x, y;
        //cout << e << ' ' << f << ' ' << g << ' ';
        if (f < g) x = min(b[e], b[i] - b[e]), y = max(b[e], b[i] - b[e]);
        else x = min(b[e - 1], b[i] - b[e - 1]), y = max(b[e - 1], b[i] - b[e - 1]);
        //cout << c[i + 1] << ' ' << d[i + 1] << '\n';
        z = min(z, max(d[i + 1], y) - min(c[i + 1], x));
    }
    cout << z;
}

