        P = P_temp;
        Q = Q_temp;
        idx_lft = min(idx_lft+1,idx_mid);
      }
    }
    --idx_lft;
    ll R=-1,S;
    while(idx_rgt<N){
      ll R_temp = cumu[idx_rgt] - cumu[idx_mid];
      ll S_temp = cumu[N] - cumu[idx_rgt];
      if(R>0 && abs(R-S)<abs(R_temp-S_temp)){
        break;
      }else{
        R = R_temp;
        S = S_temp;
        idx_rgt = min(idx_rgt+1,(int)N);
      }
    }
    --idx_rgt;
    ll cand = abs(max({P,Q,R,S}) - min({P,Q,R,S}) );
    chmin(ans,cand);
    ++idx_mid;
  }
  cout << ans << "\n";
}

