int n,cnt;
double a[200050],A,B,C,D,sum;
int main(){
	cnt=0;
	sum=0;
	A=0;
	B=0;
	C=0;
	D=0;
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%lf",&a[i]);
		sum+=a[i];
	}
	for(int i=1;i<=n;i++){
		if(cnt==0){
			if(i>n-3||fabs(A+a[i]-sum/4)>=fabs(A-sum/4)){
				B+=a[i];
				cnt++;
			}
			else A+=a[i];
		}
		else if(cnt==1){
			if(i>n-2||fabs(B+a[i]-sum/4)>=fabs(B-sum/4)){
				C+=a[i];
				cnt++;
			}
			else B+=a[i];
		}
		else if(cnt==2){
			if(i>n-1||fabs(C+a[i]-sum/4)>=fabs(C-sum/4)){
				D+=a[i];
				cnt++;
			}
			else C+=a[i];
		}
		else D+=a[i];
	}
	printf("%.0lf\n",max(A,max(B,max(C,D)))-min(A,min(B,min(C,D))));
}

