			//cout << R << endl;
			if (abs(R - (sum_RS / 2)) <= difference_RS_min) {
				slash_right_decision = slash_right;
				difference_RS_min = abs(R - (sum_RS / 2));
			}
		}
		//cout << slash_right_decision << endl;
		int R_decision = sum(slash_middle, slash_right_decision, A);
		int S_decision = sum(slash_right_decision, N, A);
		//cout << R_decision << "  " << S_decision << '\n' << endl;

		int P_Q_R_S[4];
		P_Q_R_S[0] = P_decision;
		P_Q_R_S[1] = Q_decision;
		P_Q_R_S[2] = R_decision;
		P_Q_R_S[3] = S_decision;

