			cout << P_Q_R_S[i] << endl;
		}
		*/

		if (i == 2) {
			ans = P_Q_R_S[3] - P_Q_R_S[0];
		}else if(ans > (P_Q_R_S[3] - P_Q_R_S[0])) {
