using namespace std;

long n;

void calc_mm(  vector<long>& s, vector<pair<long,long> >& mm )
{
    long j_save = 0;
    long i;
    for(i=1; i<n; i++) {
        long j;
        for(j=j_save; j<i; j++) {
            if(s[j+1]>s[i+1]/2) {
                break;
            }
        }
        long tmp = abs((s[i+1]-s[j])-s[j]);
        j_save=j;
        mm[i].first=MIN(s[i+1]-s[j], s[j]);
        mm[i].second=MAX(s[i+1]-s[j], s[j]);
        if(tmp > abs((s[i+1]-s[j+1])-s[j+1])) {
            mm[i].first=MIN(s[i+1]-s[j+1], s[j+1]);
            mm[i].second=MAX(s[i+1]-s[j+1], s[j+1]);
            j_save=j+1;
        }
    }
    return;
}

int main(int argc, char* argv[])
{
    scanf("%ld", &n);

    vector<long> a(n);
    long i;
    for(i=0; i<n; i++) {
        scanf("%ld", &a[i]);
    }

    vector<pair<long,long> > mm0(n);
    {
        vector<long> s0(n+1);
        s0[0]=0;
        for(i=0; i<n; i++) {
            s0[i+1]=s0[i]+a[i];
        }
        calc_mm( s0, mm0 );
    }

    vector<pair<long,long> > mm1(n);
    {
        vector<long> s1(n+1);
        s1[0]=0;
        for(i=0; i<n; i++) {
            s1[i+1]=s1[i]+a[n-1-i];
        }        
        calc_mm( s1, mm1 );
    }

    long ans=INF;
    for(i=1; i<n-2; i++) {
        long min = MIN(mm0[i].first, mm1[n-2-i].first);
        long max = MAX(mm0[i].second, mm1[n-2-i].second);
        ans = MIN(ans, max-min);
    }
    printf("%ld\n", ans);

    return 0;
}

