	}

	int i1 = 1;
	int i3 = 3;
	i64 ans = 1000000000000;

	for (size_t i = 2; i < (N - 1); i++)
	{
		i64 a1 = (A[i] - A[i1]) ;
		i64 a2 = A[i1]; 
		i64 ans1 = abs(a1 - a2);

		for (int ti = i1 + 1; ti < i; ti++)
		{
			i64 ta1 = (A[i] - A[ti]);
			i64 ta2 = A[ti];
			i64 at = abs(ta1 - ta2);
