			}
		}

		i64 a3 = (A[i3] - A[i]);
		i64 a4 = (A[N] - A[i3]);
		i64 ans2 = abs(a3 - a4);
		for (int ti = i3 + 1; ti < N; ti++)
		{
			i64 ta3 = (A[ti] - A[i]);
