typedef long long ll;
typedef vector<int> vi;
typedef vector<ll> vll;

vll cumsum(vll& A){
  vll cum;
  int N=A.size();
  cum.push_back(0);
  for (int i=0;i<N;++i){
    cum.push_back(cum[i]+A[i]);
  }
  return cum;
}

//[low, high-1]から探す。
int b_search(vll& cum, int low, int high, ll c){
  int lb=low-1, ub=high;
  while(ub-lb>1){
    int mid=(ub+lb)/2;
    if(cum[mid]>=c){ub=mid;}
    else{lb=mid;}
  }
  return ub;
}

int main(){
  int N;cin>>N;
  vll A;
  for (int i=0;i<N;++i){
    ll a;cin>>a;A.push_back(a);
  }

  vll cum=cumsum(A);

  ll smallest=cum[N];
  //i,i+1の間でまんなかを切る
  for (int i=2i<N-1;++i){
    ll lc=cum[i];
    ll hc=cum[N]-cum[i];
    int lub=b_search(cum, 1, i+1, lc/2);
    int hub=b_search(cum, i+1, N+1, uc/2);
    ll B=cumsum[lub];
    ll C=cumsum[i]-cumsum[lub];
    ll D=cumsum[hub]-cumsum[i];
    ll E=cumsum[N]-cumsum[hub];
    ll M=max(B,C);M=max(M,D);M=max(M,E);
    ll m=min(B,C);m=min(m,D);m=min(m, E);
    smallest=min(smallest, M-m);
    if(lub!=1){
      B=cumsum[lub-1];
      C=cumsum[i]-cumsum[lub-1];
      M=max(B,C);M=max(M,D);M=max(M,E);
      m=min(B,C);m=min(m,D);m=min(m, E);
      smallest=min(smallest, M-m);
    }
    if(hub!=i+1){
      D=cumsum[hub-1]-cumsum[i];
      E=cumsum[N]-cumsum[hub-1];
      M=max(B,C);M=max(M,D);M=max(M,E);
      m=min(B,C);m=min(m,D);m=min(m, E);
      smallest=min(smallest, M-m);
    }
  }

  cout << smallest << endl;
  return 0;
}

