    ll s[4];
    ll ans = INFLL;
    for (int cent = 1; cent <n-2 ; cent++) {
        while(abs((as[cent+1] - as[l+1])-as[l+1]) > abs((as[cent+1] - as[l+2])-as[l+2])){
            l++;
        }

        if(r<=cent) r = cent+1;
        // printf("%d %d %d %d\n", as[cent+1], as[r+1], as[r+2], as[n]);
        while(abs((as[r+1] - as[cent+1])-(as[n] - as[r+1])) > abs((as[r+2] - as[cent+1])-(as[n] - as[r+2]))){
            r++;
        }

        s[0] = as[l+1];
        s[1] = as[cent+1] - as[l+1];
        s[2] = as[r+1] - as[cent+1];
        s[3] = as[n] - as[r+1];

        // printf("%d %d %d\n", l, cent, r);
        // printf("%d %d %d %d\n", s[0], s[1], s[2], s[3]);

        ll MAX=0, MIN = INFLL;
        rep(i, 4){
            MAX = max(MAX, s[i]);
            MIN = min(MIN, s[i]);
        }
        ans = min(ans, MAX-MIN);

    }

    cout << ans << endl;
    // printf("%d\n", N);
    return 0;
}

