const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a;
ll s[MAX_N];

ll sum_of_sub_seq(ll start, ll end){
    return s[end + 1] - s[start];
}

ll lb_search(ll key, ll left, ll right){
    ll s_idx = left;
    if (sum_of_sub_seq(s_idx, left) >= key) return left;
    ll mid = left + (right - left) / 2;
    ll l_value, r_value;

    while(right >= left){
        mid = left + (right - left) / 2;
        l_value = sum_of_sub_seq(s_idx, mid - 1); r_value = sum_of_sub_seq(s_idx, mid);
        if (mid == left) {
            l_value = sum_of_sub_seq(s_idx, left); r_value = sum_of_sub_seq(s_idx, left + 1);
            if (l_value < key && key <= r_value) return left + 1;
            else return right;
        }
        if (l_value < key && key <= r_value) return mid;
        else if (l_value >= key) right = mid - 1;
        else if (r_value < key) left = mid;
    }

    return right; // all the elements < key
}

ll calc_diff(ll d1, ll d2, ll d3){
    ll s1, s2, s3, s4;
    s1 = sum_of_sub_seq(0, d1); s2 = sum_of_sub_seq(d1 + 1, d2);
    s3 = sum_of_sub_seq(d2 + 1, d3); s4 = sum_of_sub_seq(d3 + 1, n - 1);

    ll sm = min(s1, min(s2, min(s3, s4))); ll sM = max(s1, max(s2, max(s3, s4)));
    return sM - sm;
}

void solve(ll n){
    s[0] = 0;
    rep(i, n){in1(a); s[i + 1] = a + s[i];}

    ll s12, s34; answer = INF;
    For(div2, 1, n - 2){
        s12 = sum_of_sub_seq(0, div2); s34 = sum_of_sub_seq(div2 + 1, n - 1);
        ll div1 = lb_search(s12 / 2, 0, div2 - 1);
        ll div3 = lb_search(s34 / 2, div2 + 1, n - 2);
        // 1, 3, 7
        if (div1 == -1 || div3 == -1) continue;
        answer = min(answer, calc_diff(div1, div2, div3));

        if (div1 != 0 && div3 != div2 + 1) answer = min(answer, calc_diff(div1 - 1, div2, div3 - 1));        
        if (div1 != 0) answer = min(answer, calc_diff(div1 - 1, div2, div3));
        if (div3 != div2 + 1) answer = min(answer, calc_diff(div1, div2, div3 - 1));
    }

    prl(answer);
}

