// Cuts A[i:j] into A[i:x] and A[x:j]
int cut(const vector<long> &A, int i, int j)
{
    long si = A.at(i);
    long sj = A.at(--j);
    while (i < j - 1)
    {
        long di = abs((si + A.at(i + 1)) - sj);
        long dj = abs((sj + A.at(j - 2)) - si);
        if (di < dj)
            si += A.at(++i);
        else
            sj += A.at(--j);
    }
    return j;
}


long sum(const vector<long> &A, int i, int j)
{
    long s(0);
    for (; i < j; ++i) s += A.at(i);
    return s;
}


long delta(const vector<long> &A, int i1, int i2, int i3)
{
    array<long, 4> S({
            sum(A, 0, i1), sum(A, i1, i2), sum(A, i2, i3), sum(A, i3, A.size())
        });
    long s_min(0), s_max(0);
    for (auto s : S)
    {
        if (s < s_min or s_min == 0) s_min = s; 
        if (s > s_max or s_max == 0) s_max = s;
    }
    return (s_max - s_min);
}


int main()
{
    int N;
    cin >> N;

    vector<long> A(N, 0);
    for (int i = 0; i < N; ++i)
        cin >> A[i];

    int i2 = max(2, min(N - 2, cut(A, 0, N)));
    int i1 = cut(A, 0, i2);
    int i3 = cut(A, i2, N);
    long sa0 = sum(A, 0, i2);
    long sb0 = sum(A, i2, N);
    auto d_min = delta(A, i1, i2, i3);

    cerr << "# cut[0]: [ 0, " << i1 << ", " << i2 << ", " << i3 << ", "
         << N << " ]" << endl;
    cerr << "# d[0] = " << d_min << endl;

    for (auto u : { 1, -1 })
    {
        long sa(sa0), sb(sb0);
        for (int di = u; (i2 + di > 1) && (i2 + di < N - 1); di += u)
        {
            int i2d = i2 + di;
            int i1 = cut(A, 0, i2d);
            int i3 = cut(A, i2d, N);

            auto d = delta(A, i1, i2d, i3);

            cerr << "# cut[" << di << "]: [ 0, "
                 << i1 << ", " << i2d << ", " << i3 << ", "
                 << N << " ]" << endl;
            cerr << "# d[" << di << "] = " << d << endl;

            if (d < d_min)
                d_min = d;

            if (u > 0)
                sa += A[i2d - 1], sb -= A[i2d - 1];
            else
                sa -= A[i2d], sb += A[i2d];
            if (d_min * 2 < abs(sa - sb))
                break;
        }
    }

    cout << d_min << endl;
}

