    ll minSum = min(sum[leftMid], min(sum[i] - sum[leftMid], min(sum[rightMid] - sum[i], sum[n-1] - sum[rightMid])));
    minDiff = min(minDiff, maxSum - minSum);
  }
  cout << minDiff << endl;
}

