long long sum(const int begin, const int end) {
    return AC[end] - AC[begin - 1];
}

long long score(const int begin, const int end, const int mid) {
    long long val1 = sum(begin, mid - 1);
    long long val2 = sum(mid, end);
    return labs(val1 - val2);
}

int get_best(const int begin, const int end) {
    if (begin + 1 == end) {
        return end;
    }

    int from = begin;
    int to = end;
    while (true) {
        int mid = (from + to) / 2;
        if (score(begin, end, mid+1) < score(begin, end, mid)) {
            from = mid;
        } else {
            to = mid;
        }
        if (from + 1 == to) {
            break;
        }
    }
    return to;
}

long long max_dist(const long long v1, const long long v2, const long long v3, const long long v4) {
    std::vector<long long> vec;
    vec.push_back(v1);
    vec.push_back(v2);
    vec.push_back(v3);
    vec.push_back(v4);

    std::sort(vec.begin(), vec.end());
    return vec[vec.size()-1] - vec[0];
}

