        auto first = lower_bound(dp.begin(), dp.begin() + i, dp[i - 1] / 2) - dp.begin();
        auto second = lower_bound(dp.begin() + i, dp.end(), (dp[n]+dp[i] )/ 2) - dp.begin();
        // 二分探索＋近傍探索で殴る
        for (int j = -20; j <= 20; j += 1)
        {
            if (first + j < i && first + j > 0)
            {
            for (int k = -20; k <= 20; k += 1)
            {
                if (second + k < n && second + k > i)
                {
                ll mn = 1LL<<62;
                ll mx = -mn;
                mx = max(dp[i] - dp[first + j], mx);
                mn = min(dp[i] - dp[first + j], mn);

                mx = max(dp[first + j] - dp[0], mx);
                mn = min(dp[first + j] - dp[0], mn);

                mx = max(dp[n] - dp[second + k], mx);
                mn = min(dp[n] - dp[second + k], mn);

                mx = max(dp[second + k] - dp[i], mx);
                mn = min(dp[second + k] - dp[i], mn);
                if(mx>=mn)
                    ans = min(ans, mx - mn);
                }
            }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

using i64 = int64_t;

i64 cumsum[200005]={0};

int divide(int left, int right, const vector<i64> &v){
    int ok = left, ng = right;
    while(abs(ok-ng) > 1){
        int mid = (ok + ng) / 2;
        if(cumsum[mid-1]-cumsum[left-1] < cumsum[right-1]-cumsum[mid-1])ok = mid;
        else ng = mid;
    }
    i64 d1 = abs(cumsum[right-1]-cumsum[ok-1] - (cumsum[ok-1]-cumsum[left-1]));
    i64 d2 = abs(cumsum[right-1]-cumsum[ok] - (cumsum[ok]-cumsum[left-1]));
    return (d1 < d2 ? ok : ok + 1);
}

int main(){
    int n;
    cin >> n;
    vector<i64> v;
    for(int i=0;i<n;++i){
        i64 a;
        cin >> a;
        v.push_back(a);
    }
    for(int i=1;i<=n;++i){
        cumsum[i] = cumsum[i-1] + v[i-1];
    }

    i64 ans = LLONG_MAX;
    for(int i=3;i<=n-1;++i){
        i64 bc = divide(1, i, v), de = divide(i, n+1, v);
        i64 p = cumsum[bc-1] - cumsum[0], q = cumsum[i-1] - cumsum[bc-1], r = cumsum[de-1] - cumsum[i-1], s = cumsum[n] - cumsum[de-1];
        ans = min(ans, abs(max({p,q,r,s})-min({p,q,r,s})));
    }
    cout << ans << endl;

    return 0;
}

