#include <bits/stdc++.h>
using namespace std;

int update_i1(int i1, int i2, const vector<long long> & cums){
    long long p = cums[i1];
    long long q = cums[i2] - cums[i1];
    long long score = abs(p - q);
    int new_i1 = i1;
    while (p < q and new_i1 + 1 < i2){
        ++new_i1;
        p = cums[new_i1];
        q = cums[i2] - cums[new_i1];
        if (score < abs(p - q)){
            return new_i1 - 1;
        }else{
            score = abs(p - q);
        }
    }
    return new_i1;
}

int update_i3(int i3, int i2, const vector<long long> & cums){
    int N = cums.size();
    int new_i3 = max(i3, i2 + 1);
    long long r = cums[new_i3] - cums[i2];
    long long s = cums[N - 1] - cums[new_i3];
    long long score = abs(r - s);
    while (r < s and new_i3 < N - 2){
        ++new_i3;
        r = cums[new_i3] - cums[i2];
        s = cums[N - 1] - cums[new_i3];
        if (score < abs(r - s)){
            return new_i3 - 1;
        }else{
            score = abs(r - s);
        }
    }
    return new_i3;
}

