    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<long long> As(N);
    for (auto & a : As) cin >> a;
    vector<long long> cums(N);
    long long cum = 0;
    for (int i = 0; i < N; ++i){
        cum += As[i];
        cums[i] = cum;
    }
    long long ans = 1e15;
    int i1 = 0;
    int i3 = 2;
    for (int i2 = 1; i2 < N - 2; ++i2){
        i1 = update_i1(i1, i2, cums);
        i3 = update_i3(i3, i2, cums);
        long long p = cums[i1];
        long long q = cums[i2] - cums[i1];
        long long r = cums[i3] - cums[i2];
        long long s = cums[N - 1] - cums[i3];
        ans = min(ans, max({p, q, r, s}) - min({p, q, r, s}));
    }
    cout << ans << endl;
    return 0;
}

