ll A[200001] = {};
ll S[200001] = {};
ll L[200001] = {};
ll R[200001] = {};
int main() {
	ll N; cin >> N;
	repe(i, 1, N) {
		ll a; cin >> a;
		A[i] = a;
		if (i == 0)S[i] = A[i];
		else S[i] += S[i - 1] + A[i];
	}

	//left side
	ll l = N, r = N;
	while (r > 0) {
		while (l > 0 && abs(abs(S[r] - S[l - 1]) - abs(S[l - 1] - S[0])) > abs(abs(S[r] - S[l - 2]) - abs(S[l - 2] - S[0]))) {
			l--;
		}
		cout << "L: " << l << ":" << abs(S[l - 1] - S[0]) << "R: " << r << ":" << abs(S[r] - S[l - 1]) << endl;
		L[r] = l;
		r--;
	}

	//right side
	l = 1, r = 1;
	while (l < N) {
		while (r < N &&  abs(abs(S[N] - S[r]) - abs(S[r] - S[l - 1])) > abs(abs(S[N] - S[r + 1]) - abs(S[r + 1] - S[l - 1])))
		{
			r++;
		}
		cout << "L: " << l << ":" << abs(S[r] - S[l - 1]) << "R: " << r << ":" << abs(S[N] - S[r]) << endl;
		R[l] = r;
		l++;
	}

	ll minV = LL_MAX;
	rep(k, 0, N) {
		ll p = S[L[k] - 1];
		ll q = S[k] - S[L[k]];
		ll r = S[R[k]] - S[k];
		ll s = S[N] - S[R[k]];

		ll ma = max(p, max(q, max(r, s)));
		ll mi = min(p, min(q, min(r, s)));
		cout << "p: " << p << " q: " << q << " r: " << r << " s: " << s << " max: " << ma << " min: " << mi << endl;

		minV = min(abs(max(p, max(q, max(r, s))) - min(p, min(q, min(r, s)))), minV);
	}
	cout << minV << endl;

	return 0;
}

