    }

    auto func = [&](int mid, auto litr, auto ritr) -> ll {
        if (litr == sum.begin() || litr == sum.begin() + mid)
            return 1e18;
        if (ritr == sum.begin() + mid || ritr == sum.end() - 1)
            return 1e18;
        ll mi = 1e18, ma = 0;
        mi = min(*litr, mi);
        mi = min(sum[mid] - *litr, mi);
        mi = min(*ritr - sum[mid], mi);
        mi = min(sum[N] - *ritr, mi);
        ma = max(*litr, ma);
        ma = max(sum[mid] - *litr, ma);
        ma = max(*ritr - sum[mid], ma);
        ma = max(sum[N] - *ritr, ma);
        return ma - mi;
    };

    ll ans = 1e18;
    int idx = lower_bound(sum.begin(), sum.end(), sum[N] / 2) - sum.begin();
    for (int i = max(2, idx - 2); i <= min(N - 2, idx + 2); ++i) {
        auto litr = lower_bound(sum.begin() + 1, sum.begin() + i + 1, sum[i] / 2);
        auto ritr = lower_bound(sum.begin() + i + 1, sum.end(), (sum[i] + sum[N]) / 2);
        ans = min(func(i, litr, ritr), ans);
        ans = min(func(i, litr - 1, ritr), ans);
        ans = min(func(i, litr, ritr - 1), ans);
        ans = min(func(i, litr - 1, ritr - 1), ans);
    }

    cout << ans << endl;
    return 0;
}

