int N,A[200001];
ll S[2000002],ans=LLONG_MAX;

int can(ll high) {
    vector<ll> nums;
    int idx=0,before=0;
    REP(i,1,N+2){
        if(S[i] - S[before] > high) {
            if(i-1==before){
                nums.push_back(S[i]-S[before]);
                before=i;
            }else{
                nums.push_back(S[i-1]-S[before]);
                before=i-1;
            }

        }
    }
    if(before!=N){
        nums.push_back(S[N+1]-S[before]);
    }
    // cout<<high<<endl;
    // REP(i,0,nums.size()){
    //     cout<<nums[i]<<" ";
    // }
    // cout<<endl;
    // cout<<"idx = " << idx << endl;
    if (nums.size() < 4)return -1;
    else if (nums.size() > 4) return 1;
    ll mi=LLONG_MAX,ma=-1;

    REP(i,0,4){
        mi=min(mi,nums[i]);
        ma=max(ma,nums[i]);
    }
    // cout<<endl;
    // cout<<"ans = " << (ma-mi)<<endl;
    ans = min(ans, (ma-mi));
    return 0;
}

