int main(){
  fastio;
  ll N;
  cin >> N;
  auto A = mdeq<ll>(N+1);
  rep(i, 0, N){
    cin >> A[i+1];
    A[i+1] = A[i] + A[i+1];
  }
  ll sp1{0}, sp2{0}, sp3{0};
  ll ans{MOD};
  auto P = [&](){return A[sp1] - A[0];};
  auto Q = [&](){return A[sp2] - A[sp1];};
  auto R = [&](){return A[sp3] - A[sp2];};
  auto S = [&](){return A[N] - A[sp3];};
  auto write = [&](){
    cout << sp1 << sp2 << sp3 << sp << P() << sp << Q() << sp << R() << sp << S() << sp;
