  };
  auto rule = [&](){
    return 0 < sp1 && sp1 < sp2 && sp2 < sp3 && sp3 < N;
  };
  while(max({sp1, sp2, sp3}) < N){
    while(P() < Q()){
      sp1++;
    }
    while(R() < S()){
      sp3++;
    }
    sp1--;
    if(rule()) write();
    sp3--;
    if(rule()) write();
    sp1++;
    if(rule()) write();
    sp3++;
    if(rule()) write();
    sp2++;
  }
  cout << ans << rt;
}

