ll N;
ll A[201010];
ll P, Q, R, S;
ll PQ, RS;
ll Qlb, Slb;

ll calc_abs() {
  ll ma = max(P, max(Q, max(R, S)));
  ll mi = min(P, min(Q, min(R, S)));
  return abs(ma - mi);
}

int main() {
  cin >> N;
  ll sum = 0;
  rep(i, 0, N) {
    cin >> A[i];
    sum += A[i];
  }
  P = A[0];
  Q = A[1];
  Qlb = 1;
  S = sum - A[0] - A[1];
  rep(i, 2, N - 1) {
    ll rr = R + A[i];
    ll ss = S - A[i];
    if (abs(ss - rr) < abs(S - R)) {
      R += A[i];
      S -= A[i];
      Slb = i + 1;
    }
  }

  ll ans = calc_abs();
  rep(i, 2, N - 2) {
    Q += A[i];
    R -= A[i];

    rep(j, Qlb, i) {
      ll pp = P + A[j];
      ll qq = Q - A[j];
      if (abs(pp - qq) < abs(P - Q)) {
        P += A[j];
        Q -= A[j];
        Qlb = j + 1;
      } else {
        break;
      }
    }

    rep(j, Slb, N - 1) {
      ll rr = R + A[j];
      ll ss = S - A[j];
      if (abs(ss - rr) < abs(S - R)) {
        R += A[j];
        S -= A[j];
        Slb = j + 1;
      } else {
        break;
      }
    }
    ans = min(ans, calc_abs());
  }

  cout << ans << endl;
}

