		max_sub = max(P, max(Q, max(R, S)));
		min_sub = min(P, min(Q, min(R, S)));
		ans = min(ans, max_sub - min_sub);

		P = cum_A[l-1];
		Q = cum_A[m] - cum_A[l-1];
		R = cum_A[r-1] - cum_A[m];
		S = cum_A[N] - cum_A[r-1];
		max_sub = max(P, max(Q, max(R, S)));
		min_sub = min(P, min(Q, min(R, S)));
		ans = min(ans, max_sub - min_sub);
	}

	cout << ans << endl;

	return 0;
}

