using namespace std;
typedef long long ll;

ll range_sum(const vector<ll>& cs, ll i, ll j){
    assert(i <= j);
    return cs.at(j) - cs.at(i);
}

int main(){
    ll n;
    cin >> n;
    vector<ll> a(n);
    for(int i = 0; i < n; ++i){
        cin >> a.at(i);
    }

    vector<ll> cs(n + 1, 0);
    for(int i = 0; i < n; ++i){
        cs.at(i + 1) = a.at(i) + cs.at(i);
    }

    ll ans = cs.back();
    ll left = 1, right = n - 1;
    for(int i = 2; i < n - 1; ++i){
        while(left + 1 < i){
            ll diff = abs(range_sum(cs, 0, left) - range_sum(cs, left, i));
            ll diff2 = abs(range_sum(cs, 0, left + 1) - range_sum(cs, left + 1, i));
            if(diff > diff2){
                left++;
            }else{
                break;
            }
        }
        right = max(right, i + 1LL);
        while(right + 1 < n){
            ll diff = abs(range_sum(cs, i, right) - range_sum(cs, right, n));
            ll diff2 = abs(range_sum(cs, i, right + 1) - range_sum(cs, right + 1, n));
            if(diff > diff2){
                right++;
            }else{
                break;
            }
        }

        ll x1 = range_sum(cs, 0, left);
        ll x2 = range_sum(cs, left, i);
        ll x3 = range_sum(cs, i, right);
        ll x4 = range_sum(cs, right, n);
        ans = min(ans, abs(max({x1, x2, x3, x4}) - min({x1, x2, x3, x4})));
    }
    cout << ans << endl;
    return 0;
}

