    lli ans = 1e18;
    for(int i=3; i<n; i++){
        int s[2] = {1, i};
        int e[2] = {i-1, n};
        lli tmin[2][2], tmax[2][2];
        for(int d=0; d<2; d++){
            lli total = a[e[d]] -a[s[d]-1];
            lli half = a[s[d]-1] + total/2;
            int mididx = upper_bound(a.begin()+s[d], a.begin()+e[d]+1, half) -a.begin();
            for(int j=0; j<2; j++){
                if(mididx+j <= s[d] || e[d] < mididx+j){
                    tmin[d][j] = 0;
                    tmax[d][j] = 1e18;
                    continue;
                }
                lli sum1 = a[mididx+j-1] -a[s[d]-1];
                lli sum2 = a[e[d]] -a[mididx+j-1];
                if(sum1 > sum2) swap(sum1, sum2);
                tmin[d][j] = sum1;
                tmax[d][j] = sum2;
            }
        }
        for(int j=0; j<2; j++){
            for(int k=0; k<2; k++){
                ans = min(ans, max(tmax[0][j], tmax[1][k]) -min(tmin[0][j], tmin[1][k]));
            }
        }
    }
