ll power(ll x, ll y) 
{ 
    ll res = 1;      // Initialize result 

    x = x % mod;  // Update x if it is more than or 
                // equal to p 

    while (y > 0) 
    { 
        // If y is odd, multiply x with result 
        if (y & 1) 
            res = (res*x) % mod; 

        // y must be even now 
        y = y>>1; // y = y/2 
        x = (x*x) % mod; 
    } 
    return res; 
} 
