  for(int i=1;i<n;i++) {
    sum[i] = sum[i-1] + a[i]; 
  }

  ll result = numeric_limits<ll>::max();

  int c = 1;
  int d = 2;
  int e = 3;
  ll p, q, r, s;
  for(;d<=n-2;d++) {
    if(e <= d) {
      e = d + 1;
    }
