		while (ok - ng > 1) {
			mid = (ok + ng) / 2;
			if (a[mid] >= a[i] - a[mid])ok = mid;
			else ng = mid;
		}
		int mi, ma;
		if (abs((a[i] - a[ok]) - a[ok]) > abs((a[i] - a[ok - 1]) - a[ok - 1])) {
			mi = min(a[i] - a[ok - 1],a[ok-1]);
			ma = max(a[i] - a[ok - 1], a[ok - 1]);
		}
		else {
			mi = min(a[i] - a[ok], a[ok]);
			ma = max(a[i] - a[ok], a[ok]);
		}
		ng = i, ok = n;
		while (ok - ng > 1) {
			mid = (ok + ng) / 2;
			if (a[mid]-a[i] >= a[n] - a[mid])ok = mid;
			else ng = mid;
		}
		if (abs(a[ok] - a[i] - a[n] + a[ok] > abs(a[ok - 1] - a[i] - a[n] + a[ok - 1]))) {
			mi = min({ mi,a[ok - 1] - a[i],a[n] - a[ok - 1] });
			ma = max({ ma,a[ok - 1] - a[i],a[n] - a[ok - 1] });
		}
		else {
			mi = min({ mi,a[ok] - a[i],a[n] - a[ok] });
			ma = max({ ma,a[ok] - a[i],a[n] - a[ok] });
		}
		ans = min(ans, ma - mi);
	}
	cout << ans << endl;
	return 0;
}

