int solve(int x,int y,int in,long long s[]){
    int left=x; int right=y;
    while(right-left>1){
        int mid=(left+right)/2;
        if(s[in]-s[mid]<=s[mid]){
            right=mid;
        }else{
            left=mid;
        }
    }
    return left;
}

int solve2(int x,int y,int in,long long s[]){
    int left=x; int right=y;
    while(right-left>1){
        int mid=(left+right)/2;
        if(s[N]-s[mid]<=s[mid]-s[in]){
            right=mid;
        }else{
            left=mid;
        }
    }
    return left;
}

