    int ans = INF;
    FOR(i,2,N-1){//yは2からN-2で全探索
        int y = i;

        //PQの境界を求める
        int ng = 0;
        int ok = y-1;
        while(abs(ok-ng)>1){
            int mid = (ok+ng)/2;
            if(S[mid] >= S[y]-S[mid]){//ここに条件をかく
                ok = mid;
            }else{
                ng = mid;
            }
        }
        int x;
