                save-=sum[index];
                index++;
            }
            else if(index<=2&&sum[index]>save/(4-index)){
                if((i>>index)%2){
                    save-=sum[index];
                    index++;
                }
                else{
                    sum[index]-=a[j];
                    save-=sum[index];
                    index++;
                    sum[index]+=a[j];
                }
            }
        }
        sort(sum,sum+4);
        //cout<<sum[0]<<" "<<sum[3]<<endl;
        if(sum[3]-sum[0]<min){
            min=sum[3]-sum[0];
        }

        index=0;
    }
    cout<<min;

    return 0;

}

