void solve(LL N, vector<LL> A){
	LL l = A[0], r = A[1], p = A[2], q = A[N - 1];   // sum of each segment
	int l_sep = 1, p_sep;

	// initialize p and q
	int left = 3, right = N - 2;
	while (left < right) {
		if (p <= q) {
			p += A[left];
			left++;
		} else {
			q += A[right];
			right--;
		}
	}
	if (left == right) {
		if (p <= q) {
			p += A[left];
			p_sep = left + 1;
		} else {
			q += A[right];
			p_sep = left;
		}
	}

	//printf("l=%lld, r=%lld (l_sep=%d), p=%lld, q=%lld (p_sep=%d)", l, r, l_sep, p, q, p_sep);

	LL min_diff = abs(max({l, r, p, q}) - min({l, r, p, q}));

	//printf(" diff=%d\n", min_diff);

	// sweep the middle separation
	for (int i = 2; i < N - 2; i++) {
		r += A[i];
		while (1) {   // move l_sep to right until optimum (= min(l - r))
			LL l_new = l + A[l_sep];
			LL r_new = r - A[l_sep];
			if (abs(l_new - r_new) < abs(l - r)) {
				l = l_new;
				r = r_new;
				l_sep++;
			} else {
				break;
			}
		}
		p -= A[i];
		if (i + 1 == p_sep) {   // p consisted of only a single element, so we have to shift p_sep right by 1
			p += A[i + 1];
			q -= A[i + 1];
			p_sep++;
		}
		while (1) {   // move p_sep to right until optimum
			LL p_new = p + A[p_sep];
			LL q_new = q - A[p_sep];
			if (abs(p_new - q_new) < abs(p - q)) {
				p = p_new;
				q = q_new;
				p_sep++;
			} else {
				break;
			}
		}
		LL diff = abs(max({l, r, p, q}) - min({l, r, p, q}));
		if (diff < min_diff) {
			min_diff = diff;
		}

		//printf("l=%lld, r=%lld (l_sep=%d), p=%lld, q=%lld (p_sep=%d) diff=%d\n", l, r, l_sep, p, q, p_sep, diff);
	}
	cout << min_diff << endl;
}


