template<class typeNode> struct nodeSumPointAdd {
	typeNode unitNode = 0;
	typeNode funcNode(typeNode l,typeNode r){return l+r;}
	typeNode funcMerge(typeNode l,typeNode r){return l+r;}
	// Binary Search for first index at where funcCheck is true
	bool funcCheck(typeNode nodeVal,typeNode var){return nodeVal > var-nodeVal;}
};

int main() {
    int N; cin >> N;
    vector<ll> A(N);
    for(int i = 0; i < N; ++i) cin >> A[i];
    SegmentTree<nodeSumPointAdd<ll>> seg(A);
    ll ans = LOWINF;
    for(int i = 2; i+2 < N; ++i) {
        ll suml = seg.get(0,i);
        ll sumr = seg.get(i,N);
        size_t l = seg.BinarySearch(0,i,suml);
        size_t r = seg.BinarySearch(i,N,sumr);
        for(int j = 0; j < 2; ++j){
            for(int k = 0; k < 2; ++k){
                ll P = seg.get(0,l+j);
                ll Q = seg.get(l+j,i);
                ll R = seg.get(i,r+k);
                ll S = seg.get(r+k,N);
                ll maxi = max({P,Q,R,S});
                ll mini = min({P,Q,R,S});
                if(mini) chmin(ans,maxi-mini);
            }
        }
    }
    cout << ans << endl;

    return 0;
}

#include <algorithm>
