using namespace std;


long N;
vector<long> A(200000);


int main()
{
    cin >> N;
    for( int i = 0; i < N; ++i ) cin >> A[i];

    // 予め和の配列を求めていく
    vector<long> S(200000);  // S[i] = A[0]~A[i]の和
    for( int i = 0; i < N; ++i ){
        if( i == 0 ) S[i] = A[i];
        else S[i] = S[i-1] + A[i];
    }

    // 分割点は全て +1 との間で定義 (つまりinclusive) 
    int posl = 0, posr = 2;
    vector<long> P(4); 
    long ans = LONG_MAX;
    // 2番目の分割点についてしゃくとり法で全探索
    for( int middle = 1; middle < N-2; ++middle ){
        long diffl = LONG_MAX, diffr = LONG_MAX;

        for( int left = posl; left < middle; ++left ){
            if( diffl > abs(S[middle] - 2*S[left]) ){
                diffl = abs( (S[middle] - S[left]) - S[left] );
                posl = left;
            }else break;
        }

        for( int right = max(middle+1, posr); right < N-1; ++right ){
            if( diffr > abs(S[N-1] - 2*S[right] + S[middle]) ){
                diffr = abs( (S[N-1] - S[right]) - (S[right] - S[middle]) );
                posr = right;
            }else break;
        }

        P[0] = S[posl];
        P[1] = S[middle] - S[posl];
        P[2] = S[posr] - S[middle];
        P[3] = S[N-1] - S[posr];
        sort( P.begin(), P.end() );

        ans = min( ans, P[3] - P[0] );
    }

    cout << ans << endl;

    return 0;
}

