#define REP(i, n) for(int i=0; i<int(n); ++i)
#define FOR(i, a, b) for(int i=int(a); i<int(b); ++i)
#define RFOR(i, a, b) for(int i=int(b); i>=int(a); --i)
using ll = long long;

int main() {

	int n;
	std::cin >> n;

	std::vector<ll> a(n);
	REP(i, n) std::cin >> a[i];

	std::vector<ll> c(n + 1, 0);
	REP(i, n) {
		c[i + 1] = c[i] + a[i];
	}

	std::vector<ll> l(n), r(n);
	{ // l
		int p = 0;
		ll sum = 0;
		FOR(i, 2, n - 1) {
			while (p < i && std::abs(c[i] - (sum + a[p]) * 2) < std::abs(c[i] - sum * 2)) {
				sum += a[p++];
			}
			l[i] = p;
		}
	}
	{ // r
		int p = n - 1;
		ll sum = 0;
		RFOR(i, 2, n - 1) {
			ll all = c[n] - c[i];
			while (p >= i && std::abs(all - (sum + a[p]) * 2) < std::abs(all - sum * 2)) {
				sum += a[p--];
			}
			r[i] = p + 1;
		}
	}

	ll ans = (1 << 30);
	FOR(i, 2, n - 1) {
		ll P = c[l[i]];
		ll Q = c[i] - c[l[i]];
		ll R = c[r[i]] - c[i];
		ll S = c[n] - c[r[i]];
		ans = std::min(ans, std::max({ P,Q,R,S }) - std::min({ P,Q,R,S }));
	}
	std::cout << ans << std::endl;
	return 0;
}

