			else r=mid;
		}
		sb=abs(sur-sul);
		su[0]=sul;
		su[1]=sur;
		if(abs(sur-sul-2*(v[mid+1]-v[mid]))<sb){
			su[0]+=v[mid+1]-v[mid];
			su[1]-=v[mid+1]-v[mid];
		}
		//cout<< su[0] << " " << su[1] << " ";

		l=i+1;
		r=n;
		while(1){
			mid=(l+r)/2;
			sul=v[mid]-v[i];
			sur=v[n]-v[mid];
			//cout<< l << "#" << r << " " << sul << " " << sur <<endl;
			if(r-l<2) break;

			if(sul<sur) l=mid;
			else r=mid;
		}
		sb=abs(sur-sul);
		su[2]=sul;
		su[3]=sur;
		if(abs(sur-sul-2*(v[mid+1]-v[mid]))<sb){
			su[2]+=v[mid+1]-v[mid];
			su[3]-=v[mid+1]-v[mid];
		}
		//cout<< su[2] << " " << su[3] <<endl;

		sort(su.begin(), su.end());
		//PVL(su);
		mi=min(mi, su[3]-su[0]);
	}

	cout<< mi <<endl;

	return 0;
}

