#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main(){
    int n,i1=1,i2=2,i3;
    cin >> n;
    vector<ll> a(n),s(n);
    for(int i = 0;i < n;i ++){
        cin >> a[i];
        if(!i) s[i] = a[i];
        else s[i] = s[i-1] + a[i];
    }
    ll P,Q,R,S,m,M,ans;
    P = a[0];
    Q = a[i1];
    ll sub = 1e15;
    for(int j = 3;j < n;j ++){
        if(abs((s[j-1] - s[1])-(s[n-1] - s[j-1]))<sub){
            R = s[j-1] - s[1];
            S = s[n-1] - s[j-1];
            sub = abs(R-S);
        }else{
            i3 = j-1;
            break;
        }
    }
    m = min(min(P,Q),min(R,S));
    M = max(max(P,Q),max(R,S));
    ans = M-m;
    for(int i = 2;i < n-1;i ++){
        i2 = i;
        if(abs((P+a[i1])-(Q+a[i2]-a[i1]))>abs(P-(Q+a[i2]))){
            Q += a[i2];
        }else{
            P += a[i1];
            Q = Q+a[i2]-a[i1];
            i1 ++;
        }
        if(abs((R-a[i2]+a[i3])-(S-a[i3]))>abs((R-a[i2])-S)||i3==n){
            R -= a[i2];
        }else{
            R = R-a[i2]+a[i3];
            S -= a[i3];
            i3 ++;
        }
        m = min(min(P,Q),min(R,S));
        M = max(max(P,Q),max(R,S));
        if(ans>M-m)ans = M-m;
    }
    cout << ans << endl;
    return 0;
}

