    right = 1;
    for(int i = 2; i < N-2; i++){
        if(sumrl + A[i] < sumrr - A[i]){
            sumrl = sumrl + A[i];
            sumrr = sumrr - A[i];
            right++;
        }else{
            break;
        }
    }
    ans = min(ans, diff(sumll, sumlr, sumrl, sumrr));
    ans = min(ans, diff(sumll, sumlr, sumrl+A[right+1], sumrr-A[right+1]));
    ans = min(ans, diff(sumll+A[left+1], sumlr-A[left+1], sumrl, sumrr));
    ans = min(ans, diff(sumll+A[left+1], sumlr-A[left+1], sumrl+A[right+1], sumrr-A[right+1]));
    for(int mid = 2; mid < N-2; mid++){
        sumlr += A[mid];
        sumrl -= A[mid];
        for(int i = left+1; i < N-2; i++){
            if(sumll + A[i] < sumlr - A[i]){
                sumll = sumll + A[i];
                sumlr = sumlr - A[i];
                left++;
            }else{
                break;
            }
        }
        for(int i = right+1; i < N-2; i++){
            if(sumrl + A[i] < sumrr - A[i]){
                sumrl = sumrl + A[i];
                sumrr = sumrr - A[i];
                right++;
            }else{
                break;
            }
        }
        ans = min(ans, diff(sumll, sumlr, sumrl, sumrr));
        ans = min(ans, diff(sumll, sumlr, sumrl+A[right+1], sumrr-A[right+1]));
        ans = min(ans, diff(sumll+A[left+1], sumlr-A[left+1], sumrl, sumrr));
        ans = min(ans, diff(sumll+A[left+1], sumlr-A[left+1], sumrl+A[right+1], sumrr-A[right+1]));
    }
    cout << ans << endl;
}

