int min_sub(vector<int> accum, int l, int m, int r){
    vector<int> tmp;
    tmp.push_back(accum[l]);
    tmp.push_back(accum[m] - accum[l]);
    tmp.push_back(accum[r] - accum[m]);
    tmp.push_back(accum[accum.size() - 1] - accum[r]);
    return *max_element(tmp.begin(), tmp.end()) - *min_element(tmp.begin(), tmp.end());
}

int main(){
