    int ac = 0;
    for (int i=0; i<N; i++){
        ac += A[i];
        accum.push_back(ac);
    }
    int l = 0;
    int m = 1;
    int r = 2;
    while (true){
        if (abs((accum[A.size() - 1] - accum[r]) - (accum[r] - accum[m])) < abs((accum[A.size() - 1] - accum[r+1]) - (accum[r+1] - accum[m]))){
            break;
        }
        r++;
    }
    int ans = min_sub(accum, l, m, r);
    for (int i=m+1; i<N-2; i++){
        while (abs(accum[i] - accum[l] - accum[l]) > abs(accum[i] - accum[l+1] - accum[l+1])){
            l++;
            if (l + 1 == i) break;
        }
        while (abs((accum[A.size() - 1] - accum[r]) - (accum[r] - accum[i])) > abs((accum[A.size() - 1] - accum[r+1]) - (accum[r+1] - accum[i]))){
            r++;
            if (r + 1 == A.size() - 1) break;
        }
