      P[3] -= a[k];
    }
    while(k < N - 1 && P[2] + a[k + 1] < P[3]){
      ++k;
      P[2] += a[k];
      P[3] -= a[k];
    }
    A = min(A, *max_element(P, P + 4) - *min_element(P, P + 4));
  }
  cout << A << endl;
}

