vector<long long> su(100000);

int Search(int le, int ri,long long ta) {
	if (ri - le == 1)
		return le;
	if (su[(le + ri) / 2]*2 > ta) {
		return Search(le, (le + ri) / 2, ta);
	}
	else {
		return Search((le + ri) / 2, ri, ta);
	}
}

long long check(int n,int size) {
	int a = Search(0, n, su[n]);
	int b = Search(n + 1, size - 1, su[size - 1] + su[n]);
	long long MA = max(max(su[a], su[n] - su[a]), max(su[b] - su[n], su[size-1] - su[b]));
	long long MI = min(min(su[a], su[n] - su[a]), min(su[b] - su[n], su[size-1] - su[b]));
	return MA - MI;
}

