void solve()
{
    ll N;
    in(N);
    vll A(N);
    vin(A, N);
    // (i番目の数をj番目の塊として選択中、最大値がa、最小値がb)
    vll csum(N + 1);
    for1 (i, N) {
        csum[i + 1] = csum[i] + A[i];
    }
    ll ans = INF;

    // 2つずつに切る位置 i-1 | i
    for2 (i, 2, N - 1) {
        ll pq = csum[i];
        ll rs = csum[N] - csum[i];

        ll lo = 1;
        ll hi = i - 1 + 1;
        auto delta1 = [&](ll m) {
            ll a = csum[m];
            ll b = pq - a;
            return abs(a - b);
        };
        while (hi - lo > 1) {
            ll mi = (hi + lo) / 2;
            if (csum[mi] * 2 <= pq) {
                lo = mi;
            }
            else {
                hi = mi;
            }
        }
        ll c1 = lo;
        if (delta1(c1) > delta1(c1 + 1)) {
            c1++;
        }

        lo = i + 1;
        hi = N - 1 + 1;
        auto delta2 = [&](ll m) {
            ll a = csum[m] - pq;
            ll b = rs - a;
            return abs(a - b);
        };
        while (hi - lo > 1) {
            ll mi = (hi + lo) / 2;
            if ((csum[mi] - pq) * 2 <= rs) {
                lo = mi;
            }
            else {
                hi = mi;
            }
        }
        ll c2 = lo;
        if (delta2(c2) > delta2(c2 + 1)) {
            c2++;
        }

        vll s(4);
        s[0] = csum[c1];
        s[1] = csum[i] - csum[c1];
        s[2] = csum[c2] - csum[i];
        s[3] = csum[N] - csum[c2];
        ll d = *max_element(all(s)) - *min_element(all(s));
        // dump(c1, i, c2, d, s);
        chmin(ans, d);
    }
    print(ans);
}
