			ans = min(ans, max(a[i-1]-a[j-1], a[k]-a[i-1]) - min(a[j-1], a[n]-a[k]));
			if(k >= i+1){
				ans = min(ans, max(a[i-1]-a[j-1], a[n]-a[k-1]) - min(a[j-1], a[k-1]-a[i-1]));
			}
		}else if(k >= i+1){
			ans = min(ans, max(a[j], a[n]-a[k-1]) - min(a[i-1]-a[j], a[k-1]-a[i-1]));
		}
//		cout << i << " " << j << " " << k << "\n";
	}
	cout << ans << "\n";
}

