    }

    ll answer = 1e10;
    for (int i=2; i<N; i++) {
        int left = 0;
        int right = i;

        while (1 < right - left) {
            int mid = (right + left)/2;
            if (A[mid] < A[right] - A[mid]) {
                left = mid;
            } else {
                right = mid;
            }
        }
        ll B = A[left];
        ll C = A[i] - A[left];
        ll B2 = A[right];
        ll C2 = A[i] - A[right];

        ll lmin = min(B,C);
        ll lmax = max(B,C);
        if (abs(B2-C2) < abs(B-C)) {
            lmin = min(B2,C2);
            lmax = max(B2,C2);
        }

        left = i;
        right = N;
        while (1 < right - left) {
            int mid = (right + left)/2;
            if (A[mid] - A[i] < A[N-1] - A[mid]) {
                left = mid;
            } else {
