long long int min4(long long int p, long long int q, long long int r, long long int s) {

	long long int ret = p;
	if (ret > q) { ret = q; }
	if (ret > r) { ret = r; }
	if (ret > s) { ret = s; }

	return ret;
}

long long int max4(long long int p, long long int q, long long int r, long long int s) {

	long long int ret = p;
	if (ret < q) { ret = q; }
	if (ret < r) { ret = r; }
	if (ret < s) { ret = s; }

	return ret;
}

