pair<int, int> solve_two (vector<int> sum, int begin, int end) {
  int x=0, y=0, ans=1e15;
  pair<int, int> p;
  for(int i=begin;i<end;i++) {
    x = sum[i] - sum[begin];
    y = sum[end] - sum[i];
    if (ans != min(ans, abs(x - y))) {
      ans = abs(x - y);
      p.first = x;
      p.second = y;
    }
  }
  return p;
}

