static vector<int> A;
static vector<long> accum;

// A[ [top, bot) ] の合計
static long
sum(int top, int bot)
{
  return accum[bot] - accum[top];
}

static void
fit(int &pos, int top, int bot)
{
  long lsum = sum(top, pos);
  long rsum = sum(pos, bot);
  long diff = abs(lsum - rsum);
  while (pos < bot - 1)
  {
    long new_lsum = sum(top, pos + 1);
    long new_rsum = sum(pos + 1, bot);
    long new_diff = abs(new_lsum - new_rsum);
    if (diff <= new_diff)
    {
      break;
    }
    diff = new_diff;
    pos++;
  }
}

int
main()
{
  int N;
  cin >> N;
  A.resize(N);
  accum.resize(N + 1);
  accum[0] = 0;
  {
    long total = 0;
    for (int i = 0; i < N; i++)
    {
      int val;
      cin >> val;
      A[i] = val;
      total += val;
      accum[i + 1] = total;
    }
  }
  int l = 1;
  int r = 3;
  long min_diff = -1;
  for (int c = 2; c < N - 1; c++)
  {
    fit(l, 0, c);
    fit(r, c, N);
    long P = sum(0, l);
    long Q = sum(l, c);
    long R = sum(c, r);
    long S = sum(r, N);
    long diff = max({P, Q, R, S}) - min({P, Q, R, S});
    min_diff = (min_diff == -1 ? diff : min(diff, min_diff));
  }
  cout << min_diff << endl;
  return 0;
}

