int EC(int SUM, vector<int> v, int start, int end){
  int sum = 0;
  int res;
  for(int i = start; i < end+1; ++i){
    int presum = sum;
    sum += v.at(i);
    if( sum >= SUM/2 && presum <= SUM/2){
      res = i;
      break;
    }
  }
  return res;
}

