            }
            if (i != pos) {
                v.pb(sum - arr[i]);
                rec(p + 1, i, v);
                v.pop_back();
            }
            v.pb(sum);
            rec(p + 1, i + 1, v); v.pop_back();
            if (n - i - 1 >= 4 - p) {
                v.pb(sum + arr[i + 1]);
                rec(p + 1, i + 2, v);
                v.pop_back();
            }
            if (n - i - 2 >= 4 - p) {
                v.pb(sum + arr[i + 1] + arr[i + 2]);
                rec(p + 1, i + 3, v);
                v.pop_back();
            }
