LL getsum(int l,int r)
{
    return sum[r] - sum[l - 1];
}
LL partition(int l,int mid,int r)
{
    LL s1 = getsum(l,mid);
    LL s2 = getsum(mid + 1,r);
    return ABS(s1 - s2);
}

