using namespace std;

class CumulativeSum {

public:
    std::vector<long long> memo1;               // 1次元用の累積和表

    CumulativeSum() {}

    void build(const std::vector<long long> &line) {
        this->memo1.assign(line.size() + 1, 0);

        for (long long i = 0; i < line.size(); ++i) {
            this->memo1[i + 1] = this->memo1[i] + line[i];
        }
    }

    long long sum(int left, int right) {
        return this->memo1[right] - this->memo1[left];
    }
};


pair<LL, LL> func(int left, int right, CumulativeSum &cs) {

    LL total = cs.sum(left, right);

    // [low, high)
    long long low = left, high = right;
    while (high - low > 1) {
        long long middle = (low + high) / 2;
        LL l = cs.sum(left, middle);
        LL r = total - l;
        if (l < r) {
            low = middle;
        }
        else {
            high = middle;
        }
    }

    pair<LL, LL> ans;
    LL best_diff = INF;
    FOR(i, max(0LL, low - 1), min<LL>(right, low + 2)) {
        LL l = cs.sum(left, i);
        LL r = total - l;
        if (abs(l - r) < best_diff) {
            best_diff = abs(l - r);
            ans = make_pair(l, r);
        }
    }

    return ans;
};


