    }

    CumulativeSum cs;
    cs.build(A);

    LL ans = INF;
    FOR(m, 2, N - 1) {
        auto a = func(0, m, cs);
        auto b = func(m, N, cs);

        vector<LL> v = {a.first, a.second, b.first, b.second};
        ans = min(ans, MAX(v) - MIN(v));
    }
    print(ans);

    return 0;
}

