uint n;
ll a[200001];
uint l, c, r;

ll getval() {
  ll prev_diff, curr_diff;
  ll cval = a[c], eval = a[n];

  // left side
  prev_diff = numeric_limits<ll>::max();
  while (1) {
    curr_diff = abs((cval - a[l]) - (a[l] - 0));
    if (curr_diff > prev_diff) {
      --l;
      break;
    }

    prev_diff = curr_diff;
    ++l;
    if (l >= c) {
      --l;
      break;
    }
  }

  // right side
  prev_diff = numeric_limits<ll>::max();
  while(1) {
    curr_diff = abs((eval - a[r]) - (a[r] - cval));
    if (curr_diff > prev_diff) {
      --r;
      break;
    }

    prev_diff = curr_diff;
    ++r;
    if (r >= n) {
      --r;
      break;
    }
  }

  // calc val
  ll sum[4];
  sum[0] = a[l] - 0;
  sum[1] = cval - a[l];
  sum[2] = a[r] - cval;
  sum[3] = eval - a[r];
  ll maxval = *max_element(sum, sum+4);
  ll minval = *min_element(sum, sum+4);
  return maxval - minval;
}

int main() {
  scanf("%u", &n);

  a[0] = 0;
  rep(i,n) {
    scanf("%llu", &a[i+1]);
    a[i+1] += a[i];
  }

  ll minval = numeric_limits<ll>::max();
  for (l = 1, c = 2, r = 3; c <= n - 2; ++c) {
    if (r <= c) r = c + 1;   
    ll val = getval();
    if (val < minval) minval = val;
  }

  printf("%llu\n", minval);
  return 0;
}

