		int m=lower_bound(sum,sum+n,sum[i-1]+(sum[n-1]-sum[i-1]+1)/2)-sum;
		if(m<n-1)g=sum[m]-sum[i-1],h=sum[n-1]-sum[m];
		if(m>i)j=sum[m-1]-sum[i-1],l=sum[n-1]-sum[m-1];
		if(abs(g-h)<=abs(j-l))gg=max(g,h),hh=min(g,h);
		else gg=max(j,l),hh=min(j,l);
		ans=min(ans,max(max(bb-cc,gg-hh),max(gg-cc,bb-hh)));
	}
	c(ans)
}

