    vector<ll> C;
    ll s = 0;
    for (ll i = 0; i < N; ++i) {
        ll a;
        cin >> a;
        A.push_back(a);
        s += a;
        C.push_back(s);
    }
    ll ans = 99999999999;
    for (ll i = 1; i < N - 2; ++i) {
        ll P, Q, R, S;

        ll Ls = 0;
        ll Lm = 99999999999;
        for (ll j = 0; j < i; ++j) {
            P = C[j];
            Q = C[i] - C[j];
            ll d = abs(P - Q);
            if (d < Lm) {
                Ls = j;
                Lm = d;
            }
        }
        P = C[Ls];
        Q = C[i] - C[Ls];
        ll Rs = i + 1;
        ll Rm = 999999999999;
        for (ll k = i + 1; k < N - 1; ++k) {
            R = C[k] - C[i];
            S = C[N - 1] - C[k];
            ll d = abs(R - S);
            if (d < Rm) {
                Rs = k;
                Rm = d;
            }
        }
        R = C[Rs] - C[i];
        S = C[N - 1] - C[Rs];

        ll d = max(max(max(P, Q), R), S) - min(min(min(P, Q), R), S);
        if (ans > d) {
            ans = d;
        }
    }
    cout << ans << endl;
}

