int n;
ll ecut(int from, int to)
{
    if (to - from <= 1)
        return -1;

    int s = from + 1, t = to, mid;
    ll target = (a[to] + a[from]) / 2;
    while (s != t)
    {
        mid = (s + t) / 2;
        if (a[mid] == target)
            s = t = mid;
        else if(a[mid] > target)
            t = mid;
        else
            s = mid + 1;
    }

    ll ans = a[to];
    rep(i, 3)
    {
        int p = s - 1 + i;
        if (p <= from or p > to) continue;
        ll cand = max(a[p] - a[from], a[to] - a[p]);
        ans = min(ans, cand);
    }
    return ans;
}

