    rep(i, n + 1)
    {
        ll c1 = ecut(0, i);
        ll c2 = ecut(i, n);
        if (c1 == -1 or c2 == -1) continue;

        ll cand = max(c1, c2) - min(a[i] - c1, a[n] - a[i] - c2);
        ans = min(ans, cand);
    }
    cout << ans << endl;
}

