#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = 1000000000000000000LL;

int n;
vector<ll> a;
vector<ll> prefSums;

ll getPrefSum(int l, int r)
{
	ll valL = l == 0 ? 0 : prefSums[l - 1];
	ll valR = prefSums[r];
	return valR - valL;
}

ll calcDiff(int l, int m, int r)
{
	return abs(getPrefSum(l, m) - getPrefSum(m + 1, r));
}

int ternarySearch(int l_, int r_)
{
	int l = l_, r = r_ - 1;
	while (r - l >= 3)
	{
		int m1 = l + (r - l) / 3;
		int m2 = r - (r - l) / 3;
		if (calcDiff(l_, m1, r_) > calcDiff(l_, m2, r_))
			l = m1;
		else
			r = m2;
	}
	ll minRes = 2 * INF;
	int minI = 0;
	for (int i = l; i <= r; i++)
	{
		ll res = calcDiff(l_, i, r_);
		if (res < minRes)
		{
			minRes = res;
			minI = i;
		}
	}
	return minI;
}

int main()
{
	ios::sync_with_stdio(false);
	cin >> n;
	a.resize(n);
	prefSums.resize(n);
	for (int i = 0; i < n; i++)
	{
		cin >> a[i];
		if (i != 0)
			prefSums[i] = prefSums[i - 1];
		prefSums[i] += a[i];
	}
	ll result = INF;
	for (int i = 2; i < n - 1; i++)
	{
		int t1 = ternarySearch(0, i - 1);
		int t2 = ternarySearch(i, n - 1);
		ll sum1 = getPrefSum(0, t1), sum2 = getPrefSum(t1 + 1, i - 1);
		ll sum3 = getPrefSum(i, t2), sum4 = getPrefSum(t2 + 1, n - 1);
		ll maxSum = max(max(sum1, sum2), max(sum3, sum4));
		ll minSum = min(min(sum1, sum2), min(sum3, sum4));
		result = min(result, maxSum - minSum);
	}
	cout << result << endl;
}

