int binary_search(long long key){
	// key以上の値をとるindexは全てokとする
    int ng=-1; // aの左の範囲外は必ずng
    int ok=n; // aの右の範囲外は必ずok

    while (abs(ok-ng)>1) {
        int mid=(ok+ng)/2;
        if(isOK(mid,key)) ok=mid;
        else ng=mid;
    }
    return ok;
}

