template<typename T> T max4(T x, T y, T z, T w){
  return max(max(x, y), max(z, w));
}

template<typename T> T min4(T x, T y, T z, T w){
  return min(min(x, y), min(z, w));
}

template<typename T> T diff4(T x, T y, T z, T w){
  return max4(x, y, z, w) - min4(x, y, z, w);
