  for (auto& ai: a) scanf("%jd", &ai);

  a.insert(a.begin(), 0);
  for (size_t i = 1; i <= n; ++i) a[i] += a[i-1];

  std::vector<std::tuple<size_t, size_t, size_t>> cand;
  for (size_t j = 2; j+1 < n; ++j) {
    size_t i = std::lower_bound(a.begin(), a.end(), a[n]/4) - a.begin();
    size_t k = std::lower_bound(a.begin(), a.end(), a[n]*3/4) - a.begin();

    for (int di = -3; di <= 3; ++di)
      for (int dk = -3; dk <= 3; ++dk)
        cand.emplace_back(i+di, j, k+dk);
  }

  intmax_t res = a[n];
