    if (!(0 < i && i < j && j < k && k < n)) continue;
    std::array<intmax_t, 4> d{{a[i], a[j]-a[i], a[k]-a[j], a[n]-a[k]}};
    std::sort(d.begin(), d.end());
    intmax_t cur = d[3] - d[0];
    res = std::min(res, cur);
  }

