template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }
const ll INF = 1e18;
const ll MOD = 1e9 + 7;


int main(){
    int n;
    cin >> n;
    vector<int> v(n);
    rep(i, n) cin >> v[i];

    vector<ll> sum(n);
    sum[0] = v[0];
    for(int i=1; i<n; i++) sum[i] = sum[i-1] + v[i];

    ll ans = INF;
    for(int m=1; m<=n-2; m++){
        ll l = sum[m];
        auto iter = lower_bound(all(sum), (double)l / 2.0);
        int pos = distance(sum.begin(), iter);
        ll P = sum[pos];
        ll Q = l - P;
        if(abs(P-Q) > abs((P - v[pos]) - (Q + v[pos]))){
            P -= v[pos];
            Q += v[pos];
        }

        ll r = sum[n-1] - sum[m];
        iter = lower_bound(all(sum), l + (double)r / 2.0);
        pos = distance(sum.begin(), iter);
        ll R = sum[pos] - l;
        ll S = r - R;
        if(abs(R-S) > abs((R-v[pos]) - (S+v[pos]))){
            R -= v[pos];
            S += v[pos];
        }

        chmin(ans, max({P, Q, R, S}) - min({P, Q, R, S}));
    }

    cout << ans << endl;
}

