using namespace std;

pair<int, int> solve(list<int> &input, list<int> &front, list<int> &back){
  int sum_front = 0, sum_back = 0;

  int count = 0;
  for(auto each: input){
    if(count < input.size()){
      front.push_back(each);
      sum_front += each;
    }else{
      back.push_back(each);
      sum_back += each;
    }
    count++;
  }

  bool f_flag = false, b_flag = false;
  while (true) {
    if(sum_front > sum_back){
      if(b_flag){
        int now = abs(sum_back - sum_front);
        int moved = front.back();
        int next = abs((sum_back + moved) - (sum_front - moved));
        if(now < next){
          break;
        }else{
          int moved = front.back();

          back.push_front(moved);
          sum_back += moved;

          front.pop_back();
          sum_front -= moved;
          break;
        }
      }
      int moved = front.back();

      back.push_front(moved);
      sum_back += moved;

      front.pop_back();
      sum_front -= moved;

      f_flag = true;
    }else{
      if(f_flag){
        int now = abs(sum_back - sum_front);
        int moved = back.front();
        int next = abs((sum_back - moved) - (sum_front + moved));
        if(now < next){
          break;
        }else{
          int moved = back.front();

          front.push_back(moved);
          sum_front -= moved;

          back.pop_front();
          sum_back += moved;
          break;
        }
      }
      int moved = back.front();

      front.push_back(moved);
      sum_front -= moved;

      back.pop_front();
      sum_back += moved;

      b_flag = true;
    }
  }
  return make_pair(sum_front, sum_back);
}

int main() {
  int N;

  scanf("%d", &N);

  list<int> input;
  for(int i = 0; i < N; i++){
    int tmp;
    scanf("%d", &tmp);
    input.push_back(tmp);
  }

  list<int> ab, cd;
  list<int> a, b, c, d;

  solve(input, ab, cd);
  pair<int, int> sum_ab = solve(ab, a, b);
  pair<int, int> sum_cd = solve(cd, c, d);

  int sum_a = std::accumulate(a.begin(), a.end(), 0);
    int sum_b = std::accumulate(b.begin(), b.end(), 0);
      int sum_c = std::accumulate(c.begin(), c.end(), 0);
        int sum_d = std::accumulate(d.begin(), d.end(), 0);

  int max_a = max(sum_a, max(sum_b, max(sum_c, sum_d)));
  int min_a = min(sum_a, min(sum_b, min(sum_c, sum_d)));

  printf("%d", abs(max_a - min_a));

  return 0;
}

