void solve() {
    int N;
    cin >> N;
    vector<ll> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    vector<ll> acc(N + 1);
    for (int i = 0; i < N; i++) {
        acc[i + 1] = acc[i] + A[i];
    }
    ll ans = 1LL << 60;
    for(int j = 2; j < N - 1; j++) {
        int i1 = lower_bound(all(acc), acc[j] / 2) - acc.begin();
        int k1 = lower_bound(all(acc), acc[j] + (acc[N] - acc[j]) / 2) - acc.begin();
        vector<int> I = {i1};
        vector<int> K = {k1};
        if (i1 - 1 >= 0) I.push_back(i1 - 1);
        if (k1 - 1 >= 0) K.push_back(k1 - 1);
        for(int u = 0; u < I.size(); u++) {
            for(int v = 0; v < K.size(); v++) {
                int i = I[u], k = K[v];
                vector<ll> area;
                area.push_back(acc[i]);
                area.push_back(acc[j] - acc[i]);
                area.push_back(acc[k] - acc[j]);
                area.push_back(acc[N] - acc[k]);
                sort(all(area));
                ans = min(ans, area.back() - area[0]);
            }
        }
    }
    cout << ans << endl;
}

