    for (int i = 0; i < N; ++i)
    {
        int a;
        cin >> a;
        if (i == 0)
        {
            sumArray[i] = a;
        }
        else
        {
            sumArray[i] = sumArray[i - 1] + a;
        }
    }

    auto calc = [](int first, int last, s64* min, s64* max) {
        int leftLast = findLeftLast(first, last, first, last - 1);
        s64 left, right, diff;
        calcLR(first, last, leftLast, &left, &right);
        if (left < right)
        {
            *min = left;
            *max = right;
        }
        else
        {
            *min = right;
            *max = left;
        }
        diff = *max - *min;

        if (leftLast > 0)
        {
            calcLR(first, last, leftLast - 1, &left, &right);
            s64 d = abs(left - right);
            if (d < diff)
            {
                diff = d;
                if (left < right)
                {
                    *min = left;
                    *max = right;
                }
                else
                {
                    *min = right;
                    *max = left;
                }
            }
        }
        if (leftLast < N - 2)
        {
            calcLR(first, last, leftLast + 1, &left, &right);
            s64 d = abs(left - right);
            if (d < diff)
            {
                diff = d;
                if (left < right)
                {
                    *min = left;
                    *max = right;
                }
                else
                {
                    *min = right;
                    *max = left;
                }
            }
        }
    };

    s64 diffMin = -1;
    for (int leftLast = 1; leftLast <= N - 3; ++leftLast)
    {
        s64 leftMin, leftMax, rightMin, rightMax;
        calc(0, leftLast, &leftMin, &leftMax);
        calc(leftLast + 1, N - 1, &rightMin, &rightMax);
        s64 diff = max(leftMax, rightMax) - min(leftMin, rightMin);
        if (diffMin == -1 || diff < diffMin)
        {
            diffMin = diff;
        }
    }
    cout << diffMin << endl;

    return 0;
}

