ll P, Q, R, S;

ll sa(){
  vector<ll> vec(4);
  vec[0] = P, vec[1] = Q, vec[2] = R, vec[3] = S;
  sort(vec.begin(), vec.end());
  return vec[3] - vec[0];
}

int main(){
