  ll s = 0, t = -1;
  P = A[0];
  Q = A[1];
  ll sum[N-1];
  sum[0] = 0;
  ll ss = 0;
  for(int i = 1; i < N-1; i++){
    sum[i] = sum[i-1] + A[i+1];
