long long std_abs(long long a)
{
  return a < 0 ? -a : a;
}

int main()
{
  int n;
  scanf("%d", &n);
  vector<long long> data(n);
  for(int i = 0; i < n; i++) {
    scanf("%lld", &data[i]);
  }
  int last1, last2, last3;
  long long sum = 0;
  for(int i = 0; i < n; i++) {
    sum += data[i];
  }
  long long sum12 = 0;
  long long sum34 = 0;
  long long sum1 = 0;
  long long sum2 = 0;
  long long sum3 = 0;
  long long sum4 = 0;
  long long prev_diff;

  prev_diff = LLONG_MAX;
  sum12 += data[0];
  for(last2 = 1; last2 <= n - 3; last2++) {
    sum12 += data[last2];
    sum34 = sum - sum12;
    if(std_abs(sum12 - sum34) < prev_diff) {
      prev_diff = std_abs(sum12 - sum34);
    } else {
      sum12 -= data[last2];
      sum34 = sum - sum12;
      last2--;
      break;
    }
  }

  prev_diff = LLONG_MAX;
  for(last1 = 0; last1 < last2; last1++) {
    sum1 += data[last1];
    sum2 = sum12 - sum1;
    if(std_abs(sum1 - sum2) < prev_diff) {
      prev_diff = std_abs(sum1 - sum2);
    } else {
      sum1 -= data[last1];
      sum2 = sum12 - sum1;
      last1--;
      break;
    }
  }

  prev_diff = LLONG_MAX;
  for(last3 = last2+1; last3 <= n-2; last3++) {
    sum3 += data[last3];
    sum4 = sum34 - sum3;
    if(std_abs(sum3 - sum4) < prev_diff) {
      prev_diff = std_abs(sum3 - sum4);
    } else {
      sum3 -= data[last3];
      sum4 = sum34 - sum3;
      last3--;
      break;
    }
  }

  prev_diff = std_abs(sum2 - sum3);
  if(sum2 < sum3) {
    while(1) {
      last2++;
      sum2 += data[last2];
      sum3 -= data[last2];
      if(prev_diff < std_abs(sum2 - sum3)) {
        sum2 -= data[last2];
        sum3 += data[last2];
        last2--;
        break;
      }
    }
  } else {
    while(1) {
      sum2 -= data[last2];
      sum3 += data[last2];
      last2--;
      if(prev_diff < std_abs(sum2 - sum3)) {
        last2++;
        sum2 += data[last2];
        sum3 -= data[last2];
        break;
      }
    }
  }

  printf("%lld\n", std_abs(max(sum1, max(sum2, max(sum3, sum4))) - min(sum1, min(sum2, min(sum3, sum4)))));
  return 0;
}

