int     Pos(long AA, vector<long> &A) {
        int a=0;
        int b=A.size()-1;
        while (1<b-a) {
                int c=(a+b)/2;
                if (AA>=A.at(c))
                        a=c;
                else b=c;
        }
        return a;
}

int     Mid(int a, int b, vector<long> &A) {
        long T=(A.at(a)+A.at(b))/2;
        return Pos(T, A);
}

int     F(int L, int R, vector<long> &A, int S) {
        long L1=A.at(S)-A.at(L);
        long R1=A.at(R)-A.at(S);
        long D1=abs(L1-R1);
        if (L1>=R1) return S;
        for (;;) {
                if (R-S==1) return S;
                S++;
                long L2=A.at(S)-A.at(L);
                long R2=A.at(R)-A.at(S);
                long D2=abs(L2-R2);
                if (L2>=R2) {
                        if (D1<D2) return (S-1);
                        else return S;
                }
                L1=L2;
                R1=R2;
                D1=D2;
        }
}

