        vector<int> L(N+1, 0);
        vector<int> R(N+1, 0);
        L.at(1)=1;
        R.at(1)=3;
        long AAA=A.at(N);
        long S=A.at(N);
        for (int i=2; i<N-1; i++) {
                L.at(i)=F(0, i, A, L.at(i-1));
                R.at(i)=F(i, N, A, R.at(i-1));
                int D1=A.at(L.at(i));
                int D2=A.at(i)-D1;
                int D3=A.at(R.at(i))-D2-D1;
                int D4=AAA-D3-D2-D1;
                long SS=max(max(D4, D3), max(D2, D1))-min(min(D4, D3), min(D2, D1));
