typedef long long s64;
s64 sumArray[200000];
int N;

void calcLR(int first, int last, int leftLast, s64* left, s64* right)
{
    *left = sumArray[leftLast];
    if (first != 0)
    {
        *left -= sumArray[first - 1];
    }
    *right = sumArray[last] - sumArray[leftLast];
}

int findLeftLast(int first, int last, int candFirst, int candLast, int depth)
{
    if (candFirst == candLast)
    {
        return candFirst;
    }
    if (candLast - candFirst == 1)
    {
        s64 left, right;
        calcLR(first, last, candFirst, &left, &right);
        s64 diff1 = abs(left - right);
        calcLR(first, last, candLast, &left, &right);
        s64 diff2 = abs(left - right);
        if (diff1 < diff2)
        {
            return candFirst;
        }
        else
        {
            return candLast;
        }
    }
    int llast = (candFirst + candLast) / 2;
    s64 left, right;
    calcLR(first, last, llast, &left, &right);
    if (left == right)
    {
        return llast;
    }
    else if (left < right)
    {
        if (llast == last - 1)
        {
            return llast;
        }
        return findLeftLast(first, last, llast, candLast, depth + 1);
    }
    else
    {
        if (llast == 0)
        {
            return llast;
        }
        return findLeftLast(first, last, candFirst, llast, depth + 1);
    }
}

int main()
{
    cin >> N;
    for (int i = 0; i < N; ++i)
    {
        int a;
        cin >> a;
        if (i == 0)
        {
            sumArray[i] = a;
        }
        else
        {
            sumArray[i] = sumArray[i - 1] + a;
        }
    }

    auto calc = [](int first, int last, s64* min, s64* max) {
        int leftLast = findLeftLast(first, last, first, last - 1, 0);
        s64 left, right, diff;
        calcLR(first, last, leftLast, &left, &right);
        if (left < right)
        {
            *min = left;
            *max = right;
        }
        else
        {
            *min = right;
            *max = left;
        }
    };

    s64 diffMin = -1;
    for (int leftLast = 1; leftLast <= N - 3; ++leftLast)
    {
        s64 leftMin, leftMax, rightMin, rightMax;
        calc(0, leftLast, &leftMin, &leftMax);
        calc(leftLast + 1, N - 1, &rightMin, &rightMax);
        s64 diff = max(leftMax, rightMax) - min(leftMin, rightMin);
        if (diffMin == -1 || diff < diffMin)
        {
            diffMin = diff;
        }
    }
    cout << diffMin << endl;

    return 0;
}

