#define rep(i, n) for (int i = 0; i < (int)(n); i++)
using namespace std;
typedef long long ll;

int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    vector<ll> sum(N + 1);
    rep(i, N) {
        cin >> A[i];
        sum[i + 1] = A[i];
    }
    sum.push_back(__LONG_LONG_MAX__);

    for (int i = 0; i < N; i++) {
        sum[i + 1] += sum[i];
    }

    ll ans = __LONG_LONG_MAX__;
    for (int i = 0; i < N; i++) {
        if (i < 2) continue;
        if (i > N - 2) continue;

        ll X = sum[i];
        int l = 0;
        int r = i + 1;
        while (r - l >= 1) {
            int mid = (r + l) / 2;
            if (2 * sum[mid] >= X) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        ll P, Q;
        // rかr-1が候補
        ll p1 = sum[r]; ll q1 = X - p1; 
        ll p2 = sum[r - 1]; ll q2 = X - p2;
        if (abs(q1 - p1) > abs(q2 - p2)) {
            P = p2; Q = q2;
        } else {
            P = p1; Q = q1;
        }
// cout << "  i: " << i << ", P: " << P << ", Q: " << Q << endl;

        ll Y = sum[N] - X;
        l = i + 1;
        r = N + 1;
        while (r - l >= 1) {
            int mid = (r + l) / 2;
            if (2 * (sum[mid] - sum[i]) >= Y) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        ll R, S;
        ll r1 = sum[r] - sum[i]; ll s1 = Y - r1;
        ll r2 = sum[r - 1] - sum[i]; ll s2 = Y - r2;
        if (abs(s1 - r1) > abs(s2 - r2)) {
            R = r2; S = s2;
        } else {
            R = r1; S = s1;
        }
        // cout << "  i: " << i << ", R: " << R << ", S: " << S << endl;

        ans = min(ans, max(P, max(Q, max(R, S))) - min(P, min(Q, min(R, S))));
    }
    cout << ans << endl;
}

