int main() {
    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        sum += a[i];
    }

    // (l)(i)(r)()
    l = 0;
    m = 1;
    r = 2;
    ll sum1 = a[0];
    ll sum2 = a[1];
    ll sum3 = a[2];
    ll sum4 = sum - sum1 - sum2 - sum3;
    mx = max(max(sum1, sum2), max(sum3, sum4));
    mi = min(min(sum1, sum2), min(sum3, sum4));
    ans = mx - mi;
    // sum1(l) sum2(m) sum3(r) sum4
    while (1) {
        ++m;
        if (m >= n - 2) break;
        sum2 += a[m];
        sum3 -= a[m];
        if (r == m) {
            ++r;
            sum3 += a[r];
            sum4 -= a[r];
        }
        while (1) {
            ll dl = abs(sum2 - sum1);
            ll ndl = abs(sum1 + a[l + 1] - (sum2 - a[l + 1]));
            if (ndl < dl) {
                ++l;
                sum1 += a[l];
                sum2 -= a[l];
            } else {
                break;
            }
        }
        while (1) {
            ll dr = abs(sum3 - sum4);
            ll ndr = abs(sum3 + a[r + 1] - (sum4 - a[r + 1]));
