                ++r;
                sum3 += a[r];
                sum4 -= a[r];
            } else {
                break;
            }
            // cout << r << ' ' << sum3 << ' ' << sum4 << endl;
        }
        ll mx = max(max(sum1, sum2), max(sum3, sum4));
        ll mi = min(min(sum1, sum2), min(sum3, sum4));
        ans = min(ans, mx - mi);
    }
    cout << ans << endl;
    return 0;
}

