typedef long long ll;
const int N=2e5+100;
ll mm[N],L[N],R[N];

void go(int l,int r,ll &X,ll &Y){//intervalos cerrados
	ll here=L[r];
	if(l-1>=0)here-=L[l-1];
	ll mid=here/2;
	if(l-1>=0)mid+=L[l-1];
	int pos=lower_bound(L+l,L+r,mid)-L;
	assert(pos>=l&&pos<=r);
	X=L[pos];
	if(l-1>0)X-=L[l-1];
	Y=here-X;
	int Xaux=X-mm[pos],Yaux=Y+mm[pos];
	if(abs(Y-X)>abs(Xaux-Yaux)){
		X=Xaux,Y=Yaux;
	}

}

int main(){
	int n;cin>>n;
	for(int i=0;i<n;i++)cin>>mm[i];
	L[0]=mm[0];
	for(int i=1;i<n;i++)L[i]=mm[i]+L[i-1];
	R[n-1]=mm[n-1];
	for(int i=n-2;i>+0;i--)R[i]=mm[i]+R[i+1];
	int ans=INT_MAX;
	for(int i=1;i<n-2;i++){
		ll B,C,D,E;
		go(0,i,B,C);
		go(i+1,n-1,D,E);
		ll mx=max({B,C,D,E});
		ll mn=min({B,C,D,E});
		ans=min(ans,mx-mn);
	}
	cout<<ans<<endl;
	return 0;
}

