constexpr int MAXN = 2e5+42;

ll N, A[MAXN], P[MAXN];

ll calc(int m)
{
  int j=0;
  for(int i=1; i<m; i++)
  {
    if(abs(P[m]/2 - P[i]) < abs(P[m]/2 - P[j]))
      j = i;
  }
  int k=m+1;
  for(int i=m+2; i<N; i++)
  {
    if(abs((P[N-1]-P[m])/2 - (P[i]-P[m])) < abs((P[N-1]-P[m])/2 - (P[k]-P[m])))
      k = i;
  }
  ll s1 = P[j];
  ll s2 = P[m]-P[j];
  ll s3 = P[k]-P[m];
  ll s4 = P[N-1]-P[k];
  vector<ll> s{s1,s2,s3,s4};
  sort(s.begin(),s.end());
  return s[3]-s[0];
}

int main()
{
  read(N);
  for(int i=0; i<N; i++)
    read(A[i]);
  partial_sum(A,A+N,P);
  int l=1, r=N-3;
  while(r - l > 16)
  {
    int m = (r-l)/3;
    if(calc(l+m) < calc(r-m))
      r -= m;
    else
      l += m;
  }
  ll res = LINF;
  for(int i=l; i<=r; i++)
    res = min(res,calc(i));
  print(res);
  return 0;
}

