int main() {
    ll n;
    std::cin >> n;
    vector<ll> a(n);
    vector<ll> sum(n+1);
    ll res = 1e18;
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
        sum[i+1] = sum[i] + a[i];
    }
    // どこで切りましょうかね〜
    for (int i = 1; i < n-2; i++) {
        ll lmin,lmax;
        ll lsum = sum[i+1];
        ll rsum = sum[n]-sum[i+1];
        // inまで含む
        auto in = distance(sum.begin(), lower_bound(sum.begin()+1,sum.begin()+i-1,lsum/2));
        // inかin--
        // まずin
        lmin = min(lsum-sum[in+1],sum[in+1]);
        lmax = max(lsum-sum[in+1],sum[in+1]);
        ll ldif = lmax -lmin;
        if(in!=1 && ldif > max(lsum-sum[in],sum[in])-min(lsum-sum[in],sum[in]) ){
            lmin = min(lsum-sum[in],sum[in]);
            lmax = max(lsum-sum[in],sum[in]);
        }
        ll rmin,rmax;
        // inまで含む,iより大きい。
        in = distance(sum.begin(), lower_bound(sum.begin()+i+1,sum.end()-1,lsum+rsum/2));
        rmin = min(sum[n]-sum[in+1],sum[in+1]-lsum);
        rmax = max(sum[n]-sum[in+1],sum[in+1]-lsum);
        ll rdif = rmax-rmin;
        if(in-1!=i && rdif > max(sum[n]-sum[in],sum[in]-lsum)-min(sum[n]-sum[in],sum[in]-lsum)){
            rmin = min(sum[n]-sum[in],sum[in]-lsum);
            rmax = max(sum[n]-sum[in],sum[in]-lsum);
        }
        // std::cout << lmin<<" "<<lmax <<" "<<rmin<<" "<<rmax << std::endl;
        res = min(res,max(rmax,lmax)-min(rmin,lmin));
    }
    std::cout << res << std::endl;
}

