	i64 A[200010];
	A[0] = 0;
	for (size_t i = 0; i < N; i++)
	{	
		int a;
		cin >> a;
		A[i + 1] = A[i] + a;
	}

	int i1 = 1;
	int i3 = 3;
	i64 ans = 1000000000000;

	for (size_t i = 2; i < (N - 1); i++)
	{
		i64 ans1 = 1000000000000;
		i64 a1;
		i64 a2;
		for (; i1 < i; i1++)
		{
			i64 at = abs((A[i] - A[i1]) - A[i1]);
			if (ans1 > at) {
				ans1 = min(ans1, at);
				a1 = A[i] - A[i1];
				a2 = A[i1];
			}
			else {
				break;
			}
		}
		i1--;

		i64 ans2 = 10000000000000;
		i64 a3;
		i64 a4;
		for (; i3 < N; i3++)
		{
			i64 at = abs((A[N] - A[i3]) - (A[i3] - A[i]));
			if (ans2 > at) {
				ans2 = min(at, ans2);
				a3 = A[N] - A[i3];
				a4 = A[i3] - A[i];
			}
			else {
				break;
			}
		}
		i3--;
		ans = min(ans, abs(max(a1, max(a2, max(a3, a4))) - min(a1, min(a2, min(a3, a4)))));
	}

