struct AccSum{
    vector<ll> Ac;
    ll L;
    AccSum(){}
    AccSum(vector<ll> &A){
        L = A.size();
        Ac.resize(L+1);
        FOR(i, 0, L){
            Ac[i+1] = Ac[i] + A[i];
        }
    }
    // sum of [a, b]
    ll sum(ll a, ll b){
        if(a<0) return -1;
        if(b>L-1) return -1;
        return Ac[b+1] - Ac[a];
    }
};

// [0, r]までの範囲で最適な分割をした場合の2つの和を返す
PII f(AccSum& Acc, ll r){
  ll sum = Acc.sum(0, r);
  auto it = lower_bound(ALL(Acc.Ac), sum/2);

  ll a = *it;
  ll b = sum-a;

  if(it!=Acc.Ac.begin()){
    it--;
    ll a2 = *it;
    ll b2 = sum-a2;
    if(abs(a2-b2)<abs(a-b)){
      a = a2;
      b = b2;      
      debug(sum, a, b);
    }
  }
  return MP(a,b);
}

