#define REP(var,n) for(int var=0;var<(n);var++)
#define REPP(var,n) for(int var=1;var<(n);var++)
#define ALL(c) (c).begin(),(c).end()

int main(){
    int N,i;
    cin >> N;

    ll a[N], sum[N];
    REP(i,N){
       cin >> a[i];
       if(i>0){
           sum[i] = sum[i-1]+a[i];
       }
       else{
           sum[0] = a[0];
       }
    }
    int j,k,l;
    int x=1;
    int y=0;
    int z=2;// 各切れ目を表す。

    vector<ll> result(4);
    vector<ll> value;
    for(x=1;x<N-2; x++){
        //左、右の総和を計算する
        ll leftsum = sum[x];
        ll rightsum = sum[N-1]-sum[x];

        for(j=y;j<=x;j++){
            //もし端っこまで行ったらその手前で切らないといけない
            if(j==x){
               y=x-1;
               break;
            }
            //全体の半分超えたところを覚えておく
            if(sum[j] > leftsum/2){
                y=j;
                break;
            }
        }
        for(k=z;k<N;k++){
            if(k==N-1){
                z=N-2;
                break;
            }

            if(sum[k]-sum[x] > rightsum/2){
                z=k;
                break;
            }
        }
        for(int j=y-1;j<=y;j++){
            if(j>=0){
                for(int k=z-1;k<=z;k++){
                    result[0] = sum[j];
                    result[1] = sum[x]-sum[j];
                    result[2] = sum[k]-sum[x];
                    result[3] = sum[N-1]-sum[k];                
                    sort(result.begin(), result.end());
                    value.push_back(result[3]-result[0]);                  
                }
            }
        }

    }
    sort(value.begin(), value.end());
    cout << value[0] << endl;
}

