    return 0 < sp1 && sp1 < sp2 && sp2 < sp3 && sp3 < N;
  };
  while(max({sp1, sp2, sp3}) < N){
    while(P() < Q() && sp1 < sp2){
      sp1++;
      // cout << sp1 << sp2 << sp3 << endl;
    }
    while(R() < S() && sp3 < N){
      sp3++;
      // cout << sp1 << sp2 << sp3 << endl;
    }
    sp1--;
    if(rule()) write();
    sp3--;
    if(rule()) write();
    sp1++;
    if(rule()) write();
    sp3++;
    if(rule()) write();
    if(sp1 > 0) sp1--;
    sp3--;
    sp2++;
  }
  cout << ans << rt;
}

