#define ll long long
using namespace std;

int N,A[200001];
ll S[2000002],ans=LLONG_MAX;

int can(ll high) {
    vector<ll> nums;
    int idx=0,before=0;
    // cout<<"high = " <<high<<endl;
    REP(i,1,N+2){
        if(S[i] - S[before] > high) {
            nums.push_back(S[i-1]-S[before]);
            before=i-1;
        }
    }
    if(before!=N){
        nums.push_back(S[N+1]-S[before]);
    }
    // cout<<"idx = " << idx << endl;
    if (nums.size() < 4)return -1;
    else if (nums.size() > 4) return 1;
    ll mi=LLONG_MAX,ma=-1;
    // REP(i,0,nums.size()){
    //     cout<<nums[i]<<" ";
    // }
    // cout<<endl;
    REP(i,0,4){
        mi=min(mi,nums[i]);
        ma=max(ma,nums[i]);
    }
    // cout<<endl;
    // cout<<"ans = " << (ma-mi)<<endl;
    ans = min(ans, (ma-mi));
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin>>N;
    S[0]=0;
    REP(i,0,N){
        cin>>A[i];
        S[i+1] = S[i]+A[i];
    }
    S[N+1]=S[N];

    ll lo = 0, hi = S[N];
    while (lo < hi) {
        ll mid = (lo + hi) / 2;
        ll res = can(mid);
        if (res<0) {
            hi = mid-1;
        } else if (res > 0) lo = mid+1;
        else if (res == 0) {
            hi = mid-1;
        }
    }
    cout << ans;
    return 0;
}
