typedef long long ll;

vector<ll> v(200005),w(200005);

int ft(ll l, ll r, ll &m, vector<ll> &vctr){
  ll x = w[m-1] - w[l-1];
  ll y = w[r-1] - w[m-1];

  ll d = abs(x-y);

  while((x<y) && (m<r-1)){
    ++m;
    x += v[m-2];
    y -= v[m-2];

    if(d >= abs(x-y)){
      d = abs(x-y);
      continue;
    }else{
      x -= v[m-2];
      y += v[m-2];
      --m;
      break;
    }
  }

  vctr[0] = max(x,y);
  vctr[1] = min(x,y);
  return 0;
}


int main(){
  ll n;
