vector<vector<long long int>> f(int b, int e, const vector<long long int>& v, const vector<long long int>& pre) {
	vector<vector<long long int>> res;
	long long int s = pre[e];
	if (b > 0) s -= pre[b - 1];
	int bb = b, ee = e;
	while (b < e) {
		int m = (b + e) / 2;
		long long int c1 = pre[m];
		if (bb > 0) c1 -= pre[bb - 1];
		long long int c2 = s - c1;
		if (c1 < c2) {
			b = m + 1;
		} else {
			e = m;
		}
	}
	if (b == ee) {
		res.push_back({min(v[e], s - v[e]), max(v[e], s - v[e])});
		return res;
	}
	long long int s1 = pre[e];
	if (bb > 0) s1 -= pre[bb - 1];
	res.push_back({min(s1, s - s1), max(s1, s - s1)});
	if (e > bb) {
		s1 -= v[e];
		res.push_back({min(s1, s - s1), max(s1, s - s1)});
	}
	return res;
}

int main() {
    int n;
    cin >> n;
    vector<long long int> v(n, 0);
    vector<long long int> pre(n, 0);
    long long int c = 0;
    for (int i = 0; i < n; i++) {
    	cin >> v[i];
    	c += v[i];
    	pre[i] = c;
    }
    long long int res = 0x3f3f3f3f;
    for (int i = 1; i < n - 2; i++) {
    	vector<vector<long long int>> ret1 = f(0, i, v, pre), ret2 = f(i + 1, n - 1, v, pre);
    	for (int j = 0; j < ret1.size(); j++) {
    		for (int k = 0; k < ret2.size(); k++) {
    			res = min(res, max(ret1[j][1], ret2[k][1]) - min(ret1[j][0], ret2[k][0]));
    		}
    	}
    }
    cout << res << endl;
}

