using namespace std;

long long sum(int start, int end,vector<long long> A) {
	long long total=0;
	for (int i = start;i < end;i++) {
		total += A[i];
	}
	return total;
}

int find_position(int start,int end,vector<long long> A) {
	int slash = start + 1;
	long long difference = abs(sum(start, slash, A) - sum(slash, end, A));
	//cout << difference << endl;
	while (difference >= abs(sum(start, slash, A) - sum(slash, end, A))) {
		difference = abs(sum(start, slash, A) - sum(slash, end, A));
		slash++;
	}
	slash--;
	//cout << slash << endl;
	return slash;
}

int main() {
	long long ans;

	int N;
	cin >> N;
	vector<long long> A(N);
	for (int i = 0;i < N;i++) {
		cin >> A[i];
	}

	for (int middle = 2;middle <= N - 2;middle++) {
		int left = find_position(0, middle, A);
		int right = find_position(middle, N, A);
		long long P = sum(0, left, A);
		long long Q = sum(left, middle, A);
		long long R = sum(middle, right, A);
		long long S = sum(right, N, A);
		//cout << P << Q << R << S << endl;

		vector<long long> P_Q_R_S(4);
		P_Q_R_S[0] = P;
		P_Q_R_S[1] = Q;
		P_Q_R_S[2] = R;
		P_Q_R_S[3] = S;

		if (middle == 2) {
			ans = *max_element(P_Q_R_S.begin(), P_Q_R_S.end()) - *min_element(P_Q_R_S.begin(), P_Q_R_S.end());
		}
		else if (ans > *max_element(P_Q_R_S.begin(), P_Q_R_S.end()) - *min_element(P_Q_R_S.begin(), P_Q_R_S.end())) {
			ans = *max_element(P_Q_R_S.begin(), P_Q_R_S.end()) - *min_element(P_Q_R_S.begin(), P_Q_R_S.end());
		}
	}

	cout << ans << endl;

	return 0;
}

