ll calc(ll left, ll right, bool isLeft) {
  ll low = left, high = right;
  while (high - low > 1) {
    ll mid = (high + low) / 2;
    if (sum[mid] - (isLeft ? 0 : sum[left-1]) >= sum[right] - sum[mid-1]) {
      high = mid;
    } else {
      low = mid;
    }
  }
  return low;
}

void solve() {
  sum.push_back(a[0]);
  for (ll i=1;i<n;i++) {
    sum.push_back(a[i] + sum[i-1]);
  }
  ll minDiff = INF;
  for (ll i=1;i<n-2;i++) {
    ll leftMid = calc(0, i, true);
    ll rightMid = calc(i+1, n-1, false);
    ll maxSum = max(sum[leftMid], max(sum[i] - sum[leftMid], max(sum[rightMid] - sum[i], sum[n-1] - sum[rightMid])));
    ll minSum = min(sum[leftMid], min(sum[i] - sum[leftMid], min(sum[rightMid] - sum[i], sum[n-1] - sum[rightMid])));
    minDiff = min(minDiff, maxSum - minSum);
  }
  cout << minDiff << endl;
}

