        cin >> a[i];
    }

    // cumulative sum
    for(int i=1; i<n; i++){
        a[i] += a[i-1];
    }

    int c, l, r;
    vector<int> left(n-2), right(n-2);// arg c = center-cut position (1 ~ n-3)
    left[1] = 0;// o|o|oooo...
    right[n-3] = n-2;// n >= 4

    // left
    c = 2;
    l = 0;
    while(1){
        // for fixed c, move l
        while(abs( (a[c] - a[l])   - a[l]   ) 
           >  abs( (a[c] - a[l+1]) - a[l+1] )
           && l < c - 1
        ){
            l += 1;
        }

        // left[c] deterined, move on to next c
        left[c] = l;
        if(c < n - 3) c += 1;
        else break;
    }

    // right
    c = 1;
    r = 2;
    while(1){
        // for fixed c, move r
        while(abs( (a[n-1] - a[r]  ) - (a[r]   - a[c]))
           >  abs( (a[n-1] - a[r+1]) - (a[r+1] - a[c]))
           && r < n - 2
        ){
            r += 1;
        }

        // right[c] determined, move on to next c
        right[c] = r;
        //cout << c << " " << r << endl;
        if(c < r - 1) c += 1;
        else if(r < n - 2){
            c += 1;
            r += 1;
        }
        else break;
    }

    long long int ans = INF;
    for(int ci=1; ci<=n-3; ci++){// center

        //cout << a[left[ci]] << " " 
        //     << a[ci] - a[left[ci]] << " "
        //     << a[right[ci]]- a[ci] << " "
        //     << a[n-1]- a[right[ci]] << endl;

        long long int diff
        = abs(
          max({ a[left[ci]], a[ci] - a[left[ci]], a[right[ci]]- a[ci], a[n-1]- a[right[ci]] })
        - min({ a[left[ci]], a[ci] - a[left[ci]], a[right[ci]]- a[ci], a[n-1]- a[right[ci]] })
        );
        if(diff < ans) ans = diff;
    }
    cout << ans << endl;

    return 0;
}

