}

#include<bits/stdc++.h>
using namespace std;

const int64_t INF = 1e18;

int64_t calc(int64_t b, int64_t c, int64_t d, int64_t e){
  int64_t ret = max({b,c,d,e}) - min({b,c,d,e});
  if(b == 0 || c == 0 || d == 0 || e == 0){
    ret = INF;
  }
  return ret;
}


int main(){
  int N;
  cin >> N;
  vector<int64_t> vec(N);
  for(int i=0; i<N; i++){
    cin >> vec[i];
  }

  int64_t ans = INF;

  vector<int64_t> sum(N);
  for(int i=0; i<N; i++){
    if(i == 0){
      sum[i] = vec[i];
    }
    else{
      sum[i] = sum[i-1] + vec[i];
    }
  }

  vector<int64_t>::iterator pos;
  for(int i=1; i<N-2; i++){ //どこの右側に仕切りを入れるか？
    int64_t B, C, D, E, idx1, idx2;
    //左側
    int64_t L = sum[i]/2;
    pos = lower_bound(sum.begin(),sum.end(),L);
    idx1 = distance(sum.begin(),pos);
    //右側
    int64_t R = (sum[N-1] - sum[i])/2;
    pos = lower_bound(sum.begin(),sum.end(),R + sum[i]);
    idx2 = distance(sum.begin(),pos);

    //0にならなければいい、パターン列挙
    B = sum[idx1];
    C = sum[i] - sum[idx1];
    D = sum[idx2] - sum[i];
    E = sum[N-1] - sum[idx2];
    ans = min(ans,calc(B,C,D,E));

    B = sum[idx1-1];
    C = sum[i] - sum[idx1-1];
    D = sum[idx2] - sum[i];
    E = sum[N-1] - sum[idx2];
    ans = min(ans,calc(B,C,D,E));

    B = sum[idx1-1];
    C = sum[i] - sum[idx1-1];
    D = sum[idx2-1] - sum[i];
    E = sum[N-1] - sum[idx2-1];
    ans = min(ans,calc(B,C,D,E));

    B = sum[idx1];
    C = sum[i] - sum[idx1];
    D = sum[idx2-1] - sum[i];
    E = sum[N-1] - sum[idx2-1];
    ans = min(ans,calc(B,C,D,E));
  }
  cout << ans << endl;
}

