	int i;

	for(i=0;i<N;i++){
		scanf(" %lld",&A[i]);
	}

	for(i=1;i<N;i++){
		A[i]+=A[i-1];
	}

	ll ans=1ll<<60;

	for(i=1;i<=N-3;i++){

		ll sum_l=A[i];
		ll sum_r=A[N-1]-A[i];

		int l,r,mid;

		l=1;
		r=i;

		while(l<=r){
			mid=(l+r)/2;
			if(A[mid]>sum_l-A[mid]){
				r=mid-1;
			}
			else{
				l=mid+1;
			}
		}
		ll s11,s12,s21,s22;

		s11=llabs(A[mid-1]-(sum_l-A[mid-1]));
		s12=llabs(A[mid]-(sum_l-A[mid]));

		ll ma;
		ll mi;

		if(s11<s12){
			ma=max(A[mid-1],sum_l-A[mid-1]);
			mi=min(A[mid-1],sum_l-A[mid-1]);
		}
		else{
			ma=max(A[mid],sum_l-A[mid]);
			mi=min(A[mid],sum_l-A[mid]);
		}

		l=i+1;
		r=N;

		while(l<=r){
			mid=(l+r)/2;
			if(A[mid]-A[i]>sum_r-(A[mid]-A[i])){
				r=mid-1;
			}
			else{
				l=mid+1;
			}
		}

		s21=llabs(A[mid-1]-A[i]-(sum_r-(A[mid-1]-A[i])));
		s22=llabs(A[mid]-A[i]-(sum_r-(A[mid]-A[i])));

		if(s21<s22){
			ma=max(ma,max(A[mid-1]-A[i],sum_r-(A[mid-1]-A[i])));
			mi=min(mi,min(A[mid-1]-A[i],sum_r-(A[mid-1]-A[i])));
		}
		else{
			ma=max(ma,max(A[mid]-A[i],sum_r-(A[mid]-A[i])));
			mi=min(mi,min(A[mid]-A[i],sum_r-(A[mid]-A[i])));
		}
		if(ans>ma-mi){ans=ma-mi;}
	}

	printf("%lld\n",ans);

	return 0;
}

