		cout << max({a[0],a[1],a[2],a[3]}) - min({a[0],a[1],a[2],a[3]}) << endl;
		return 0;
	}

	vector<ll> sum(n);
	sum[0] = a[0];
	rep(i,n-1) sum[i+1] = sum[i] + a[i+1];

	ll P,Q,R,S;
