	ll res = 1e18;

	while(mid < n-3){

		while(l < mid-1){
			ll prev = abs(sum[mid]-2*sum[l]);
			ll next = abs(sum[mid]-2*sum[l+1]);
			if(prev > next) l++;
			else break;
		}

		while(r < n-2){
			ll prev = abs(sum[n-1]-2*sum[r]+sum[mid]);
			ll next = abs(sum[n-1]-2*sum[r+1]+sum[mid]);
			if(prev > next) r++;
			else break;
		}

		P = sum[l];
		Q = sum[mid] - sum[l];
		R = sum[r] - sum[mid];
		S = sum[n-1] - sum[r];

		res = min(res, max({P,Q,R,S}) - min({P,Q,R,S}));
