int main() {
  ll n;
  cin >> n;
  vector<ll> v(n), sum(n + 1);  // 半開区間の累積和
  for (int i = 0; i < n; i++) cin >> v[i];
  for (int i = 0; i < n; i++) sum[i + 1] = sum[i] + v[i];

  // cout << sum << endl;

  ll ans = INFL;
  for (int i = 2; i <= n - 2; i++) {      // iは全ての真ん中の位置(半開区間的)
    vector<ll> res = {0, INFL, 0, INFL};  // 4つに区切った時のそれぞれの総和を突っ込むvector
    ll left, right;

    // 左側が真に小さくなるギリギリ
    left = 0, right = i;
    while (right - left > 1) {
      ll mid = (left + right) / 2;
      if (sum[mid] < sum[i] - sum[mid])
        left = mid;
      else
        right = mid;
    }

    // 端だった時の場合分けをして、2パターンを整理
    if (0 < left) res[0] = sum[left], res[1] = sum[i] - sum[left];
    if (right < i) {
      if (abs(res[1] - res[0]) > abs(sum[i] - 2 * sum[right]))
        res[0] = sum[right], res[1] = sum[i] - sum[right];
    }

    // ＝＝＝＝＝＝＝＝＝＝＝ 右側 ＝＝＝＝＝＝＝＝＝＝＝＝
    left = i, right = n;
    while (right - left > 1) {
      ll mid = (left + right) / 2;
      if (sum[mid] - sum[i] < sum[n] - sum[mid])
        left = mid;
      else
        right = mid;
    }

    // 端だった時の場合分けをして、2パターンを整理
    if (i < left) res[2] = sum[left] - sum[i], res[3] = sum[n] - sum[left];
    if (right < n) {
      if (abs(res[3] - res[2]) > abs(sum[n] - 2 * sum[right] + sum[i]))
        res[2] = sum[right] - sum[i], res[3] = sum[n] - sum[right];
    }

    // cout << left << " " << right << res << endl;

    ans = min(ans, *max_element(res.begin(), res.end()) - *min_element(res.begin(), res.end()));
  }
  cout << ans << endl;
}

