void solve() {
    int N; cin >> N;
    vector<ll> A(N), sum(N + 1);
    ll ans = INF;
    sum[0] = 0;
    rep(i, N) {
        cin >> A[i];
        sum[i + 1] = sum[i] + A[i];
    }
    for(int i = 2; i <= N - 2; i++) {
        int j = lower_bound(sum.begin(), sum.end(), sum[i] / 2) - sum.begin();
        int k = lower_bound(sum.begin(), sum.end(), sum[i] + (sum[N] - sum[i] / 2)) - sum.begin();
        ll P1 = sum[j], Q1 = sum[i] - sum[j];
        ll P2 = sum[j + 1], Q2 = sum[i] - sum[j + 1];
        ll R1 = sum[k] - sum[i], S1 = sum[N] - sum[k];
        ll R2 = sum[k + 1] - sum[i], S2 = sum[N] - sum[k + 1];
        ll P, Q, R, S;
        if(abs(P1 - Q1) < abs(P2 - Q2) || j + 1 >= i) {
            P = P1; Q = Q1;
        } else {
            P = P2; Q = Q2;
        }
        if(abs(R1 - S1) < abs(R2 - S2) || k + 1 >= N) {
            R = R1; S = S1;
        } else {
            R = R2; S = S2;
        }
        ll ret = min({abs(P - Q), abs(P - R), abs(P - S), abs(Q - R), abs(Q - S), abs(R - S)});
        ans = min(ans, ret);
    }
    cout << ans << endl;
}

