            c1 = i-1;
        }else{
            ll ok = i-1;
            ll ng = 0;
            while(abs(ok-ng)>1){
                ll mid = (ok+ng)/2;
                if(sum[mid+1]>=sum[i+1]-sum[mid+1]){
                    ok = mid;
                }else{
                    ng = mid;
                }
            }
            c1 = ok;
            if(abs(sum[i+1]-sum[c1+1]-sum[c1+1])>abs(sum[i+1]-sum[c1]-sum[c1])){
                c1--;
            }
        }
        if(a[i+1]>=sum[n]-sum[i+2]){
            c3 = i+1;
        }else if(a[n-1]>=sum[n-1]-sum[i+1]){
            c3 = n-2;
        }else{
            ll ok = n-2;
            ll ng = i+1;
            while(abs(ok-ng)>1){
                ll mid = (ok+ng)/2;
                if(sum[mid+1]-sum[i+1]>=sum[n]-sum[mid+1]){
                    ok = mid;
                }else{
                    ng = mid;
                }
