            if(abs(sum[n]-sum[c3+1]-(sum[c3+1]-sum[i+1]))>abs(sum[n]-sum[c3]-(sum[c3]-sum[i+1]))){
                c3--;
            }
        }
        ll mx = max({sum[c1+1], sum[c2+1]-sum[c1+1], sum[c3+1]-sum[c2+1], sum[n]-sum[c3+1]});
        ll mn = min({sum[c1+1], sum[c2+1]-sum[c1+1], sum[c3+1]-sum[c2+1], sum[n]-sum[c3+1]});
