using ll = long long;
using P = pair<ll, ll>;

template <class Iterator>
P f(Iterator first, Iterator last) {
    ll S = *(last - 1) - *first;
    auto ub = upper_bound(first + 1, last, *first + S / 2);
    int n = distance(first, last) - 1;
    int i1 = distance(first, ub);
    int j1 = n - i1;
    int i0 = i1 - 1;
    int j0 = j1 + 1;
    ll Si1, Si0, Sj1, Sj0;
    if (i1 >= 1 && j1 >= 1) {
        Si1 = *(first + i1) - *first;
        Sj1 = S - Si1;
    } else {
        Si1 = LLONG_MAX;
        Sj1 = LLONG_MIN;
    }
    if (i0 >= 1 && j0 >= 1) {
        Si0 = *(first + i0) - *first;
        Sj0 = S - Si0;
    } else {
        Si0 = LLONG_MIN;
        Sj0 = LLONG_MAX;
    }
    return P(min(Si1, Sj0), max(Sj1, Si0));
}

