	while (l3 != r3) {
		int mid3 = (l3 + r3) / 2 + 1;
		if (A[mid3] - A[r2] <= A[N - 1] - A[mid3]) l3 = mid3;
		else r3 = mid3 - 1;
	}
	if (abs(2 * A[r3] - A[r2] - A[N - 1]) > abs(2 * A[r3 + 1] - A[r2] - A[N - 1])) r3++;
	long long minimum = 1e18;
