	minimum = min(minimum, A[r1]);
	minimum = min(minimum, A[r2] - A[r1]);
	minimum = min(minimum, A[r3] - A[r2]);
	minimum = min(minimum, A[N - 1] - A[r3]);
	maximum = max(maximum, A[r1]);
	maximum = max(maximum, A[r2] - A[r1]);
	maximum = max(maximum, A[r3] - A[r2]);
	maximum = max(maximum, A[N - 1] - A[r3]);
	kotae = min(kotae, maximum - minimum);
	cout << kotae << "\n";
