    vector<ll> dp(n + 1);
    rep(i, n)
    {
        cin >> dp[i + 1];
        dp[i + 1] += dp[i];
    }
    ll ans = 1e18;
    for (int i = 0; i <= n; i++)
    {
        auto first = lower_bound(dp.begin(), dp.begin() + i, dp[i - 1] / 2) - dp.begin();
        auto second = lower_bound(dp.begin() + i, dp.end(), (dp[n]+dp[i] )/ 2) - dp.begin();
        // 近傍探索して
        for (int j = -2; j <= 2; j += 1)
        {
            if (first + j >= i || first + j <= 0)
            {
                continue;
            }
            for (int k = -2; k <= 2; k += 1)
            {
                if (second + k >= n || second + j <= i)
                {
                    continue;
                }
                ll mx = 0;
                ll mn = 1e18;
                mx = max(dp[i] - dp[first + j], mx);
