int main()
{
    int N; cin >> N;
    vector<ll> A(N); for (auto& e : A) cin >> e;

    vector<ll> s(N);
    partial_sum(A.begin(), A.end(), s.begin());

    ll ans = LLONG_MAX;
    for (int c = 2; c <= N-2; c++) {
        auto it_l = upper_bound(s.begin(), s.begin() + c, s[c-1]/2);
        int l = max(1, (int)distance(s.begin(), it_l));
        if (l + 1 != c) {
            ll d1 = abs(s[c-1] - s[l-1] - s[l-1]);
            ll d2 = abs(s[c-1] - s[l] - s[l]);
            if (d2 < d1) l++;
        }

        auto it_r = upper_bound(s.begin() + c, s.end(), (s[c-1]+s.back())/2);
        int r = max(c+1, (int)distance(s.begin(), it_r));
        if (r + 1 != N) {
            ll d1 = abs((s[r-1] - s[c-1]) - (s.back() - s[r-1]));
            ll d2 = abs((s[r  ] - s[c-1]) - (s.back() - s[r]));
            if (d2 < d1) r++;
        }
        vector<ll> pqrs(4);
        pqrs[0] = s[l-1];
        pqrs[1] = s[c-1]   - s[l-1];
        pqrs[2] = s[r-1]   - s[c-1];
        pqrs[3] = s.back() - s[r-1];

        ll a = *max_element(pqrs.begin(), pqrs.end()) - *min_element(pqrs.begin(), pqrs.end());
        ans = min(ans, a);
    }

    cout << ans << endl;
}

