P bino(vector<ll> array, ll s, ll e){
  ll a = s;
  ll b = e;
  ll base = s == 0 ? 0 : array[s-1];
  if (e - s == 1) {
    return P(array[s] - base, array[e] - array[s]);
  }
  while(b - a > 1){
    ll i = (a + b) / 2;
    ll tmp = array[e] - 2 * array[i] + base;
    if (tmp >= 0){
      a = i;
    }else{
      b = i;
    }
  }

  if (abs(array[e] - 2 * array[a] + base) < abs(array[e] - 2 * array[b] + base)){
    return P(array[a] - base, array[e] - array[a]);
  }else{
    return P(array[b] - base, array[e] - array[b]);
  }
}

