    tmp[0] = p.first;
    tmp[1] = p.second;
    tmp[2] = q.first;
    tmp[3] = q.second;
    sort(tmp.begin(), tmp.end());
    ans = min(ans, tmp[3] - tmp[0]);

  }
  cout << ans << endl;


  return 0;
}

