int main() {
	ll N; 
	cin >> N;
	vector<ll> a(N);
	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}

	vector<ll> al(N, 0);
	al[0] = a[0];
	for (int i = 1; i < N; i++) {
		al[i] += al[i - 1] + a[i];
	}
	vector<ll> ar(N, 0);
	ar[0] = a[N - 1];
	for (int i = 1; i < N; i++) {
		ar[i] += ar[i - 1] + a[N - 1 - i];
	}

	ll res = 1e15;
	for (int i = 2; i <= N - 2; i++) {
		auto mid1 = lower_bound(al.begin(), al.end(), al[i - 1] / 2);
		int it1 = (mid1 - al.begin());
		ll P = al[it1], Q = al[i - 1] - P;
		ll tp = al[it1 - 1], tq = al[i - 1] - tp;
		if (abs(P - Q) > abs(tp - tq)) {
			P = tp;
			Q = tq;
		}

		auto mid2 = lower_bound(ar.begin(), ar.end(), ar[N - 1 - i] / 2);
		int it2 = (mid2 - ar.begin());
		ll S = ar[it2], R = ar[N - 1 - i] - S;
		ll ts = ar[it2 - 1], tr = ar[N - 1 - i] - ts;
		if (abs(R - S) > abs(tr - ts)) {
			R = tr;
			S = ts;
		}

		ll max_num = max(P, max(Q, max(R, S)));
		ll min_num = min(P, min(Q, min(R, S)));
		res = min(res, abs(max_num - min_num));
	}

