#define FOR(i,a,b) for (int i = a; i < b; ++i)
#define REP(i,n) FOR(i,0,n)

uint N;
ll A[200001];

void getLeftPos(uint& l, uint& c) {
  ll cval = A[c];
  ll pre_diff = abs((A[l - 1] - 0) - (cval - A[l - 1]));
  ll lsum, rsum;

  while(l < c) {
    lsum = A[l] - 0;
    rsum = cval - A[l];

    if (lsum - rsum > 0) {
      if (pre_diff < abs(lsum - rsum)) --l;
      return;
    }

    ++l;
    pre_diff = abs(lsum - rsum);
  }

  --l;
  return;
}

void getRightPos(uint& r, uint& c) {
  ll cval = A[c];
  ll eval = A[N];
  ll pre_diff = abs((A[r - 1] - cval) - (eval - A[r - 1]));
  ll lsum, rsum;

  while(r < N) {
    lsum = A[r] - cval;
    rsum = eval - A[r];

    if (lsum - rsum > 0) {
      if (pre_diff < abs(lsum - rsum)) --r;
      return;
    }
    ++r;
    pre_diff = abs(lsum - rsum);
  }

  --r;
  return;
}

ll getVal(uint l, uint c, uint r) {
  vector<ll> sum(4);
  sum[0] = A[l] - 0;
  sum[1] = A[c] - A[l];
  sum[2] = A[r] - A[c];
  sum[3] = A[N] - A[r];

  ll maxval = *max_element(sum.begin(), sum.end());
  ll minval = *min_element(sum.begin(), sum.end());

  return maxval - minval;
}

int main() {
  uint N;
  scanf("%u", &N);

  A[0] = 0;
  REP(i,N) {
    scanf("%d", &A[i+1]);
    A[i+1] += A[i];
  }

  ll minval = numeric_limits<ll>::max();
  uint l = 1, r = 3;
  for (uint c = 2; c <= N - 2; ++c) {
    if (r <= c) r = c + 1;

    getLeftPos(l, c);
    getRightPos(r, c);

    ll val = getVal(l, c, r);
    if (val < minval) minval = val;
  }

  printf("%lld\n", minval);
  return 0;
}

