tuple<int64, int64> split2two(const vector<int64>& vSum, const int* vA, const int N){
    int64 sum=vSum[N-1];

    int64 min=INT64_MAX;
    uint minIdxL=0;
    for(int i=0; i<N-1; ++i){
        int64 diff = abs(vSum[i]-(sum-vSum[i]));
        if(diff<min){
            min = diff;
            minIdxL = i;
        }
    }

    int64 sumL = accumulate(&vA[0], &vA[minIdxL+1], 0ll);
    int64 sumR = accumulate(&vA[minIdxL+1], &vA[N], 0ll);
    return tie(sumL, sumR);
}

