int main() {
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N;cin >> N;
    vector<long long> retu(N);
    for(int i = 0;i<N;i++) cin >> retu.at(i);
    vector<long long> rui(N+1);
    for(int i = 0;i<N;i++){
        rui.at(i+1) = rui.at(i)+retu.at(i);
    }
    //中央切りを全探索
    long long ans = INF;
    for(int i = 0;i<=N;i++){
        //左側
        int left = 0,right = i;
        while(right - left > 1){
            int mid = (left+right)/2;
            if(rui.at(mid) < rui.at(i)-rui.at(mid)){
                left = mid;
            }
            else{
                right = mid;
            }
        }
        long long P = rui.at(left);long long Q = rui.at(i)-rui.at(left);
        //一応left,rightの両方見ておく
        long long P2 = rui.at(right);long long Q2 = rui.at(i)-rui.at(right);
        long long LEFT_MAX = -INF,LEFT_MIN = INF;
        if(abs(P-Q) > abs(P2-Q2)){
            LEFT_MAX = max(P2,Q2);
            LEFT_MIN = min(P2,Q2);
        }
        else{
            LEFT_MAX = max(P,Q);
            LEFT_MIN = min(P,Q);
        }
        //右側
        left = i,right = N;
        while(right - left > 1){
            int mid = (left+right)/2;
            if(rui.at(mid)-rui.at(i) < rui.at(N)-rui.at(mid)){
                left = mid;
            }
            else{
                right = mid;
            }
        }
        long long R = rui.at(left)-rui.at(i);long long S = rui.at(N)-rui.at(left);
        long long R2 = rui.at(right)-rui.at(i);long long S2 = rui.at(N)-rui.at(right);
        long long RIGHT_MAX = -INF,RIGHT_MIN = INF;
        if(abs(R-S) > abs(R2-S2)){
            RIGHT_MAX = max(R2,S2);
            RIGHT_MIN = min(R2,S2);
        }
        else{
            RIGHT_MAX = max(R,S);
            RIGHT_MIN = min(R,S);
        }
        ans = min(ans,max(LEFT_MAX,RIGHT_MAX) - min(LEFT_MIN,RIGHT_MIN));
    }
    cout << ans << endl;
}

