int     Pos(long AA, vector<long> &A) {
        int a=0;
        int b=A.size()-1;
        while (1<b-a) {
                int c=(a+b)/2;
                if (AA>=A.at(c))
                        a=c;
                else b=c;
        }
        return a;
}

int     Mid(int a, int b, vector<long> &A) {
        long T=(A.at(a)+A.at(b))/2;
        return Pos(T, A);
}

