#define ll long long

int main () {
  ll n;
  cin >> n;
  ll a[n + 1], sum[n + 1];
  a[0] = 0;
  sum[0] = 0;
  for (ll i = 1; i <= n; i++) {
    cin >> a[i];
    sum[i] = sum[i - 1] + a[i];  
  }  
  ll min = -1;
  for (ll i = 2; i <= n - 2; i++) {
    // 1 ~ i番目と (i + 1)番目 ~ n番目
    // で2つの部分にとりあえず区切る

    // [1] 1 ~ i番目で
    ll center = sum[i] / 2;
    // centerを超えるときのiを求める
    ll left = 0;
    ll right = i + 1;
    while (left < right - 1) {
      ll mid = (left + right) / 2;
      if (sum[mid] > center) {
        right = mid;  
      }  
      else {
        left = mid;  
      }
    }  
    // rightの値の時に初めて越すのである。
    ll a[4] = {
      sum[right], sum[i] - sum[right],
      sum[right - 1], sum[i] - sum[right - 1]  
    };

    center = (sum[n] - sum[i]) / 2;
    left = i;
    right = n + 1;
    while (left < right - 1) {
      ll mid = (right + left) / 2;
      if ((sum[mid] - sum[i]) > center) {
        right = mid;  
      }  
      else {
        left = mid;  
      }
    }

    ll b[4] = {
      sum[right] - sum[i], sum[n] - sum[right],
      sum[right - 1] - sum[i], sum[n] - sum[right - 1]
    };
    ll ans[4];
    for (ll i = 0; i < 4; i++) {
      if (i % 2 == 0) {
        ans[0] = a[0];
        ans[1] = a[1];  
      }  
      else {
        ans[0] = a[2];
        ans[1] = a[3];  
      }
      if (i <= 1) {
        ans[2] = b[0];
        ans[3] = b[1];  
      }
      else {
        ans[2] = b[2];
        ans[3] = b[3];  
      }
      sort(ans, ans + 4);
      if (ans[0] != 0) {
        ll now = ans[3] - ans[0];
        if (min == -1 || min > now) {
          min = now;  
        }  
      }
    }
  }
  cout << min << endl;
}

