int main()
{
    ll n;
    cin >> n;
    vector<ll> a(n);
    for(ll i = 0; i < n; i++)cin >> a[i];
    vector<ll> sum(n + 1);
    for(ll i = 0; i < n; i++)sum[i + 1] = sum[i] + a[i];


    ll ans = 1e18;
    for(ll i = 2; i < n - 1; i++) {
        // i = n;
        ll a, b, c, d;

        {//front
            ll fsum = sum[i];
            auto kug = lower_bound(sum.begin(), sum.begin() + i, fsum / 2) - sum.begin();
            ll ta = sum[kug];
            ll tb = sum[i] - sum[kug];
            a = sum[kug + 1];
            b = sum[i] - sum[kug + 1];
            // cerr << a << " -- -" << b << endl;
            if(abs(ta - tb) < abs(a - b)) {
                a = ta, b = tb;
            }
            ta = sum[kug - 1];
            tb = sum[i] - sum[kug - 1];
            if(abs(ta - tb) < abs(a - b)) {
                a = ta, b = tb;
            }
        }

        {//back
            ll bsum = sum[n] - sum[i];
            auto kug = lower_bound(sum.begin() + i, sum.end(), bsum / 2 + sum[i]) - sum.begin();
            ll ta = sum[kug] - sum[i];
            ll tb = sum[n] - sum[kug];
            c = sum[kug + 1] - sum[i];
            d = sum[n] - sum[kug + 1];
            if(abs(ta - tb) < abs(c - d)) {
                c = ta, d = tb;
            }
            ta = sum[kug - 1] - sum[i];
            tb = sum[n] - sum[kug - 1];
            if(abs(ta - tb) < abs(c - d)) {
                c = ta, d = tb;
            }
        }
        // cerr << a << " - " << b << " - " << c << " - " << d << endl;
        ans = min(ans, max({a,b,c,d}) - min({a,b,c,d}));
        // cerr << a << " - " <<  b << endl;
    }
    cout << ans << endl;
}

