#define pb(a) push_back(a)
#define mp make_pair

int main(){
	CIN(n);
	VC1(n,a);
	V rui(n + 1, 0);
	REP(i,n)
		rui[i+1] = rui[i] + a[i];

	// [op,cl)を二等分した場合の差の計算を行う

	auto calc = [&](int op, int cl){
		ll sum = rui[cl] - rui[op];
		ll st = op;
		ll en = cl + 1;
		while(en-st>1){
			ll num = (st+en)/2;
			((rui[num] - rui[op] < sum / 2)?st:en) = num;
		}
		return mp(rui[en] - rui[op], rui[cl] - rui[en]);
	};
	auto calc2 = [&](int op, int cl){
		ll sum = rui[cl] - rui[op];
		ll st = op;
		ll en = cl + 1;
		while(en-st>1){
			ll num = (st+en)/2;
			((rui[num] - rui[op] < sum / 2)?st:en) = num;
		}
		return mp(rui[en - 1] - rui[op], rui[cl] - rui[en - 1]);
	};
	ll ans = LINF;
	FOR(i,2,n-1){
		P p1 = calc(0, i);
		P p2 = calc(i, n);
		P p3 = calc2(0, i);
		P p4 = calc2(i, n);
		ans = min(ans, max({p1.second, p2.second, p1.first, p2.first}) - min({p1.first, p2.first, p1.second, p2.second}));
		ans = min(ans, max({p1.second, p4.second, p1.first, p4.first}) - min({p1.first, p4.first, p1.second, p4.second}));
		ans = min(ans, max({p3.second, p4.second, p3.first, p4.first}) - min({p3.first, p4.first, p3.second, p4.second}));
		ans = min(ans, max({p3.second, p2.second, p3.first, p2.first}) - min({p3.first, p2.first, p3.second, p2.second}));
	}
	COUT(ans);
}

