    long long left_min = min(P, Q), left_max = max(P, Q);
    if (abs(P2 - Q2) < abs(P - Q)) left_min = min(P2, Q2), left_max = max(P2, Q2);

    // R < S となる最大の切れ目を求める
    low = i, high = N;
    while (high - low > 1) {
      int mid = (low + high) / 2;
      if (sum[mid] - sum[i] >= sum[N] - sum[mid])
        high = mid;
      else
