typedef long long ll;

class CumulativeSum {
  private:
    std::vector<long long> s;

  public:
    explicit CumulativeSum (int N) {
      s.resize(N+1);
    }

    // s0 = 0, s1 = a0, s2 = a0 + a1, ...
    void build ( const std::vector<long long> &a ) {
      s[0] = 0;
      for(int i=1; i<s.size(); i++) s[i] = s[i-1] + a[i-1];
    }

    // Get [ i, j )
    long long Get ( int i, int j ) {
      return s[j] - s[i];
    }
};


int main (void) {

  int N;  std::cin >> N;

  std::vector<long long> A(N);
  for(int i=0; i<N; i++) std::cin >> A[i];

  CumulativeSum s(N);
  s.build(A);

  ll ans = 1e15;
  int r = 1;
  int l = -1;
  for(int centre = 2; centre <= N-2; centre++) {
    ll Rmin = 1e15;
    int rnext = r;
    for(int rr = r; rr<centre; rr++) {
      ll RR = s.Get(0,rr);
      ll RL = s.Get(rr, centre);
      if ( Rmin >= std::abs(RR-RL) ) {
        Rmin = std::abs(RR-RL);
        rnext = rr;
        r = rnext;
        continue;
      }
      r = rnext;
      break;
    }

    if ( l <= centre ) l = centre+1;
    Rmin = 1e15;
    rnext = l;
    for(int rr = l; rr<N; rr++) {
      ll RR = s.Get(centre,rr);
      ll RL = s.Get(rr, N);
      if ( Rmin >= std::abs(RR-RL) ) {
        Rmin = std::abs(RR-RL);
        rnext = rr;
        l = rnext;
        continue;
      }
      l = rnext;
      break;
    }

    ans = std::min(ans, 
        std::abs( 
          std::max({s.Get(0,r),s.Get(r,centre), s.Get(centre,l), s.Get(l,N)}) - std::min({s.Get(0,r),s.Get(r,centre), s.Get(centre,l), s.Get(l,N)})
          ));
    /*
    for(int i=0; i<r; i++) std::cout << A[i] << " ";
    std::cout << " : ";
    for(int i=r; i<centre; i++) std::cout << A[i] << " ";
    std::cout << " ^ ";
    for(int i=centre; i<l; i++) std::cout << A[i] << " ";
    std::cout << " : ";
    for(int i=l; i<N; i++) std::cout << A[i] << " ";
    std::cout << std::endl;
    std::cout << "( " << s.Get(0,r) << " " << s.Get(r,centre) << " " << s.Get(centre,l) << " " <<  s.Get(l,N) << " ) " << std::endl;
    */
  }
  std::cout << ans << std::endl;

  return 0;
}

