			if(query(0,mid) <= s1/2) lo = mid;
			else hi = mid;
		}
		vector<ii> op1;
		for(int cut = lo-3; cut <= lo+3; ++cut){
			if(cut <= 0) continue;
			if(cut >= l) break;
			op1.pb( make_pair( query(0,cut), query(cut,l) ) );
		}
		lo = l, hi = n;
		while(hi - lo > 1){
			int mid = (lo + hi) / 2;
			if(query(l,mid) <= s2/2) lo = mid;
			else hi = mid;
		}
		vector<ii> op2;
		for(int cut = lo-3; cut <= lo+3; ++cut){
			if(cut <= l) continue;
			if(cut >= n) break;
			op2.pb( make_pair(query(l,cut), query(cut,n)) );
		}

		// test
		for(ii p1 : op1) for(ii p2 : op2){
			int mx = max({p1.first, p1.second, p2.first, p2.second});
			int mn = min({p1.first, p1.second, p2.first, p2.second});
			ans = min(ans, mx - mn);
		}
	}

	cout << ans << endl;

	return 0;
}

