  for (int i = 0; i < n; ++i) {
    int x;
    scanf("%d", &x);
    a[i + 1] = a[i] + x;
  }
  int64 ret = INF;
  vector<int64> A(4);
  for (int k = 2; k <= n - 2; ++k) {
    int64 L = a[k] - a[0];
    int u = lower_bound(a.begin(), a.begin() + k, L / 2) - a.begin();
    int64 best = INF;
    int best_u = -1;
    if (u > 0 && u < k) {
      if (best > abs((a[k] - a[u]) - a[u])) {
        best = abs((a[k] - a[u]) - a[u]);
        best_u = u;
      }
    }
    --u;
    if (u > 0 && u < k) {
      if (best > abs((a[k] - a[u]) - a[u])) {
        best = abs((a[k] - a[u]) - a[u]);
        best_u = u;
      }
    }
    int64 R = a[n] - a[k];
    int v = lower_bound(a.begin() + k, a.end(), R / 2 + a[k]) - a.begin();
    best = INF;
    int best_v = -1;
    if (v > k && v < n) {
      if (best > abs((a[n] - a[v]) - (a[v] - a[k]))) {
        best = abs((a[n] - a[v]) - (a[v] - a[k]));
        best_v = v;
      }
    }
    --v;
    if (v > k && v < n) {
      if (best > abs((a[n] - a[v]) - (a[v] - a[k]))) {
        best = abs((a[n] - a[v]) - (a[v] - a[k]));
        best_v = v;
      }
    }
    A[0] = a[best_u]; A[1] = a[k] - a[best_u];
    A[2] = a[best_v] - a[k]; A[3] = a[n] - a[best_v];
    sort(A.begin(), A.end());
    ret = min(ret, A.back() - *A.begin());
  }
  printf("%lld\n", ret);
  return 0;
}

