ll findMaximal1(ll from, ll to) {
	// d[i] = a[i] - a[i-1]とする。
	// このとき、d[i] > 0 <=> a[i] > a[i-1]なので、
	// d[i] > 0なる最大のi in (from, to)を見つけると、a[i]が最大値
	for (;to - from > 1;) {
		ll mid = (from + to) / 2;
		(unimodalFunc(from,to,mid) - unimodalFunc(from,to,mid - 1) < 0 ? from : to) = mid;
        //cout<<from<<" "<<to<<endl;
	}

    max1=fmaxl(s[ii]-s[from],s[from]-s[0]);
    min1=fminl(s[ii]-s[from],s[from]-s[0]);
	return from;
}

