        if (i > N - 1) continue;

        ll X = sum[i];
        int l = 0;
        int r = i + 1;
        while (r - l >= 1) {
            int mid = (r + l) / 2;
            if (2 * sum[mid] >= X) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        // r, r - 1が候補
        ll P, Q;
        ll p1 = sum[r]; ll q1 = X - p1;
        ll p2 = sum[r - 1]; ll q2 = X - p2;
        if (abs(q1 - p1) > abs(q2 - p2)) {
            P = p2; Q = q2;
        } else {
            P = p1; Q = q1;
        }

        ll Y = sum[N] - sum[i];
        l = i + 1;
        r = N + 1;
        while (r - l >= 1) {
            int mid = (r + l) / 2;
            if (2 * (sum[mid] - sum[i]) >= Y) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        ll R, S;
        ll r1 = sum[r] - sum[i]; ll s1 = Y - r1;
        ll r2 = sum[r - 1] - sum[i]; ll s2 = Y - r2;
        if (abs(s1 - r1) > abs(s2 - r2)) {
            R = r2; S = s2;
        } else {
            R = r1; S = s1;
        }

        ans = min(ans, max(P, max(Q, max(R, S))) - min(P, min(Q, min(R, S))));
    }

    cout << ans << endl;
}

