   for (int i = 1; i < N - 1; i++) {
      // cout << "-------" << endl;
      // cout << i << endl;
      decltype(v)::iterator it = lower_bound(v.begin(), v.begin() + i, S[i + 1] / 2);
      tmp1 = S[it - v.begin()];
      tmp2 = S[i + 1] - tmp1;
      if (it - v.begin() - 1 >= 0) {
         tmp3 = S[it - v.begin() - 1];
         tmp4 = S[i + 1] - tmp3;
         // cout << "------" << tmp3 << " " << tmp4 << endl;
         if (tmp3 != 0 && tmp4 != 0) {
            if (abs(tmp1 - tmp2) > abs(tmp3 - tmp4)) {
               tmp1 = tmp3;
               tmp2 = tmp4;
            }
         }
      }

      if (tmp1 == 0 || tmp2 == 0) continue;

      if (tmp1 > tmp2) {
         MAX = tmp1;
         MIN = tmp2;
      } else {
         MAX = tmp2;
         MIN = tmp1;
      }
      // cout << tmp1 << " " << tmp2 << endl;

      // cout << "--" << (S[N] + S[i + 1]) / 2 << endl;
      decltype(v)::iterator it2 = lower_bound(v.begin(), v.end(), (S[N] + S[i + 1]) / 2);
      tmp1 = S[it2 - v.begin()] - S[i + 1];
      tmp2 = S[N] - S[it2 - v.begin()];
      if (it2 - v.begin() - 1 >= 0) {
         tmp3 = S[it2 - v.begin() - 1] - S[i + 1];
         tmp4 = S[N] - S[it2 - v.begin() - 1];
