               tmp2 = tmp4;
            }
         }
      }

      if (tmp1 == 0 || tmp2 == 0) continue;
      // cout << tmp1 << " " << tmp2 << endl;

      if (tmp1 > MAX) MAX = tmp1;
      else if (tmp2 > MAX) MAX = tmp2;
      if (tmp1 < MIN) MIN = tmp1;
      else if (tmp2 < MIN) MIN = tmp2;

      if (ans == -1) ans = MAX - MIN;
      else if (ans > MAX - MIN) ans = MAX - MIN;
      // cout << "-->" << ans << endl;
   }
