    }
    if (sum)c++;
    return c <= m;
}
ll binary_search()
{
    ll s = 1, e = 1e18, ret = 1e18, mx=-1e18;
    while (s <= e)
    {
        ll mid = (s + e) / 2;
        if (check(mid))
        {
            e = mid - 1;
            mx=max(mx,mid);
            ret = mid;
        }
        else s = mid + 1;
    }
    return abs(ret-mx);
}
