        int k = lower_bound(c + j, c + n, c[j-1] + (c[n-1] - c[j-1] + 1)/2) - c;
        cal(i, j - 1, k);
        cal(i - 1, j - 1, k);
        cal(i, j - 1, k - 1);
        cal(i - 1, j - 1, k - 1);
    }
    cout << ans;
}


