vll cumsum(vll& A){
  vll cum;
  int N=A.size();
  cum.push_back(0);
  for (int i=0;i<N;++i){
    cum.push_back(cum[i]+A[i]);
  }
  return cum;
}

//[low, high-1]から探す。
int b_search(vll& cum, int low, int high, ll c){
  int lb=low-1, ub=high;
  while(ub-lb>1){
    int mid=(ub+lb)/2;
    if(cum[mid]>=c){ub=mid;}
    else{lb=mid;}
  }
  return ub;
}

int main(){
