    a[i] = a[i - 1] + t;
  }

  uint64_t ans = ~0LLU;
  int left_cut = 1, right_cut = 2;
  for (int i = 2; i < n - 2; ++i) {
    while (left_cut < i) {
      if (abs(a[i] - 2 * a[left_cut + 1]) < abs(a[i] - 2 * a[left_cut])) {
        left_cut++;
      } else {
        break;
      }
    }
    right_cut = max(i + 1, right_cut);
    while (right_cut < n) {
      if (abs(a[n] - 2 * a[right_cut + 1] + a[i]) < abs(a[n] - 2 * a[right_cut] + a[i])) {
        right_cut++;
      } else {
        break;
      }
    }
    int sums[] = {a[left_cut], a[i] - a[left_cut], a[right_cut] - a[i],
                  a[n] - a[right_cut]};
    uint64_t score =
        *max_element(sums, sums + 4) - *min_element(sums, sums + 4);
    ans = min(ans, score);
  }
  cout << ans << "\n";
