int n;

pLL tersearch(int L, int R)
{
    int l = L+1, r = R-1;
    while(r - l > 3)
    {
        int m1 = (l+l+r) / 3, m2 = (l+r+r) / 3;
        if(abs(S[R]-S[m1]-(S[m1]-S[L])) < abs(S[R]-S[m2]-(S[m2]-S[L])))
            r = m2;
        else
            l = m1;
    }
    pLL ans = {S[R]-S[r],(S[r]-S[L])};
    if(ans.first> ans.second)
        swap(ans.first, ans.second);
    for(int i = l; i <= r; ++i)
    {
        pLL cur = {S[R]-S[i],(S[i]-S[L])};
        if(cur.first> cur.second)
            swap(cur.first, cur.second);
        if(cur.second-cur.first<ans.second-ans.first)
            ans = cur;
    }
    //cerr<<L<<' '<<R<<' '<<ans.first<<' '<<ans.second<<endl;
    //cerr<<l<<' '<<r<<endl;
    return ans;
}

LL f(int mid)
{
    pLL l = tersearch(0, mid), r = tersearch(mid, n);
    return max(l.second, r.second) - min(l.first, r.first);
}

