int main() {
    lint n;
    cin>>n;
    vec a(n);
    rep(i,n)cin>>a[i];
    vector<cint> S(n+1,0);
    repi(i,1,n+1)S[i]=S[i-1]+a[i-1];
    cint ave=S[n]/4;
    vector<lint>v(3);
    rep(i,n){
        if(S[i]<=S[n]/4&&S[n]/4<=S[i+1])v[0]=i;
        if(S[i]<=S[n]/2&&S[n]/2<=S[i+1])v[1]=i;
        if(S[i]<=S[n]*3/4&&S[n]*3/4<=S[i+1])v[2]=i;
    }
    cint cnt=INF;
    vector<cint> b(4);
    repi(i,-79,80)repi(j,-79,80)repi(k,-79,80){
        if(v[0]+i<0||n<v[0]+i)continue;
        if(v[1]+j<0||n<v[1]+j)continue;
        if(v[2]+k<0||n<v[2]+k)continue;
        b[0]=S[v[0]+i]-ave;
        b[1]=S[v[1]+j]-S[v[0]+i]-ave;
        b[2]=S[v[2]+k]-S[v[1]+j]-ave;
        b[3]=S[n]-S[v[2]+k]-ave;
        cint x=cmax(b)-cmin(b);
        if(x<cnt)cnt=x;
    }
    cout<<cnt;
}

