using namespace std;
using ull = unsigned long long;
using ll = long long;
ll a[200001], sum[200001];
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	ull n;
	cin >> n;
	for (size_t i = 1; i <= n; i++) {
		cin >> a[i];
		sum[i] = sum[i - 1] + a[i];
	}
	ll ans = sum[n];
	size_t ptr1 = 1, ptr2 = 3, t;
	for (size_t i = 2; i < n - 1; i++) {
		ll curdif = abs(sum[i] - sum[ptr1] - sum[ptr1]);
		while ((t = ptr1 + 1) < i) {
			ll tcurdif = abs(sum[i] - sum[t] - sum[t]);
			if (tcurdif < curdif) {
				ptr1 = t;
				curdif = tcurdif;
			}
			else
				break;
		}
		curdif = abs(sum[ptr2] - sum[i] - (sum[n] - sum[ptr2]));
		while ((t = ptr2 + 1) < n) {
			ll tcurdif = abs(sum[t] - sum[i] - (sum[n] - sum[t]));
			if (tcurdif < curdif) {
				ptr2 = t;
				curdif = tcurdif;
			}
			else
				break;
		}
		ll p = sum[ptr1], q = sum[i] - sum[ptr1], r = sum[ptr2] - sum[i], s = sum[n] - sum[ptr2];
		ll x = min(min(p, q), min(r, s));
		ll y = max(max(p, q), max(r, s));
		ll t_ans = y - x;
		if (t_ans < ans) {
			ans = t_ans;
		}
	}
	cout << ans << endl;
	return 0;
}

