int main()
{
    int array[200000];
    int N;
    cin >> N;
    long long sum = 0;
    for (int i = 0; i < N; ++i)
    {
        int a;
        cin >> a;
        array[i] = a;
        sum += a;
    }
    double avg = sum / 4.0;

    long long s = 0;
    long long min = -1;
    long long max = -1;
    for (int i = 0; i < N; ++i)
    {
        int a = array[i];
        if (s > 0 && s + a > avg)
        {
            double d1 = avg - s;
            double d2 = s + a - avg;
            if (d1 > d2) { s += a; }
            if (min == -1 || min > s) { min = s; }
            if (max == -1 || max < s) { max = s; }
            if (d1 <= d2) { s = a; }
            continue;
        }
        s += array[i];
    }
    if (min == -1 || min > s) { min = s; }
    if (max == -1 || max < s) { max = s; }

    cout << max - min << endl;
    return 0;
}

#include <stdio.h>

void search(long long int *A,int N,long long int *min,long long int *max){ 
  long long int find = A[N]-A[0];
  int bottom=1,top=N-1;

  while(top-bottom-1>0)
    if(find<(A[(top+bottom)/2]-A[0])*2)
      top=(top+bottom)/2;
    else
      bottom=(top+bottom)/2;

  if(2*(A[top]-A[0])-find<find-2*(A[bottom]-A[0])) bottom=top; 
  long long int first=A[bottom]-A[0],second=A[N]-A[bottom];

  if(*min>first) *min=first;
  if(*max<first) *max=first;
  if(*min>second) *min=second;
  if(*max<second) *max=second;
  //  printf("\t[%d:%d]=%lld[%d:%d]=%lld :: ",1,bottom,first,bottom+1,N,second);
  // for(int i=0;i<=N;i++)
  // printf("%lld ",A[i]);
  //printf("\n");

}

int main(){
  int N,a;
  long long int A[300000],s;
  long long int min,max,sunuke;

  scanf("%d",&N);

  s=A[0]=0;
  for(int i=1;i<=N;i++){
    scanf("%d",&a);
    s+=a;
    A[i]=s;
  }
  //for(int i=0;i<=N;i++)
    //  printf("%lld ",A[i]);
  //printf("\n");

  sunuke=1000000000000000;
  for(int i=2;i<=N-2;i++){
    // printf("[%d:%d],[%d:%d]\n",1,i,i+1,N);
    min=1000000000000000;
    max=0;
    search(A,i,&min,&max);
    search(A+i,N-i,&min,&max);
    if(sunuke>max-min) sunuke = max-min;
  }

  printf("%lld\n",sunuke);
}

#include <bits/stdc++.h>
using namespace std;
#define rep(i, n) for (int i = 0; i < (int)(n); i++)
typedef pair<int, int> P;
typedef long long ll;
int main()
{
    int n;
    cin >> n;
    vector<ll> dp(n + 1);
    rep(i, n)
    {
        cin >> dp[i + 1];
        dp[i + 1] += dp[i];
    }
    ll ans = 1e18;
    for (int i = 3; i < n-1; i++)
    {
        auto first = lower_bound(dp.begin(), dp.begin() + i, dp[i - 1] / 2) - dp.begin();
        auto second = lower_bound(dp.begin() + i, dp.end(), (dp[n]+dp[i] )/ 2) - dp.begin();
        // 近傍探索して
        for (int j = -1; j <= 1; j += 1)
        {
            if (first + j >= i || first + j <= 0)
            {
                continue;
            }
            for (int k = -1; k <= 1; k += 1)
            {
                if (second + k >= n || second + j <= i)
                {
                    continue;
                }
                ll mx = 0;
                ll mn = 1e18;
                mx = max(dp[i] - dp[first + j], mx);
                mx = max(dp[first + j] - dp[0], mx);
                mx = max(dp[n] - dp[second + k], mx);
                mx = max(dp[second + k] - dp[i], mx);
                mn = min(dp[i] - dp[first + j], mn);
                mn = min(dp[first + j] - dp[0], mn);
                mn = min(dp[n] - dp[second + k], mn);
                mn = min(dp[second + k] - dp[i], mn);
                ans = min(ans, mx - mn);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

