constexpr int MAXN = 2e5+42;

int N, A[MAXN];
ll P[MAXN];

ll calc(int m)
{
  int j=0;
  for(int i=1; i<m; i++)
  {
    if(abs(P[m]/2 - P[i]) < abs(P[m]/2 - P[j]))
      j = i;
  }
  int k=m+1;
  for(int i=m+2; i<N; i++)
  {
    if(abs((P[N-1]-P[m])/2 - (P[i]-P[m])) < abs((P[N-1]-P[m])/2 - (P[k]-P[m])))
      k = i;
  }
  ll s1 = P[j];
  ll s2 = P[m]-P[j];
  ll s3 = P[k]-P[m];
  ll s4 = P[N-1]-P[k];
  vector<ll> s{s1,s2,s3,s4};
  sort(s.begin(),s.end());
  return s[3]-s[0];
}

int main()
{
  read(N);
  for(int i=0; i<N; i++)
    read(A[i]);
  partial_sum(A,A+N,P);
  int l=1, r=N-3;
  while(l < r)
  {
    int m = (l+r)/2;
    if(calc(m) < calc(m+1))
      r = m;
    else
      l = m+1;
  }
  print(calc(r));
  return 0;
}

