        ll R=*lower_bound(sum+bEnd+1,sum+N,(sum[N-1]-sum[bEnd])/2+sum[bEnd])-sum[bEnd];
        ll S=sum[N-1]-sum[bEnd]-R;
        ll R_=*(lower_bound(sum+bEnd+1,sum+N,(sum[N-1]-sum[bEnd])/2+sum[bEnd])-1)-sum[bEnd];
        ll S_=sum[N-1]-sum[bEnd]-R_;
        if(max(S,R)-min(S,R) > max(S_,R_)-min(S_,R_)){
            S=S_;
            R=R_;
        }
        ans=min(ans,max({P,Q,R,S})-min({P,Q,R,S}));
    }
    cout<<ans<<endl;
    return 0;
}

