using namespace std;
using ll = long long;
template <typename Domain, typename Range, typename Function>
Domain tsearch(Domain L, Domain R, const Function& f, bool concave_up = true) {
#ifdef DEBUG
    using actual_type = typename callable_traits<Function>::function_type;
    using expected_type = typename callable_traits<Range(Domain)>::function_type;
    static_assert(is_same<actual_type, expected_type>::value, "tsearch 'f' must be Range(Domain)");
#endif
    while(R - L > 1) {
        Domain M = (L + R) / 2;
        ((concave_up ? f(M) < f(M + 1) : f(M) > f(M + 1)) ? R : L) = M;
    }
    return (concave_up ? f(L) < f(R) : f(L) > f(R)) ? L : R;
}
int main() {
	int n;
	cin >> n;
	vector<ll> a(n);
	for(int i = 0; i < n; i++) {
		cin >> a[i];
	}
	vector<ll> s(n);
	partial_sum(a.begin(), a.end(), s.begin());
	auto rsq = [&](int L, int R) {
		return s[R - 1] - (L ? s[L - 1] : 0);
	};
	ll ans = accumulate(a.begin(), a.end(), 0);
	for(int i = 2; i <= n - 2; i++) {
		int lcut = tsearch<int, ll>(1, i - 1, [&](int j) {
			return abs(rsq(0, j) - rsq(j, i));
		});
		int rcut = tsearch<int, ll>(i + 1, n - 1, [&](int j) {
			return abs(rsq(i, j) - rsq(j, n));
		});
		for(int llcut = max(lcut - 1, 1); llcut <= min(lcut + 1, i - 1); llcut++) {
			for(int rrcut = max(rcut - 1, i + 1); rrcut <= min(rcut + 1, n - 1); rrcut++) {
				ll mini = min({rsq(0, llcut), rsq(llcut, i), rsq(i, rrcut), rsq(rrcut, n)});
				ll maxi = max({rsq(0, llcut), rsq(llcut, i), rsq(i, rrcut), rsq(rrcut, n)});
				ans = min(ans, abs(maxi - mini));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

