// [l, r)
res minimize(int l0, int r0) {
  ll s = S[r0] - S[l0];
  int l = l0, r = r0;
  while(r - l > 1) {
    int m = (l+r)/2;
    if(S[m+1] - S[l0] <= s/2) {
      l = m;
    } else {
      r = m;
    }
  }
  if(r0 > l + 2 && abs(2*S[l+1]- S[l0] - S[r0]) > abs(2*S[l+2]- S[l0] - S[r0])) l++;
  ll x = S[l+1] - S[l0];
  ll y = S[r0] - S[l+1];
  return res(min(x,y), max(x,y));
}

