int searchborder(int r,int l){//二分探索で「左側の右端」のindexを求める
  if(l>r){
    cout<<"error"<<endl;
    return -1;
  }
  int tmpl=l;
  int tmpr=r;
  int mid=(l+r)/2;
  while(tmpl!=mid){
    //cout<<" l "<<l << " r "<<r<<" mid "<<mid<<endl;
    if(getsum(mid,l)<=getsum(r,mid+1)){
      tmpl=mid;
    }else{
      tmpr=mid-1;
    }
    mid=(tmpr+tmpl)/2;
  }
  return mid;
}
