	for (ll i = 1; i <= n; i++) {
		scanf("%lld", &sum[i]);

		sum[i] = sum[i] + sum[i - 1];
	}
	sum[n + 1] = sum[n] * 2;

	ans = sum[n + 1];
	// left, mid, right;
	// sum[left], sum[mid] - sum[left], sum[right] - sum[mid], sum[n] - sum[right]

	for (ll mid_part = 2; mid_part <= n - 2; mid_part++) {
		ll left_part, right_part;
		ll valid, invalid;
		ll key;

		valid = 1; invalid = mid_part;
		key = sum[mid_part] / 2;
		while (llabs(invalid - valid) > 1) {
			ll mid = (valid + invalid) / 2;

			if (sum[mid] <= key) {
				valid = mid;
			} else {
				invalid = mid;
			}
		}
		left_part = valid;
		if (llabs(sum[mid_part] - sum[left_part] - sum[left_part])
				> llabs(sum[mid_part] - sum[left_part + 1] - sum[left_part + 1]) &&
				left_part + 1 < mid_part) {
			left_part = left_part + 1;
		}

		valid = mid_part + 1; invalid = n + 1;
		key = (sum[n] - sum[mid_part]) / 2;
		while (llabs(invalid - valid) > 1) {
			ll mid = (valid + invalid) / 2;

			if (sum[mid] - sum[mid_part] <= key) {
				valid = mid;
			} else {
				invalid = mid;
			}
		}
		right_part = valid;
		if (llabs((sum[n] - sum[right_part]) - (sum[right_part] - sum[mid_part]))
				> llabs((sum[n] - sum[right_part + 1]) - (sum[right_part + 1] - sum[mid_part])) &&
				right_part + 1 < n) {
			right_part = right_part + 1;
		}

		/*
		printf("%lld : %lld : %lld\n", left_part, mid_part, right_part);
		printf("%lld, %lld, %lld, %lld\n", sum[left_part], sum[mid_part] - sum[left_part],
				sum[right_part] - sum[mid_part], sum[n] - sum[right_part]);
				*/

		ans = min(ans, max(sum[left_part], max(sum[mid_part] - sum[left_part], max(sum[right_part] - sum[mid_part], sum[n] - sum[right_part]))) -
				min(sum[left_part], min(sum[mid_part] - sum[left_part], min(sum[right_part] - sum[mid_part], sum[n] - sum[right_part]))));
	}

	printf("%lld\n", ans);

	return 0;
}

