long max4(long *a)
{
  long ans = a[0], i;
  for (i = 0; i < 3; ++i)
  {
    if (a[i + 1] > ans)
    {
      ans = a[i + 1];
    }
  }
  return ans;
}

long min4(long *a)
{
  long ans = a[0], i;
  for (i = 0; i < 3; ++i)
  {
    if (a[i + 1] < ans)
    {
      ans = a[i + 1];
    }
  }
  return ans;
}

long min(long *a, long size)
{
  long ans = a[0], i;
  for (i = 0; i < size - 1; ++i)
  {
    if (a[i + 1] < ans)
    {
      ans = a[i + 1];
    }
  }
  return ans;
}

