      if (sum[med] < sum[i + 1] - sum[med]) l = med;
      else r = med;
    }
    if (sum[r] == sum[i + 1] - sum[r]) lmin = lmax = sum[r];
    else {
      if (2 * sum[r] - sum[i + 1] < -(2 * sum[l] - sum[i + 1])) {
	lmin = sum[i + 1] - sum[r];
	lmax = sum[r];
      } else {
	lmin = sum[l];
	lmax = sum[i + 1] - sum[l];
      }
    }

    l = i + 1; r = n;
    while (r - l > 1) {
      med = (l + r) / 2;
      if (sum[med] - sum[i + 1] < sum[n] - sum[med]) l = med;
      else r = med;
    }
    if (sum[r] - sum[i + 1] == sum[n] - sum[r])
      rmin = rmax = sum[r] - sum[r];
    else {
      ll x = -(2 * sum[l] - sum[i + 1] - sum[n]);
      ll y = 2 * sum[r] - sum[i + 1] - sum[n];
      if (x < y) {
	rmax = sum[n] - sum[l];
	rmin = sum[l] - sum[i + 1];
      } else {
	rmax = sum[r] - sum[i + 1];
	rmin = sum[n] - sum[r];
      }
