  for (i = 1; i <= n - 3; ++i)
  {
    // j = 0
    s[0] = o[0];
    s[1] = o[i] - o[0];
    for (j = 1; j < i; ++j)
    {
      sn[0] = o[j];
      sn[1] = o[i] - o[j];

      if (abso(sn[0] - sn[1]) < abso(s[0] - s[1]))
      {
        s[0] = sn[0];
        s[1] = sn[1];
      }
      else
      {
        break;
      }
    }

    // j = i + 1
    s[2] = o[i + 1] - o[i];
    s[3] = o[n - 1] - o[i + 1];
    for (j = i + 2; j <= n - 2; ++j)
    {
      sn[2] = o[j] - o[i];
      sn[3] = o[n - 1] - o[j];

      if (abso(sn[2] - sn[3]) < abso(s[2] - s[3]))
      {
        s[2] = sn[2];
        s[3] = sn[3];
      }
      else
      {
        break;
      }
    }

    min_s = s[0];
    max_s = s[0];
    for (j = 1; j < 4; ++j) {
      if (min_s > s[j])
      {
        min_s = s[j];
      }
      if (max_s < s[j])
      {
        max_s = s[j];
      }
    }

    if (i == 1 || (max_s - min_s) < ans) {
      ans = max_s - min_s;
    }
  }

  printf("%ld\n", ans);

  return 0;
}

long abso(long x)
{
  return ((x >= 0)? x : - x);
}

