fun accumulate(A: MutableList<Long>) {
    for(i in 1..(A.size - 1)) {
        A.set(i, A.get(i) + A.get(i - 1))
    }
}

fun minIndex(A: List<Long>, startIndex: Int = 0, endIndex: Int = -1) : Int {
    var min = Long.MAX_VALUE
    var index = -1

    for (i in startIndex..(A.size + endIndex)) {
        val elm = A.get(i)

        if (elm < min) {
            min = elm
            index = i
        }
    }

    return index
}

