procedure find(h,t:longint);
var
    l,r,q,mid,x,y,x1,y1,x2,y2:longint;
begin
    l:=h;r:=t;q:=(b[t]-b[h-1]) div 2;
    while l<>r-1 do
        begin 
            mid:=(l+r) div 2;
            if b[mid]-b[h-1]>q then r:=mid else l:=mid;
        end;
    x1:=b[l]-b[h-1];
    y1:=b[t]-b[l];
    x2:=b[r]-b[h-1];
    y2:=b[t]-b[r];
    if abs(x1-y1)<abs(x2-y2) then 
        begin
            x:=x1;y:=y1;
        end
    else
        begin
            x:=x2;y:=y2;
        end;
    if x>max then max:=x;
    if x<min then min:=x;
    if y>max then max:=y;
    if y<min then min:=y;
end;
