	public int f(long a[],  int s, int t) {
		int p = -1;
		int l=s+1;
		int r=t-1;
		long S = a[t]-a[s];
		while(l<=r) {
			int m=(l+r)/2;
			long x = a[m]-a[s];
			if(x<S-x) {
				l=m+1;
			}
			if(x==S-x) {
				p=m;
				break;
			}
			if(x>S-x) {
				r=m-1;
			}
		}
		if(p==-1) {
			if(Math.abs((a[l]-a[s])-(a[t]-a[l])) < Math.abs((a[r]-a[s])-(a[t]-a[r]))) {
				p=l;
			}else {
				p=r;
			}
		}
		return p;
	}
}

