			long max = Math.max(Math.max(sum[rcut1],sum[cut2] - sum[rcut1]),Math.max(sum[rcut3] - sum[cut2],sum[N-1] - sum[rcut3]));
			long min = Math.min(Math.min(sum[rcut1],sum[cut2] - sum[rcut1]),Math.min(sum[rcut3] - sum[cut2],sum[N-1] - sum[rcut3]));
