		long C=0;
		for(int i=0;i<N;i++) {
			C=C+(long)A[i];
			B[i]=C;
		}
		long abs;
		long ans=Long.MAX_VALUE;
		int d=0;
		int f=0;
		int i=0;
		for(i=1;i<N-2;i++) {
			long c=Long.MAX_VALUE;
			for(int k=0;k<i;k++) {
				abs=Math.abs(B[k]-(B[i]-B[k]));
				if(abs<c) {
					c=abs;
					d=k;
				}else {
					break;
				}
			}
			long e=Long.MAX_VALUE;
			for(int k=i+1;k<N-1;k++) {
				abs=Math.abs((B[k]-B[i])-(B[N-1]-B[k]));
				if(abs<e) {
