class Main {
    static Scanner scanner = new Scanner();

    public static void main(String[]$) {
        int n = scanner.nextInt();
        long[] a = new long[n];
        long[] b = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = b[i] = scanner.nextInt();
            if (i > 0) {
                b[i] += b[i - 1];
            }
        }
        long min = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int j = 0, k = i;
            while (++j <= i && b[j] * 2 <= b[i]);
            while (++k < n && (b[k] - b[i]) * 2 <= b[n - 1] - b[i]);
            for (int j1 = j - 1, l = 0; l < 3; j1++, l++) {
                for (int k1 = k - 1, m = 0; m < 3; k1++, m++) {
                    min = Math.min(min, f(b, j1, i, k1));
                }
            }
        }

        System.out.println(min);
    }

    static long f(long[] array, int i, int j, int k) {
        if (i < j && j < k && 0 < i && k < array.length) {
            long a = array[i - 1];
            long b = array[j - 1] - array[i - 1];
            long c = array[k - 1] - array[j - 1];
            long d = array[array.length - 1] - array[k - 1];
            return Math.max(Math.max(Math.max(a, b), c), d) - Math.min(Math.min(Math.min(a, b), c), d);
        }
        return Integer.MAX_VALUE;
    }

    static class Scanner {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 1 << 15);
        StringTokenizer tokenizer;

        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException ignored) {
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

class Main {

	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long[] A = new long[N];
		for (int i = 0; i < N; i++) {
			A[i] = sc.nextLong();
		}
		solve(N, A);
	}

	static void solve(int N, long[] A) {
		long[] sum = new long[N + 1];
		for (int i = 0; i < N; i++) {
			sum[i + 1] = sum[i] + A[i];
		}

		int l = 1;
		int r = 3;
		long answer = Long.MAX_VALUE;
		for (int i = 2; i < N - 1; i++) {
			while (l < i - 1 && Math.abs(sum[i] - sum[l] * 2) >
					Math.abs(sum[i] - sum[l + 1] * 2)) {
				l++;
			}

			while (r < N - 1 && Math.abs(sum[N] - sum[i] - (sum[r] - sum[i]) * 2) >
					Math.abs(sum[N] - sum[i] - (sum[r + 1] - sum[i]) * 2)) {
				r++;
			}

			long[] a = new long[]{sum[l], sum[i] - sum[l], sum[r] - sum[i], sum[N] - sum[r]};
			Arrays.sort(a);

			answer = Math.min(answer, Math.abs(a[3] - a[0]));
		}

		System.out.println(answer);
	}
}

