					c=abs;
					d=k;
				}else {
					break;
				}
			}
			long e=Long.MAX_VALUE;
			for(int k=2;k<N-1;k++) {
				abs=Math.abs((B[k]-B[i])-(B[N-1]-B[k]));
				if(abs<e) {
					e=abs;
					f=k;
