      int t = p;
      int m = 0;
      for(int j = p; j < n - 2; j++) {
        long s1 = rui[j] - rui[i];
        long s2 = rui[n - 1] - rui[j];
        if(s1 >= s2) {
          t = j;
          if(j == p) m = 1;
          break;
        }
      }
      if(t == p) {
        if(m == 0) {
          r[i] = n - 2;
          p = (n - 2);
        }
        if(m == 1) {
          r[i] = p;
        }
      } else {
        if(Math.abs(rui[n - 1] - rui[t] - rui[t] + rui[i]) >= Math.abs(rui[n - 1] - rui[t - 1] - rui[t - 1] + rui[i])) {
          r[i] = (t - 1);
          p = (t - 1);
        } else {
          r[i] = t;
          p = t;
        }
      }
    }
    long ans = Long.MAX_VALUE;
    for(int i = 1; i < n - 2; i++) {
      long s1 = rui[l[i]];
      long s2 = rui[i] - rui[l[i]];
      long s3 = rui[r[i]] - rui[i];
      long s4 = rui[n - 1] - rui[r[i]];
      long ma = Math.max(s1, s2);
      ma = Math.max(ma, s3);
      ma = Math.max(ma, s4);
      long mi = Math.min(s1, s2);
      mi = Math.min(mi, s3);
      mi = Math.min(mi, s4);
      ans = Math.min(ans, ma - mi);
    }
    System.out.println(ans);
  }
}

