		for (int i = 1; i <= N; i++) {
			A[i] = A[i-1] + sc.nextInt();
		}
		long ans = Integer.MAX_VALUE;
		int preL = 1;
		int preR = 3;
		long[] block = new long[4];
		for (int i = 2; i < N - 1; i++) {
			long minL = Integer.MAX_VALUE;
			for (int j = preL; j < i; j++) {
				long t0 = A[j];
				long t1 = A[i] - A[j];
				long dif = Math.abs(t1 - t0);
				if (dif <= minL) {
					minL = dif;
					preL = j;
					block[0] = t0;
					block[1] = t1;
				} else {
					break;
				}
			}
			long minR = Integer.MAX_VALUE;
