public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextLong();
        }

        long[] cumSum = new long[N + 1];
        for (int i = 1; i < N + 1; i++) {
            cumSum[i] = cumSum[i - 1] + A[i - 1];
        }

        long ret = Long.MAX_VALUE;

        int leftp = 0;
        int rightp = 2;

        for (int center = 1; center <= N - 3; center++) {
            long leftSum;
            long rightSum;
            long leftmin;
            leftSum = cumSum[leftp + 1] - cumSum[0];
            rightSum = cumSum[center + 1] - cumSum[leftp + 1];
            leftmin = Math.abs(leftSum - rightSum);

            while (true) {
                leftSum = cumSum[leftp + 2] - cumSum[0];
                rightSum = cumSum[center + 1] - cumSum[leftp + 2];
                if (Math.abs(leftSum - rightSum) > leftmin) break;
                leftp++;
            }

            long rightmin;
            leftSum = cumSum[rightp + 1] - cumSum[center + 1];
            rightSum = cumSum[N] - cumSum[rightp + 1];
            rightmin = Math.abs(leftSum - rightSum);

            while (rightp + 2 <= N - 1) {
                leftSum = cumSum[rightp + 2] - cumSum[center + 1];
                rightSum = cumSum[N] - cumSum[rightp + 2];
                if (Math.abs(leftSum - rightSum) > rightmin) break;
                rightp++;
            }

            long[] data = new long[4];
            data[0] = cumSum[leftp + 1] - cumSum[0];
            data[1] = cumSum[center + 1] - cumSum[leftp + 1];
            data[2] = cumSum[rightp + 1] - cumSum[center + 1];
            data[3] = cumSum[N] - cumSum[rightp + 1];
            Arrays.sort(data);

            ret = Math.min(ret, data[3] - data[0]);
        }

        System.out.println(ret);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final long[] cumulativeSum = new long[n];
        cumulativeSum[0] = scanner.nextLong();

        for (int i = 1; i < n; i++) {
            cumulativeSum[i] = cumulativeSum[i - 1] + scanner.nextLong();
        }

        int firstIndex = 0;
        int thirdIndex = 2;
        long answer = Integer.MAX_VALUE;
        for (int secondIndex = 1; secondIndex < n - 2; secondIndex++) {
            for (; firstIndex < secondIndex - 1; firstIndex++) {
                if (Math.abs(cumulativeSum[secondIndex] - cumulativeSum[firstIndex] * 2) <= Math.abs((cumulativeSum[secondIndex] - cumulativeSum[firstIndex + 1] * 2))) {
                    break;
                }
            }

            for (; thirdIndex < n - 2; thirdIndex++) {
                if (Math.abs(cumulativeSum[n - 1] - cumulativeSum[thirdIndex] * 2 + cumulativeSum[secondIndex]) <= Math.abs(cumulativeSum[n - 1] - cumulativeSum[thirdIndex + 1] * 2 + cumulativeSum[secondIndex])) {
                    break;
                }
            }

            long a = cumulativeSum[firstIndex];
            long b = cumulativeSum[secondIndex] - cumulativeSum[firstIndex];
            long c = cumulativeSum[thirdIndex] - cumulativeSum[secondIndex];
            long d = cumulativeSum[n - 1] - cumulativeSum[thirdIndex];

            long tmp = max(a, b, c, d) - min(a, b, c, d);
            answer = Math.min(tmp, answer);
        }

        System.out.println(answer);
    }

    private static long max(final long a, final long b, final long c, final long d) {
        return Math.max(Math.max(a, b), Math.max(c, d));
    }

    private static long min(final long a, final long b, final long c, final long d) {
        return Math.min(Math.min(a, b), Math.min(c, d));
    }
}

