		 }
		 //配列みっつめ
		 for(int i = pp+1 ; i < N-1 ; i++){

			 before += T[i];
			 int babs = Math.abs(before-sum);
			 after  = before + T[i+1];
			 int aabs = Math.abs(after-sum);
			 if(babs>aabs){
				 //足す前のほうが大きい(sumから離れている)場合、繰上げ
				 if(i == N-2){
					 pp = i;
					 U[2] = before;
					 before = 0 ;
					 after = 0;
				 }else{
				 continue;
				 }
				 //回りきった場合は、総和を挿入する
			 }else{
				 pp = i;
				 U[2] = before;
				 before = 0 ;
				 after = 0;
				 break;

			 }
		 }
		 //配列よっつめ
		 for(int i = pp+1 ; i < N ; i++){
			 U[3] += T[i];
		 }
/*
		 for(int i = 0 ; i < 4 ; i++){
			 System.out.println(U[i]);
		 }
*/

		 Arrays.sort(U);
		 System.out.println(U[3]-U[0]);
	}
}

