import java.util.Scanner;

public class Main{
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();

    //ここから累積和のやつ
    long[] s = new long[N + 1];
    for(int i = 1; i <= N; i++){
      s[i] = sc.nextLong();
      s[i] += s[i - 1];
    }
    //累積和のやつここまで

    int L = 1;
    int R = 3; //切り口Lと切り口Rを定義
    long ans = s[N];

    for(int i = 2; i < N - 1; i++){
      long last = s[N];
      while(L < i){ //切り口Lは中央より左に来る
        long dist = Math.abs(s[i] - s[L]*2); //1番左の塊の長さと左から2番目の塊の長さとの差の絶対値
        if(dist > last){break;} //distが単調増加しはじめたら探索をやめる
        else{last = dist; //distが単調減少している間はlastを更新し探索続行
        L++; //切り口Lを右に寄せる
        }
      }
      L--; //単調減少するギリギリのところにLを戻す

      //ここからは同様のことをRでやる
      last = s[N];
      while(R < N){
        long dist = Math.abs(s[N] + s[i] - s[R]*2);
        if(dist > last){break;}
        else{last = dist;
        R++;
        }
      }
      R--;
      //同様のやつここまで

      long max = Math.max(Math.max(Math.max(s[L], s[i] - s[L]), s[R] - s[i]), s[N] - s[R]);
      long min = Math.min(Math.min(Math.min(s[L], s[i] - s[L]), s[R] - s[i]), s[N] - s[R]);
      ans = Math.min(max - min, ans);
    }

    System.out.println(ans);
  }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説どおりに作成したソースコード
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			long[] sum = new long[n + 1];
			sum[0] = 0L;
			IntStream.rangeClosed(1, n).forEach(i -> sum[i] = sum[i - 1] + scanner.nextInt());
			// 左と右の配列のそれぞれ区切ったところ
			int left = 1, right = 3;
			long answer = Long.MAX_VALUE;
			for (int i = 2; i <= n - 2; i++) {
				while ((left < i - 1) && (Math.abs(sum[left] - (sum[i] - sum[left])) > Math
						.abs(sum[left + 1] - (sum[i] - sum[left + 1])))) {
					left++;
				}
				while ((right < n - 1) && (Math.abs((sum[right] - sum[i]) - (sum[n] - sum[right])) > Math
						.abs((sum[right + 1] - sum[i]) - (sum[n] - sum[right + 1])))) {
					right++;
				}
				answer = Math.min(answer,
						Math.abs(max(sum[left], sum[i] - sum[left], sum[right] - sum[i], sum[n] - sum[right])
								- min(sum[left], sum[i] - sum[left], sum[right] - sum[i], sum[n] - sum[right])));
			}
			System.out.println(answer);
		}
	}

	/**
	 * 複数のlongの最大値を取得する
	 * 
	 * @param longs 複数のlong
	 * @return 複数のlongの最大値
	 */
	private static long max(long... longs) {
		if (null != longs) {
			return Arrays.stream(longs).max().getAsLong();
		}
		return 0L;
	}

	/**
	 * 複数のlongの最小値を取得する
	 * 
	 * @param longs 複数のlong
	 * @return 複数のlongの最小値
	 */
	private static long min(long... longs) {
		if (null != longs) {
			return Arrays.stream(longs).min().getAsLong();
		}
		return 0L;
	}
}

