		long buf,sum = 0;
		for(int i = 0;i < N;i++) {
			buf = scn.nextLong();
			A[i] = buf;
			sum += buf;
		}
		long P = 0,Q = 0,R = 0,S = 0,ans = 1000000000000l,max,min;
		for(int i = 0;i < N-3;i++) {
			P += A[i];
			for(int j = i + 1;j < N-2;j++) {
				Q += A[j];
				for(int k = j+1;k < N-1;k++) {
					R += A[k];
