import java.io.*;
import java.util.*;
import java.util.function.IntPredicate;

class Main {
    static Scanner scanner = new Scanner();

    static long ans = Long.MAX_VALUE;
    static int n;
    static long[] a, b;
    public static void main(String[]$) {
        n = scanner.nextInt();
        a = new long[n];
        b = new long[n + 1];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            b[i + 1] = a[i] + b[i];
        }
        for (int m = 2; m < n; m++) {
            long maxL = b[m];
            long maxR = b[n];
            int l = binarySearch(0, m, i -> b[i] * 2 <= maxL);
            int r = binarySearch(m, n, i -> b[i] * 2 <= maxL + maxR);
            f(l, m, r);
            f(l, m, r - 1);
            f(l - 1, m, r);
            f(l - 1, m, r - 1);
        }
        System.out.println(ans);
    }

    static void f(int l, int m, int r) {
        long a1 = b[l];
        long b1 = b[m] - b[l];
        long c1 = b[r] - b[m];
        long d1 = b[n] - b[r];
        ans = Math.min(ans, max(a1, b1, c1, d1) - min(a1, b1, c1, d1));
    }

    static long min(long... a) {
        long n = a[0];
        for (int i = 1; i < a.length; i++) {
            n = Math.min(n, a[i]);
        }
        return n;
    }

    static long max(long... a) {
        long n = a[0];
        for (int i = 1; i < a.length; i++) {
            n = Math.max(n, a[i]);
        }
        return n;
    }

    static int binarySearch(int min, int max, IntPredicate predicate) {
        int ok = min, ng = max;
        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
            if (predicate.test(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return ng;
    }

    static class Scanner {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 1 << 15);
        StringTokenizer tokenizer;

        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException ignored) {
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
public class Main {

  public static void main(String[] args) { 
      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      int[] arr = new int[n];
      for(int i = 0; i < n; i++)
        arr[i] = sc.nextInt();

      long res = Long.MAX_VALUE;
      for(int idx = 1; idx < n - 2; idx++) {
            long[] leftMax = getMax(Arrays.copyOfRange(arr, 0, idx + 1));
            long[] rightMax = getMax(Arrays.copyOfRange(arr, idx + 1, n));

            long max = Math.max(leftMax[0], leftMax[1]);
            max = Math.max(max, Math.max(rightMax[0], rightMax[1]));

            long min = Math.min(leftMax[0], leftMax[1]);
            min = Math.min(min, Math.min(rightMax[0], rightMax[1]));

            res = Math.min(res, Math.abs(min - max));
      }
      System.out.println(res);
  }

  private static long[] getMax(int[] arr) {

      long[] leftSum = new long[arr.length];
      leftSum[0] = arr[0];
      for(int i = 1; i < arr.length; i++)
        leftSum[i] = leftSum[i - 1] + arr[i];

      long[] rightSum = new long[arr.length];
      rightSum[arr.length - 1] = arr[arr.length - 1];
      for(int i = arr.length - 2; i >=0; i--) {
        rightSum[i] = rightSum[i+1] + arr[i];
      }

      long minDiff = Math.abs(leftSum[0] - rightSum[1]);
      int minIdx = 0;
      for(int i = 1; i < arr.length - 1; i++) {
        long curDiff = Math.abs(leftSum[i] - rightSum[i + 1]);
        if(minDiff > curDiff) {
          minDiff = curDiff;
          minIdx = i;
        }
      }
      return new long[]{ leftSum[minIdx], rightSum[minIdx+1] };
  }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.LongStream;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < A.length; ++i) {
            A[i] = sc.nextInt();
        }

        System.out.println(solve(A));

        sc.close();
    }

    static long solve(int[] A) {
        long prefixSum = 0;
        long[] prefixSums = new long[A.length];
        for (int i = 0; i < prefixSums.length; ++i) {
            prefixSum += A[i];
            prefixSums[i] = prefixSum;
        }

        long result = Long.MAX_VALUE;
        for (int middleIndex = 1; middleIndex + 2 < A.length; ++middleIndex) {
            List<long[]> leftNearestPairs = findNearestPairs(prefixSums, 0, 0, middleIndex);
            List<long[]> rightNearestPairs = findNearestPairs(prefixSums, prefixSums[middleIndex], middleIndex + 1,
                    A.length - 1);

            for (long[] leftNearestPair : leftNearestPairs) {
                for (long[] rightNearestPair : rightNearestPairs) {
                    long[] sorted = LongStream.concat(Arrays.stream(leftNearestPair), Arrays.stream(rightNearestPair))
                            .sorted().toArray();

                    result = Math.min(result, sorted[sorted.length - 1] - sorted[0]);
                }
            }
        }

        return result;
    }

    static List<long[]> findNearestPairs(long[] prefixSums, long basePrefixSum, int beginIndex, int endIndex) {
        long total = prefixSums[endIndex] - basePrefixSum;

        int leftIndex = beginIndex - 1;
        int lower = beginIndex;
        int upper = endIndex;
        while (lower <= upper) {
            int middle = (lower + upper) / 2;
            long leftSum = prefixSums[middle] - basePrefixSum;
            long rightSum = total - leftSum;

            if (leftSum <= rightSum) {
                leftIndex = middle;
                lower = middle + 1;
            } else {
                upper = middle - 1;
            }
        }

        List<long[]> result = new ArrayList<>();
        if (leftIndex >= beginIndex && leftIndex < endIndex) {
            long leftSum = prefixSums[leftIndex] - basePrefixSum;

            result.add(new long[] { leftSum, total - leftSum });
        }
        if (leftIndex + 1 >= beginIndex && leftIndex + 1 < endIndex) {
            long leftSum = prefixSums[leftIndex + 1] - basePrefixSum;

            result.add(new long[] { leftSum, total - leftSum });
        }

        return result;
    }
}

import java.io.InputStream;
