                if (diffLeft < minDiff) {
                    minDiff = diffLeft;
                    l = j;
                } else {
                    break;
                }
            }
            minDiff = Long.MAX_VALUE;
            for (int j = r ; j <= n - 2; j++) {
                long diffRight = Math.abs(b[r] - b[i] - (b[n - 1] - b[r]));
                if (diffRight < minDiff) {
