	static class TaskX {

		int n;
		long[] a = new long[200010];
		long[] sum = new long[200010];
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			n = in.nextInt();
			for (int i = 1; i <= n; i++) {
				a[i] = in.nextLong();
				sum[i] = sum[i-1] + a[i];
			}

			long ans = LINF;
			// 半分に区切る位置を全探索
			for (int i = 2; i <= n-1; i++) {
				P[] psum = new P[2];

				psum[0] = divide(1, i);
				psum[1] = divide(i+1, n);

				List<Long> list = new ArrayList<>();
				list.add(psum[0].a);
				list.add(psum[0].b);
				list.add(psum[1].a);
				list.add(psum[1].b);

				Collections.sort(list);

				ans = Math.min(ans, list.get(3) - list.get(0));

			}

			out.println(ans);

		}

		// 閉区間[b, e]の数列をなるべく均等に分ける各配列の総和をペアで返す
		P divide(int b, int e) {

			int l = b, r = e;
			long ds= sum[e] - sum[b-1];

			// 二分探索で[b, m]の和が[b, e]の半分以下になる最大のmを探す
			while (r - l > 1) {
				int m = (r + l) / 2;

				long ps = sum[m] - sum[b-1];
				if (ps * 2 <= ds) {
					l = m;
				} else {
					r = m;
				}
			}

			// P <= Q の場合
			P ret1 = new P(sum[l] - sum[b-1], sum[e] - sum[l]);

			// P > Q の場合
			P ret2 = new P(sum[l+1] - sum[b-1], sum[e] - sum[l+1]);

			if (ret1.a - ret1.b > ret2.b - ret2.a) {
				return ret1;
			} else {
				return ret2;
			}
		}


		class P {
			long a;
			long b;

			public P(long a, long b) {
				super();
				this.a = a;
				this.b = b;
			}

		}
	}


