        long[] ac=new long[n];
        for(int i=0;i<n;i++) ac[i]=fsc.nextLong()+(i>0?ac[i-1]:0);
        fsc.close();
        long sum=ac[n-1];
        long pass,fail;
        pass=0; fail=sum/4+1;
        while(fail-pass>1){
            long mid=pass+(fail-pass)/2;
            if(isOK(ac, mid)) pass=mid;
            else fail=mid;
        }
        long min=pass;
        fail=sum/4-1; pass=sum;
        while(pass-fail>1){
            long mid=fail+(pass-fail)/2;
