public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0 ; i < n ; i++) {
            a[i] = sc.nextInt();
        }
        //累積和
        long[] b = new long[n];
        long c = 0;
        for (int i = 0 ; i < n ; i++) {
            c += (long) a[i];
            b[i] = c;
        }
        int l = 0;
        int r = 2;
        long ans = Long.MAX_VALUE;
        for (int i = 1 ; i <= n - 3 ; i++) {
            long diffLeft = Math.abs(b[i] - b[l] - b[l]);
            while (l < i && diffLeft > Math.abs(b[i] - b[l + 1] - b[l + 1])) {
                l++;
            }
            long diffRight = Math.abs(b[r] - b[i] - (b[n - 1] - b[r]));
            while (r + 1 < n && diffRight > Math.abs(b[r + 1] - b[i] - (b[n - 1] - b[r + 1]))) {
                r++;
            }
            long p = b[l];
            long q = b[i] - b[l];
            long x = b[r] - b[i];
            long y = b[n - 1] - b[r];
            long max = Math.max(Math.max(p, q), Math.max(x, y));
            long min = Math.min(Math.min(p, q), Math.min(x, y));
            ans = Math.min(ans, Math.abs(max - min));
        }

        System.out.println(ans);

    }

}

import java.util.*;
import static java.lang.Math.*;
import java.math.BigInteger;

public class Main {
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		// 入力
		int n = sc.nextInt();
		long[] a = new long[n];
		long[] sum = new long[n+1];
		for(int i = 0; i < n; i++){
		    a[i] = sc.nextInt();
		    sum[i+1] = sum[i] + a[i];
		}

		// 計算
		long result = Long.MAX_VALUE;
		for(int i = 2; i < n-1; i++){
		    long sumLeft = sum[i] - sum[0];
		    long sumRight = sum[n] - sum[i];
		    long[] left = calc(Arrays.copyOfRange(a, 0, i), sumLeft);
		    long[] right = calc(Arrays.copyOfRange(a, i, n), sumRight);
		    long max = max(left[1], max(left[2], max(right[1], right[2])));
		    long min = min(left[1], min(left[2], min(right[1], right[2])));
		    result = min(result, max - min);
		}
		// 出力
		System.out.println(result);
	}

	static long[] calc(long[] list, long sum){
	    long tmp = 0;
	    long[] res = new long[3];
	    for(int i = 0; i < list.length; i++){
	        tmp += list[i];
	        if(tmp >= sum/2){
	            if(abs(sum - 2*tmp) < abs(sum - 2*(tmp - list[i]))){
	                res[0] = i+1;
	                res[1] = tmp;
	                res[2] = sum - tmp;
	            }else{
	                res[0] = i;
	                res[1] = tmp - list[i];
	                res[2] = sum - (tmp - list[i]);
	            }
	            return res;
	        }
	    }
	    return res;
	}
}

