		tr(a);
		int idx;
		long res = 1000000000000000L;
		for (int i = 1; i < n - 2; i++) {
			long ma = 1000000000000000L;
			long mi = 0;
			idx = upper_bound(a, 0, i + 1, a[i + 1] / 2) - 1;
			if (idx >= 0) {
				ma = Math.min(ma, Math.max(a[idx], a[i + 1] - a[idx]));
				mi = Math.max(mi, Math.min(a[idx], a[i + 1] - a[idx]));
			}
			idx++;
			if (idx <= i + 1) {
				ma = Math.min(ma, Math.max(a[idx], a[i + 1] - a[idx]));
				mi = Math.max(mi, Math.min(a[idx], a[i + 1] - a[idx]));
			}
			long mma = 1000000000000000L;
			long mmi = 0;
			idx = upper_bound(a, i + 1, n, a[i + 1] + (a[n] - a[i + 1]) / 2) - 1;
			if (idx >= i + 1) {
				mma = Math.min(mma, Math.max(a[idx] - a[i + 1], a[n] - a[idx]));
				mmi = Math.max(mmi, Math.min(a[idx] - a[i + 1], a[n] - a[idx]));
			}
			idx++;
			if (idx <= n) {
				mma = Math.min(mma, Math.max(a[idx] - a[i + 1], a[n] - a[idx]));
				mmi = Math.max(mmi, Math.min(a[idx] - a[i + 1], a[n] - a[idx]));
			}
			res = Math.min(res, Math.max(mma, ma) - Math.min(mi, mmi));
		}
		out.println(res);
	}

	public static int upper_bound(long[] a, int fromIndex, int toIndex, long val) {
		if (val >= a[toIndex])
			return toIndex + 1;
		if (val < a[fromIndex])
			return fromIndex;
		int lb = fromIndex - 1, ub = toIndex;
		while (ub - lb > 1) {
			int mid = (ub - lb) / 2 + lb;
			if (a[mid] > val) {
				ub = mid;
			} else {
				lb = mid;
			}
		}
		return ub;
	}

