import static java.lang.Math.abs;
import static java.lang.Math.min;


public class Main {
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = fsc.nextLong();
        }
        long[] s = ArrayUtil.cumsum(a);
        long ans = Const.LINF;
        for (int p = 0; p <= n; p++) {
            int l, r;
            l = 0;
            r = p;
            while (r - l > 1) {
                int m = l + (r - l) / 2;
                if (sum(s, 0, m) * 2 <= sum(s, 0, p)) {
                    l = m;
                } else {
                    r = m;
                }
            }
            long w, x;
            if (del(s, 0, l, l, p) < del(s, 0, r, r, p)) {
                w = sum(s, 0, l);
                x = sum(s, l, p);
            } else {
                w = sum(s, 0, r);
                x = sum(s, r, p);
            }

            l = p;
            r = n;
            while (r - l > 1) {
                int m = l + (r - l) / 2;
                if (sum(s, p, m) * 2 <= sum(s, p, n)) {
                    l = m;
                } else {
                    r = m;
                }
            }
            long y, z;
            if (del(s, p, l, l, n) < del(s, p, r, r, n)) {
                y = sum(s, p, l);
                z = sum(s, l, n);
            } else {
                y = sum(s, p, r);
                z = sum(s, r, n);
            }
            long min = LongUtil.min(w, x, y, z);
            long max = LongUtil.max(w, x, y, z);
            ans = min(ans, max - min);
        }
        System.out.println(ans);
    }

    public static long sum(long[] s, int l, int r) {
        return s[r] - s[l];
    }

    public static long del(long[] s, int l1, int r1, int l2, int r2) {
        return abs(sum(s, l1, r1) - sum(s, l2, r2));
    }
}


class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}


class LongUtil {
    public static long min(long... a) {
        long ret = Const.LINF;
        for (long c : a) ret = Math.min(ret, c);
        return ret;
    }

    public static long max(long... a) {
        long ret = -Const.LINF;
        for (long c : a) ret = Math.max(ret, c);
        return ret;
    }

    /**
     * Caluculate the ceil of a/b. Returns the smallest integer greater than or
     * equal to a/b while 'a/b' rounds fractional parts to ZERO.
     * 
     * @param a
     * @param b
     * @return the smallest integer greater than or equal to a/b
     */
    public static long cld(long a, long b) {
        if (a > 0 && b > 0) return (a + b - 1) / b;
        else if (a < 0 && b < 0) return (a + b + 1) / b;
        else return a / b;
    }

    /**
     * Caluculate the floor of a/b. Returns the largest integer less than or equal
     * to a/b while 'a/b' rounds fractional parts to ZERO.
     * 
     * @param a
     * @param b
     * @return the largest integer less than or equal to a/b
     */
    public static long fld(long a, long b) {
        if (a <= 0 && b > 0) return (a - b + 1) / b;
        else if (a > 0 && b <= 0) return (a - b - 1) / b;
        else return a / b;
    }

    public static long fold(LongBinaryOperator func, long a, long... b) {
        long ret = a;
        for (long c : b) ret = func.applyAsLong(ret, c);
        return ret;
    }
}

