import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		long sum = 0;
		long[] sums = new long[4];
		long[] a = new long[n];

		for(int i=0;i<n;i++) {
			long input = in.nextLong();
			sum = sum + input;
			a[i] = input;
		}

		long ave = sum/4;

		int[] lastIdx = new int[4];

		long min = Long.MAX_VALUE;

		for(int i=0;i<8;i++) {
			sums[0]=sums[1]=sums[2]=0;
			for(int j=0;j<3;j++) {
				if(j==0) lastIdx[j] = -1;
				else lastIdx[j] = lastIdx[j-1];
				if(((i>>j)&1)==0) {
					while(lastIdx[j]<n-2 && sums[j]+a[lastIdx[j]+1]<ave) {
						lastIdx[j]++;
						sums[j] = sums[j] + a[lastIdx[j]];
					}
				}else {
					while(lastIdx[j]<n-2 && sums[j]<ave) {
						lastIdx[j]++;
						sums[j] = sums[j] + a[lastIdx[j]];
					}
				}
			}
			sums[3] = sum - sums[0] - sums[1] - sums[2];
			long absDif = getAbsoluteDifference(sums);
			if(absDif<min) min=absDif;
		}
		System.out.println(min);
	}

	public static long getAbsoluteDifference(long[] sums) {
		long min = Math.min(Math.min(sums[0], sums[1]), Math.min(sums[2], sums[3]));
		long max = Math.max(Math.max(sums[0], sums[1]), Math.max(sums[2], sums[3]));
		return max - min;
	}

}

import java.util.Scanner;

public class Main {
    public long getMaxDif(long[] s, int x, int y, int z) {
        long[] a = {0, 0, 0, 0};
        a[0] = s[x];
        a[1] = s[y] - s[x];
        a[2] = s[z] - s[y];
        a[3] = s[s.length - 1] - s[z];
        long max = a[0];
        long min = a[0];
        for (int i = 1; i < 4; ++i) {
            if (a[i] > max) {
                max = a[i];
            }
            if (a[i] < min) {
                min = a[i];
            }
        }
        return max - min;
    }

    public static void main(String[] args) {
        Scanner stdIn = new Scanner(System.in);
        int n = stdIn.nextInt();
        long[] array1 = new long[n];
        long[] array2 = new long[n];
        array1[0] = stdIn.nextLong();
        array2[0] = array1[0];
        for (int i = 1; i < n; ++i) {
            array1[i] = stdIn.nextLong();
            array2[i] = array2[i-1] + array1[i];
        }
        long mindif = Long.MAX_VALUE;
        int[] num = new int[3];
        for (int i1 = 0; i1 < n - 3; ++i1) {
            for (int i2 = i1 + 1; i2 < n - 2; ++i2) {
                for (int i3 = i2 + 1; i3 < n - 1; ++i3) {
