import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;
	private long ans = Long.MAX_VALUE;

	void solve() throws IOException {
		int[] a = nia(ni());
//		Helper.tr(a);
		long sum = 0;
		for (int i = 0; i < a.length; i++)
			sum += a[i];
		solve(a, 0, 4, sum, new long[4]);
		out.println(ans);
	}

	private void solve(int[] a, int i, int parts, long sum, long[] preSums) {
//		Helper.tr(i, parts, sum, preSums);
		if (parts == 1) {
			preSums[3] = sum;
//			Helper.tr("->", preSums);
			long min = Long.MAX_VALUE;
			long max = Long.MIN_VALUE;
			for (int j = 0; j < 4; j++) {
				min = Math.min(preSums[j], min);
				max = Math.max(preSums[j], max);
			}
			ans = Math.min(ans, max - min);
//			Helper.tr("->>", ans);
			return;
		}
		long s = 0;
		int j = i;
		while (j <= a.length - parts && (s + a[j]) * parts < sum) {
			s += a[j];
			j++;
		}
		preSums[4 - parts] = s;
		if (j > i)
			solve(a, j, parts - 1, sum - s, preSums);
		if (j < a.length - 1) {
			s += a[j];
			preSums[4 - parts] = s;
			solve(a, j + 1, parts - 1, sum - s, preSums);
			if (j + 1 < a.length - 1) {
				s += a[j + 1];
				preSums[4 - parts] = s;
				solve(a, j + 2, parts - 1, sum - s, preSums);
			}
		}

	}

	String ns() throws IOException {
		while (!tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine(), " ");
		}
		return tok.nextToken();
	}

	int ni() throws IOException {
		return Integer.parseInt(ns());
	}

	long nl() throws IOException {
		return Long.parseLong(ns());
	}

	double nd() throws IOException {
		return Double.parseDouble(ns());
	}

	String[] nsa(int n) throws IOException {
		String[] res = new String[n];
		for (int i = 0; i < n; i++) {
			res[i] = ns();
		}
		return res;
	}

	int[] nia(int n) throws IOException {
		int[] res = new int[n];
		for (int i = 0; i < n; i++) {
			res[i] = ni();
		}
		return res;
	}

	long[] nla(int n) throws IOException {
		long[] res = new long[n];
		for (int i = 0; i < n; i++) {
			res[i] = nl();
		}
		return res;
	}

	public static void main(String[] args) throws IOException {
		in = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);
		tok = new StringTokenizer("");
		Main main = new Main();
		main.solve();
		out.close();
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

class Program
{
    static void Main()
    {
        var N = int.Parse(ReadLine());
        var A = ReadLine().Split().Select(int.Parse).ToArray();
        var B = new int[N + 1];
        for (int i = 0; i < N; i++)
        {
            B[i + 1] = B[i] + A[i];
        }

        var s2 = LowerBound(B, B[N] / 2);
        var s1 = LowerBound(B, B[N] / 4);
        var s3 = LowerBound(B, B[N] / 2 + B[N] / 4);
        var ans = long.MaxValue;
        var n = N + 1;
        for (int i = s1 - 25; i < 50; i++)
        {
            for (int j = s2 - 25; j < 50; j++)
            {
                for (int k = s3 - 25; k < 50; k++)
                {
                    if ((uint)i < n && (uint)j < n && (uint)k < n)
                    {
                        var can = Math.Max(Math.Max(B[i] - B[0], B[j] - B[i]), Math.Max(B[k] - B[j], B[N] - B[k])) - Math.Min(Math.Min(B[i] - B[0], B[j] - B[i]), Math.Min(B[k] - B[j], B[N] - B[k]));
                        ans = Math.Min(can, ans);
                    }
                }
            }
        }
        WriteLine(ans);
    }

    static int LowerBound(int[] a, int x)
    {
        var low = -1;
        var high = a.Length;
        while (high - low != 1)
        {
            var mid = (low + high) / 2;
            if (x <= a[mid])
            {
                high = mid;
            }
            else
            {
                low = mid;
            }
        }
        return high;
    }
}

