    void chmin<T>(ref T a, T b) where T : IComparable<T> { a = a.CompareTo(b) < 0 ? a : b; }

    void solve()
    {
        int N = cin.nextint;
        var A = cin.scanlong;
        var B = new long[N];
        B[0] = A[0];
        for (int i = 1; i < N; i++)
        {
