        }

        long ans = long.MaxValue;
        for (int i = 1; i <= N - 3; i++)//iの後ろを真ん中カットとする
        {
            int x = upper_bound(B, B[i] / 2);
            var D = new long[4];
            D[0] = B[x];
            D[1] = B[i] - B[x];
            if (x > 0 && Abs(B[x - 1] - B[i] / 2) < Abs(B[x] - B[i] / 2))
            {
                D[0] = B[x - 1];
                D[1] = B[i] - B[x - 1];
            }


            var S = B[i] + (B[N - 1] - B[i]) / 2;

            x = upper_bound(B, S);
            D[2] = B[x] - B[i];
            D[3] = B[N - 1] - B[x];
            if (x > i + 1 && Abs(B[x - 1] - S) < Abs(B[x] - S))
            {
                D[2] = B[x - 1] - B[i];
                D[3] = B[N - 1] - B[x - 1];
            }

            if (i == 3)
            {
                //WriteLine(string.Join(" ", D));
            }
            chmin(ref ans, D.Max() - D.Min());
        }

        WriteLine(ans);
    }

    int upper_bound(long[] arr, long val)
    {
        int low = 0, high = arr.Count();
        int mid;

        while (low < high)
        {
            mid = ((high - low) >> 1) + low;
            if (arr[mid] < val) low = mid + 1;
            else high = mid;
        }
        return low;
    }

}

