public class Hello
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        string[] line = Console.ReadLine().Trim().Split(' ');
        var a = Array.ConvertAll(line, int.Parse);
        var b = new int[n + 1];
        b[1] = a[0];
        for (int i = 1; i < n; i++)
            b[i + 1] = b[i] + a[i];
        var ret = int.MaxValue;
        for (int i = 2; i <= n - 2; i++)
        {
            var ans = new int[4];
            var p1 = getL(a, b, i);
            var p2 = getr(a, b, i);
            ans[0] = p1.p1;  ans[1] = p1.p2;  ans[2] = p2.p1;  ans[3] = p2.p2;
            var t = ans.Max() - ans.Min();
            if (t < ret) ret = t;
        }
        Console.WriteLine(ret);
    }
    public  static P getr(int[] a, int[] b, int k)
    {
        var n = a.Length;
        if (k ==  n -2) return new P { p1 = a[n -1], p2 = a[n -2] };
        var tsum = b[n] - b[k ];
        var ret = int.MaxValue; var retL = 0; var retr = 0;
        for (int i = k; i <= n; i++)
        {
            var sumL = b[i] - b[k];
            var sumr = tsum - sumL;
            var w = Math.Abs(sumL - sumr);
            if (w < ret) { ret = w; retL = sumL; retr = sumr; }
        }
        return new P { p1 = retL, p2 = retr };
    }
    public static P getL (int[] a, int[] b, int k)
    {
        if (k == 2) return new P { p1 = a[0], p2 = a[1] };
        var tsum = b[k];
        var ret = int.MaxValue;  var retL = 0;  var retr = 0;
        for (int i = 1; i <= k-1; i++)
        {
            var sumL = b[i];
            var sumr = tsum - sumL;
            var w = Math.Abs(sumL - sumr);
            if ( w < ret) { ret = w; retL = sumL; retr = sumr;  }
        }
        return new P { p1 = retL, p2 = retr };
    }
}

