        {
            var N = ReadLong();
            var array = ReadLongArray();

            var cum = CumulativeSum(array).ToArray();
            var res = new List<long>();
            for (int i = 2; i < N-1; i++)
            {
                var left = 0;
                var right = N - 2;
                long half = cum[i];
                while (left < i && cum[left] < half / 2)
                {
                    left++;
                }
                while (right > i && cum[right] - half > (cum[N-1] - half)/2)
                {
                    right--;
                }
                var candidate = new long[] { cum[left-1], half - cum[left-1], cum[right+1] - half, cum[N-1] - cum[right+1] };
                res.Add(candidate.Max() - candidate.Min());
                candidate = new long[] { cum[left], half - cum[left], cum[right+1] - half, cum[N-1] - cum[right+1] };
                res.Add(candidate.Max() - candidate.Min());
                candidate = new long[] { cum[left-1], half - cum[left-1], cum[right] - half, cum[N-1] - cum[right] };
                res.Add(candidate.Max() - candidate.Min());
                candidate = new long[] { cum[left], half - cum[left], cum[right] - half, cum[N-1] - cum[right] };
                res.Add(candidate.Max() - candidate.Min());
            }
            WriteLine(res.Min());
        }
    }
