using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

using static System.Console;
using static PB10004.Algorithm.Util;

namespace PB10004.Algorithm
{
    class Template
    {
        static void Main(string[] args)
        {
            var N = ReadLong();
            var array = ReadLongArray();

            var cum = CumulativeSum(array).ToArray();

            long[] D1 = new long[N];
            long i = 0;
            long c = 0;
            while (i < N)
            {
                if (IsBestL(i, c, cum, N))
                {
                    D1[i] = c;
                    i++;
                }
                else
                    c++;
            }

            long[] D2 = new long[N];
            i = N - 1;
            c = N - 1;
            while (i >= 0)
            {
                if (IsBestR(i, c, cum, N))
                {
                    D2[i] = c;
                    i--;
                }
                else
                    c--;
            }
            long best = long.MaxValue;
            for (i = 0; i < N; i++)
            {
                long c1 = D1[i];
                long c2 = i;
                long c3 = D2[i];
                long c4 = N - 1;
                long p1 = cum[c1];
                long p2 = cum[c2] - cum[c1];
                long p3 = cum[c3] - cum[c2];
                long p4 = cum[c4] - cum[c3];

                long mn = Math.Min(p1, Math.Min(p2, Math.Min(p3, p4)));
                long mx = Math.Max(p1, Math.Max(p2, Math.Max(p3, p4)));
                best = Math.Min(best, mx - mn);
            }
            WriteLine(best);
        }
        static bool IsBestL(long i, long c, long[] S, long N)
        {
            if (c == i) return true;
            long s = S[i];
            long sc = S[c];
            long sn = S[c + 1];
            long current = Math.Abs(s - 2 * sc);
            long next = Math.Abs(s - 2 * sn);
            return current <= next;
        }

        static bool IsBestR(long i, long c, long[] S, long N)
        {
            if (c == i) return true;
            long s = S[N - 1] - S[i];
            long sc = S[N - 1] - S[c];
            long sn = S[N - 1] - S[c - 1];
            long current = Math.Abs(s - 2 * sc);
            long next = Math.Abs(s - 2 * sn);
            return current <= next;
        }
    }
