    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var a = new int[N + 1];
            Array.Copy(consoleReader.Split.Int, 0, a, 1, N);
            var sums = a.ToArray();
            for (int i = 1; i < sums.Length; i++)
                sums[i] += sums[i - 1];

            var pq = 2;
            var rs = 4;
            var min = int.MaxValue;
            for (int i = 3; i < sums.Length - 1; i++)
            {
                while (pq < i - 1)
                {
                    var pq1 = Math.Abs(sums[pq - 1] - (sums[i - 1] - sums[pq - 1]));
                    var pq2 = Math.Abs(sums[pq] - (sums[i - 1] - sums[pq]));
                    if (pq2 < pq1) ++pq;
                    else break;
                }
                while (rs < sums.Length - 1)
                {
                    var rs1 = Math.Abs((sums[rs - 1] - sums[i - 1]) - (sums[sums.Length - 1] - sums[rs - 1]));
                    var rs2 = Math.Abs((sums[rs] - sums[i - 1]) - (sums[sums.Length - 1] - sums[rs]));
                    if (rs2 < rs1) ++rs;
                    else break;
                }
                var pqrs = new[] { sums[pq - 1], sums[i - 1] - sums[pq - 1], sums[rs - 1] - sums[i - 1], sums[sums.Length - 1] - sums[rs - 1] };
                Array.Sort(pqrs);
                min = Math.Min(min, pqrs.Last() - pqrs.First());
            }

            return min;
        }


        #region いつもの
        private readonly ConsoleReader consoleReader;
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc()); static string AllLines<T>(IEnumerable<T> source) => string.Join("\n", source);
        #endregion
    }

