public class Program
{

    public void Proc()
    {
        int inputCount = int.Parse(Reader.ReadLine());
        this.Items = Reader.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();
        this.RuisekiWa = new long[inputCount];

        for (int i = 0; i < Items.Length; i++) {
            if(i==0) {
                this.RuisekiWa[0] = this.Items[0];
            }     else {
                this.RuisekiWa[i] = this.RuisekiWa[i - 1] + this.Items[i];
            }
        }

        long ans = long.MaxValue;

        for (int i = 1; i < Items.Length - 2; i++) {
            ans = Math.Min(ans, GetAns(i));            
        }
        Console.WriteLine(ans);

    }


    private long GetAns(int idx) {
        int firstSectionLast = GetIdx(0, idx, 0, idx - 1);
        long num1 = GetValue(0, firstSectionLast);
        long num2 = GetValue(firstSectionLast + 1, idx);

        int thirdSectionLast = GetIdx(idx + 1, Items.Length - 1, idx + 1, Items.Length - 2);

        long num3 = GetValue(idx + 1, thirdSectionLast);
        long num4 = GetValue(thirdSectionLast + 1, Items.Length - 1);

        long min = Math.Min(num1, Math.Min(num2, Math.Min(num3, num4)));
        long max = Math.Max(num1, Math.Max(num2, Math.Max(num3, num4)));

        return Math.Abs(max - min);
    }

    private int GetIdx(int startIdx, int endIdx, int min, int max) {
        if(max - min <= 2) {
            int mid = (max + min) / 2;
            long num1 = Math.Abs(GetValue(startIdx, min) - GetValue(min + 1, endIdx));
            long num2 = Math.Abs(GetValue(startIdx, mid) - GetValue(mid + 1, endIdx));
            long num3 = Math.Abs(GetValue(startIdx, max) - GetValue(max + 1, endIdx));
            if(num1<=num2&&num1 <= num3) {
                return min;
            } else if(num2 <= num1 && num2 <= num3){
                return mid;
            } else {
                return max;
            }
        }
        int mid1 = min + (max - min) / 3;
        int mid2 = max - (max - min) / 3;

        long val1 = Math.Abs(GetValue(startIdx, min) - GetValue(min + 1, endIdx));
        long val2 = Math.Abs(GetValue(startIdx, mid1) - GetValue(mid1 + 1, endIdx));
        long val3 = Math.Abs(GetValue(startIdx, mid2) - GetValue(mid2 + 1, endIdx));
        long val4 = Math.Abs(GetValue(startIdx, max) - GetValue(max + 1, endIdx));

        long minVal = new long[] { val1, val2, val3, val4 }.Min();
        if(val1 == minVal) {
            return GetIdx(startIdx, endIdx, min, mid1);
        } else if(val2 == minVal) {
            return GetIdx(startIdx, endIdx, min, mid2);
        } else if(val3 == minVal) {
            return GetIdx(startIdx, endIdx, mid1, max);
        } else {
            return GetIdx(startIdx, endIdx, mid2, max);
        }
    }

    private long GetValue(int startIdx, int endIdx) {
        long val = RuisekiWa[endIdx];
        if(startIdx > 0) {
            val -= RuisekiWa[startIdx - 1];
        }
        return val;
    }

