using System;
using System.Collections.Generic;
using System.Linq;
class Program
{
    static void Main(string[] args)
    {
        var N = long.Parse(Console.ReadLine());
        var array = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
        var div = SearchDiv(array, true);
        List<long> v1 = new List<long>();
        for (int i = 0; i < div; i++)
        {
            v1.Add(array[i]);
        }
        List<long> v2 = new List<long>();
        for (int i = div; i < N; i++)
        {
            v2.Add(array[i]);
        }
        var first = SearchDiv(v1.ToArray(),false);
        var second = div;
        var third = div + SearchDiv(v2.ToArray(), false);
        Console.WriteLine(CalcDiv4(array, first,second,third));
    }
    static int SearchDiv(long[] array, bool first)
    {
        if (array.Length == 2)
        {
            return 1;
        }
        int argMin;
        if (!first)
        {
            long min = CalcDiv2(array, 1);
            argMin = 1;
            for (int i = 2; i < array.Length - 1; i++)
            {
                var val = CalcDiv2(array, i);
                if (min > val)
                {
                    min = val;
                    argMin = i;
                }
            }
        }
        else
        {
            long min = CalcDiv2(array, 2);
            argMin = 2;
            for (int i = 3; i < array.Length - 1; i++)
            {
                var val = CalcDiv2(array, i);
                if (min > val)
                {
                    min = val;
                    argMin = i;
                }
            }
        }
        return argMin;
    }
    static long CalcDiv2(long[] array, int div)
    {
        long s1 = 0;
        long s2 = 0;
        for (int i = 0; i < div; i++)
        {
            s1 += array[i];
        }
        for (int i = div; i < array.Length; i++)
        {
            s2 += array[i];
        }
        return Math.Min(s1, s2);
    }
    static long CalcDiv4(long[] array, int first, int second, int third)
    {
        var res = new long[4];
        res[0] = 0;
        res[1] = 0;
        res[2] = 0;
        res[3] = 0;
        for (int i = 0; i < first; i++)
        {
            res[0] += array[i];
        }
        for (int i = first; i <second; i++)
        {
            res[1] += array[i];
        }
        for (int i = second; i < third; i++)
        {
            res[2] += array[i];
        }
        for (int i = third; i < array.Length; i++)
        {
            res[3] += array[i];
        }
        return res.Max() - res.Min();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;
using static System.Int32;

class Program
{
    static void Main(string[] args)
    {
        label:
        int n = Parse(ReadLine());
        var ruiseki = new long[n];
        var sp = ReadLine().Split();
        long tmp = 0;
        for (int i = 0; i < sp.Length; ++i)
        {
            tmp += long.Parse(sp[i]);
            ruiseki[i] = tmp;
        }
        int left = 0;
        var splits = new long[n - 2, 4];
        for (int naka = 1; naka < n - 2; ++naka)
        {
            long diff = Math.Abs(ruiseki[naka] - ruiseki[left] * 2);
            for (int newLeft = left + 1; newLeft < naka; ++newLeft)
            {
                tmp = Math.Abs(ruiseki[naka] - ruiseki[newLeft] * 2);
                if (tmp < diff)
                {
                    left = newLeft;
                    diff = tmp;
                }
                else
                {
                    break;
                }
            }
            splits[naka - 1, 0] = ruiseki[left];
            splits[naka - 1, 1] = ruiseki[naka] - ruiseki[left];
            //WriteLine($"{naka + 1}:{splits[naka - 1, 0]}/{splits[naka - 1, 1]}  diff[{Math.Abs(splits[naka - 1, 0] - splits[naka - 1, 1])}]({left + 1}:{naka - left})");
        }
        int right = n - 2;
        for (int naka = n - 3; 1 <= naka; --naka)
        {
            long all = ruiseki[n - 1] + ruiseki[naka];
            long diff = Math.Abs(all - ruiseki[right] * 2);
            for (int newRight = right - 1; naka < newRight; --newRight)
            {
                tmp = Math.Abs(all - ruiseki[newRight] * 2);
                if (tmp < diff)
                {
                    right = newRight;
                    diff = tmp;
                }
                else
                {
                    break;
                }
            }
            splits[naka - 1, 2] = ruiseki[right] - ruiseki[naka];
            splits[naka - 1, 3] = ruiseki[n - 1] - ruiseki[right];
            //WriteLine($"{n - naka - 1}:{splits[naka - 1, 2]}/{splits[naka - 1, 3]}  diff[{Math.Abs(splits[naka - 1, 2] - splits[naka - 1, 3])}]({right - naka}:{n - right - 1})");
        }
        long result = long.MaxValue;
        for(int i = 0; i < n - 3; ++i)
        {
            long max = splits[i, 0];
            long min = max;
            for(int j = 1; j < 4; ++j)
            {
                max = Math.Max(max, splits[i, j]);
                min = Math.Min(min, splits[i, j]);
            }
            result = Math.Min(result, max - min);
        }
        WriteLine(result);
    }
}

