namespace AtTest.ABC_102
{
    class ABC_102_D
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            string[] input = Console.ReadLine().Split(' ');
            long[] array = new long[n];
            long[] sums = new long[n];//累積和
            for (int i = 0; i < n; i++)
            {
                array[i] = int.Parse(input[i]);
                if (i == 0)
                {
                    sums[i] = array[i];
                }
                else
                {
                    sums[i] = sums[i - 1] + array[i];
                }
            }

            long min = 0;
            int leftIndex = 0, rightIndex = 2;
            long[] rangeSums = new long[4];
            for (int i = 2; i < n - 1; i++)//真ん中の区切り数ループ
            {
                while (leftIndex < i - 1
                    && Math.Abs(sums[i - 1] - 2 * sums[leftIndex + 1])
                    < Math.Abs(sums[i - 1] - 2 * sums[leftIndex]))
                {
                    leftIndex++;
                }
                while (rightIndex < n - 1
                    && Math.Abs(sums[n - 1] - 2 * sums[rightIndex + 1] + sums[i - 1])
                    < Math.Abs(sums[n - 1] - 2 * sums[rightIndex] + sums[i - 1]))
                {
                    rightIndex++;
                }
                rangeSums[0] = sums[leftIndex];
                rangeSums[1] = sums[i - 1] - sums[leftIndex];
                rangeSums[2] = sums[rightIndex] - sums[i - 1];
                rangeSums[3] = sums[n - 1] - sums[rightIndex];
                Array.Sort(rangeSums);
                if (i == 2 || rangeSums[3] - rangeSums[0] < min)
                {
                    min = rangeSums[3] - rangeSums[0];
                }
            }

            Console.WriteLine(min);
        }
    }
}

using System;
using System.Linq;
using static System.Math;

class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Console.ReadLine().Split().Select(int.Parse).ToArray();
		var s = new long[n + 1];
		for (int i = 0; i < n; i++) s[i + 1] = s[i] + a[i];

		var r = long.MaxValue;
		for (int i = 2; i < n - 1; i++)
		{
			long s1 = s[i], s2 = s[n] - s1;
			long sh1 = s1 / 2, sh2 = s1 + s2 / 2;

			var i1 = Array.BinarySearch(s, sh1);
			if (i1 < 0) i1 = ~i1;
			if (i1 == i || sh1 - s[i1 - 1] <= s[i1] - sh1) i1--;
			long M1 = Max(s[i1], s1 - s[i1]), m1 = s1 - M1;

			var i2 = Array.BinarySearch(s, sh2);
			if (i2 < 0) i2 = ~i2;
			if (i2 == n + 1 || sh2 - s[i2 - 1] <= s[i2] - sh2) i2--;
			long M2 = Max(s[i2] - s1, s[n] - s[i2]), m2 = s2 - M2;

			r = Min(r, Max(M1, M2) - Min(m1, m2));
		}
		Console.WriteLine(r);
	}
}

