using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

namespace TOPSIC
{
	public class Program
	{
		/// <summary>
		/// ABC 102
		/// </summary>
		public static void Main()
		{
			int n = int.Parse(ReadLine());
			var list = ReadLine().Split().Select(x => int.Parse(x))
				.ToList();

			// 高速化のために、累積和を先に求めておく
			var sum = new List<double>();
			sum.Add(list[0]);
			for(int i = 1; i<n; i++)
			{
				sum.Add(sum[i - 1] + list[i]);
			}

			// 目的は左右の合計の差の最小値を探すこと。
			double min = double.MaxValue;
			var list2 = new double[4];

			// 中央の区切り
			for (int i = 1; i<n; i++)
			{
				// 左の区切り
				var leftMin = double.MaxValue;
				var leftTotal = sum[i];
				for (int j = 0; j < i; j++)
				{
					var leftA = sum[j];
					var leftB = leftTotal - leftA;
					var leftD = Math.Abs(leftA - leftB);
					if (leftD < leftMin)
					{
						leftMin = leftD;
						list2[0] = leftA;
						list2[1] = leftB;
					}

					// 右の区切りを決める
					var rightMin = double.MaxValue;
					var rightSum = 0D;
					var rightTotal = (double)list.Skip(i+1).Sum();
					for (int k = i + 1; k < n; k++)
					{
						rightSum += list[k];

						var rightA = rightSum;
						var rightB = rightTotal - rightA;
						var rightD = Math.Abs(rightA - rightB);
						if (rightD < rightMin)
						{
							rightMin = rightD;
							list2[2] = rightA;
							list2[3] = rightB;
						}

						var m = Math.Abs(list2.Max() - list2.Min());
						if (m < min)
						{
							min = m;
						}
					}
				}
			}

			WriteLine(min);
		}
	}
}

