        public static void Main(string[] args)
        {
            // A(); 2m
            // B(); 3m
            // C(); 13m
            D();
        }

        public static void D()
        {
            long N = rl;
            long[] A = rla;
            long[] S = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                S[i + 1] = S[i] + A[i];
            }

            bool[,] visited = new bool[N + 1, 4];
            Pair[,] memo = new Pair[N + 1, 4];
            Func<long, long, Pair> rec = null;
            rec = (i, cut) =>
            {
                if (visited[i, cut]) return memo[i, cut];
                if (i > N)
                {
                    visited[i, cut] = true;
                    return null;
                }
                if (cut == 3)
                {
                    long s = S[N] - S[i];
                    var p = new Pair(s, s);
                    visited[i, cut] = true;
                    memo[i, cut] = p;
                    return p;
                }
                else
                {
                    long max = -INF, min = INF;
                    bool ok = false;
                    for (int j = (int)i + 1; j <= N; j++)
                    {
                        long max1 = S[j] - S[i];
                        long min1 = max1;
                        var p1 = rec(j, cut + 1);
                        if (p1 == null)
                            continue;
                        ok = true;
                        ChMax(ref max1, p1.Item1);
                        ChMin(ref min1, p1.Item2);
                        if(Abs(max-min) > Abs(max1-min1))
                        {
                            max = max1;
                            min = min1;
                        }
                    }
                    visited[i, cut] = true;
                    memo[i, cut] = ok ? new Pair(max, min) : null;
                    return memo[i, cut];
                }
            };

            var ans = rec(0, 0);
            Console.WriteLine(ans.Item1 - ans.Item2);
        }

