        public static void D()
        {
            long N = rl;
            long[] A = rla;
            long[] S = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                S[i + 1] = S[i] + A[i];
            }

            Pair[,] memo = new Pair[N + 1, 4];
            Func<long, long, Pair> rec = null;
            rec = (i, cut) =>
            {
                if (memo[i, cut] != null) return memo[i, cut];
