                else
                {
                    long max = -INF, min = INF;
                    bool ok = false;
                    for (int j = (int)i + 1; j <= N; j++)
                    {
                        long max1 = S[j] - S[i];
                        long min1 = max1;
                        var p1 = rec(j, cut + 1);
                        if (p1 == null)
                            continue;
                        ok = true;
                        ChMax(ref max1, p1.Item1);
                        ChMin(ref min1, p1.Item2);
                        if(Abs(max-min) > Abs(max1-min1))
                        {
                            max = max1;
                            min = min1;
                        }
                    }
                    memo[i, cut] = ok ? new Pair(max, min) : null;
                    return memo[i, cut];
                }
            };

            var p = rec(0, 0);
            Console.WriteLine(p.Item1 - p.Item2);
        }

