    /// <summary>
    /// UnionFindTree
    /// </summary>
    public class UnionFindTree
    {
        public int[] Node;

        public UnionFindTree(int N)
        {
            Node = new int[N];
            for (int i = 0; i < N; i++)
            {
                Node[i] = -1;
            }
        }

        public bool IsSameGroup(int x, int y)
        {
            return GetRoot(x) == GetRoot(y);
        }

        public bool Merge(int x, int y)
        {
            int xr = GetRoot(x);
            int yr = GetRoot(y);

            if (xr == yr)
                return false;

            // xが、大きなグループを示すようにSwapする（値が小さい方が大きなグループ）
            if (Node[xr] > Node[yr])
                Swap(ref xr, ref yr);

            // グループの数を合算する
            Node[xr] += Node[yr];

            // 根を張り替える
            Node[yr] = xr;
            return true;
        }

        public int Size(int x)
        {
            return -Node[GetRoot(x)];
        }

        public int GetRoot(int n)
        {
            if (Node[n] < 0)
            {
                return n;
            }
            else
            {
                // 根を張りなおす。
                Node[n] = GetRoot(Node[n]);
                return Node[n];
            }
        }
    }

    /// <summary>
    /// PriorityQueue
    /// </summary>
    /// <typeparam name="T"></typeparam>
    public class PriorityQueue<T>
    {
        private Comparison<T> _comparison = null;
        private int _type = 0;

        private T[] _heap;
        private int _sz = 0;

        private int _count = 0;

        /// <summary>
        /// Priority queue
        /// </summary>
        /// <param name="maxSize">max size</param>
        /// <param name="type">0: asc, 1:desc</param>
        public PriorityQueue(int maxSize, int type = 0)
        {
            _heap = new T[maxSize];
            _type = type;
        }

        public PriorityQueue(int maxSize, Comparison<T> comparison)
        {
            _heap = new T[maxSize];
            _comparison = comparison;
        }

        private int Compare(T x, T y)
        {
            return _comparison(x, y);
            //if (_comparison != null) return _comparison(x, y);
            //return _type == 0 ? x.CompareTo(y) : y.CompareTo(x);
        }

        public void Push(T x)
        {
            _count++;

            //node number
            var i = _sz++;

            while (i > 0)
            {
                //parent node number
                var p = (i - 1) / 2;

                if (Compare(_heap[p], x) <= 0) break;

                _heap[i] = _heap[p];
                i = p;
            }

            _heap[i] = x;
        }

        public T Pop()
        {
            _count--;

            T ret = _heap[0];
            T x = _heap[--_sz];

            int i = 0;
            while (i * 2 + 1 < _sz)
            {
                //children
                int a = i * 2 + 1;
                int b = i * 2 + 2;

                if (b < _sz && Compare(_heap[b], _heap[a]) < 0) a = b;

                if (Compare(_heap[a], x) >= 0) break;

                _heap[i] = _heap[a];
                i = a;
            }

            _heap[i] = x;

            return ret;
        }

        public int Count()
        {
            return _count;
        }

        public T Peek()
        {
            return _heap[0];
        }

        public bool Contains(T x)
        {
            for (int i = 0; i < _sz; i++) if (x.Equals(_heap[i])) return true;
            return false;
        }

        public void Clear()
        {
            while (this.Count() > 0) this.Pop();
        }

        public IEnumerator<T> GetEnumerator()
        {
            var ret = new List<T>();

            while (this.Count() > 0)
            {
                ret.Add(this.Pop());
            }

            foreach (var r in ret)
            {
                this.Push(r);
                yield return r;
            }
        }

        public T[] ToArray()
        {
            T[] array = new T[_sz];
            int i = 0;

            foreach (var r in this)
            {
                array[i++] = r;
            }

            return array;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

class Program
{
    static void Main()
    {
        var N = int.Parse(ReadLine());
        var A = ReadLine().Split().Select(int.Parse).ToArray();
        var B = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            B[i + 1] = B[i] + A[i];
        }

        var s2 = LowerBound(B, B[N] / 2);
        var s1 = LowerBound(B, B[N] / 4);
        var s3 = LowerBound(B, B[N] / 2 + B[N] / 4);
        var ans = long.MaxValue;
        var n = N + 1;
        for (int i = s1 - 50; i < 100; i++)
        {
            for (int j = s2 - 50; j < 100; j++)
            {
                for (int k = s3 - 50; k < 100; k++)
                {
                    if ((uint)i < n && (uint)j < n && (uint)k < n && i != 0 && j != i && k != j && N != j)
                    {
                        var can = Math.Max(Math.Max(B[i] - B[0], B[j] - B[i]), Math.Max(B[k] - B[j], B[N] - B[k])) - Math.Min(Math.Min(B[i] - B[0], B[j] - B[i]), Math.Min(B[k] - B[j], B[N] - B[k]));
                        ans = Math.Min(can, ans);
                    }
                }
            }
        }
        WriteLine(ans);
    }

    static int LowerBound(long[] a, long x)
    {
        var low = -1;
        var high = a.Length;
        while (high - low != 1)
        {
            var mid = (low + high) / 2;
            if (x <= a[mid])
            {
                high = mid;
            }
            else
            {
                low = mid;
            }
        }
        return high;
    }
}

using System;
using System.Linq;
class Program {
  static long[] a;
  static int[] d;
  static long[] s;
  static long minGap;
  static void Main() {
    Console.ReadLine();
    a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
    d = new[] { 1, 2, 3, a.Length };
    s = new[] { a[0], a[1], a[2], a.Skip(3).Sum() };
    FlattenSums(2, 2, 3);
    minGap = s.Max() - s.Min();
    for (var i = 3; i < a.Length - 1; i++)
      SolveMin(i);
    Console.WriteLine(minGap);
  }

    static void SolveMin(int center) {
        s[1] += a[d[1]];
        s[2] -= a[d[1]];
        d[1] = center;
        FlattenSums(0, 0, 1);
        FlattenSums(2, 2, 3);
        var gap = s.Max() - s.Min();
        if (gap < minGap) minGap = gap;
    }

    static void FlattenSums(int di, int si1, int si2) {
        if (s[si1] >= s[si2]) return;
        for (var i = d[di] + 1; i < d[di + 1]; i++)
        {
            var s1 = s[si1] + a[d[di]];
            var s2 = s[si2] - a[d[di]];
            if (s1 <= s2)
            {
                s[si1] = s1;
                s[si2] = s2;
                d[di] = i;
            }
            else
            {
                if (s1 - s2 < s[si2] - s[si1])
                {
                    s[si1] = s1;
                    s[si2] = s2;
                    d[di] = i;
                }
                break;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

namespace AtCoder
{
	public class Program
	{
		/// <summary>
		/// ABC 102
		/// </summary>
		public static void Main()
		{
			int n = int.Parse(ReadLine());
			var list = ReadLine().Split().Select(x => int.Parse(x))
				.ToList();

			// 高速化のために、累積和を先に求めておく
			var sum = new List<double>();
			sum.Add(list[0]);
			for(int i = 1; i<n; i++)
			{
				sum.Add(sum[i - 1] + list[i]);
			}

			// 目的は左右の合計の差の最小値を探すこと。
			double min = double.MaxValue;
			var list2 = new double[4];

			// 中央の区切り
			for (int i = 1; i<n; i++)
			{
				// 左の区切り
				var leftMin = double.MaxValue;
				var leftTotal = sum[i];
				for (int j = 0; j < i; j++)
				{
					var leftA = sum[j];
					var leftB = leftTotal - leftA;
					var leftD = Math.Abs(leftA - leftB);
					if (leftD < leftMin)
					{
						leftMin = leftD;
						list2[0] = leftA;
						list2[1] = leftB;
					}

					// 右の区切りを決める
					var rightMin = double.MaxValue;
					var rightSum = 0D;
					var rightTotal = list.Skip(i+1).Sum();
					for (int k = i + 1; k < n; k++)
					{
						rightSum += list[k];

						var rightA = rightSum;
						var rightB = rightTotal - rightA;
						var rightD = Math.Abs(rightA - rightB);
						if (rightD < rightMin)
						{
							rightMin = rightD;
							list2[2] = rightA;
							list2[3] = rightB;
						}

						var m = Math.Abs(list2.Max() - list2.Min());
						if (m < min)
						{
							min = m;
						}
					}
				}
			}

			WriteLine(min);
		}
	}
}

