using System;
using System.Linq;
using static System.Console;
class Program {
  static long[] a;
  static int[] d;
  static long[] s;
  static void Main() {
    ReadLine();
    a = ReadLine().Split().Select(long.Parse).ToArray();
    var gap0 = Init();
    if (d[3] == 4) { WriteLine(gap0); return; }
    var gapMin = Enumerable.Range(3, d[3] - 4).Min(_ => NextGap());
    WriteLine(Math.Min(gap0, gapMin));
  }

static long Init()
{
    d = new[] { 1, 2, 3, a.Length };
    s = new[] { a[0], a[1], a[2], a.Skip(3).Sum() };
    Flatten(2);
    return s.Max() - s.Min();
}

static long NextGap()
{
    Slide(1);
    Flatten(0);
    Flatten(2);
    return s.Max() - s.Min();
}

static void Flatten(int di)
{
    var di2 = di + 1;
    if (s[di] >= s[di2]) return;
    while (d[di] + 1 < d[di2])
    {
        var s1 = s[di] + a[d[di]];
        var s2 = s[di2] - a[d[di]];
        if (s1 <= s2) Slide(di);
        else
        {
            if (s1 - s2 < s[di2] - s[di]) Slide(di);
            break;
        }
    }
}

static void Slide(int di)
{
    s[di] += a[d[di]];
    s[di + 1] -= a[d[di]++];
}
}

