namespace D
{
    class Program
    {

        private static MinAndMax data = new MinAndMax();

        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            long tmp = 0L;
            var sum = Console.ReadLine()
                .Split()
                .Select(i =>
                {
                    tmp += long.Parse(i);
                    return tmp;
                })
                .ToArray();

            long ans = long.MaxValue;
            MinAndMax leftData;
            MinAndMax rightData;
            for (var i = 2; i < N - 1; i++)
            {
                // dataの初期化
                data.Min = 0;
                data.Max = 10000000000;
                long[] left = new long[i];
                Array.Copy(sum, 0, left, 0, left.Length);
                LeftJudge(left, 0, left.Length - 1);
                leftData = data;

                // dataの初期化
                data.Min = 0;
                data.Max = 10000000000;
                long[] right = new long[N - i];
                Array.Copy(sum, i, right, 0, right.Length);
                RightJudge(right, 0, right.Length - 1, left[left.Length - 1]);
                rightData = data;

                long min = (leftData.Min < rightData.Min) ? leftData.Min : rightData.Min;
                long max = (leftData.Max > rightData.Max) ? leftData.Max : rightData.Max;
                ans = (max - min < ans) ? max - min : ans;
            }
            Console.WriteLine(ans);
        }

        static void RightJudge(long[] array, int lidx, int ridx, long offset = 0L)
        {
            int middle = (ridx + lidx) / 2;
            long left = array[middle] - offset;
            long right = array[array.Length - 1] - array[middle];
            if (Math.Abs(right - left) < data.Diff)
            {
                data.Min = (left < right) ? left : right;
                data.Max = (left > right) ? left : right;
            }
            if (left < right && ridx - lidx != 1)
            {
                RightJudge(array, middle, ridx, offset);
            }
            else if (left > right && ridx - lidx != 1)
            {
                RightJudge(array, lidx, middle, offset);
            }
        }

        static void LeftJudge(long[] array, int lidx, int ridx)
        {
            int middle = (ridx + lidx) / 2;
            long left = array[middle];
            long right = array[array.Length - 1] - array[middle];
            if (Math.Abs(right - left) < data.Diff)
            {
                data.Min = (left < right) ? left : right;
                data.Max = (left > right) ? left : right;
            }
            if (left < right && ridx - lidx != 1)
            {
                LeftJudge(array, middle, ridx);
            }
            else if (left > right && ridx - lidx != 1)
            {
                LeftJudge(array, lidx, middle);
            }
        }
    }
    struct MinAndMax
    {
        public long Min;
        public long Max;
        public long Diff { get { return Max - Min; } }
    }
}

