public class Program
{

    public void Proc()
    {
        int inputCount = int.Parse(Reader.ReadLine());
        this.Items = Reader.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();
        this.RuisekiWa = new long[inputCount];

        decimal total = 0;

        for (int i = 0; i < Items.Length; i++) {
            if(i==0) {
                this.RuisekiWa[0] = this.Items[0];
            }     else {
                this.RuisekiWa[i] = this.RuisekiWa[i - 1] + this.Items[i];
            }
            total += (decimal)this.Items[i];
        }

        this.Avg = total / 4;

        long ans = GetAns(long.MaxValue, long.MinValue, 0, 4);
        Console.WriteLine(ans);

    }


    private long GetAns(long min, long max, int idx, long remain) {
        if(idx < 0) {
            return -1;
        }
        if (idx >= this.Items.Length)
        {
            return -1;
        }
        if(remain == 1) {
            long num = this.RuisekiWa[this.RuisekiWa.Length - 1];
            if(idx>0) {
                num -= this.RuisekiWa[idx - 1];
            }
            long subMin = Math.Min(min, num);
            long subMax = Math.Max(max, num);
            return subMax - subMin;
        }


        long ans = long.MaxValue;
        decimal target = (decimal)this.RuisekiWa.Last();
        if(idx>0) {
            target -= this.RuisekiWa[idx - 1];
        }
        target = target / remain;

        for (int i = idx; i < Items.Length; i++) {
            long num = this.RuisekiWa[i];
            if(idx>0) {
                num -= this.RuisekiWa[idx - 1];
            }
            if(num >= target) {
                long subMin = Math.Min(min, num);
                long subMax = Math.Max(max, num);
                long ret = GetAns(subMin, subMax, i + 1, remain - 1);
                if(ret >= 0) {
                    ans = Math.Min(ans, ret);                    
                }
                if(i > 0 && i - 1 >= idx) {
                    num = this.RuisekiWa[i - 1];
                    if(idx > 0) {
                        num -= RuisekiWa[idx - 1];
                    }
                    subMin = Math.Min(min, num);
                    subMax = Math.Max(max, num);
                    ret = GetAns(subMin, subMax, i, remain - 1);
                    if(ret >= 0) {
                        ans = Math.Min(ans, ret);
                    }
                }
                if(i < Items.Length - 1) {
                    num = this.RuisekiWa[i + 1];
                    if(idx > 0) {
                        num -= RuisekiWa[idx - 1];
                    }
                    subMin = Math.Min(min, num);
                    subMax = Math.Max(max, num);
                    ret = GetAns(subMin, subMax, i + 2, remain - 1);
                    if (ret >= 0)
                    {
                        ans = Math.Min(ans, ret);
                    }
                }
                break;
            }
        }
        return ans;
    } 

