                    }
                    add++;
                }
                var diffr = Abs(ruiseki[N] - ruiseki[right[N - i + 1]] * 2 + ruiseki[N - i + 1]);
                add = 0;
                while (true)
                {
                    if (diffr >= Abs(ruiseki[N] - ruiseki[right[N - i + 1] - add] * 2 + ruiseki[N - i + 1]))
                    {
                        diffr = Abs(ruiseki[N] - ruiseki[right[N - i + 1] - add] * 2 + ruiseki[N - i + 1]);
                        right[N - i] = right[N - i + 1] - add;
                    }
                    else
                    {
