                var Q = ruiseki[e] - ruiseki[left[e]];
                var R = ruiseki[right[e - 1]] - ruiseki[e];
                var S = ruiseki[N] - ruiseki[right[e - 1]];
                var ary = new[] { P, Q, R, S };
