    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var a = consoleReader.Split.Int;
            var sums = new long[a.Length];
            sums[0] = a[0];
            for (int i = 1; i < sums.Length; i++)
                sums[i] = a[i] + sums[i - 1];

            var pq = 0;
            var rs = 2;
            var min = long.MaxValue;
            for (int i = 1; i < sums.Length - 2; i++)
            {
                while (pq < i - 1)
                {
                    var pq1 = Math.Abs(sums[pq] - (sums[i] - sums[pq]));
                    var pq2 = Math.Abs(sums[pq + 1] - (sums[i] - sums[pq + 1]));
                    if (pq2 < pq1) ++pq;
                    else break;
                }
                while (rs < sums.Length - 1)
                {
                    var rs1 = Math.Abs((sums[rs] - sums[i]) - (sums[sums.Length - 1] - sums[rs]));
                    var rs2 = Math.Abs((sums[rs + 1] - sums[i]) - (sums[sums.Length - 1] - sums[rs + 1]));
                    if (rs2 < rs1) ++rs;
                    else break;
                }
                var pqrs = new[] { sums[pq], sums[i] - sums[pq], sums[rs] - sums[i], sums[sums.Length - 1] - sums[rs] };
                Array.Sort(pqrs);
                min = Math.Min(min, pqrs.Last() - pqrs.First());
            }

            return min;
        }


