using System;
using System.Linq;
class Program {
  static long[] a;
  static void Main() {
    Console.ReadLine();
    a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
    Console.WriteLine(GetMin());
  }

  static long GetMin()
  {
    long M, m;
    var center = FlattenSums(0, a.Length, out M, out m);
    var min = GetMin(center);

    var min2 = Enumerable.Range(center + 1, a.Length - center - 2)
      .Select(GetMin)
      .TakeWhile(x => x <= min)
      .LastOrDefault();
    if (min2 != 0) return min2;

    var min1 = Enumerable.Range(2, center - 2)
      .Reverse()
      .Select(GetMin)
      .TakeWhile(x => x <= min)
      .LastOrDefault();
    if (min1 != 0) return min1;

    return min;
  }

  static long GetMin(int center) {
    long M1, m1, M2, m2;
    FlattenSums(0, center, out M1, out m1);
    FlattenSums(center, a.Length - center, out M2, out m2);
    return Math.Max(M1, M2) - Math.Min(m1, m2);
  }

  static int FlattenSums(int start, int count, out long max, out long min) {
    var i1 = start;
    var i2 = start + count - 1;
    var sum1 = a[i1];
    var sum2 = a[i2];
    while (i2 - i1 > 1)
    {
      if (sum1 < sum2) sum1 += a[++i1];
      else sum2 += a[--i2];
    }
    max = Math.Max(sum1, sum2);
    min = Math.Min(sum1, sum2);
    return i2;
  }
}

using System;
using System.Linq;
class Program {
  static void Main() {
    Console.ReadLine();
    var a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
    Console.WriteLine(Enumerable.Range(2, a.Length - 3).Min(i => GetMin(a, i)));
  }

  static long GetMin(long[] a, int center) {
    var r1 = FlattenSums(a, 0, center);
    var r2 = FlattenSums(a, center, a.Length - center);
    return Math.Max(r1.Max, r2.Max) - Math.Min(r1.Min, r2.Min);
  }

  static MaxMin FlattenSums(long[] a, int start, int count) {
    var i1 = start;
    var i2 = start + count - 1;
    var sum1 = a[i1];
    var sum2 = a[i2];
    while (i2 - i1 > 1)
    {
      if (sum1 < sum2)
        sum1 += a[++i1];
      else
        sum2 += a[--i2];
    }
    return (sum1 < sum2) ? new MaxMin(sum2, sum1) : new MaxMin(sum1, sum2);
  }
}

struct MaxMin {
  public long Max;
  public long Min;
  public MaxMin(long max, long min) {
    Max = max;
    Min = min;
  }
}

using System;
