class Program {
  static long[] s;
  static void Main() {
    var n = int.Parse(Console.ReadLine());
    var a = Console.ReadLine().Split().Select(int.Parse).ToArray();
    s = new long[n + 1];
    for (var i = 0; i < n; i++) s[i + 1] = s[i] + a[i];
    Console.WriteLine(Enumerable.Range(2, n - 3).Min(i => GetMin(i)));
  }

  static long GetMin(int ci) {
    var vs = Flatten(0, ci).Concat(Flatten(ci, s.Length - 1 - ci)).ToArray();
    return vs.Max() - vs.Min();
  }

  static long[] Flatten(int start, int count) {
    var c = (s[start] + s[start + count]) / 2;
    var ci = Enumerable.Range(start, count).TakeWhile(i => s[i] <= c).Last();
    if (c - s[ci] >= s[ci + 1] - c) ci++;
    return new[] { s[ci] - s[start], s[start + count] - s[ci] };
  }
}

