namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var N = Sarray()[0];
            var Ai = Sarray();
            rui = new long[N + 1];
            for (var i = 0; i < N; ++i)
                rui[i + 1] = Ai[i] + rui[i];
            var min = long.MaxValue;
            for (var l = 2; l < N - 1; ++l)
                min = Min(min, Calc1(l,N));
            WriteLine(min);
        }
        static long[] rui;
        //[0,l)と[l,N)にわける
        static long Calc1(long l,long N)
        {
            var ll = binarysearch(0, l);
            var rr = binarysearch(l, N);

            var m1 = rui[ll + 1];
            var m2 = rui[l] - rui[ll + 1];
            var m4 = rui[ll + 2];
            var m3 = rui[l] - rui[ll + 2];
            var l1 = m3;
            var l2 = m4;
            if (Abs(m1 - m2) < Abs(m3 - m4))
            {
                l1 = m1;
                l2 = m2;
            }

            var m5 = rui[rr + 1] - rui[l];
            var m6 = rui[N] - rui[rr + 1];
            var m7 = rui[rr + 2] - rui[l];
            var m8 = rui[N] - rui[rr + 2];
            var r1 = m7;
            var r2 = m8;
            if (Abs(m5 - m6) < Abs(m7 - m8))
            {
                r1 = m5;
                r2 = m6;
            }
            var max = Max(Max(r1, r2), Max(l1, l2));
            var min = Min(Min(r1, r2), Min(l1, l2));

            return Abs(max - min);
        }
        //[l,r)間で<sum/2となるところを探す
        static long binarysearch(long l, long r)
        {
            var s = l;
            var J = (rui[r] - rui[s]) / 2;
            while (1 < r - l)
            {
                var mid = l + (r - l) / 2;
                if (rui[mid + 1] - rui[s] < J)
                    l = mid;
                else
                    r = mid;
            }
            return l;
        }
    }
}

