                if (i == 0)
                {
                    sums[i] = array[i];
                }
                else
                {
                    sums[i] = sums[i - 1] + array[i];
                }
            }

            long min = 0;
            for (int i = 2; i < n - 1; i++)//真ん中の区切り数ループ
            {
                long minL = 0, minR = 0;
                int leftIndex = 0, rightIndex = 0;
                for (int j = 0; j < i - 1; j++)//左
                {
                    long margin = Math.Abs(sums[i-1] - 2 * sums[j]);
                    if (j == 0 || margin < minL)
                    {
                        minL = margin;
                        leftIndex = j;
                    }
                }
                for (int j = i; j < n - 1; j++)//右
                {
                    long margin = Math.Abs(sums[n - 1] - sums[j]
                        - (sums[j] - sums[i - 1]));
                    if (j == i || margin < minR)
                    {
                        minR = margin;
                        rightIndex = j;
                    }
                }

                long wholeMargin = Margin(sums[n - 1] - sums[rightIndex],
                    sums[rightIndex] - sums[i - 1],
                    sums[i - 1] - sums[leftIndex], sums[leftIndex]);
                if (i == 2 || wholeMargin < min)
                {
                    min = wholeMargin;
                    /*
                    Console.WriteLine(leftIndex);
                    Console.WriteLine(i);
                    Console.WriteLine(rightIndex);
                    */
                }
            }

            Console.WriteLine(min);
        }

        static long Margin(params long[] array)
        {
            long min = 0, max = 0;
            for(int i = 0; i < array.Length; i++)
            {
                if (i == 0)
                {
                    min = array[i];
                    max = array[i];
                }
                else
                {
                    if (array[i] < min)
                    {
                        min = array[i];
                    }
                    if (array[i] > max)
                    {
                        max = array[i];
                    }
                }
            }
            return max - min;
        }
    }
