namespace D
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split().Select(i => long.Parse(i)).ToList();
            long[] sum = new long[N];
            sum[0] = A[0];
            for (var i = 1; i < N; i++)
            {
                sum[i] += sum[i - 1] + A[i];
            }

            long ans = long.MaxValue;
            for (var i = 2; i < N - 1; i++)
            {
                long[] left = new long[i];
                Array.Copy(sum, 0, left, 0, left.Length);
                ArrayJudge(left, out long leftMin, out long leftMax);

                long[] right = new long[N - i];
                Array.Copy(sum, i, right, 0, right.Length);
                ArrayJudge(right, out long rightMin, out long rightMax, left[left.Length - 1]);

                long min = (leftMin < rightMin) ? leftMin : rightMin;
                long max = (leftMax > rightMax) ? leftMax : rightMax;
                ans = (max - min < ans) ? max - min : ans;
            }
            Console.WriteLine(ans);
        }

        static void ArrayJudge(long[] array, out long min, out long max, long offset = 0L)
        {
            long minDiff = long.MaxValue;
            long tmpMin = 0L;
            long tmpMax = 0L;
            for (var i = 0; i < array.Length - 1; i++)
            {
                long left = array[i] - offset;
                long right = array[array.Length - 1] - array[i];
                long diff = Math.Abs(right - left);
                if (diff < minDiff)
                {
                    minDiff = diff;
                    if (right < left)
                    {
                        tmpMin = right;
                        tmpMax = left;
                    }
                    else
                    {
                        tmpMin = left;
                        tmpMax = right;
                    }
                }
            }
            min = tmpMin;
            max = tmpMax;
        }
    }
}

