    public class Program
    {
        public static void Main(string[] args)
        {
            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            //Out.Flush();
            Read();
        }

        static void Solve()
        {
            var N = Sarray()[0];
            var Ai = Sarray();

            var p = Ai[0];
            var q = 0L;
            var r = Ai[1] + Ai[2];
            var s = Ai.Sum() - Ai.Take(3).Sum();
            var diff = long.MaxValue;
            for (long bc = 1, de = 2, ef = 3; de < N - 1; ++de)
            {
                q = q + Ai[de - 1];
                for (var i = bc + 1; i < de; ++i)
                {
                    var d = Abs(p - q);
                    var np = p + Ai[i - 1];
                    var nq = q - Ai[i - 1];
                    if (Abs(np - nq) < d)
                    {
                        p = np;
                        q = nq;
                        bc = i;
                    }
                    else
                        break;
                }
                r = r - Ai[de - 1];
                for (var i = ef + 1; i < N; ++i)
                {
                    var d = Abs(r - s);
                    var nr = r + Ai[i - 1];
                    var ns = s - Ai[i - 1];
                    if (Abs(nr - ns) < d)
                    {
                        r = nr;
                        s = ns;
                        ef = i;
                    }
                    else
                        break;
                }
                var maxPqrs = Max(Max(p, q), Max(r, s));
                var minPqrs = Min(Min(p, q), Min(r, s));
                diff = Min(diff, maxPqrs - minPqrs);
            }
            WriteLine(diff);
        }

