    class ABC_102_D
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            string[] input = Console.ReadLine().Split(' ');
            long[] array = new long[n];
            long sum = 0;
            for (int i = 0; i < n; i++)
            {
                array[i] = int.Parse(input[i]);
                sum += array[i];
            }

            long min = 100000000000;
            long[] sums = new long[4];
            for (int i = 1; i < n - 2; i++)
            {
                sums[0] += array[i - 1];
                sums[1] = 0;
                for (int j = i + 1; j < n - 1; j++)
                {
                    sums[1] += array[j - 1];
                    sums[2] = 0;
                    for (int k = j + 1; k < n; k++)
                    {
                        sums[2] += array[k - 1];
                        sums[3] = sum - sums[0] - sums[1] - sums[2];
                        long margin = Max(sums) - Min(sums);
                        if (margin < min)
                        {
                            min = margin;
                        }
                        /*Console.WriteLine(string.Format("{0},{1},{2},{3}",
                            sums[0], sums[1], sums[2], sums[3]));*/
                    }
                }
            }
            Console.WriteLine(min);
        }

        static long Sum(long[] array,int start,int last)
        {
            long s = 0;
            for(int i = start; i < last; i++)
            {
                s += array[i];
            }
            return s;
        }

        static long Max(long[] array)
        {
            long max = 0;
            for(int i = 0; i < array.Length; i++)
            {
                if (i == 0 || max < array[i])
                {
                    max = array[i];
                }
            }
            return max;
        }

        static long Min(long[] array)
        {
            long min = 0;
            for (int i = 0; i < array.Length; i++)
            {
                if (i == 0 || min> array[i])
                {
                    min = array[i];
                }
            }
            return min;
        }
    }
