using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

namespace TOPSIC
{
	public class Program
	{
		/// <summary>
		/// ABC 102
		/// </summary>
		public static void Main()
		{
			int n = int.Parse(ReadLine());
			var list = ReadLine().Split().Select(x => int.Parse(x))
				.ToList();

			// 高速化のために、累積和を先に求めておく
			var sum = new List<double>();
			sum.Add(list[0]);
			for(int i = 1; i<n; i++)
			{
				sum.Add(sum[i - 1] + list[i]);
			}

			// 目的は左右の合計の差の最小値を探すこと。
			double min = double.MaxValue;
			var list2 = new double[4];
			int leftIndex = 0;
			int rightIndex = 2;
			// 中央の区切り
			for (int i = 2; i < n - 1; i++)
			{
				// 左の区切り
				while (leftIndex < i
					&& Math.Abs(sum[i - 1] - 2 * sum[leftIndex + 1])
					 < Math.Abs(sum[i - 1] - 2 * sum[leftIndex]))
				{
					leftIndex++;
				}
				while (rightIndex < n - 1
					&& Math.Abs(sum[n - 1] - 2 * sum[rightIndex + 1] + sum[i - 1])
					< Math.Abs(sum[n - 1] - 2 * sum[rightIndex] + sum[i - 1]))
				{
					rightIndex++;
				}

				list2[0] = sum[leftIndex];
				list2[1] = sum[i - 1] - sum[leftIndex];
				list2[2] = sum[rightIndex] - sum[i - 1];
				list2[3] = sum[n - 1] - sum[rightIndex];
				var m = list2.Max() - list2.Min();
				if(m < min)
				{
					min = m;
				}
			}

			WriteLine(min);
		}
	}
}

