            var Alist = NNList(N);
            var ruiseki = new long[N + 1];
            for (var i = 1; i <= N; i++)
            {
                ruiseki[i] = ruiseki[i - 1] + Alist[i - 1];
            }


            Func<int, long, int> get = (bidx, pivot) =>
            {
                for (var i = bidx + 1; i < N; i++)
                {
                    if (ruiseki[i] - ruiseki[bidx] > pivot)
                    {
                        return i;
                    }
                }

                return (int)N - 1;
            };
            Func<Tuple<int, long>[], int[]> get2 = (param) =>
            {
                var res = new List<int>();
                foreach (var item in param)
                {
                    var ridx = get(item.Item1, item.Item2);
                    res.Add(ridx);
                    res.Add(ridx - 1);
                    res.Add(ridx + 1);
                }

                return res.ToArray();
            };

            var idx1 = get2(new[] { Tuple.Create(0, ruiseki[N] / 4) });
            var idx2 = get2(idx1.Select(e => Tuple.Create(e, (ruiseki[N] - ruiseki[e]) / 3)).ToArray());
            var idx3 = get2(idx2.Select(e => Tuple.Create(e, (ruiseki[N] - ruiseki[e]) / 2)).ToArray());
            var ans = long.MaxValue;
            foreach (var item1 in idx1)
            {
                foreach (var item2 in idx2)
                {
                    if (item1 >= item2) continue;
                    foreach (var item3 in idx3)
                    {
                        if (item1 >= item3) continue;
                        if (item2 >= item3) continue;
                        var P = ruiseki[item1];
                        var Q = ruiseki[item2] - ruiseki[item1];
                        var R = ruiseki[item3] - ruiseki[item2];
                        var S = ruiseki[N] - ruiseki[item3];
                        var ary = new[] { P, Q, R, S };
                        ans = Min(ans, ary.Max() - ary.Min());
                    }
                }
            }
            Console.WriteLine(ans);
        }

