		for (int i = 2; i < n - 1; i++)
		{
			long s1 = s[i], s2 = s[n] - s1;
			long sh1 = (s1 + 1) / 2, sh2 = s1 + (s2 + 1) / 2;

			var i1 = Array.BinarySearch(s, sh1);
			if (i1 < 0) i1 = ~i1;
