internal partial class Solver {
    struct Result {
        public long Min, Max;
    }

    public void Run() {
        var n = ni();
        var a = ni(n);

        var x = TwoMinMax(a);
        var y = TwoMinMax(a.Reverse().ToArray());
        Array.Reverse(y);

        long ans = long.MaxValue;
        for (int i = 0; i + 1 < n; i++) {
            var min = Math.Min(x[i].Min, y[i + 1].Min);
            var max = Math.Max(x[i].Max, y[i + 1].Max);
            ans = Math.Min(ans, max - min);
        }
        cout.WriteLine(ans);
    }

    private Result[] TwoMinMax(int[] a) {
        var n = a.Length;
        var r = new Result[n];
        long leftSum = 0;
        long rightSum = 0;
        var rightQueue = new Queue<int>();

        for (int i = 0; i < n; i++) {
            rightSum += a[i];
            rightQueue.Enqueue(a[i]);

            while (rightQueue.Count > 0) {
                var afterLeft = leftSum + rightQueue.Peek();
                var afterRight = rightSum - rightQueue.Peek();
                if (Math.Abs(leftSum - rightSum) >= Math.Abs(afterLeft - afterRight)) {
                    var x = rightQueue.Dequeue();
                    leftSum += x;
                    rightSum -= x;
                } else {
                    break;
                }
            }
            r[i] = new Result { Min = Math.Min(leftSum, rightSum), Max = Math.Max(leftSum, rightSum) };
        }

        return r;
    }
}

