public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		long[] A = GetLongs(N);

		long[] csum = new long[N + 1];
		for(int i = 0; i < N; i++)
			csum[i + 1] = csum[i] + A[i];

		long ans = long.MaxValue / 2;
		for(int i = 2; i < N - 1; i++)
		{
			int leftSpl = meguruBinarySearch(csum, 1, i);
			int rightSpl = meguruBinarySearch(csum, i + 1, N);
			for(int j = 0; j < 2; j++)
			{
				if(leftSpl - j < 0)
					continue;

				for(int k = 0; k < 2; k++)
				{
					if(rightSpl - k < i)
						continue;

					long P = csum[leftSpl - j];
					long Q = csum[i] - csum[leftSpl - j];			
					long R = csum[rightSpl - k] - csum[i];
					long S = csum[N] - csum[rightSpl - k];

					long max = Math.Max(P, Math.Max(Q, Math.Max(R, S)));
					long min = Math.Min(P, Math.Min(Q, Math.Min(R, S)));
					ans = Math.Min(ans, max - min);
				}				
			}
		}

		Console.WriteLine(ans);
	}

	private int meguruBinarySearch(long[] csum, int first, int last)
	{
		long sum = csum[last] - csum[first - 1];
		int ok = last;
		int ng = first - 1;
		while(Math.Abs(ng - ok) > 1)
		{
			int mid = (ng + ok) / 2;
			if((csum[mid] - csum[first - 1]) * 2 > sum)
				ok = mid;
			else
				ng = mid;
		}
		return ok;
	}
}


