                    if (Abs(ruiseki[i] - pivot) > Abs(ruiseki[i - 1] - pivot))
                    {
                        --idx1;
                    }
                    break;
                }
            }
            var idx2 = 0;
            for (var i = idx1 + 1; i < N; i++)
