                if ((ruiseki[i] - ruiseki[idx1]) >= pivot)
                {
                    idx2 = i;
                    if (Abs((ruiseki[i] - ruiseki[idx1]) - pivot) > Abs((ruiseki[i - 1] - ruiseki[idx1]) - pivot))
