                if ((ruiseki[i] - ruiseki[idx2]) >= pivot)
                {
                    idx3 = i;
                    if (Abs((ruiseki[i] - ruiseki[idx2]) - pivot) > Abs((ruiseki[i - 1] - ruiseki[idx2]) - pivot))
                    {
                        --idx3;
                    }
                    if (idx3 == idx2) ++idx3;
                    break;
                }
            }
            if (idx3 == 0)
            {
                idx3 = (int)N - 2;
            }
            var P = ruiseki[idx1];
            var Q = ruiseki[idx2] - ruiseki[idx1];
            var R = ruiseki[idx3] - ruiseki[idx2];
            var S = ruiseki[N - 1] - ruiseki[idx3];
            var ary = new[] { P, Q, R, S };
