namespace D
{
    class Program
    {

        private static MinAndMax data = new MinAndMax();

        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            long tmp = 0L;
            var sum = Console.ReadLine()
                .Split()
                .Select(i =>
                {
                    tmp += long.Parse(i);
                    return tmp;
                })
                .ToArray();

            long ans = long.MaxValue;
            MinAndMax leftData;
            MinAndMax rightData;
            for (var i = 2; i < N - 1; i++)
            {
                // dataの初期化
                data.Min = 0;
                data.Max = 10000000000;
                LeftJudge(sum, 0, i, sum[i - 1]);
                leftData = data;

                // dataの初期化
                data.Min = 0;
                data.Max = 10000000000;
                RightJudge(sum, i, N - 1, sum[i - 1]);
                rightData = data;

                long min = Math.Min(leftData.Min, rightData.Min);
                long max = Math.Max(leftData.Max, rightData.Max);
                ans = Math.Min(ans, max - min);
            }
            Console.WriteLine(ans);
        }

        static void RightJudge(long[] array, int lidx, int ridx, long offset = 0L)
        {
            int middle = (ridx + lidx) >> 1;
            long left = array[middle] - offset;
            long right = array[array.Length - 1] - array[middle];
            if (Math.Abs(right - left) < data.Diff)
            {
                data.Min = Math.Min(left, right);
                data.Max = Math.Max(left, right);
            }
            if (left < right && ridx - lidx > 1)
            {
                RightJudge(array, middle, ridx, offset);
            }
            else if (left > right && ridx - lidx > 1)
            {
                RightJudge(array, lidx, middle, offset);
            }
        }

        static void LeftJudge(long[] array, int lidx, int ridx, long end)
        {
            int middle = (ridx + lidx) >> 1;
            long left = array[middle];
            long right = end - array[middle];
            if (Math.Abs(right - left) < data.Diff)
            {
                data.Min = Math.Min(left, right);
                data.Max = Math.Max(left, right);
            }
            if (left < right && ridx - lidx != 1)
            {
                LeftJudge(array, middle, ridx, end);
            }
            else if (left > right && ridx - lidx != 1)
            {
                LeftJudge(array, lidx, middle, end);
            }
        }
    }
    struct MinAndMax
    {
        public long Min;
        public long Max;
        public long Diff { get { return Max - Min; } }
    }
}

