public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		long[] A = GetLongs(N);

		long[] csum = new long[N + 1];
		for(int i = 0; i < N; i++)
			csum[i + 1] = csum[i] + A[i];

		long ans = long.MaxValue / 2;
		for(int i = 2; i < N - 1; i++)
		{
			int leftSpl = Math.Max(1, meguruBinarySearch(csum, 1, i));
			long P = csum[leftSpl];
			long Q = csum[i] - csum[leftSpl];

			int rightSpl = Math.Max(i + 1, meguruBinarySearch(csum, i + 1, N));
			long R = csum[rightSpl] - csum[i];
			long S = csum[N] - csum[rightSpl];

			long max = Math.Max(P, Math.Max(Q, Math.Max(R, S)));
			long min = Math.Min(P, Math.Min(Q, Math.Min(R, S)));
			ans = Math.Min(ans, max - min);
		}

		Console.WriteLine(ans);
	}

	private int meguruBinarySearch(long[] csum, int first, int last)
	{
		long sum = csum[last] - csum[first - 1];
		long minDiff = long.MaxValue / 2;
		int ok = first - 1;
		int ng = last;
		while(Math.Abs(ng - ok) > 1)
		{
			int mid = (ng + ok) / 2;
			long diff = Math.Abs(sum - 2 * (csum[mid] - csum[first - 1]));
			if(diff < minDiff)
			{
				ok = mid;
				minDiff = diff;
			}
			else
				ng = mid;
		}
		return ok;
	}
}


