using System;
using System.Linq;
class Program {
  static void Main() {
    Console.ReadLine();
    var a = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
    Console.WriteLine(Enumerable.Range(2, a.Length - 3).Min(i => GetMin(a, i)));
  }

  static int GetMin(int[] a, int center) {
    var r1 = FlattenSums(a, 0, center);
    var r2 = FlattenSums(a, center, a.Length - center);
    return Math.Max(r1.Max, r2.Max) - Math.Min(r1.Min, r2.Min);
  }

  static MaxMin FlattenSums(int[] a, int start, int count) {
    var sum = a.Skip(start).Take(count).Sum();
    var half = sum / 2.0;

    var current = a[start];
    if (half <= current) return new MaxMin(current, sum - current);
    for (var i = start + 1; i < start + count - 1; i++)
    {
      var next = current + a[i];
      if (half <= next) return (half - current < next - half) ? new MaxMin(sum - current, current) : new MaxMin(next, sum - next);
      current = next;
    }
    return new MaxMin(sum - current, current);
  }
}

struct MaxMin {
  public int Max;
  public int Min;
  public MaxMin(int max, int min) {
    Max = max;
    Min = min;
  }
}

