    class Program
    {
        private int N;
        private long[] A;
        private long[] S;
        public void Solve()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            A = sc.LongArray();
            S = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                S[i + 1] = S[i] + A[i];
            }

            //[0,i),[i,N)
            long ans = long.MaxValue;
            for (int i = 2; i <= N - 2; i++)
            {
                var abs = Abs(i);
                //Console.WriteLine(abs);
                ans = Math.Min(ans, abs);

            }
            Console.WriteLine(ans);
        }

        private int Naka(int l, int r)
        {
            int min = l;
            int max = r;
            long sum = Sum(l, r);
            while (max - min > 1)
            {
                int med = (min + max) / 2;
                if (Sum(l, med) > Sum(med, r))
                {
                    max = med;
                }
                else
                {
                    min = med;
                }
            }

            return min;
        }

        private long Abs(int i)
        {
            int aa = Naka(0, i);
            int bb = Naka(i, N);
            //Console.WriteLine($"{aa} {bb}");
            long ans = long.MaxValue;
            for (int j = 0; j <= 1; j++)
            {
                int bc = aa + j;
                //Console.WriteLine("bc="+bc);
                if (bc - 0 <= 0 || i - bc <= 0) continue;
                //Console.WriteLine("bc=" + bc);
                for (int k = 0; k <= 1; k++)
                {
                    int de = bb + k;
                    if(de-i<=0||N-de<=0)continue;
                    //Console.WriteLine($"{bc} {de}");
                    long b = Sum(0, bc);
                    long c = Sum(bc, i);
                    long d = Sum(i, de);
                    long e = Sum(de, N);
                    long min = Math.Min(b, Math.Min(c, Math.Min(d, e)));
                    long max = Math.Max(b, Math.Max(c, Math.Max(d, e)));
                    ans = Math.Min(ans, max - min);
                    //Console.WriteLine(ans);
                }
            }

            return ans;
        }

        /// <summary>
        /// [l,r)の和
        /// </summary>
        /// <param name="l"></param>
        /// <param name="r"></param>
        /// <returns></returns>
        private long Sum(int l, int r)
        {
            return S[r] - S[l];
        }

        static void Main(string[] args) => new Program().Solve();
    }
