    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split().Select(i => long.Parse(i)).ToList();
            long[] sum = new long[N];
            sum[0] = A[0];
            for (var i = 1; i < N; i++)
            {
                sum[i] += sum[i - 1] + A[i];
            }

            long ans = long.MaxValue;
            for (var i = 2; i < N - 1; i++)
            {
                long[] left = new long[i];
                Array.Copy(sum, 0, left, 0, left.Length);
                MinAndMax leftData = ArrayJudge(left);

                long[] right = new long[N - i];
                Array.Copy(sum, i, right, 0, right.Length);
                MinAndMax rightData = ArrayJudge(right, left[left.Length - 1]);

                long min = (leftData.Min < rightData.Min) ? leftData.Min : rightData.Min;
                long max = (leftData.Max > rightData.Max) ? leftData.Max : rightData.Max;
                ans = (max - min < ans) ? max - min : ans;
            }
            Console.WriteLine(ans);
        }

        static MinAndMax ArrayJudge(long[] array, long offset = 0L)
        {
            long minDiff = long.MaxValue;
            MinAndMax data = new MinAndMax();
            for (var i = 0; i < array.Length - 1; i++)
            {
                long left = array[i] - offset;
                long right = array[array.Length - 1] - array[i];
                long diff = Math.Abs(right - left);
                if (diff < minDiff)
                {
                    minDiff = diff;
                    if (right < left)
                    {
                        data.Min = right;
                        data.Max = left;
                    }
                    else
                    {
                        data.Min = left;
                        data.Max = right;
                    }
                }
            }
            return data;
        }
    }
    class MinAndMax
    {
        public long Min;
        public long Max;
    }
}

