    class Program
    {
        private int N;
        private long[] A;
        private long[] S;
        public void Solve()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            A = sc.LongArray();
            S = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                S[i + 1] = S[i] + A[i];
            }

            //[0,i),[i,N)
            long ans = long.MaxValue;
            for (int i = 2; i <= N - 2; i++)
            {
                var abs = Abs(i);
                //Console.WriteLine(abs);
                ans = Math.Min(ans, abs);

            }
            Console.WriteLine(ans);
        }

        private int Naka(int l, int r)
        {
            int min = l;
            int max = r;
            long sum = Sum(l, r);
            while (max - min > 1)
            {
                int med = (min + max) / 2;
                if (Sum(l, med) > Sum(med, r))
                {
                    max = med;
                }
                else
                {
                    min = med;
                }
            }

            return min;
        }

        private long Abs(int i)
        {
            int aa = Naka(0, i);
            int bb = Naka(i, N);
            //Console.WriteLine($"{aa} {bb}");
            long ans = long.MaxValue;
            for (int j = -5; j < 5; j++)
            {
                int bc = aa + j;
                //Console.WriteLine("bc="+bc);
                if (bc - 0 <= 0 || i - bc <= 0) continue;
                //Console.WriteLine("bc=" + bc);
                for (int k = -5; k < 5; k++)
                {
                    int de = bb + k;
                    if(de-i<=0||N-de<=0)continue;
                    //Console.WriteLine($"{bc} {de}");
                    long b = Sum(0, bc);
                    long c = Sum(bc, i);
                    long d = Sum(i, de);
                    long e = Sum(de, N);
                    long min = Math.Min(b, Math.Min(c, Math.Min(d, e)));
                    long max = Math.Max(b, Math.Max(c, Math.Max(d, e)));
                    ans = Math.Min(ans, max - min);
                    //Console.WriteLine(ans);
                }
            }

            return ans;
        }

        /// <summary>
        /// [l,r)の和
        /// </summary>
        /// <param name="l"></param>
        /// <param name="r"></param>
        /// <returns></returns>
        private long Sum(int l, int r)
        {
            return S[r] - S[l];
        }

        static void Main(string[] args) => new Program().Solve();
    }
}

function Main(input) {
    var NA = input.split('\n');
    var N = parseInt(NA[0]);
    var A = NA[1].split(' ').map(n => parseInt(n));

    var wa = 0;
    var Aruisekiwa = A.map((n) => {
        wa += n;
        return wa;
    });


    var P = [];
    var Q = [];
    var R = [];
    var S = [];

    // 左側
    for(var i = 1, l = 0 ; i < N - 2 ; ++i) {
        var lwa = Aruisekiwa[i];

        while(i >= 2) {
            var ll = Aruisekiwa[l];
            var lr = lwa - ll;
            var llp = Aruisekiwa[l+1];
            var lrp = lwa - llp;
            if (Math.abs(lrp-llp) <= Math.abs(lr-ll)) ++l;
            else break;
        }

        P.push(Aruisekiwa[l]);
        Q.push(Aruisekiwa[i] - Aruisekiwa[l]);
    }

    // 右側
    for(var i = N-2, r = 1; i > 1 ; --i, ++r){
        var leftEnd = Aruisekiwa[i-1];
        var rwa = Aruisekiwa[N-1];

        while(i < N-2) {
            var rr = rwa - Aruisekiwa[i+r-1];
            var rl = Aruisekiwa[i+r-1] - leftEnd;
            var rrp = rwa - Aruisekiwa[i+r-2];
            var rlp = Aruisekiwa[i+r-2] - leftEnd;
            if (Math.abs(rrp-rlp) <= Math.abs(rr-rl)) --r;
            else break;
        }

        R.unshift(Aruisekiwa[i+r-1]-leftEnd);
        S.unshift(rwa - Aruisekiwa[i+r-1]);
    }

    var res = -1;
    for (var i = 0 ; i < P.length ; ++i) {
        var curRes = Math.max(P[i], Q[i], R[i], S[i]) - Math.min(P[i], Q[i], R[i], S[i]);
        if (res < 0 || curRes < res) res = curRes; 
    }
    console.log(res);

}
