)

var N int
var as []int
var sums []int

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	fmt.Sscanf(scanner.Text(), "%d", &N)

	as = make([]int, N)
	sums = make([]int, N)
	for i := 0; i < N; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d", &as[i])
		if i == 0 {
			sums[i] = as[i]
		} else {
			sums[i] = sums[i-1] + as[i]
		}
	}

	ans := math.MaxInt64
	left, right := 0, 2
	for mid := 1; mid < N-2; mid++ {
		left = moveLeft(left, mid, sums[mid])
		right = moveRight(right, mid, sums[mid])
		s := make([]int, 4)
		s[0] = sums[left]
		s[1] = sums[mid] - sums[left]
		s[2] = sums[right] - sums[mid]
		s[3] = sums[N-1] - sums[right]
		m := max(s...) - min(s...)
		//fmt.Println(left, mid, right, "->", s, m)
		ans = min(ans, m)
	}
	fmt.Println(ans)
}

func moveLeft(index, mid int, sum int) int {
	leftf := func(index, sum int) int {
		return sum/2 - sums[index]
	}
	for index < mid-1 && leftf(index, sum) > 0 {
		index++
	}
	if index > 1 && abs(leftf(index-1, sum)) < abs(leftf(index, sum)) {
		index--
	}
	return index
}

func moveRight(index, mid int, sum int) int {
	rightf := func(index, sum int) int {
		return (sums[N-1]-sums[mid])/2 - (sums[index] - sums[mid])
	}
	for index < N && rightf(index, sum) > 0 {
		index++
	}
	if index > mid+1 && abs(rightf(index-1, sum)) < abs(rightf(index, sum)) {
		index--
	}
	return index
}

func min(ns ...int) int {
	ret := math.MaxInt64
	for _, n := range ns {
		if n < ret {
			ret = n
		}
	}
	return ret
}

func max(ns ...int) int {
	ret := math.MinInt64
	for _, n := range ns {
		if n > ret {
			ret = n
		}
	}
	return ret
}

func abs(n int) int {
	if n >= 0 {
		return n
	}
	return -n
}

