		panic("failed scan string")
	}
	return sc.Text()
}

func nextInt() int {
	if !sc.Scan() {
		panic("failed scan int")
	}
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func main() {
	sc.Split(bufio.ScanWords)
	n := nextInt()
	as := make([]int, n)

	for i := 0; i < n; i++ {
		as[i] = nextInt()
	}

	var sums [4]int
	index := [4]int{0, 1, 2, 3}

	sums[0] = as[0]
	sums[1] = as[1]
	sums[2] = as[2]
	for i := 3; i < n; i++ {
		sums[3] += as[i]
	}
	// min -> max
	order := []int{0, 1, 2, 3}

	sortOrder := func() {
		for i := 0; i < 4; i++ {
			for j := 0; j < 3; j++ {
				if sums[order[j]] > sums[order[j+1]] {
					order[j], order[i] = order[i], order[j]
				}
			}
		}
	}
	sortOrder()

	move := func(i int) bool {
		// min
		if i == order[0] {
			return false
		}
		// max
		if i-1 == order[3] {
			return false
		}
		delSum := sums[i] - as[index[i]]
		addSum := sums[i-1] + as[index[i]]

		if delSum < sums[order[0]] {
