func getSum(a []int64, start, end int) int64 {
	ans := a[end-1]
	if start != 0 {
		ans -= a[start-1]
	}
	return ans
}

func renew(a []int64, start, prev, end int) int {
	i := prev
	for i < len(a) {
		lv := getSum(a, start, i)
		rv := getSum(a, i, end)
		j := i + 1
		nlv := getSum(a, start, j)
		nrv := getSum(a, j, end)
		if absInt64(lv-rv) < absInt64(nlv-nrv) {
			break
		}
		i = j
	}
	return i
}

type Int64s []int64

func (is Int64s) Len() int {
	return len(is)
}
func (is Int64s) Less(a, b int) bool {
	return is[a] < is[b]
}
func (is Int64s) Swap(a, b int) {
	is[a], is[b] = is[b], is[a]
}

func calc(a []int64, b, c, d, e int) int64 {
	score := make([]int64, 0)
	score = append(score, getSum(a, b, c))
	score = append(score, getSum(a, c, d))
	score = append(score, getSum(a, d, e))
	score = append(score, getSum(a, e, len(a)))
	sort.Sort(Int64s(score))
	return score[3] - score[0]
}

