func binary_search(a []interface{}, key interface{}, Less func(a, b interface{}) bool) int {
	ok, ng := -1, len(a)
	for abs(ok-ng) > 1 {
		mid := (ok + ng) / 2

		if Less(a[mid], key) {
			ok = mid
		} else {
			ng = mid
		}
	}

	return ok
}

