//Namori Graph
type Namori struct {
	g  [][]int
	in []int
}

func NewNamori(N int) *Namori {
	return &Namori{make([][]int, N), make([]int, N)}
}

func (data *Namori) add_edge(a, b int) {
	data.g[a] = append(data.g[a], b)
}

func (data *Namori) decomposition(loop []int, forest [][]int) {
	N := len(data.g)
	for i := 0; i < N; i++ {
		data.in[i] = len(data.g[i])
	}
	forest = make([][]int, N)
	qu := NewQueue()
	v := make([]bool, N)

	for i := 0; i < N; i++ {
		if data.in[i] == 1 {
			qu.push(i)
			v[i] = true
		}
	}

	for !qu.empty() {
		idx := qu.frontInt()
		qu.pop()

		for to := range data.g[idx] {
			if v[to] {
				continue
			}

			data.in[to] -= 1
			forest[to] = append(forest[to], idx)
			forest[idx] = append(forest[idx], to)

			if data.in[to] > 1 {
				continue
			}

			qu.push(to)
			v[to] = true
		}
	}

	var dfs func(idx int)
	dfs = func(idx int) {
		loop = append(loop, idx)

		for to := range data.g[idx] {
			if v[to] {
				continue
			}

			v[to] = true
			dfs(to)
		}
	}

	for i := 0; i < N; i++ {
		if v[i] {
			continue
		}

		v[i] = true
		dfs(i)
		break
	}
}

