func getNextLine(scanner *bufio.Reader) string {
	var buffer string
	for {
		line, isPrefix, _ := scanner.ReadLine()
		buffer += string(line)
		if isPrefix == false {
			break
		}
	}
	return buffer
}

func getIntList(scanner *bufio.Reader) []int {
	list := strings.Split(getNextLine(scanner), " ")
	l := len(list)
	result := make([]int, l)
	for i := 0; i < l; i++ {
		result[i], _ = strconv.Atoi(list[i])
	}
	return result
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)

	var n int
	fmt.Sscan(getNextLine(scanner), &n)
	aaa := getIntList(scanner)
	sums := make([]int64, n+2)
	for i := 0; i < n; i++ {
		sums[i+1] = sums[i] + int64(aaa[i])
	}
	sums[n+1] = sums[n]
	min := sums[n]
	for i := 3; i < n; i++ {
		l := 0
		r := i
		half := sums[i-1]
		for l < r {
			m := (l + r) / 2
			if sums[m]*2 < half {
				l = m + 1
				continue
			}
			r = m
		}
		forward := l
		if 1 < l && sums[l]*2-half > half-sums[l-1]*2 {
			forward--
		}
		l = i
		r = n + 1
		half = (sums[n] - sums[i-1])
		for l < r {
			m := (l + r) / 2
			if (sums[m]-sums[i-1])*2 < half {
				l = m + 1
				continue
			}
			r = m
		}
		back := l
		if i < l && (sums[l]-sums[i-1])*2-half > half-(sums[l-1]-sums[i-1])*2 {
			back--
		}
		ch := chokudai(forward, i, back, sums)
		if min > ch {
			min = ch
		}
	}
	fmt.Println(min)
}

func chokudai(forward int, center int, back int, sums []int64) int64 {
	l := make(SortBy, 4)
	l[0] = sums[forward]
	l[1] = sums[center-1] - sums[forward]
	l[2] = sums[back] - sums[center-1]
	l[3] = sums[len(sums)-1] - sums[back]
	sort.Sort(l)
	return l[3] - l[0]
}

type SortBy []int64

func (a SortBy) Len() int           { return len(a) }
func (a SortBy) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a SortBy) Less(i, j int) bool { return a[i] < a[j] }

