func getSum(a []int64, start, end int) int64 {
	ans := a[end-1]
	if start != 0 {
		ans -= a[start-1]
	}
	return ans
}

func renew(a []int64, start, prev, end int) int {
	i := prev
	for i < len(a) {
		lv := getSum(a, start, i)
		rv := getSum(a, i, end)
		j := i + 1
		nlv := getSum(a, start, j)
		nrv := getSum(a, j, end)
		if absInt64(lv-rv) < absInt64(nlv-nrv) {
			break
		}
		i = j
	}
	return i
}

func calc(a []int64, b, c, d, e int) int64 {
	var min, max int64
	min = getSum(a, b, c)
	max = min
	for _, v := range []int64{getSum(a, c, d), getSum(a, d, e), getSum(a, e, len(a))} {
		if v < min {
			min = v
		}
		if max < v {
			max = v
		}
	}
	return max - min
}

func main() {
	defer stdout.Flush()

	n := readInt()
	a := make([]int64, n)
	a[0] = readInt64()
	for i := 1; i < n; i++ {
		a[i] = readInt64() + a[i-1]
	}

	b := 0
	c := 1
	d := 2
	e := renew(a, 2, 3, n)
	min := calc(a, b, c, d, e)
	for d < n-1 {
		d++
		c := renew(a, b, c, d)
		e := renew(a, d, e, n)
		min = minInt64(min, calc(a, b, c, d, e))
	}
	println(min)
}

