  foreach (i; 1..n) cr[i] = cr[i-1]+a[$-1-i];

  auto r = 10L^^18;
  foreach (i; 2..n-1) {
    auto d1 = divide(cl[0..i]);
    auto d2 = divide(cr[0..n-i]);
