auto divide(long[] c)
{
  auto t = c[$-1], cs = c.assumeSorted;
  if (t%2 == 0 && cs.contains(t/2))
    return [t/2, t/2];
  auto a = cs.lowerBound(t/2+1), b = cs.upperBound(t/2);
  if (a.empty)
    return [t-c[0], c[0]];
  auto a1 = a.back, a2 = t-a1, b2 = b.front, b1 = t-b2;
  if (a2-a1 < b2-b1)
    return [a1, a2];
  else
    return [b1, b2];
}

