	{
		ts[ i + 1 ] = ts[ i ] + a;
	}

	auto ans = long.max;
	auto ps = [ 0L, 1L, 2L, 3L, as.length.signed ];
	for( ; ps[ 2 ] < as.length.signed - 1; ps[ 2 ]++ )
	{
