			auto db = abs( ( p + as[ ps[ 1 ] ] ) - ( q - as[ ps[ 1 ] ] ) );
			if( da < db ) break;
			p += as[ ps[ 1 ] ];
			q -= as[ ps[ 1 ] ];
			ps[ 1 ]++;
		}

		auto r = ts[ ps[ 3 ] ] - ts[ ps[ 2 ] ];
		auto s = ts[ ps[ 4 ] ] - ts[ ps[ 3 ] ];
