		{
			auto da = abs( r - s );
			auto db = abs( ( r + as[ ps[ 3 ] ] ) - ( s - as[ ps[ 3 ] ] ) );
			if( da < db ) break;
			r += as[ ps[ 3 ] ];
			s -= as[ ps[ 3 ] ];
			ps[ 3 ]++;
		}

		auto ms = [ p, q, r, s ].reduce!( min, max );
		ans = min( ans, ms[ 1 ] - ms[ 0 ] );
