auto bisect( alias pred )( long ng, long ok )
if( is( typeof( pred( ng ) ) : bool ) )
{
	while( 1 < abs( ok - ng ) )
	{
		auto x = ( ok + ng ) / 2;
		if( pred( x ) ) ok = x;
		else            ng = x;
	}
	return ok;
}

