def min_diff(x, base=0):
    n = len(x)
    ok = - 1  # x[ok] - base < x[n - 1] - x[ok]
    ng = n - 1
    while ng - ok > 1:
        mid = (ok + ng) // 2
        if x[mid] - base < x[n - 1] - x[mid]:
            ok = mid
        else:
            ng = mid
    d_ok = abs((x[ok] - base) - (x[n - 1] - x[ok]))
    d_ng = abs((x[ng] - base) - (x[n - 1] - x[ng]))
    if d_ok < d_ng:
        return (x[ok] - base), (x[n - 1] - x[ok])
    else:
        return (x[ng] - base), (x[n - 1] - x[ng])


