import itertools

def getMinPartition(accB, offset=0):
  index = binary_search(accB, (accB[-1] - offset)/2 + offset)
  print('index ' + str(index))
  return return_min(accB, index, offset)

def calculate_min(accB, index, offset):
  return abs(accB[-1] - 2 * accB[index] + offset)

def return_min(accB, index, offset):
  if calculate_min(accB, index, offset) < calculate_min(accB, index-1, offset):
    return [accB[index] - offset, accB[-1] - accB[index]]
  return [accB[index-1] - offset, accB[-1] - accB[index-1]]


def binary_search(accB, value):
  N = len(accB)
  lowerId = 0
  upperId = N-1
  while lowerId+1 != upperId:
    midId = int((lowerId + upperId)/2)
    if(accB[midId] < value):
      lowerId = midId
    else:
      upperId = midId
  return lowerId

def calculate(accA, i):
  print(i)
  P, Q = getMinPartition(accA[:i])
  R, S = getMinPartition(accA[i:], accA[i-1])
  print('P, Q, R, S: {}, {} ,{} ,{}'.format(P, Q, R, S))
  return max([P, Q, R, S]) - min([P, Q, R, S])


