def solve(N: int, A: "List[int]"):
    cums = [0]
    for v in A:
        cums.append(cums[-1] + v)

    ret = float('inf')
    i, j, k = 1, 2, 3
    while j < N - 1:
        lm = cums[j]
        while i < j and cums[i] < lm / 2:
            i += 1
        if abs(lm - 2 * cums[i]) > abs(lm - 2 * cums[i - 1]):
            i -= 1

        rm = cums[N] - cums[j]
        while k < N and cums[k] - cums[j] < rm / 2:
            k += 1
        if k > j and abs(rm - 2 * (cums[k] - cums[j])) > abs(lm - 2 * (cums[k - 1] - cums[j])):
            k -= 1

        a, b, c, d = cums[i], cums[j] - cums[i], cums[k] - cums[j], cums[N] - cums[k]
        tmp = max(a, b, c, d) - min(a, b, c, d)
        ret = min(ret, tmp)
        j += 1
    print(ret)
    return

