    for i in 1..n {
        cumsum[i] += cumsum[i - 1];
    }

    let mut l = 0;
    let mut r = 2;

    let mut ans = std::i64::MAX;

    let mut v = vec![0; 4];
    for i in 0..n - 2 {
        if i == 0 {
            continue;
        }
        while (cumsum[l + 1] - (cumsum[i] - cumsum[l + 1])).abs()
            < (cumsum[l] - (cumsum[i] - cumsum[l])).abs()
