fn calc(cumsum: &[u64], border: usize) -> u64 {
    let min = cumsum[0];
    let max = cumsum.last().unwrap();
    let left = cumsum[border] - min;
    let right = max - cumsum[border];
    left.abs_diff(right)
}

fn split(cumsum: &[u64]) -> usize {
    let mut left = 1;
    let mut right = cumsum.len() - 1;

    loop {
        let width = right - left;

        if width < 15 {
            return (left..right+1).min_by_key(|&i| calc(cumsum, i)).unwrap();
        }

        let mid_l = left + width / 3;
        let mid_l_val = calc(cumsum, mid_l);
        let mid_r = left + width * 2 / 3;
        let mid_r_val = calc(cumsum, mid_r);
        if mid_l_val < mid_r_val {
            right = mid_r;
        } else {
            left = mid_l;
        }
    }
}

