fn main() {
    let mut scanner = Scanner::new(stdin());
    let n = scanner.read::<usize>().unwrap();
    let arr = scanner.read_vector::<i64>().unwrap();
    let mut cumsum = vec![arr[0]];
    for i in 1..n {
        let last = cumsum[i - 1];
        cumsum.push(last + arr[i]);
    }
    let mut minimum = std::i64::MAX;
    let (mut left_index, mut right_index) = (0, 2);
    for i in 1..(n - 2) {
        right_index = max(right_index, i + 1);
        let (mut left_min, mut left_max) = (min(cumsum[left_index], cumsum[i] - cumsum[left_index]), max(cumsum[left_index], cumsum[i] - cumsum[left_index]));
        let (mut right_min, mut right_max) = (min(cumsum[right_index] - cumsum[i], cumsum[n - 1] - cumsum[right_index]), max(cumsum[right_index] - cumsum[i], cumsum[n - 1] - cumsum[right_index]));
        while left_index + 1 < i {
            let l1 = cumsum[left_index + 1];
            let l2 = cumsum[i] - cumsum[left_index + 1];
            if (l2 - l1).abs() < left_max - left_min {
                left_index += 1;
                left_min = min(l1, l2);
                left_max = max(l1, l2);
            } else {
                break;
            }
        }
        while right_index + 1 < n - 1 {
            let r1 = cumsum[right_index + 1] - cumsum[i];
            let r2 = cumsum[n - 1] - cumsum[right_index + 1];
            if (r2 - r1).abs() < right_max - right_min {
                right_index += 1;
                right_min = min(r1, r2);
                right_max = max(r1, r2);
            } else {
                break;
            }
        }
        let diff = max(left_max, right_max) - min(left_min, right_min);
        minimum = min(diff, minimum);
    }

    println!("{}", minimum);
}

