fn diff(a: i64, b: i64, c: i64, d: i64) -> i64 {
    let min = min(min(a, b), min(c, d));
    let max = max(max(a, b), max(c, d));
    return max - min;
}

fn split(f: usize, t: usize, imos: &Vec<i64>) -> ((i64, i64), (i64, i64)) {
    let sum = imos[t] - imos[f];
    if t - f <= 2 {
        let one = imos[f+1] - imos[f];
        let two = imos[f+2] - imos[f+1];
        return ((one, two), (one, two));
    }

    let mut low = f;
    let mut high = t;
    while (high - low > 1) {
        let med = (low + high) / 2;
        let left = imos[med] - imos[f];
        let right = imos[t] - imos[med];
        if left < sum / 2 {
            low = med;
        } else {
            high = med;
        }
    }
    let one = imos[low] - imos[f];
    let two = imos[t] - imos[low];

    if low+1 == t {
        return ((one, two), (one, two))
    } else {
        let onen = imos[low+1] - imos[f];
        let twon = imos[t] - imos[low+1];
        return ((one, two), (onen, twon));
    }
}

