fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..n)
        .map(|_| itr.next().unwrap().parse().unwrap())
        .collect();

    let mut s = vec![0i64; n + 1];
    for i in 0..n {
        s[i + 1] = s[i] + a[i];
    }

    let mut ans = 1i64 << 60;

    let mut p = 1;
    let mut r = 3;
    for q in 2..n - 1 {
        let mut P = s[p];
        let mut Q = s[q] - s[p];
        let mut R = s[r] - s[q];
        let mut S = s[n] - s[r];
        while p + 1 < q && (s[q] - s[p + 1] - s[p + 1]).abs() <= (Q - P).abs() {
            p += 1;
            P = s[p];
            Q = s[q] - s[p];
        }
        while r + 1 < n && (s[n] - s[r + 1] - s[r + 1] + s[q]).abs() <= (S - R).abs() {
            r += 1;
            R = s[r] - s[q];
            S = s[n] - s[r];
        }
        ans = min(ans, max(max(max(P, Q), R), S) - min(min(min(P, Q), R), S));
    }
    println!("{}", ans);
}

