    let cumsum: Vec<u64> = aa.iter().lscan(0, |&acc, &a| acc + a).collect();

    let ans = (2..aa.len()-1).map(|bc| {
        let ab = split(&cumsum[..bc+1]);
        let cd = bc + split(&cumsum[bc..]);
        let sums = [
            cumsum[ab],
            cumsum[bc] - cumsum[ab],
            cumsum[cd] - cumsum[bc],
            cumsum.last().unwrap() - cumsum[cd]
        ];
        sums.iter().max().unwrap() - sums.iter().min().unwrap()
    }).min().unwrap();
    println!("{}", ans);
}

