fn eval(xs_cu: &Vec<i64>, x: usize, y: usize, z: usize) -> i64 {
    let n = xs_cu.len() - 1;
    let mut ys = vec![];
    ys.push(xs_cu[x] - xs_cu[0]);
    ys.push(xs_cu[y] - xs_cu[x]);
    ys.push(xs_cu[z] - xs_cu[y]);
    ys.push(xs_cu[n] - xs_cu[z]);
    ys.sort();
    ys[3] - ys[0]
}

fn main() {
    input! {
        n: usize,
        xs: [i64; n],
    }
    let xs_cu = cu(0, &xs);
    let mut x = 1;
    let mut z = 3;
    let mut res = 1i64 << 50;
    for y in 2..n - 2 + 1 {
        while ((xs_cu[n] - xs_cu[z]) - (xs_cu[z] - xs_cu[y])).abs()
            > ((xs_cu[n] - xs_cu[z + 1]) - (xs_cu[z + 1] - xs_cu[y])).abs()
        {
            z += 1;
        }
        while ((xs_cu[y] - xs_cu[x]) - (xs_cu[x] - xs_cu[0])).abs()
            > ((xs_cu[y] - xs_cu[x + 1]) - (xs_cu[x + 1] - xs_cu[0])).abs()
        {
            x += 1;
        }
        res = min(res, eval(&xs_cu, x, y, z));
    }
    println!("{}", res);
}

