fn acc_vec(v: &[i64]) -> Vec<i64>{
    let mut res = vec![0;v.len()+1];
    let mut acc: i64 = 0;
    for i in 0..v.len(){
        acc += v[i];
        res[i+1] = acc;
    }
    res
}

//search the best position to cut equally
//return $pos: sum of [left..pos) and sum of [pos..right) are the nearest
fn cut_equally(v: &[i64], left: usize, right: usize) -> usize {
    if right > v.len() || right - left <= 1{
        panic!("wrong params");
    }

    let (mut l, mut r) = (left, right);

    let mut cur_res = (0 as usize, std::i64::MAX);
    while l < r {
        //println!("l = {}, r = {}", l, r);
        let mid = (l+r)/2;
        // left sum = [left..mid)
        // right sum = [mid..right)
        let left_sum = v[mid-1] - v[left-1];
        let right_sum = v[right-1] - v[mid-1];
        //println!("left sum = {}, right sum = {}", left_sum, right_sum);
        if (right_sum - left_sum).abs() < cur_res.1{
            cur_res = (mid, (right_sum - left_sum).abs());
        }
        if right_sum > left_sum{
            l = mid+1;
        }else{
            r = mid;
        }
    }

    return cur_res.0;
}

fn sumup(v: &[i64], left: usize, right: usize, mid: usize) -> (i64, i64){
    return (v[mid-1] - v[left-1], v[right-1] - v[mid-1]);
}

fn main(){
    let n = read_as_vec::<usize>()[0];

    let a = read_as_vec::<i64>();
    let a = acc_vec(&a);

    let mut ans = std::i64::MAX;
    for i in 3..n{
        //split to [0..i) and [i..n)

        //binary search for each left and right
        //cut the vector equally as possible
        //left side
        let left_border = cut_equally(&a, 1, i);

        //right side
        let right_border = cut_equally(&a, i, n+1);

        let pq = sumup(&a, 1, i, left_border);
        let rs = sumup(&a, i, n+1, right_border);
        let (p, q) = (pq.0, pq.1);
        let (r, s) = (rs.0, rs.1);

        let max_val = cmp::max(p, cmp::max(q, cmp::max(r, s)));
        let min_val = cmp::min(p, cmp::min(q, cmp::min(r, s)));

        if (max_val - min_val).abs() < ans{
            ans = (max_val - min_val).abs();
        }
    }

    println!("{}", ans);
}

