fn get_separate(nums:Vec<i32>) -> (usize, i32, i32) {
    let mut heap0 = std::collections::BinaryHeap::new();
    let mut reverse_heap0 = std::collections::BinaryHeap::new();
    for i in 0..nums.len() {
        heap0.push(nums[i]);
        reverse_heap0.push(MinInt{value: nums[i]});
    }
    let mut heap1 = std::collections::BinaryHeap::new();
    let mut reverse_heap1:std::collections::BinaryHeap<MinInt> = std::collections::BinaryHeap::new();
    let mut obj = 10_0000_0000;
    let mut min_index:usize = 0;
    let mut min_rvalue = 0;
    let mut min_lvalue = 0;
    for i in 0..nums.len() {
        let mut temp_obj = 0;
        if let Some(v0) = heap0.pop() {
            if let Some(v1) = reverse_heap0.pop() {
                temp_obj += v0 - v1.value;
            }
        }
        let mut temp_r_value = 0;
        if let Some(r0) = heap0.peek() {
            if let Some(r1) = reverse_heap1.peek() {
                temp_obj += r0 - r1.value;
                temp_r_value = r0 - r1.value;
            }
        }
        if temp_obj < obj {
            temp_obj = obj;
            min_index = i;
            min_rvalue = temp_r_value;
            min_lvalue = temp_obj - temp_r_value;
        }
        heap1.push(nums[0]);
        reverse_heap1.push(MinInt{value: nums[i]});
    }
    return (min_index, min_rvalue, min_lvalue);
}

