fn solve() {
    let n = get!(usize);
    let a = read::<i64>();

    let sum = a.into_iter().scan(0, |sum, e| {
        *sum += e;
        Some(*sum)
    }).collect::<Vec<_>>();

    let mut minl = vec![0; n];
    for i in 0..n {
        let mut mins = std::i64::MAX;
        let start = if i < 1 { 0 } else { minl[i-1] };
        for j in start..n {
            let tmp = (sum[i]-2*sum[j]).abs();
            if mins < tmp {
                minl[i] = j-1;
                break;
            }
            mins = tmp;
        }
    }
    let mut minr = vec![0; n];
    for i in 0..n {
        let mut mins = std::i64::MAX;
        let start = if i < 1 { 0 } else { minr[i-1] };
        for j in start..n {
            let tmp = (sum[n-1]-2*sum[j]+sum[i]).abs();
            if mins < tmp {
                minr[i] = j-1;
                break;
            }
            mins = tmp;
        }
    }
    let mut mina = std::i64::MAX;
    for i in 0..n {
        let maxt = max(sum[n-1]-sum[minr[i]], max(sum[minr[i]]-sum[i], max(sum[i]-sum[minl[i]], sum[minl[i]])));
        let mint = min(sum[n-1]-sum[minr[i]], min(sum[minr[i]]-sum[i], min(sum[i]-sum[minl[i]], sum[minl[i]])));
        mina = min(mina, maxt-mint);
    }
    println!("{}", mina);
}

