    debugln!("dbg: {}, {}, {}", sep_m, sum_l, sum_r);

    let ans = ((sep_m - 1)..(sep_m + 1 + 1))
        .map(|sep_m| {
            let (sep_l, sum_ll, sum_lr) = separate_equal(&a[..sep_m]);
            debugln!("dbg: {}, {}, {}", sep_l, sum_ll, sum_lr);

            let (sep_r, sum_rl, sum_rr) = separate_equal(&a[sep_m..]);
            debugln!("dbg: {}, {}, {}", sep_r, sum_rl, sum_rr);

            let mut sums = [sum_ll, sum_lr, sum_rl, sum_rr];
