fn separate_equal(a: &[i32]) -> (usize, i32, i32) {
    let (mut left, mut right) = (0, a.len());

    let slice_sum = |slice: &[i32]| slice.iter().sum::<i32>();

    let sum_diff = |idx| {
        let sum_l = slice_sum(&a[..idx]);
        let sum_r = slice_sum(&a[idx..]);
        (sum_l - sum_r).abs()
    };

    loop {
        let l = (left * 2 + right) / 3;
        let r = (left + right * 2) / 3;

        if sum_diff(l) < sum_diff(r) {
            if right == r {
                break;
            } else {
                right = r;
            }
        } else {
            if left == l {
                break;
            } else {
                left = l;
            }
        }
    }

    (left..(right + 1))
        .map(|i| (i, slice_sum(&a[..i]), slice_sum(&a[i..])))
        .min_by_key(|&(_, sum_l, sum_r)| (sum_l - sum_r).abs())
        .unwrap()
}

