// 累積和
struct Cummulation {
    sums: Vec<i64>
}

impl Cummulation {
    fn new(target: &Vec<i64>) -> Cummulation {
        let mut cumulation_vec: Vec<i64> = Vec::new();
        cumulation_vec.push(0);
        let mut pre = 0;
        for i in target {
            let n = i + pre;
            cumulation_vec.push(n);
            pre = n;
        }
        Cummulation {sums: cumulation_vec}
    }

    fn get(&self, left: usize, right: usize) -> i64 {
        self.sums[right + 1] - self.sums[left]
    }
}

fn binary_search(left_boundary: usize, right_boundary: usize, cummulation: &Cummulation) -> i64 {
    let mut left = left_boundary as i64 - 1;
    let mut right = right_boundary as i64 + 1;
    let mut mid: i64;
    loop {
        if (right - left).abs() <= 1 {
            if left < 0 {
                return right;
            }
            if right >= right_boundary as i64 + 1 {
                return left;
            }
            if (cummulation.get(left_boundary, left as usize) - cummulation.get(left as usize + 1, right_boundary)).abs() 
            < (cummulation.get(left_boundary, right as usize) - cummulation.get(right as usize + 1, right_boundary)).abs() {
                return left;
            } else {
                return right;
            }
        }

        mid = (left + right) / 2;
        if cummulation.get(left_boundary, mid as usize) < cummulation.get(mid as usize + 1, right_boundary) {
            left = mid;
        } else {
            right = mid;
        }   
    }

}

fn main() {
    let n: usize = input();
    let a_vec = input_vec();
    let mut sum_vec: Vec<i64> = Vec::new();
    sum_vec.push(0);
    for i in 0..n {
        sum_vec.push(a_vec[i] + sum_vec[i]);
    }
    let cummulation = Cummulation::new(&a_vec);
    let mut ans = std::i64::MAX;
    for half in 1..(n-2) {
        let mut candidates: Vec<i64> = Vec::new();
        let quater = binary_search(0, half, &cummulation);
        candidates.push(cummulation.get(0, quater as usize));
        candidates.push(cummulation.get(quater as usize + 1, half));

        let quater_third = binary_search(half + 1, n - 1, &cummulation);
        candidates.push(cummulation.get(half + 1, quater_third as usize));
        candidates.push(cummulation.get(quater_third as usize + 1, n - 1));
        candidates.sort();
        if candidates[3] - candidates[0] < ans {
            ans = candidates[3] - candidates[0];
        }
    }
    println!("{}", ans);
}

