fn solve() {
    let n = get!(usize);
    let xs = util::gets::<i64>();

    let mut csum = vec![0];

    let mut t = 0;
    for x in xs {
        t += x;
        csum.push(t);
    }

    let mut a = 1;
    let mut b = 3;
    let mut ans = 1 << 60;

    for l in 2..n - 1 {
        let d = (csum[a] - (csum[l] - csum[a])).abs();
        while a + 1 < l && d > (csum[a + 1] - (csum[l] - csum[a + 1])).abs() {
            a += 1;
        }
        let d = (csum[b] - csum[l] - (csum[n] - csum[b])).abs();
        while b + 1 < n && d > (csum[b + 1] - csum[l] - (csum[n] - csum[b + 1])).abs() {
            b += 1;
        }

        let mut v = [
            csum[a],
            csum[l] - csum[a],
            csum[b] - csum[l],
            csum[n] - csum[b],
        ];

        v.sort();

        ans = min(ans, v[3] - v[0]);
    }

    println!("{}", ans);
}

