use std::cmp;

fn input_with_space_singleline() -> Vec<i64>{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).expect("!");
    s.trim().split(" ").map(|ref x|x.parse::<i64>().unwrap()).collect::<Vec<i64>>()
