pub fn main(){
    let N = input_with_space_singleline()[0] as usize;
    let A = input_with_space_singleline();
    // 累積和
    let mut _accum = 0i64;
    let mut accum = Vec::<i64>::new();
    for a in &A {
        _accum += a;
        accum.push(_accum);
    }
    //仕切り(範囲には仕切りも含む)
    let mut upper = 0usize;
    let mut bottom = 2usize;
    let mut result: i64 = 10i64.pow(18u32);
    for middle in 1usize..(N-2) as usize {
        //尺取り法（上部
        loop{
            if upper == middle - 1 {
                break;
            }
            let u = accum[upper ];
            let b = accum[middle ] - accum[upper ];
            if (u-b).abs() > ((u + A[(upper + 1) ]) - (b - A[(upper + 1) ])).abs() {
                upper += 1;
            }else{
                break;
            }
        }
        //尺取り法（下部）
        loop{
            if bottom == N - 2 {
                break;
            }
            let u = accum[bottom ] - accum[middle ];
            let b = accum[(N-1) ] - accum[bottom ];
            if (u-b).abs() > ((u+A[(bottom+1) ])- (b-A[(bottom+1) ])).abs() {
                bottom += 1;
            }else{
                break;
            }
        }
        //最小値を求める
        let t: Vec<i64> = vec![accum[N-1] - accum[bottom], accum[bottom] - accum[middle], accum[middle] - accum[upper], accum[upper]];
        result = cmp::min(result, (*t.iter().max().unwrap() - *t.iter().min().unwrap()) as i64);
    }
    println!("{}", result);
}

