fn main() {
    let n: usize;
    input!(n);
    let a = input_vector::<isize>();
    let mut sum = 0;
    let mut s = vec![0];
    for i in a {
        sum += i;
        s.push(sum);
    }

    let mut ans = isize::max_value();

    for j in 2..s.len() - 1 {
        let mut i = lower_bound(&s, s[j] / 2);
        if s[i] != s[j] / 2 && i != 0 {
            if (s[i] - s[j] / 2).abs() > (s[j] / 2 - s[i - 1]).abs() {
                i -= 1;
            }
        }
        if i == j {
            i -= 1;
        }
        if i == 0 {
            i += 1;
        }
        let mut k = lower_bound(&s, (s[j] + *s.last().unwrap()) / 2);

        if s[j] != s[k] / 2 && k != s.len() - 1 {
            if (s[j] - s[k] / 2).abs() > (s[k] / 2 - s[j - 1]).abs() {
                k -= 1;
            }
        }

        if k == j {
            k += 1;
        }
        if k == s.len() - 1 {
            k -= 1;
        }
        let mut buf = vec![];
        buf.push(s[i]);
        buf.push(s[j] - s[i]);
        buf.push(s[k] - s[j]);
        buf.push(*s.last().unwrap() - s[k]);
        ans = std::cmp::min(ans, *buf.iter().max().unwrap() - *buf.iter().min().unwrap());
    }
    println!("{}", ans);
