use std::io;
use std::cmp;
use std::collections::BinaryHeap;
use std::collections::HashMap;

fn read_line() -> String {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    buf
}

fn main() {
    let n: usize = read_line().trim().parse().unwrap();
    let mut a: Vec<u64> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let mut memo: Vec<u64> = vec![0; n+1];

    let mut tmp = 0u64;
    for i in 0..n {
        tmp += a[i];
        memo[i+1] = tmp;
    }

    let mut ans = memo[n];
    for i in 2..n-2 {
        let mut min1 = 0;
        let mut max1 = memo[i];
        let mut l = 0;
        let mut r = i;

        while r-l > 1 {
            let mid = (l+r)/2;
            let lsum = memo[mid];
            let rsum = memo[i] - memo[mid];

            min1 = cmp::max(min1, cmp::min(lsum, rsum));
            max1 = cmp::min(max1, cmp::max(lsum, rsum));

            if lsum > rsum {
                r = mid;
            } else {
                l = mid;
            }
        }

        let mut min2 = 0;
        let mut max2 = memo[n] - memo[i];

        l = i;
        r = n;

        while r-l > 1 {
            let mid = (l+r)/2;
            let lsum = memo[mid] - memo[i];
            let rsum = memo[n] - memo[mid];

            min2 = cmp::max(min2, cmp::min(lsum, rsum));
            max2 = cmp::min(max2, cmp::max(lsum, rsum));

            if lsum > rsum {
                r = mid;
            } else {
                l = mid;
            }
        }
        ans = cmp::min(ans, cmp::max(max2, max1) - cmp::min(min1, min2));
    }

    println!("{}", ans);
}
